#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
struct VibexMessageClipboard {
    format: String,
    version: u8,
    text: String,
    attachments: Vec<MessageAttachment>,
    #[serde(default)]
    mentions: Vec<VibexUseMention>,
}

impl VibexMessageClipboard {
    fn new(text: String, attachments: Vec<MessageAttachment>) -> Self {
        Self {
            format: VIBEX_MESSAGE_CLIPBOARD_FORMAT.to_string(),
            version: VIBEX_MESSAGE_CLIPBOARD_VERSION,
            text,
            attachments,
            mentions: Vec::new(),
        }
    }

    fn with_mentions(mut self, mentions: &[VibexUseMention]) -> Self {
        self.mentions = mentions
            .iter()
            .take(VIBEX_USE_MAX_MENTIONS)
            .cloned()
            .collect();
        self
    }

    fn is_supported(&self) -> bool {
        self.format == VIBEX_MESSAGE_CLIPBOARD_FORMAT
            && self.version == VIBEX_MESSAGE_CLIPBOARD_VERSION
            && (!self.attachments.is_empty() || !self.mentions.is_empty())
            && self.attachments.len() <= VIBEX_MESSAGE_CLIPBOARD_MAX_ATTACHMENTS
            && self.mentions.len() <= VIBEX_USE_MAX_MENTIONS
    }
}

fn reveal_composer_cursor_after_layout(input: Entity<TextareaState>, window: &mut Window) {
    window.on_next_frame(move |window, _| {
        window.on_next_frame(move |_, cx| {
            input.update(cx, |input, cx| {
                let selection = input.selected_range();
                input.set_selected_range(selection, cx);
            });
        });
    });
}

fn composer_runtime_controls_are_compact(viewport_width: u32) -> bool {
    viewport_width <= NEW_SESSION_COMPACT_SELECTOR_MAX_WIDTH
}

fn composer_runtime_menu_placement(
    trigger_bounds: Option<Bounds<Pixels>>,
    viewport_height: f32,
    desired_height: f32,
    max_height: f32,
) -> RuntimeMenuPlacement {
    let desired_height = desired_height.min(max_height);
    let fallback_height = (viewport_height - RUNTIME_MENU_VIEWPORT_MARGIN * 2.0)
        .clamp(NEW_SESSION_RUNTIME_MENU_MIN_HEIGHT, max_height);
    let Some(trigger_bounds) = trigger_bounds else {
        return RuntimeMenuPlacement {
            anchor: Anchor::TopRight,
            height: desired_height.min(fallback_height),
            trigger_offset: RUNTIME_MENU_TRIGGER_GAP,
        };
    };

    let trigger_top = f32::from(trigger_bounds.origin.y);
    let trigger_height = f32::from(trigger_bounds.size.height);
    let trigger_bottom = trigger_top + trigger_height;
    let available_above = (trigger_top - RUNTIME_MENU_VIEWPORT_MARGIN).max(0.0);
    let available_below =
        (viewport_height - trigger_bottom - RUNTIME_MENU_VIEWPORT_MARGIN).max(0.0);
    let opens_below = desired_height <= available_below
        || (desired_height > available_above && available_below >= available_above);
    let available = if opens_below {
        available_below
    } else {
        available_above
    };
    RuntimeMenuPlacement {
        anchor: if opens_below {
            Anchor::TopRight
        } else {
            Anchor::BottomRight
        },
        height: desired_height.min(available.max(1.0)),
        trigger_offset: RUNTIME_MENU_TRIGGER_GAP,
    }
}

fn composer_runtime_choice_menu_height(row_count: usize, max_height: f32) -> f32 {
    (12.0 + COMPOSER_RUNTIME_CHOICE_ROW_HEIGHT * row_count.max(1) as f32).min(max_height)
}

fn new_session_project_menu_height(row_count: usize) -> f32 {
    (NEW_SESSION_PROJECT_MENU_CHROME_HEIGHT
        + NEW_SESSION_PROJECT_MENU_ROW_HEIGHT * row_count.max(1) as f32)
        .min(NEW_SESSION_PROJECT_MENU_MAX_HEIGHT)
}

/// Height of one `/` popup row for the tab that is showing.
///
/// The tab owns the row height because a quick phrase previews the text it
/// inserts on a second line, while a command keeps its name and description on
/// one. The menu's own height is estimated from the same figure, so a phrase
/// list is never measured as if its rows were one line tall.
fn composer_suggestion_row_height(phrase_layout: bool) -> f32 {
    if phrase_layout {
        COMPOSER_SUGGESTION_MENU_PHRASE_ROW_HEIGHT
    } else {
        COMPOSER_SUGGESTION_MENU_ROW_HEIGHT
    }
}

/// Height the `/` popup wants for `row_count` rows.
///
/// The quick-phrase footer is part of the popup, so it is part of this figure:
/// leaving it out capped the popup 30px below its own content, which clamped
/// the list to a sliver and cut the phrase rows it was meant to show.
fn composer_suggestion_menu_height(row_count: usize, row_height: f32, footer_height: f32) -> f32 {
    let content_height = if row_count == 0 {
        COMPOSER_SUGGESTION_MENU_EMPTY_HEIGHT
    } else {
        COMPOSER_SUGGESTION_MENU_HEADER_HEIGHT
            + COMPOSER_SUGGESTION_MENU_VERTICAL_PADDING
            + row_height * row_count as f32
    };
    (content_height + footer_height).min(COMPOSER_SUGGESTION_MENU_MAX_HEIGHT)
}

/// Places the `/` popup above the composer, or inside it when the composer
/// fills the page.
///
/// The popup normally hangs above the surface, where it covers the queue and
/// plan extensions instead of the draft. A fullscreen composer starts at the
/// window's top, leaving less room above it than the popup's own header, so
/// that anchor clamped the popup to a sliver. When the surface cannot hold the
/// popup above it, the popup opens from the caret line instead: the text being
/// typed to filter the list stays visible, and the list expands over the empty
/// part of the draft. A caret near the window's bottom flips the popup back
/// above itself, so the current line is never covered.
fn composer_suggestion_menu_placement(
    surface_bounds: Bounds<Pixels>,
    caret_line: Option<(f32, f32)>,
    viewport_height: f32,
    row_count: usize,
    row_height: f32,
    footer_height: f32,
) -> ComposerSuggestionMenuPlacement {
    let surface_top = f32::from(surface_bounds.origin.y);
    let desired_height = composer_suggestion_menu_height(row_count, row_height, footer_height);
    // One row (or the empty-state sentence when there are no rows) plus the
    // popup's own chrome is the least that reads as an expanded list.
    let minimum_height = if row_count == 0 {
        COMPOSER_SUGGESTION_MENU_EMPTY_HEIGHT + footer_height
    } else {
        COMPOSER_SUGGESTION_MENU_HEADER_HEIGHT
            + COMPOSER_SUGGESTION_MENU_VERTICAL_PADDING
            + row_height
            + footer_height
    };
    let available_above =
        (surface_top - RUNTIME_MENU_VIEWPORT_MARGIN - COMPOSER_SUGGESTION_MENU_TRIGGER_GAP)
            .max(1.0);
    let available_below_surface = (viewport_height
        - surface_top
        - RUNTIME_MENU_VIEWPORT_MARGIN
        - COMPOSER_SUGGESTION_MENU_TRIGGER_GAP)
        .max(1.0);
    if available_above >= minimum_height || available_below_surface <= available_above {
        return ComposerSuggestionMenuPlacement {
            max_height: desired_height.min(available_above),
            anchor: ComposerSuggestionMenuAnchor::AboveSurface {
                bottom_offset: viewport_height - surface_top + COMPOSER_SUGGESTION_MENU_TRIGGER_GAP,
            },
        };
    }

    let Some((caret_top, line_height)) = caret_line else {
        return ComposerSuggestionMenuPlacement {
            max_height: desired_height.min(available_below_surface),
            anchor: ComposerSuggestionMenuAnchor::BelowAnchor {
                top_offset: surface_top + COMPOSER_SUGGESTION_MENU_TRIGGER_GAP,
            },
        };
    };

    let caret_bottom = caret_top + line_height;
    let available_below_caret = (viewport_height
        - caret_bottom
        - RUNTIME_MENU_VIEWPORT_MARGIN
        - COMPOSER_SUGGESTION_MENU_TRIGGER_GAP)
        .max(1.0);
    let available_above_caret =
        (caret_top - RUNTIME_MENU_VIEWPORT_MARGIN - COMPOSER_SUGGESTION_MENU_TRIGGER_GAP).max(1.0);
    // Prefer the space below the caret so the line being typed stays above the
    // popup; use the space above it when the caret is near the window's bottom.
    if available_below_caret >= minimum_height || available_below_caret >= available_above_caret {
        ComposerSuggestionMenuPlacement {
            max_height: desired_height.min(available_below_caret),
            anchor: ComposerSuggestionMenuAnchor::BelowAnchor {
                top_offset: caret_bottom + COMPOSER_SUGGESTION_MENU_TRIGGER_GAP,
            },
        }
    } else {
        ComposerSuggestionMenuPlacement {
            max_height: desired_height.min(available_above_caret),
            anchor: ComposerSuggestionMenuAnchor::AboveCaret {
                bottom_offset: viewport_height - caret_top + COMPOSER_SUGGESTION_MENU_TRIGGER_GAP,
            },
        }
    }
}

/// The caret's current line as `(top, line height)` in window coordinates.
///
/// The last prepaint's caret geometry is unscrolled, so its scroll offset has
/// to be added before comparing it with the popup's window-space anchor.
fn composer_caret_line(input: &Entity<TextareaState>, cx: &App) -> Option<(f32, f32)> {
    let geometry = input.read(cx).prepaint_caret_geometry()?;
    let caret = geometry.cursor_bounds();
    Some((
        f32::from(caret.origin.y) + f32::from(geometry.scroll_offset().y),
        f32::from(geometry.line_height()),
    ))
}

