fn runtime_attachment_warning<T>(outcome: vibex_core::VibexResult<T>) -> Option<String> {
    outcome
        .err()
        .map(|error| format!("{}: {}", error.code, error.message))
}

fn initial_message_failure_note(error: &vibex_core::VibexError) -> Option<String> {
    if error.code == "message_submission_interrupted_before_dispatch" {
        return None;
    }
    Some(format!(
        "Session created; initial message failed: {}: {}",
        error.code, error.message
    ))
}

fn initial_message_interrupted_error() -> vibex_core::VibexError {
    vibex_core::VibexError::conflict(
        "message_submission_interrupted_before_dispatch",
        "message submission was cancelled before dispatch",
    )
}

/// Lifts a facade error into the shell error type used by the new-session
/// pipeline, which predates the backend facade.
fn backend_error_to_vibex(error: vibex_backend::BackendError) -> vibex_core::VibexError {
    let category = match error.kind {
        vibex_backend::BackendErrorKind::Loading => vibex_core::ErrorCategory::Process,
        vibex_backend::BackendErrorKind::Offline => vibex_core::ErrorCategory::Remote,
        vibex_backend::BackendErrorKind::Conflict => vibex_core::ErrorCategory::Conflict,
        vibex_backend::BackendErrorKind::Permission => vibex_core::ErrorCategory::Permission,
        vibex_backend::BackendErrorKind::Unsupported => vibex_core::ErrorCategory::Capability,
        vibex_backend::BackendErrorKind::Failed => vibex_core::ErrorCategory::Process,
    };
    vibex_core::VibexError::new(category, error.code, error.message)
}

fn runtime_token_usage_snapshot(
    runtime: &DesktopRuntime,
    session_id: &VibexSessionId,
) -> vibex_core::VibexResult<Option<AgentTokenUsage>> {
    runtime.agent_token_usage_snapshot(session_id)
}

async fn announce_created_session_before_initial_message<C, F, T>(
    created_tx: mpsc::UnboundedSender<C>,
    created: C,
    initial_message: Option<F>,
) -> Option<vibex_core::VibexError>
where
    F: Future<Output = vibex_core::VibexResult<T>>,
{
    let _ = created_tx.send(created);
    match initial_message {
        Some(submission) => submission.await.err(),
        None => None,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TimelineRestoreError {
    PageSessionMismatch,
    PrefixIncomplete,
    PaginationStalled,
}

impl TimelineRestoreError {
    fn into_vibex_error(self) -> vibex_core::VibexError {
        let (code, message) = match self {
            Self::PageSessionMismatch => (
                "timeline_page_session_mismatch",
                "timeline page belongs to another session",
            ),
            Self::PrefixIncomplete => (
                "timeline_prefix_incomplete",
                "timeline restore did not start from the authoritative prefix",
            ),
            Self::PaginationStalled => (
                "timeline_pagination_stalled",
                "timeline pagination did not advance its authoritative cursor",
            ),
        };
        vibex_core::VibexError::storage(code, message)
    }
}

fn next_authoritative_timeline_cursor(
    expected_session_id: &VibexSessionId,
    after_sequence: i64,
    page: &TimelinePage,
) -> Result<Option<i64>, TimelineRestoreError> {
    if &page.session_id != expected_session_id {
        return Err(TimelineRestoreError::PageSessionMismatch);
    }
    if after_sequence == 0
        && (page.has_older || page.start_sequence.is_some_and(|sequence| sequence > 1))
    {
        return Err(TimelineRestoreError::PrefixIncomplete);
    }
    if !page.has_newer {
        return Ok(None);
    }
    page.end_sequence
        .filter(|end_sequence| *end_sequence > after_sequence)
        .map(Some)
        .ok_or(TimelineRestoreError::PaginationStalled)
}

/// Reads a child Agent's whole timeline through the backend facade.
///
/// Child-Agent timelines are read by the parent session view, which must work
/// the same way whether the workbench owns the runtime or is paired with a
/// remote one.
async fn fetch_authoritative_timeline_via_backend(
    backend: BackendFacade,
    session_id: VibexSessionId,
) -> vibex_core::VibexResult<Vec<vibex_core::TimelineItem>> {
    let mut items = Vec::new();
    let mut after_sequence = 0_i64;
    loop {
        let page = backend
            .agent()
            .fetch_timeline(FetchTimelineRequest {
                session_id: session_id.clone(),
                after_sequence: Some(after_sequence),
                before_sequence: None,
                limit: AGENT_TIMELINE_FETCH_PAGE_LIMIT,
                max_turns: None,
                max_bytes: None,
            })
            .await
            .map_err(remote_error_into_vibex)?;
        let next_cursor = next_authoritative_timeline_cursor(&session_id, after_sequence, &page)
            .map_err(TimelineRestoreError::into_vibex_error)?;
        items.extend(page.items);
        let Some(next_cursor) = next_cursor else {
            return Ok(items);
        };
        after_sequence = next_cursor;
    }
}

/// The newest window of one session, banded or contiguous.
///
/// The banded window is what makes a running session open onto its history
/// instead of onto a slice of its live turn, but it can skip the live turn's
/// middle and says so through `omitted`. A client that refused such a page asks
/// for this with `contiguous`, which takes the ordinary turn window: it pages
/// the live turn row by row instead of handing it over in two bands, so it
/// cannot leave a hole.
async fn fetch_timeline_window_or_contiguous(
    runtime: Arc<DesktopRuntime>,
    session_id: VibexSessionId,
    contiguous: bool,
) -> vibex_core::VibexResult<vibex_core::TimelinePage> {
    runtime
        .agent()
        .fetch_timeline(FetchTimelineRequest {
            session_id,
            after_sequence: None,
            before_sequence: None,
            limit: AGENT_TIMELINE_FETCH_PAGE_LIMIT,
            max_turns: (!contiguous).then_some(AGENT_TIMELINE_TURN_WINDOW),
            max_bytes: Some(AGENT_TIMELINE_WINDOW_BYTES),
        })
        .await
}

/// Authority-agnostic twin of [`fetch_timeline_window_or_contiguous`].
async fn fetch_timeline_window_or_contiguous_via_backend(
    backend: BackendFacade,
    session_id: VibexSessionId,
    contiguous: bool,
) -> vibex_core::VibexResult<vibex_core::TimelinePage> {
    backend
        .agent()
        .fetch_timeline(FetchTimelineRequest {
            session_id,
            after_sequence: None,
            before_sequence: None,
            limit: AGENT_TIMELINE_FETCH_PAGE_LIMIT,
            max_turns: (!contiguous).then_some(AGENT_TIMELINE_TURN_WINDOW),
            max_bytes: Some(AGENT_TIMELINE_WINDOW_BYTES),
        })
        .await
        .map_err(remote_error_into_vibex)
}

/// Everything above `after_sequence`, for a refreshed cached window.
///
/// A restored view already holds a contiguous prefix, so only the tail above
/// it is missing. That tail can span several pages after a session streamed
/// while the reader was elsewhere, so this one loops.
async fn fetch_timeline_tail(
    runtime: Arc<DesktopRuntime>,
    session_id: VibexSessionId,
    after_sequence: i64,
) -> vibex_core::VibexResult<Option<Vec<vibex_core::TimelineItem>>> {
    let mut items = Vec::new();
    let mut cursor = after_sequence.max(0);
    loop {
        let page = runtime
            .agent()
            .fetch_timeline(FetchTimelineRequest {
                session_id: session_id.clone(),
                after_sequence: Some(cursor),
                before_sequence: None,
                limit: AGENT_TIMELINE_FETCH_PAGE_LIMIT,
                max_turns: None,
                max_bytes: None,
            })
            .await?;
        if page.session_id != session_id
            || page
                .items
                .iter()
                .any(|item| item.session_id != session_id || item.sequence <= cursor)
        {
            return Err(vibex_core::VibexError::storage(
                "timeline_tail_page_invalid",
                "the Agent timeline tail page is not above the cursor",
            ));
        }
        items.extend(page.items);
        if items.len() > AGENT_TIMELINE_RESUME_MAX_ITEMS {
            // The prefix is too far behind to patch; the caller re-opens the
            // newest window instead of walking history nobody is reading.
            return Ok(None);
        }
        if !page.has_newer {
            return Ok(Some(items));
        }
        let Some(next) = page.end_sequence.filter(|next| *next > cursor) else {
            return Err(vibex_core::VibexError::storage(
                "timeline_tail_stalled",
                "the Agent timeline tail cursor did not advance",
            ));
        };
        cursor = next;
    }
}

/// Authority-agnostic twin of [`fetch_timeline_tail`].
async fn fetch_timeline_tail_via_backend(
    backend: BackendFacade,
    session_id: VibexSessionId,
    after_sequence: i64,
) -> vibex_core::VibexResult<Option<Vec<vibex_core::TimelineItem>>> {
    let mut items = Vec::new();
    let mut cursor = after_sequence.max(0);
    loop {
        let page = backend
            .agent()
            .fetch_timeline(FetchTimelineRequest {
                session_id: session_id.clone(),
                after_sequence: Some(cursor),
                before_sequence: None,
                limit: AGENT_TIMELINE_FETCH_PAGE_LIMIT,
                max_turns: None,
                max_bytes: None,
            })
            .await
            .map_err(remote_error_into_vibex)?;
        if page.session_id != session_id
            || page
                .items
                .iter()
                .any(|item| item.session_id != session_id || item.sequence <= cursor)
        {
            return Err(vibex_core::VibexError::storage(
                "timeline_tail_page_invalid",
                "the Agent timeline tail page is not above the cursor",
            ));
        }
        items.extend(page.items);
        if items.len() > AGENT_TIMELINE_RESUME_MAX_ITEMS {
            return Ok(None);
        }
        if !page.has_newer {
            return Ok(Some(items));
        }
        let Some(next) = page.end_sequence.filter(|next| *next > cursor) else {
            return Err(vibex_core::VibexError::storage(
                "timeline_tail_stalled",
                "the Agent timeline tail cursor did not advance",
            ));
        };
        cursor = next;
    }
}

