impl ReleaseChannel {
    fn parse(value: &str, source: &'static str) -> vibex_core::VibexResult<Self> {
        match value.trim().to_ascii_lowercase().as_str() {
            "preview" => Ok(Self::Preview),
            "rc" => Ok(Self::ReleaseCandidate),
            "stable" => Ok(Self::Stable),
            _ => Err(vibex_core::VibexError::validation(
                "release_channel_invalid",
                "release channel must be preview, rc, or stable",
            )
            .with_diagnostic("source", source)),
        }
    }
}

/// Bridges a backend failure into the runtime-error type the workbench's
/// optimistic-completion helpers consume. Code and message survive verbatim.
pub(crate) fn remote_error_into_vibex(error: BackendError) -> vibex_core::VibexError {
    vibex_core::VibexError::new(vibex_core::ErrorCategory::Remote, error.code, error.message)
}

/// Whether a backend event is the sidebar invalidation only a remote client
/// receives.
///
/// A remote authority announces a session another client created this way and
/// through no other event: the snapshot it fans out reaches the clients that
/// share its event stream, and this projection invalidation is what the clients
/// that do not — like this shell when it drives a paired runtime — are told to
/// re-read for. A *gap* in the same projection needs no arm of its own: it
/// arrives as a lagged fan-out, and that is already answered by re-reading the
/// session list.
fn backend_event_invalidates_sidebar(event: &BackendEvent) -> bool {
    matches!(
        event,
        BackendEvent::ProjectionInvalidated(BackendProjection::Sidebar)
    )
}

/// Maps a backend event onto its identical desktop twin. The payload types
/// are the same `vibex_core` contracts the native event bridge passes
/// through, so this is a lossless 1:1 conversion except for variants the
/// desktop has no live counterpart for.
fn map_backend_event(event: BackendEvent) -> Option<DesktopEvent> {
    match event {
        BackendEvent::Timeline(event) => Some(DesktopEvent::Timeline(event)),
        BackendEvent::SessionUpdated(session) => Some(DesktopEvent::SessionUpdated(session)),
        BackendEvent::SessionsRemoved(session_ids) => {
            Some(DesktopEvent::SessionsRemoved(session_ids))
        }
        BackendEvent::Runtime(event) => Some(DesktopEvent::Runtime(event)),
        BackendEvent::RuntimeSelection(event) => Some(DesktopEvent::RuntimeSelection(event)),
        BackendEvent::ModelGateway(event) => Some(DesktopEvent::ModelGateway(event)),
        BackendEvent::ProjectionInvalidated(BackendProjection::Management) => {
            Some(DesktopEvent::ProviderConfigChanged(
                vibex_desktop_runtime::ProviderConfigChangedEvent {
                    provider_profile_ids: Vec::new(),
                    phase: ProviderConfigChangePhase::ProfilesChanged,
                },
            ))
        }
        BackendEvent::ProjectionInvalidated(BackendProjection::Usage) => {
            Some(DesktopEvent::UsageInvalidated)
        }
        BackendEvent::RuntimeRenamed(_) | BackendEvent::DeviceRenamed(_) => {
            // Identity changes are applied by the remote event pump, which owns
            // the runtime registry, rather than by a desktop event.
            None
        }
        BackendEvent::ProjectionInvalidated(_) | BackendEvent::Notification(_) => None,
        BackendEvent::Lagged {
            stream,
            skipped,
            refetch,
            ..
        } => Some(DesktopEvent::Lagged {
            stream: match stream {
                BackendEventStream::Timeline => DesktopEventStream::Timeline,
                BackendEventStream::Runtime => DesktopEventStream::Runtime,
                BackendEventStream::RuntimeSelection => DesktopEventStream::RuntimeSelection,
                BackendEventStream::Usage => DesktopEventStream::Usage,
                BackendEventStream::Fanout => DesktopEventStream::Fanout,
            },
            skipped,
            refetch: AuthoritativeRefetch {
                session_id: refetch.session_id,
                timeline: refetch.timeline,
                runtime: refetch.runtime,
                runtime_selection: refetch.runtime_selection,
                usage: refetch.projection == Some(BackendProjection::Usage),
            },
        }),
        BackendEvent::Disconnected => None,
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum RuntimeUiSignal {
    Event(Box<DesktopEvent>),
    /// The remote transport dropped its connection. Unlike a runtime shutdown
    /// the transport keeps retrying, so the drain loop stays alive and the UI
    /// only shows a reconnect note.
    RemoteReconnecting,
    /// The runtime this shell drives published a new name.
    RuntimeRenamed(String),
    /// The authority invalidated the sidebar projection a remote client draws.
    ///
    /// A remote authority announces a session another client created this way
    /// and through no other event — the ownership tree it pushes carries no
    /// creation — so the list this shell is drawing is re-read when this
    /// arrives. Its arrangement is the shell's own and is not what the
    /// authority is speaking about.
    SidebarInvalidated,
    Shutdown,
}

#[derive(Debug)]
enum AgentPollSignal {
    Timeline(TimelinePage),
    Session(AgentSession),
    RuntimeSelection(Box<AgentSessionRuntimeSelectionState>),
    RuntimeUsage {
        session_id: VibexSessionId,
        usage: Option<AgentTokenUsage>,
    },
    Terminals(Vec<TerminalSession>),
}

fn agent_projection_should_repaint(active_tab: &str, changed: bool) -> bool {
    changed && active_tab == "agent"
}

fn should_defer_timeline_streaming_work(active_tab: &str, new_session_open: bool) -> bool {
    active_tab != "agent" || new_session_open
}

/// Whether a brand-new session's authoritative acknowledgment may move the
/// workbench onto that session's conversation.
///
/// Submitting opens the conversation before the authority answers, so the
/// acknowledgment exists to reconcile the page the reader is already on — not
/// to choose it a second time. A reader who moved on in the meantime (to the
/// New Session home, to another tab, to another session) has already said what
/// they want to look at, and a creation landing in the background is not a
/// reason to pull them back. The home is what "moved on" looks like when the
/// selection still names the session being created, because opening the home
/// leaves that selection alone.
fn new_session_acknowledgment_may_navigate(
    generation_is_current: bool,
    selected_session_id: Option<&VibexSessionId>,
    created_session_id: &VibexSessionId,
    new_session_open: bool,
    active_tab: &str,
) -> bool {
    generation_is_current
        && selected_session_id == Some(created_session_id)
        && !new_session_open
        && active_tab == "agent"
}

fn timeline_live_event_is_streaming_only(event: &TimelineLiveEvent) -> bool {
    if !timeline_live_event_is_well_formed(event) {
        return false;
    }
    match &event.item.payload {
        TimelinePayload::AgentMessageDelta(_) => true,
        TimelinePayload::Reasoning(reasoning) => !reasoning.is_final,
        _ => false,
    }
}

fn timeline_batch_requires_auto_continue_refresh(events: &[TimelineLiveEvent]) -> bool {
    events.iter().any(|event| {
        if !timeline_live_event_is_well_formed(event) {
            return false;
        }
        match &event.item.payload {
            // Non-final reasoning arrives while the provider is still running.
            // The authoritative idle/error snapshot refreshes the completion
            // status once the turn settles, without scanning the history for
            // every thought chunk. Agent-message deltas remain refreshable
            // because a trailing answer delta can change the latest outcome.
            TimelinePayload::AgentMessageDelta(_) => true,
            TimelinePayload::Reasoning(reasoning) => reasoning.is_final,
            _ => true,
        }
    })
}

/// The turn verdict a freshly loaded timeline may pin to its session revision.
///
/// A page cut to a turn window can end mid-turn — the row that would prove the
/// turn ended may simply not be in the window that was read — so only a final
/// answer is evidence the turn completed. Anything else leaves the revision to
/// the authority's completion probe instead of caching an "abnormal stop" no
/// later event can revise, which is the reading that keeps a queued auto-send
/// from ever leaving.
fn authoritative_loaded_turn_status(items: &[TimelineItem]) -> Option<bool> {
    (latest_timeline_turn_ended_normally(items) == Some(true)).then_some(true)
}

/// Session snapshots also carry the latest timeline timestamp. That timestamp
/// changes for every streamed item, but it does not change the sidebar shape.
/// Keep the comparison focused on fields that can affect the sidebar so a
/// hidden workbench does not repaint for every reasoning chunk.
fn session_snapshot_sidebar_changed(previous: Option<&AgentSession>, next: &AgentSession) -> bool {
    let Some(previous) = previous else {
        return true;
    };
    previous.id != next.id
        || previous.title != next.title
        || previous.project_id != next.project_id
        || previous.workspace_id != next.workspace_id
        || previous.workspace_root != next.workspace_root
        || previous.workspace_mode != next.workspace_mode
        || previous.agent_id != next.agent_id
        || previous.state != next.state
        || previous.created_at_ms != next.created_at_ms
        || previous.archived_at_ms != next.archived_at_ms
        || previous.deleted_at_ms != next.deleted_at_ms
}

/// Whether a session belongs on the navigation sidebar.
///
/// A session is a row while it is neither deleted nor archived. The archived
/// half is not cosmetic: the authoritative root list the sidebar is drawn from
/// filters `archived_at_ms IS NULL` in SQL, so an archived session is absent
/// from it by construction. A live snapshot is the one other way a row can
/// enter the list, and it has to answer the same question, or a session another
/// client archived for the reader stays on this sidebar wearing an "Archived"
/// badge instead of leaving the way a local archive takes it off.
fn session_belongs_on_sidebar(session: &AgentSession) -> bool {
    session.deleted_at_ms.is_none() && session.archived_at_ms.is_none()
}

/// How a mutation took a session row off the sidebar before the runtime
/// answered.
///
/// The two are not interchangeable. A deletion is terminal: the row stays
/// hidden, and every authoritative read keeps ignoring it, until the deletion
/// is reconciled. An archive is reversible, so the row is only hidden while the
/// archive itself is in flight — once it settles the ordinary session list
/// omits archived rows by itself, and a restore has to be free to put the row
/// back.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SidebarSessionRemoval {
    Delete,
    Archive,
}

fn session_update_should_repaint(
    active_tab: &str,
    new_session_open: bool,
    snapshot_changed: bool,
    sidebar_changed: bool,
) -> bool {
    sidebar_changed
        || (!should_defer_timeline_streaming_work(active_tab, new_session_open) && snapshot_changed)
}

fn timeline_batch_should_repaint(
    active_tab: &str,
    unread_changed: bool,
    timeline_changed: bool,
    needs_refetch: bool,
) -> bool {
    unread_changed || agent_projection_should_repaint(active_tab, timeline_changed || needs_refetch)
}

fn timeline_virtual_rows_need_rebuild(turn_count: usize, row_size_count: usize) -> bool {
    turn_count != row_size_count
}

/// The timeline item recorded at `sequence`.
///
/// Rows name at most the first and last item they folded, and both the
/// borrowed view and a child Agent's timeline keep their items ordered by
/// sequence, so a row resolves its payload with a binary search instead of a
/// scan. Callers that need the item to really be one the row names still have
/// to check the id.
fn timeline_item_at_sequence(
    items: &[vibex_core::TimelineItem],
    sequence: i64,
) -> Option<&vibex_core::TimelineItem> {
    let index = items.partition_point(|item| item.sequence < sequence);
    items.get(index).filter(|item| item.sequence == sequence)
}

/// Position lookup for `TimelineModel::items` keyed by item id.
///
/// Row/turn renderers resolve payloads from item ids on every frame; a linear
/// scan over the whole timeline turns that into quadratic work once a session
/// accumulates thousands of items, which is exactly when scrolling must stay
/// smooth. The index is rebuilt lazily whenever the timeline identity changes.
#[derive(Default)]
struct TimelineItemIndex {
    session_id: Option<VibexSessionId>,
    revision: u64,
    item_count: usize,
    end_sequence: Option<i64>,
    positions: HashMap<String, usize>,
}

struct ChildAgentTimelineState {
    session: Option<AgentSession>,
    timeline: TimelineModel,
    loaded: bool,
    loading: bool,
    error: Option<String>,
    load_generation: u64,
    projection: ChildAgentProjection,
}

/// The child Agent projections the rail last handed out.
///
/// Projecting a child's timeline folds every item it holds — tens of thousands
/// of them for a long subagent run — and both the rail and a delegation card's
/// preview used to redo that fold on every frame, including the frames that
/// changed nothing at all. Each half is kept with the content it was built
/// from, so a repaint that did not move the timeline reuses it, and a caller
/// that reads only one half never pays for the other.
#[derive(Default)]
struct ChildAgentProjection {
    rows: Option<(
        ChildAgentProjectionKey,
        Rc<Vec<ChildAgentTimelineRowProjection>>,
    )>,
    turns: Option<(ChildAgentTurnsKey, Rc<Vec<Rc<TimelineConversationTurn>>>)>,
}

/// The timeline content a projection was built from.
#[derive(Clone, Copy, PartialEq, Eq)]
struct ChildAgentProjectionKey {
    revision: u64,
    item_count: usize,
    end_sequence: Option<i64>,
}

/// What a turn projection additionally depends on: the session state decides
/// which turn still streams, and the display mode decides which rows survive.
#[derive(Clone, PartialEq, Eq)]
struct ChildAgentTurnsKey {
    content: ChildAgentProjectionKey,
    session_state: Option<AgentSessionState>,
    pending_turn_active: bool,
    reasoning_display_mode: ReasoningDisplayMode,
}

/// Which half of a child Agent's projection a caller reads.
///
/// The rail renders turns and only falls back to rows when there is no turn to
/// show; a delegation card's preview renders the newest rows and never looks at
/// turns.
#[derive(Clone, Copy, PartialEq, Eq)]
enum ChildAgentSnapshotParts {
    Rows,
    Turns,
}

impl ChildAgentTimelineState {
    fn new(session_id: VibexSessionId) -> Self {
        let mut timeline = TimelineModel::default();
        timeline.replace_authoritative(session_id, std::iter::empty());
        Self {
            session: None,
            timeline,
            loaded: false,
            loading: false,
            error: None,
            load_generation: 0,
            projection: ChildAgentProjection::default(),
        }
    }

    fn projection_key(&self) -> ChildAgentProjectionKey {
        ChildAgentProjectionKey {
            revision: self.timeline.revision,
            item_count: self.timeline.items.len(),
            end_sequence: self.timeline.authoritative_end_sequence,
        }
    }

    fn turns_key(&self, reasoning_display_mode: ReasoningDisplayMode) -> ChildAgentTurnsKey {
        let session_state = self.session.as_ref().map(|session| session.state);
        ChildAgentTurnsKey {
            content: self.projection_key(),
            session_state,
            pending_turn_active: matches!(session_state, Some(AgentSessionState::Running)),
            reasoning_display_mode,
        }
    }

    /// The child's rows, folded once per content change.
    fn rows_projection(&mut self) -> Rc<Vec<ChildAgentTimelineRowProjection>> {
        let key = self.projection_key();
        if let Some((cached_key, rows)) = self.projection.rows.as_ref()
            && *cached_key == key
        {
            return rows.clone();
        }
        let rows = Rc::new(
            self.timeline
                .rows()
                .into_iter()
                .map(|row| ChildAgentTimelineRowProjection {
                    delegation: timeline_row_delegation(&row, &self.timeline.items),
                    row,
                })
                .collect::<Vec<_>>(),
        );
        self.projection.rows = Some((key, rows.clone()));
        rows
    }

    /// The child's turns, projected once per content, state or display change.
    fn turns_projection(
        &mut self,
        reasoning_display_mode: ReasoningDisplayMode,
    ) -> Rc<Vec<Rc<TimelineConversationTurn>>> {
        let key = self.turns_key(reasoning_display_mode);
        if let Some((cached_key, turns)) = self.projection.turns.as_ref()
            && *cached_key == key
        {
            return turns.clone();
        }
        let turns = Rc::new(
            timeline_conversation_turns_with_reasoning_mode(
                &self.timeline.items,
                key.session_state,
                key.pending_turn_active,
                key.reasoning_display_mode,
            )
            .into_iter()
            .map(Rc::new)
            .collect::<Vec<_>>(),
        );
        self.projection.turns = Some((key, turns.clone()));
        turns
    }
}

/// Reads one child Agent session as the caller asked for it.
///
/// Only [`ChildAgentSnapshotParts::Rows`] or [`ChildAgentSnapshotParts::Turns`]
/// is projected; the other half is handed back empty. A caller that renders
/// turns — the rail, on every frame — must not pay for the row fold it never
/// reads, and a delegation preview must not pay for the turn projection.
fn child_agent_snapshot_from_state(
    state: &mut ChildAgentTimelineState,
    parts: ChildAgentSnapshotParts,
    reasoning_display_mode: ReasoningDisplayMode,
) -> ChildAgentTimelineSnapshot {
    let (rows, turns) = match parts {
        ChildAgentSnapshotParts::Rows => (state.rows_projection(), Rc::new(Vec::new())),
        ChildAgentSnapshotParts::Turns => (
            Rc::new(Vec::new()),
            state.turns_projection(reasoning_display_mode),
        ),
    };
    ChildAgentTimelineSnapshot {
        loading: state.loading,
        loaded: state.loaded,
        error: state.error.clone(),
        revision: state.timeline.revision,
        rows,
        turns,
    }
}

#[derive(Clone)]
struct ChildAgentTimelineRowProjection {
    row: TimelineRow,
    delegation: Option<TimelineDelegationProjection>,
}

struct ChildAgentTimelineSnapshot {
    loading: bool,
    loaded: bool,
    error: Option<String>,
    /// The timeline revision the turns were projected from.
    ///
    /// The rail remeasures its virtual rows when this moves, so a streamed
    /// body that grew without changing the turn count is still laid out at its
    /// new height.
    revision: u64,
    /// Empty unless the caller asked for rows.
    rows: Rc<Vec<ChildAgentTimelineRowProjection>>,
    /// Empty unless the caller asked for turns; shared with the cache, so a
    /// frame that changed nothing does not copy the child's conversation.
    turns: Rc<Vec<Rc<TimelineConversationTurn>>>,
}

impl TimelineItemIndex {
    fn is_current_for(&self, timeline: &TimelineModel) -> bool {
        self.session_id.as_ref() == timeline.session_id.as_ref()
            && self.revision == timeline.revision
            && self.item_count == timeline.items.len()
            && self.end_sequence == timeline.authoritative_end_sequence
    }

    fn rebuild(&mut self, timeline: &TimelineModel) {
        self.session_id = timeline.session_id.clone();
        self.revision = timeline.revision;
        self.item_count = timeline.items.len();
        self.end_sequence = timeline.authoritative_end_sequence;
        self.positions.clear();
        self.positions.reserve(timeline.items.len());
        // Items are ordered by sequence, so a later write always wins the id.
        for (position, item) in timeline.items.iter().enumerate() {
            self.positions.insert(item.id.to_string(), position);
        }
    }

    fn sync(&mut self, timeline: &TimelineModel) {
        if self.is_current_for(timeline) {
            return;
        }

        let append_only = self.session_id.as_ref() == timeline.session_id.as_ref()
            && self.item_count < timeline.items.len()
            && (self.item_count == 0
                || timeline.items.get(self.item_count - 1).is_some_and(|item| {
                    Some(item.sequence) == self.end_sequence
                        && self.positions.get(item.id.as_str()) == Some(&(self.item_count - 1))
                }));
        if !append_only {
            self.rebuild(timeline);
            return;
        }

        self.positions
            .reserve(timeline.items.len().saturating_sub(self.item_count));
        for (position, item) in timeline.items.iter().enumerate().skip(self.item_count) {
            self.positions.insert(item.id.to_string(), position);
        }
        self.revision = timeline.revision;
        self.item_count = timeline.items.len();
        self.end_sequence = timeline.authoritative_end_sequence;
    }

    fn invalidate(&mut self) {
        *self = Self::default();
    }
}

#[derive(Clone, Copy, Default)]
struct ConversationTurnsSummary {
    has_incomplete_turn: bool,
    has_pending_permission: bool,
}

impl ConversationTurnsSummary {
    fn from_turns<T>(turns: &[T]) -> Self
    where
        T: std::borrow::Borrow<TimelineConversationTurn>,
    {
        Self {
            has_incomplete_turn: turns.iter().any(|turn| !turn.borrow().complete),
            has_pending_permission: turns.iter().any(|turn| turn.borrow().pending_permission),
        }
    }

    /// The summary of a projection whose leading turn may still be arriving.
    ///
    /// A turn that is missing its own first row is being read, not working: the
    /// rows still to come are older than the ones on screen. Reporting it as an
    /// incomplete turn would keep the duration ticker alive for a header that no
    /// longer shows a duration, and every tick it asks for is a repaint that
    /// cannot move anything.
    fn from_turns_after_leading<T>(turns: &[T], leading_still_arriving: bool) -> Self
    where
        T: std::borrow::Borrow<TimelineConversationTurn>,
    {
        let mut summary = Self::from_turns(turns);
        if leading_still_arriving && summary.has_incomplete_turn {
            summary.has_incomplete_turn = turns
                .get(1..)
                .is_some_and(|rest| rest.iter().any(|turn| !turn.borrow().complete));
        }
        summary
    }
}

/// Where the permission alert has to scroll to reach the request it names.
struct PendingPermissionRevealTarget {
    turn_id: String,
    turn_index: usize,
    item_id: String,
}

/// Every piece of state that belongs to one session's conversation view.
///
/// A session view is a *complete*, independently owned unit: the timeline and
/// its derived caches, the scroll and measurement state, the runtime selection,
/// the streaming bookkeeping and the reader's expansion choices. Nothing that
/// one session's view needs is allowed to live outside this struct, because
/// anything left outside is shared with every other session and is therefore
/// clobbered as soon as two views are on screen at once.
///
/// A group workspace keeps one live view per pane, and every session that is
/// selected, grouped or opened as a child Agent keeps its own view. Views are
/// stored in [`VibexWorkbench::session_views`]; `VibexWorkbench::view` holds the
/// one that is currently borrowed for rendering or mutation, and
/// `VibexWorkbench::view_session_id` names it. Rendering a group pane borrows
/// that pane's view, renders it, and hands it back — the state never leaves the
/// store, so no pane can observe or destroy another pane's view.
///
/// `VibexWorkbench` derefs to `SessionView`, so `self.timeline` (and every
/// other field below) resolves to the currently borrowed view. That keeps the
/// ~600 existing field accesses honest: they always mean "the view being
/// rendered", which is exactly what the renderer wants.
pub struct SessionView {
    timeline: TimelineModel,
    runtime_selection: Option<AgentSessionRuntimeSelectionState>,
    token_usage: Option<AgentTokenUsage>,
    agent_generation_stats: Option<AgentGenerationStats>,
    agent_loading: bool,
    agent_error: Option<String>,
    agent_turn_pending: bool,
    pending_user_message_edit: Option<PendingUserMessageEdit>,
    inline_user_message_edit: Option<InlineUserMessageEdit>,
    turn_preview_rail_visible: bool,
    turn_preview_active_index: Option<usize>,
    timeline_item_index: RefCell<TimelineItemIndex>,
    timeline_follow: TimelineFollowState,
    timeline_scroll: VirtualListScrollHandle,
    /// Whether the backend reported history below this view's oldest item.
    ///
    /// Per view, because it describes the window that view holds rather than
    /// the session in the abstract.
    timeline_has_older: bool,
    /// Whether this view's oldest row sits inside a conversational turn.
    ///
    /// A read looks for a turn boundary for the end of a page, so this is only
    /// true while that turn is too long to be handed over in one page: the rows
    /// still to come are older than the ones on screen, and the turn's own
    /// header — when it started, how long it worked — would move under the
    /// reader as they arrive. The leading turn reads as loading until its first
    /// row is here, and only then does it show a duration.
    timeline_starts_mid_turn: bool,
    /// How many older pages this view has outstanding.
    timeline_older_in_flight: usize,
    /// Row ids whose tool detail is being read back right now.
    ///
    /// There is no "already applied" set beside it: an item that carries a
    /// complete payload is its own record, so a refresh that replaces it with
    /// a summary asks for the detail again instead of trusting a stale note.
    timeline_detail_in_flight: BTreeSet<String>,
    timeline_scroll_to_latest_pending: bool,
    timeline_scroll_anchor_pending: bool,
    timeline_list_padding_top_px: f32,
    timeline_scroll_wheel_idle_task: Option<Task<()>>,
    timeline_bottom_control_visible: bool,
    timeline_bottom_control_mounted: bool,
    timeline_bottom_control_close_task: Option<Task<()>>,
    timeline_duration_tick_task: Option<Task<()>>,
    timeline_scrollbar_interaction_active: bool,
    timeline_row_sizes: Rc<Vec<Size<gpui::Pixels>>>,
    /// The timeline revision [`Self::timeline_row_sizes`] was built for.
    ///
    /// A parked view is not rendered, so a projection replaced while it was
    /// parked leaves extents that describe the conversation as it stood then.
    /// Comparing the stamp against the live revision is what tells a restore its
    /// table is stale before the first frame clamps the scroll offset to it.
    timeline_row_sizes_revision: u64,
    timeline_measured_turn_heights: BTreeMap<String, f32>,
    timeline_measured_turn_layout_signatures: BTreeMap<String, u64>,
    timeline_streaming_shrink_candidates: BTreeMap<String, StreamingShrinkCandidate>,
    timeline_pending_turn_heights: BTreeMap<usize, (String, f32)>,
    timeline_estimated_turn_heights: BTreeMap<String, (u64, f32)>,
    timeline_turn_layout_signature_cache: BTreeMap<String, (u64, u64)>,
    timeline_process_unit_heights: BTreeMap<String, TimelineProcessUnitHeight>,
    /// The process-unit walk of each turn, keyed by turn id and stamped with the
    /// fingerprint of the inputs the walk read.
    ///
    /// The walk is O(process_rows) and mints a unit — and its id string — for
    /// every row or collapsed group, while the renderer and the height estimator
    /// each ask for it on every frame the turn is painted. A turn holding a
    /// whole session's work therefore rebuilt the same units twice per frame for
    /// a shape that had not moved. The units are a pure function of the turn's
    /// rows and the view's display state, so they are retained between frames
    /// and rebuilt only when that fingerprint moves.
    timeline_process_units_cache: BTreeMap<String, (u64, Rc<Vec<TimelineProcessUnit>>)>,
    /// Measured heights of the rows inside an expanded process group, keyed by
    /// row id. SPIKE: windowing the group body keeps the rows it did not build,
    /// and this is the table the next frame places them from. See
    /// [`timeline_group_body`].
    timeline_group_row_heights: BTreeMap<String, TimelineGroupRowHeight>,
    /// SPIKE: the group-body rows the last frames built, in build order.
    ///
    /// Records which rows the window chose, so a test can assert the body
    /// stopped building every row and still builds the ones the viewport shows.
    #[cfg(test)]
    timeline_group_rows_built: Vec<usize>,
    timeline_disclosure_animating: bool,
    timeline_load_updates: std::rc::Weak<RefCell<timeline_loading::TimelineLoadUpdates>>,
    timeline_layout_width: Option<f32>,
    timeline_markdown_sources: BTreeMap<String, (i64, TimelineMarkdownSourceSnapshot)>,
    /// The retained text-view state of every Markdown surface the borrowed
    /// view's own timeline has rendered, keyed by view id. Rendering itself
    /// belongs to the gpui-component text view; this only keeps the parse, the
    /// selection and the find-bar highlights alive across frames.
    ///
    /// The child Agent rail paints another session's timeline while this view is
    /// borrowed, so its surfaces are kept in
    /// [`VibexWorkbench::child_agent_markdown_states`] instead. See
    /// [`MarkdownSurfaceOwner`].
    markdown_text_states: BTreeMap<String, MarkdownTextState>,
    timeline_reasoning_summaries: BTreeMap<String, (i64, TimelineReasoningSummarySnapshot)>,
    timeline_tool_card_projections: BTreeMap<String, (i64, Rc<ToolCardProjection>)>,
    timeline_activity_projections: BTreeMap<String, (i64, CachedActivityProjection)>,
    timeline_file_diff_previews: BTreeMap<String, (i64, Rc<AgentFileDiffPreview>)>,
    timeline_file_diff_scrolls: BTreeMap<String, gpui::ScrollHandle>,
    timeline_turn_file_changes: BTreeMap<String, (i64, Rc<TurnFileChangesSummary>)>,
    conversation_turns_cache: Rc<Vec<Rc<TimelineConversationTurn>>>,
    conversation_turns_render_cache: Rc<RefCell<Rc<Vec<Rc<TimelineConversationTurn>>>>>,
    conversation_turns_cache_key: Option<ConversationTurnsCacheKey>,
    conversation_turns_summary: ConversationTurnsSummary,
    streaming_row_state: Option<StreamingRowStateCache>,
    content_width: SessionContentWidthMode,
    collapsed_timeline_rows: BTreeSet<String>,
    reasoning_expansion: BTreeMap<String, bool>,
    /// Rows whose settled body the reader asked to see whole.
    ///
    /// A long settled body is drawn as its head; this is the per-row override,
    /// kept for the view's life like every other disclosure the reader made.
    timeline_body_reveal: BTreeMap<String, bool>,
    /// Where a visible settled body is cut for the folded shape, by revision.
    ///
    /// The cut scans the body's head — a few kilobytes at most — but a body on
    /// screen asks for it every frame, so the row's revision is what keeps that
    /// scan off the frame path.
    timeline_body_folds: BTreeMap<String, (i64, TimelineBodyFold)>,
    /// Where each windowed body's chunks are and how tall the window found
    /// them, by row revision.
    timeline_body_windows: BTreeMap<String, (i64, Rc<TimelineBodyWindow>)>,
    timeline_process_expansion: BTreeMap<String, bool>,
    timeline_command_expansion: BTreeMap<String, bool>,
    timeline_file_changes_expansion: BTreeMap<String, bool>,
    composer_input: Option<Entity<TextareaState>>,
    composer_attachments: Vec<InlineComposerAttachment>,
    composer_attachment_serial: u64,
    composer_command_entry: Option<AgentCommandEntry>,
    suggestions: Vec<AgentCommandEntry>,
    /// Reusable Prompts offered by the `/` popup's quick-phrase tab.
    ///
    /// Both lists arrive from one discovery request, so switching tabs stays
    /// local and behaves the same against a paired authority as against the
    /// native one.
    phrase_suggestions: Vec<AgentCommandEntry>,
    /// Collaborators and conversations offered by the `@` popup's delegation
    /// tab, fetched beside the workspace files of `suggestions`.
    delegation_suggestions: Vec<AgentCommandEntry>,
    suggestion_tab: ComposerSuggestionTab,
    suggestion_selection: ComposerSuggestionSelection,
    /// Which half of the selected delegation row owns Enter.
    suggestion_delegation_action: ComposerDelegationAction,
    /// Scrolls the popup's rows so a keyboard selection past the viewport
    /// stays visible; the list can hold more than the ten-row window.
    suggestion_scroll: ScrollHandle,
    suggestion_context: Option<ComposerSuggestionContext>,
    suggestion_loading: bool,
    suggestion_request_serial: u64,
    composer_history: ComposerHistoryState,
    composer_expanded: bool,
    composer_goal_editing: bool,
    composer_plan_expanded: Option<ComposerPlanIdentity>,
    dismissed_composer_plans: BTreeSet<ComposerPlanIdentity>,
    attachment_image_preview: Option<AttachmentImagePreviewState>,
    composer_queue_editing_id: Option<u64>,
    composer_queue_edit_attachments: Vec<InlineComposerAttachment>,
    composer_queue_edit_geometry: ComposerGeometry,
    /// The queued message being rewritten inside the Composer input itself.
    ///
    /// Set only when the edit started with an empty Composer, so the queued
    /// text could be loaded there instead of an inline row editor.
    composer_queue_edit_in_composer: Option<ComposerQueueEditInComposer>,
    /// Where this view's Composer was painted last frame.
    ///
    /// The geometry belongs to the view rather than to the workbench because a
    /// split paints one Composer per pane. Held globally, every pane's
    /// prepaint overwrote it and the surface that anchors to it — the command
    /// menu, the runtime cascade — opened over whichever pane happened to be
    /// painted last. A view keeps its own bounds, so a pane's menu lands on the
    /// pane that owns it; the root overlay reads the borrowed view, which the
    /// workspace leaves pointed at the selected (focused) pane.
    composer_geometry: ComposerGeometry,
    composer_queue_drop_target: Option<ComposerQueueDropTarget>,
    composer_terminals: Vec<TerminalSession>,
    selected_composer_terminal_id: Option<TerminalId>,
    composer_terminal_mode: bool,
    /// The Composer's bottom terminal panel is asked for. It stays true while
    /// the panel's close transition plays, so `mounted` is the flag the render
    /// path reads.
    composer_terminal_panel_open: bool,
    /// The bottom terminal panel is in the element tree. It outlives `open` by
    /// one transition so the input can be lowered back down smoothly.
    composer_terminal_panel_mounted: bool,
    composer_terminal_panel_close_task: Option<Task<()>>,
    composer_terminal_expanded: bool,
    composer_terminal_height: f32,
    composer_terminal_resize_drag: Option<ComposerTerminalResizeDragState>,
    composer_terminal_drop_target: Option<ComposerTerminalDropTarget>,
    composer_terminal_surfaces: BTreeMap<String, Entity<TerminalSurface>>,
    active_composer_terminal_surface_id: Option<String>,
    suggestion_task: Option<Task<()>>,
    /// Owns this view's keystrokes, IME state and draft, so a pane cannot
    /// type into another session's composer.
    composer_subscription: Option<Subscription>,
    /// The last [`Self::calculate_estimated_resident_bytes`] result, refreshed
    /// whenever the view is stored back into the session-view cache.
    ///
    /// A view sitting in that cache is not being mutated, so its footprint can
    /// only change while it is borrowed. Refreshing the estimate on store keeps
    /// the cache's byte budget exact while letting the eviction pass sum cached
    /// numbers instead of re-walking every stored view's timeline.
    resident_bytes: usize,
}

impl SessionView {
    fn new(content_width: SessionContentWidthMode) -> Self {
        Self {
            timeline: TimelineModel::default(),
            runtime_selection: None,
            token_usage: None,
            agent_generation_stats: None,
            agent_loading: true,
            agent_error: None,
            agent_turn_pending: false,
            pending_user_message_edit: None,
            inline_user_message_edit: None,
            turn_preview_rail_visible: false,
            turn_preview_active_index: None,
            timeline_item_index: RefCell::new(TimelineItemIndex::default()),
            timeline_follow: TimelineFollowState::default(),
            timeline_scroll: VirtualListScrollHandle::new(),
            timeline_has_older: false,
            timeline_starts_mid_turn: false,
            timeline_older_in_flight: 0,
            timeline_detail_in_flight: BTreeSet::new(),
            timeline_scroll_to_latest_pending: false,
            timeline_scroll_anchor_pending: false,
            timeline_list_padding_top_px: AGENT_TIMELINE_LIST_PADDING_TOP_PX,
            timeline_scroll_wheel_idle_task: None,
            timeline_bottom_control_visible: false,
            timeline_bottom_control_mounted: false,
            timeline_bottom_control_close_task: None,
            timeline_duration_tick_task: None,
            timeline_scrollbar_interaction_active: false,
            timeline_row_sizes: Rc::new(Vec::new()),
            timeline_row_sizes_revision: 0,
            timeline_measured_turn_heights: BTreeMap::new(),
            timeline_measured_turn_layout_signatures: BTreeMap::new(),
            timeline_streaming_shrink_candidates: BTreeMap::new(),
            timeline_pending_turn_heights: BTreeMap::new(),
            timeline_estimated_turn_heights: BTreeMap::new(),
            timeline_turn_layout_signature_cache: BTreeMap::new(),
            timeline_process_unit_heights: BTreeMap::new(),
            timeline_process_units_cache: BTreeMap::new(),
            timeline_group_row_heights: BTreeMap::new(),
            #[cfg(test)]
            timeline_group_rows_built: Vec::new(),
            timeline_disclosure_animating: false,
            timeline_load_updates: Default::default(),
            timeline_layout_width: None,
            timeline_markdown_sources: BTreeMap::new(),
            markdown_text_states: BTreeMap::new(),
            timeline_reasoning_summaries: BTreeMap::new(),
            timeline_tool_card_projections: BTreeMap::new(),
            timeline_activity_projections: BTreeMap::new(),
            timeline_file_diff_previews: BTreeMap::new(),
            timeline_file_diff_scrolls: BTreeMap::new(),
            timeline_turn_file_changes: BTreeMap::new(),
            conversation_turns_cache: Rc::new(Vec::new()),
            conversation_turns_render_cache: Rc::new(RefCell::new(Rc::new(Vec::new()))),
            conversation_turns_cache_key: None,
            conversation_turns_summary: ConversationTurnsSummary::default(),
            streaming_row_state: None,
            content_width,
            collapsed_timeline_rows: BTreeSet::new(),
            reasoning_expansion: BTreeMap::new(),
            timeline_body_reveal: BTreeMap::new(),
            timeline_body_folds: BTreeMap::new(),
            timeline_body_windows: BTreeMap::new(),
            timeline_process_expansion: BTreeMap::new(),
            timeline_command_expansion: BTreeMap::new(),
            timeline_file_changes_expansion: BTreeMap::new(),
            composer_input: None,
            composer_attachments: Vec::new(),
            composer_attachment_serial: 0,
            composer_command_entry: None,
            suggestions: Vec::new(),
            phrase_suggestions: Vec::new(),
            delegation_suggestions: Vec::new(),
            suggestion_tab: ComposerSuggestionTab::default(),
            suggestion_selection: ComposerSuggestionSelection::default(),
            suggestion_delegation_action: ComposerDelegationAction::default(),
            suggestion_scroll: ScrollHandle::new(),
            suggestion_context: None,
            suggestion_loading: false,
            suggestion_request_serial: 0,
            suggestion_task: None,
            composer_history: ComposerHistoryState::default(),
            composer_expanded: false,
            composer_goal_editing: false,
            composer_plan_expanded: None,
            dismissed_composer_plans: BTreeSet::new(),
            attachment_image_preview: None,
            composer_queue_editing_id: None,
            composer_queue_edit_attachments: Vec::new(),
            composer_queue_edit_geometry: ComposerGeometry::default(),
            composer_queue_edit_in_composer: None,
            composer_queue_drop_target: None,
            composer_geometry: ComposerGeometry::default(),
            composer_terminals: Vec::new(),
            selected_composer_terminal_id: None,
            composer_terminal_mode: false,
            composer_terminal_panel_open: false,
            composer_terminal_panel_mounted: false,
            composer_terminal_panel_close_task: None,
            composer_terminal_expanded: false,
            composer_terminal_height: COMPOSER_TERMINAL_DEFAULT_HEIGHT_PX,
            composer_terminal_resize_drag: None,
            composer_terminal_drop_target: None,
            composer_terminal_surfaces: BTreeMap::new(),
            active_composer_terminal_surface_id: None,
            composer_subscription: None,
            resident_bytes: 0,
        }
    }

    fn scroll_timeline_to_latest(&self) {
        if !self.timeline_row_sizes.is_empty() {
            // VirtualList clamps this offset to its freshly laid-out viewport
            // before placing rows. The base handle's deferred scroll_to_bottom
            // runs after the list snapshots its offset, painting one frame at
            // the old position while the scrollbar already shows the new one.
            let content_height = self
                .timeline_row_sizes
                .iter()
                .map(|row| row.height)
                .sum::<Pixels>();
            self.timeline_scroll
                .set_offset(point(px(0.0), -content_height));
        }
    }

    fn set_reasoning_expanded(&mut self, row_id: String, turn_id: Option<&str>, expanded: bool) {
        // A click changes one disclosure, not the contents of the turn. Keep
        // measured geometry as the seed for prepaint, including offscreen
        // process units: replacing it with estimates moves unrelated history.
        if let Some(height) = self.timeline_process_unit_heights.get_mut(&row_id) {
            height.layout_invalidated = true;
        }
        self.reasoning_expansion.insert(row_id, expanded);
        if let Some(turn_id) = turn_id {
            self.timeline_measured_turn_layout_signatures
                .remove(turn_id);
            self.timeline_turn_layout_signature_cache.remove(turn_id);
            self.timeline_streaming_shrink_candidates.remove(turn_id);
            self.timeline_estimated_turn_heights.remove(turn_id);
            self.timeline_pending_turn_heights
                .retain(|_, (pending_turn_id, _)| pending_turn_id != turn_id);
        }
    }

    /// Forgets every derived projection so the next render rebuilds it from
    /// `timeline`. Used when a view adopts a new authoritative timeline.
    fn invalidate_render_caches(&mut self) {
        self.timeline_row_sizes = Rc::new(Vec::new());
        self.timeline_measured_turn_heights.clear();
        self.timeline_measured_turn_layout_signatures.clear();
        self.timeline_estimated_turn_heights.clear();
        self.timeline_turn_layout_signature_cache.clear();
        self.timeline_process_unit_heights.clear();
        self.timeline_process_units_cache.clear();
        self.timeline_group_row_heights.clear();
        self.timeline_pending_turn_heights.clear();
        self.conversation_turns_cache = Rc::new(Vec::new());
        self.conversation_turns_cache_key = None;
        self.conversation_turns_summary = ConversationTurnsSummary::default();
        self.streaming_row_state = None;
        *self.conversation_turns_render_cache.borrow_mut() = Rc::new(Vec::new());
        self.timeline_streaming_shrink_candidates.clear();
        self.timeline_markdown_sources.clear();
        self.timeline_body_folds.clear();
        self.timeline_body_windows.clear();
        self.markdown_text_states.clear();
        self.timeline_reasoning_summaries.clear();
        self.timeline_tool_card_projections.clear();
        self.timeline_activity_projections.clear();
        self.timeline_file_diff_previews.clear();
        self.timeline_file_diff_scrolls.clear();
        self.timeline_turn_file_changes.clear();
        self.timeline_item_index.get_mut().invalidate();
    }

    fn calculate_estimated_resident_bytes(&self) -> usize {
        timeline_items_resident_bytes(&self.timeline.items)
            .saturating_add(
                self.conversation_turns_cache
                    .iter()
                    .map(|turn| timeline_conversation_turn_resident_bytes(turn))
                    .fold(0_usize, usize::saturating_add),
            )
            .saturating_add(
                self.timeline_row_sizes.len() * std::mem::size_of::<Size<gpui::Pixels>>(),
            )
            .saturating_add(
                self.timeline_measured_turn_heights
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_measured_turn_layout_signatures
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_estimated_turn_heights
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.collapsed_timeline_rows
                    .iter()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.reasoning_expansion
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_body_reveal
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_body_folds
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_body_windows
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_process_expansion
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_command_expansion
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_file_changes_expansion
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
            .saturating_add(
                self.timeline_process_units_cache
                    .keys()
                    .map(String::len)
                    .sum::<usize>(),
            )
    }
}

fn goal_phase_label(phase: GoalPhase) -> String {
    match phase {
        GoalPhase::Active => locale::text("Active", "进行中", "進行中").to_string(),
        GoalPhase::Paused => locale::text("Paused", "已暂停", "已暫停").to_string(),
        GoalPhase::Blocked => locale::text("Blocked", "已阻塞", "已阻塞").to_string(),
        GoalPhase::UsageLimited => {
            locale::text("Usage limited", "额度受限", "額度受限").to_string()
        }
        GoalPhase::BudgetLimited => {
            locale::text("Budget limited", "预算耗尽", "預算耗盡").to_string()
        }
        GoalPhase::Complete => locale::text("Complete", "已完成", "已完成").to_string(),
        GoalPhase::Unknown => locale::text("Unknown", "未知", "未知").to_string(),
    }
}

fn format_goal_duration(seconds: i64) -> String {
    if seconds < 60 {
        return format!("{seconds}s");
    }
    let minutes = seconds / 60;
    if minutes < 60 {
        return format!("{minutes}m");
    }
    format!("{}h", minutes / 60)
}

fn timeline_items_resident_bytes(items: &[TimelineItem]) -> usize {
    items
        .iter()
        .map(timeline_item_resident_bytes)
        .fold(0_usize, usize::saturating_add)
}

fn timeline_item_resident_bytes(item: &TimelineItem) -> usize {
    let option_len = |value: &Option<String>| value.as_ref().map_or(0, String::len);
    let raw_extension_len = |extension: &Option<vibex_core::AgentEventRawExtension>| {
        extension.as_ref().map_or(0, |extension| {
            extension
                .content_blocks
                .iter()
                .map(|block| block.block_type.len().saturating_add(block.summary.len()))
                .chain(extension.raw_input.iter().map(String::len))
                .chain(extension.raw_output.iter().map(|output| output.text.len()))
                .chain(
                    extension
                        .locations
                        .iter()
                        .map(|location| location.uri.len()),
                )
                .chain(
                    extension
                        .meta
                        .iter()
                        .map(|(key, value)| key.len().saturating_add(value.len())),
                )
                .fold(0_usize, usize::saturating_add)
        })
    };
    let payload_bytes = match &item.payload {
        TimelinePayload::UserMessage(message) => message.text.len().saturating_add(
            message
                .attachments
                .iter()
                .map(|attachment| {
                    attachment
                        .label
                        .len()
                        .saturating_add(option_len(&attachment.mime_type))
                        .saturating_add(option_len(&attachment.uri))
                })
                .sum::<usize>(),
        ),
        TimelinePayload::AgentMessageDelta(delta) => delta.text_delta.len(),
        TimelinePayload::AgentMessage(message) => message.text.len(),
        TimelinePayload::Reasoning(reasoning) => reasoning.text.len(),
        TimelinePayload::Plan(plan) => plan.title.len().saturating_add(
            plan.steps
                .iter()
                .map(|step| step.title.len())
                .sum::<usize>(),
        ),
        TimelinePayload::Goal(goal) => goal
            .goal
            .as_ref()
            .map(|snapshot| {
                snapshot.objective.len().saturating_add(
                    snapshot
                        .blocked_reason
                        .as_ref()
                        .map(|reason| reason.message.len())
                        .unwrap_or_default(),
                )
            })
            .unwrap_or_default()
            .saturating_add(goal.message.as_deref().map(str::len).unwrap_or_default()),
        TimelinePayload::ToolCall(tool) => tool
            .tool_call_id
            .len()
            .saturating_add(tool.tool_name.len())
            .saturating_add(tool.summary.len())
            .saturating_add(option_len(&tool.input_summary))
            .saturating_add(option_len(&tool.output_summary))
            .saturating_add(raw_extension_len(&tool.raw_extension)),
        TimelinePayload::Command(command) => command
            .command
            .len()
            .saturating_add(option_len(&command.cwd))
            .saturating_add(option_len(&command.output_summary))
            .saturating_add(raw_extension_len(&command.raw_extension)),
        TimelinePayload::FileOperation(operation) => operation
            .path
            .len()
            .saturating_add(operation.summary.len())
            .saturating_add(option_len(&operation.old_text))
            .saturating_add(option_len(&operation.new_text))
            .saturating_add(operation.patch.as_ref().map_or(0, |patch| patch.text.len()))
            .saturating_add(raw_extension_len(&operation.raw_extension)),
        TimelinePayload::WebSearch(search) => search
            .query
            .len()
            .saturating_add(option_len(&search.result_summary))
            .saturating_add(raw_extension_len(&search.raw_extension)),
        TimelinePayload::TodoUpdate(todo) => todo
            .title
            .len()
            .saturating_add(
                todo.items
                    .iter()
                    .map(|item| item.title.len())
                    .sum::<usize>(),
            )
            .saturating_add(raw_extension_len(&todo.raw_extension)),
        TimelinePayload::Collaboration(collaboration) => collaboration
            .action
            .len()
            .saturating_add(collaboration.summary.len())
            .saturating_add(option_len(&collaboration.agent_label))
            .saturating_add(raw_extension_len(&collaboration.raw_extension)),
        TimelinePayload::ImageGeneration(image) => image
            .summary
            .len()
            .saturating_add(option_len(&image.mime_type))
            .saturating_add(option_len(&image.image_reference))
            .saturating_add(raw_extension_len(&image.raw_extension)),
        TimelinePayload::GitNotice(notice) => notice.summary.len(),
        TimelinePayload::SystemNotice(notice) => notice.message.len(),
        TimelinePayload::PermissionRequest(request) => request
            .id
            .as_str()
            .len()
            .saturating_add(request.session_id.as_str().len())
            .saturating_add(
                request
                    .project_id
                    .as_ref()
                    .map_or(0, |id| id.as_str().len()),
            )
            .saturating_add(
                request
                    .workspace_id
                    .as_ref()
                    .map_or(0, |id| id.as_str().len()),
            )
            .saturating_add(option_len(&request.provider_request_id))
            .saturating_add(request.title.len())
            .saturating_add(
                request
                    .details
                    .iter()
                    .map(|detail| detail.label.len().saturating_add(detail.value.len()))
                    .sum::<usize>(),
            ),
        TimelinePayload::PermissionResolution(resolution) => resolution
            .request_id
            .as_str()
            .len()
            .saturating_add(resolution.session_id.as_str().len())
            .saturating_add(
                resolution
                    .responder_device_id
                    .as_ref()
                    .map_or(0, |id| id.as_str().len()),
            )
            .saturating_add(option_len(&resolution.provider_resolution_id))
            .saturating_add(option_len(&resolution.note)),
        TimelinePayload::ElicitationRequest(request) => request
            .id
            .as_str()
            .len()
            .saturating_add(request.session_id.as_str().len())
            .saturating_add(option_len(&request.provider_request_id))
            .saturating_add(option_len(&request.tool_call_id))
            .saturating_add(request.message.len())
            .saturating_add(option_len(&request.title))
            .saturating_add(option_len(&request.description))
            .saturating_add(
                request
                    .fields
                    .iter()
                    .map(|field| {
                        field
                            .id
                            .len()
                            .saturating_add(field.title.len())
                            .saturating_add(option_len(&field.description))
                            .saturating_add(elicitation_field_kind_resident_bytes(&field.kind))
                    })
                    .sum::<usize>(),
            ),
        TimelinePayload::ElicitationResolution(resolution) => resolution
            .request_id
            .as_str()
            .len()
            .saturating_add(resolution.session_id.as_str().len())
            .saturating_add(
                resolution
                    .answers
                    .iter()
                    .map(|(field_id, answer)| {
                        field_id
                            .len()
                            .saturating_add(elicitation_answer_resident_bytes(answer))
                    })
                    .sum::<usize>(),
            )
            .saturating_add(
                resolution
                    .responder_device_id
                    .as_ref()
                    .map_or(0, |id| id.as_str().len()),
            ),
        TimelinePayload::Retry(retry) => retry
            .reason
            .as_ref()
            .map_or(0, String::len)
            .saturating_add(retry.attempt.map_or(0, |value| value.to_string().len()))
            .saturating_add(
                retry
                    .max_attempts
                    .map_or(0, |value| value.to_string().len()),
            ),
        TimelinePayload::Error(error) => error.code.len().saturating_add(error.message.len()),
    };
    std::mem::size_of::<TimelineItem>()
        .saturating_add(item.id.as_str().len())
        .saturating_add(item.session_id.as_str().len())
        .saturating_add(
            item.correlation_id
                .as_ref()
                .map_or(0, |id| id.as_str().len()),
        )
        .saturating_add(option_len(&item.provider_correlation_id))
        .saturating_add(
            item.execution_attribution
                .as_ref()
                .map_or(0, |attribution| {
                    attribution
                        .agent_label
                        .len()
                        .saturating_add(attribution.auth_source_label.len())
                        .saturating_add(attribution.model_label.len())
                }),
        )
        .saturating_add(payload_bytes)
}

fn elicitation_field_kind_resident_bytes(kind: &ElicitationFieldKind) -> usize {
    let option_string_len = |value: &Option<String>| value.as_ref().map_or(0, String::len);
    let option_bytes = |options: &[vibex_core::ElicitationOption]| {
        options
            .iter()
            .map(|option| {
                option
                    .value
                    .len()
                    .saturating_add(option.title.len())
                    .saturating_add(option_string_len(&option.description))
            })
            .sum::<usize>()
    };
    match kind {
        ElicitationFieldKind::Text {
            pattern,
            default,
            options,
            ..
        } => option_string_len(pattern)
            .saturating_add(option_string_len(default))
            .saturating_add(option_bytes(options)),
        ElicitationFieldKind::Number {
            minimum,
            maximum,
            default,
        } => option_string_len(minimum)
            .saturating_add(option_string_len(maximum))
            .saturating_add(option_string_len(default)),
        ElicitationFieldKind::Integer { .. } => 0,
        ElicitationFieldKind::Boolean { .. } => 0,
        ElicitationFieldKind::MultiSelect {
            options, default, ..
        } => default
            .iter()
            .map(String::len)
            .sum::<usize>()
            .saturating_add(option_bytes(options)),
        ElicitationFieldKind::Unsupported { schema_type } => schema_type.len(),
    }
}

fn elicitation_answer_resident_bytes(answer: &vibex_core::ElicitationAnswerValue) -> usize {
    match answer {
        vibex_core::ElicitationAnswerValue::String(value)
        | vibex_core::ElicitationAnswerValue::Number(value) => value.len(),
        vibex_core::ElicitationAnswerValue::Integer(_)
        | vibex_core::ElicitationAnswerValue::Boolean(_) => 0,
        vibex_core::ElicitationAnswerValue::StringArray(values) => {
            values.iter().map(String::len).sum()
        }
    }
}

fn timeline_conversation_turn_resident_bytes(turn: &TimelineConversationTurn) -> usize {
    let row_bytes = |row: &TimelineRow| {
        row.id
            .len()
            .saturating_add(row.item_ids.iter().map(String::len).sum::<usize>())
            .saturating_add(row.turn_id.as_ref().map_or(0, String::len))
            .saturating_add(row.title.len())
            .saturating_add(row.body.len())
            .saturating_add(row.runtime_attribution.as_ref().map_or(0, String::len))
            .saturating_add(row.file_path.as_ref().map_or(0, String::len))
    };
    turn.id
        .len()
        .saturating_add(turn.runtime_attribution.as_ref().map_or(0, String::len))
        .saturating_add(turn.live_status.as_ref().map_or(0, String::len))
        .saturating_add(turn.user_row.as_ref().map_or(0, row_bytes))
        .saturating_add(
            turn.process_rows
                .iter()
                .map(row_bytes)
                .fold(0_usize, usize::saturating_add),
        )
        .saturating_add(turn.conclusion_row.as_ref().map_or(0, row_bytes))
        .saturating_add(
            turn.process_activity_groups
                .iter()
                .map(|group| group.id.len())
                .sum::<usize>(),
        )
        .saturating_add(
            turn.process_activity_groups_with_commands
                .iter()
                .chain(turn.process_activity_groups_with_file_operations.iter())
                .chain(
                    turn.process_activity_groups_with_commands_and_file_operations
                        .iter(),
                )
                .map(|group| group.id.len())
                .sum::<usize>(),
        )
}

fn timeline_process_activity_groups_for_display(
    turn: &TimelineConversationTurn,
    enhanced_command_display: bool,
) -> &[TimelineProcessActivityGroup] {
    // File details choose their renderer inside the group; they do not break
    // the surrounding activity run. Enhanced commands retain their approval card.
    if enhanced_command_display {
        &turn.process_activity_groups_with_file_operations
    } else {
        &turn.process_activity_groups_with_commands_and_file_operations
    }
}

/// The rows one expanded process group's body stands for.
///
/// A group's own range is the projection's, not the unit's: the unit spans the
/// same rows today, but a body built during prepaint only has the group's id, so
/// this is the lookup that keeps it from re-deriving the whole unit walk.
fn timeline_group_body_rows<'a>(
    turn: &'a TimelineConversationTurn,
    group_id: &str,
    enhanced_command_display: bool,
) -> Option<&'a [TimelineRow]> {
    let group = timeline_process_activity_groups_for_display(turn, enhanced_command_display)
        .iter()
        .find(|group| group.id == group_id)?;
    turn.process_rows.get(group.start_row..group.end_row)
}

struct SidebarProjectionCache {
    revision: u64,
    groups: Rc<Vec<SidebarProjectProjection>>,
}

/// Where one sidebar session row belongs, for the move-selection comparisons.
///
/// Two rows may be moved together when both halves agree: the project scope the
/// sidebar projection places them in, and the project the session itself belongs
/// to. The comparison runs once per candidate row of every selected row, so it
/// reads a map built once instead of rebuilding the projection each time.
#[derive(Clone, PartialEq, Eq, Hash)]
struct SidebarRowScope {
    project_scope: Option<String>,
    project_id: ProjectId,
}

/// One project's slice of a shift/ctrl multi-selection.
///
/// The slice is what a drag from one of the project's rows carries, and what the
/// batch commands of its row menus act on. Both answers are the same for every
/// row of the project, so the slice is resolved once and shared for the rest of
/// the frame.
struct SidebarSelectionSlice {
    /// The rows a drag from this project carries, in sidebar order.
    items: Vec<SidebarOrganizationItem>,
    /// The sessions among them, in the same order.
    session_ids: Rc<Vec<String>>,
    /// The groups the sessions could join, when they share one Worktree.
    group_candidates: Vec<(String, String)>,
    /// Whether any of the sessions already belongs to a group.
    has_group_members: bool,
    /// Whether every one of them is already being deleted.
    deletion_pending: bool,
    /// Whether every one of them is already being archived.
    archive_pending: bool,
    /// Whether every one of them has auto continue on.
    auto_continue_enabled: bool,
    /// Whether any of them has auto continue paused.
    auto_continue_paused: bool,
    /// Whether every one of them is pinned.
    pinned: bool,
}

/// The shift/ctrl multi-selection resolved for the rows of one frame.
///
/// Resolving a slice walks the placement tree and the session list for every
/// candidate row, and the sidebar asks for one on every row it paints. With a
/// large selection that cost `rows × selection × projection` in a single frame,
/// which is what took the frame rate to single digits the moment a
/// multi-selection was made. One frame resolves each project once and shares the
/// answer with the rest of its rows.
#[derive(Default)]
struct SidebarSelectionIndex {
    /// The selection the entries describe, so a change made between frames
    /// rebuilds them instead of serving a stale answer.
    selection: BTreeSet<SidebarOrganizationItem>,
    /// The session the workbench shows, which joins the selection while one is
    /// on screen.
    current_session: Option<String>,
    /// Whether the resolved entries below belong to this index.
    built: bool,
    /// Session id → the scope its row is compared by.
    scopes: BTreeMap<String, SidebarRowScope>,
    /// The selection as the sidebar paints it: the move set plus the open
    /// session's row, in the order a drag lists them.
    effective: Vec<SidebarOrganizationItem>,
    /// The same rows, for membership tests.
    effective_members: BTreeSet<SidebarOrganizationItem>,
    /// The selected sessions, for the group the selection could become.
    selected_sessions: BTreeSet<String>,
    /// The selection as one group; `Some(None)` is a resolved "it cannot".
    group_creation: Option<Option<(String, String, Vec<String>)>>,
    /// One project's slice, by the scope its rows share.
    slices: HashMap<SidebarRowScope, Rc<SidebarSelectionSlice>>,
    /// The slice of a selection of project rows.
    project_slice: Option<Rc<SidebarSelectionSlice>>,
}

/// Inputs that `conversation_turns` depends on. Timeline identity/content fields
/// also let the cache prove that a change was append-only before reusing its
/// completed prefix.
#[derive(Clone, PartialEq, Eq)]
struct ConversationTurnsCacheKey {
    session_id: Option<VibexSessionId>,
    timeline_revision: u64,
    item_count: usize,
    end_sequence: Option<i64>,
    session_state: Option<AgentSessionState>,
    agent_turn_pending: bool,
    pending_edit: Option<(VibexSessionId, i64, i64)>,
    optimistic_message: Option<(VibexSessionId, String, i64)>,
    reasoning_display_mode: ReasoningDisplayMode,
    /// Where the window's leading turn begins, when a read placed it. A read
    /// that lands one changes the projection without moving a single item.
    leading_turn_start: Option<TimelineTurnStart>,
}

fn conversation_turn_start_index(
    turn: &TimelineConversationTurn,
    items: &[TimelineItem],
) -> Option<usize> {
    if let Some(sequence) = turn.user_row.as_ref().map(|row| row.first_sequence) {
        return items
            .binary_search_by_key(&sequence, |item| item.sequence)
            .ok();
    }

    if let Some(item_id) = turn.id.strip_prefix("turn:continuation:") {
        return items.iter().position(|item| item.id.as_str() == item_id);
    }

    let sequence = turn
        .process_rows
        .iter()
        .chain(turn.conclusion_row.iter())
        .map(|row| row.first_sequence)
        .min()?;
    items
        .binary_search_by_key(&sequence, |item| item.sequence)
        .ok()
}

/// Rebuild only the final real turn after an append-only timeline update. The
/// prefix is shared by `Rc`, so a GPUI frame holding the previous projection
/// cannot force a deep clone of the whole conversation.
fn refresh_conversation_turns_cache_incrementally(
    cache: &mut Rc<Vec<Rc<TimelineConversationTurn>>>,
    previous_key: &ConversationTurnsCacheKey,
    next_key: &ConversationTurnsCacheKey,
    timeline: &TimelineModel,
) -> bool {
    if previous_key.session_id != next_key.session_id
        || next_key.session_id != timeline.session_id
        || previous_key.reasoning_display_mode != next_key.reasoning_display_mode
        || previous_key.pending_edit.is_some()
        || next_key.pending_edit.is_some()
        || previous_key.optimistic_message.is_some()
        || next_key.optimistic_message.is_some()
        || previous_key.item_count > next_key.item_count
        || next_key.item_count != timeline.items.len()
        // A prefix kept from the cache still carries the projection it was
        // built with, so a read that moved the leading turn's anchor has to
        // rebuild rather than splice.
        || previous_key.leading_turn_start != next_key.leading_turn_start
    {
        return false;
    }

    let append_only = if previous_key.item_count < next_key.item_count {
        previous_key.item_count > 0
            && previous_key.end_sequence
                == timeline
                    .items
                    .get(previous_key.item_count - 1)
                    .map(|item| item.sequence)
    } else {
        previous_key.item_count == next_key.item_count
            && previous_key.timeline_revision == next_key.timeline_revision
    };
    if !append_only || cache.is_empty() {
        return false;
    }

    let Some((turn_index, start_index)) =
        cache.iter().enumerate().rev().find_map(|(index, turn)| {
            conversation_turn_start_index(turn, &timeline.items).map(|start| (index, start))
        })
    else {
        return false;
    };
    let suffix = timeline_conversation_turns_with_leading_turn_start(
        &timeline.items[start_index..],
        next_key.session_state,
        next_key.agent_turn_pending,
        next_key.reasoning_display_mode,
        // Only a suffix that begins at the window's own leading turn has a
        // missing opening row to place; a later turn starts inside the suffix.
        if turn_index == 0 {
            next_key.leading_turn_start
        } else {
            None
        },
    );
    let Some(first_suffix) = suffix.first() else {
        return false;
    };
    if first_suffix.id != cache[turn_index].id {
        return false;
    }

    let mut turns = cache[..turn_index].to_vec();
    turns.extend(suffix.into_iter().map(Rc::new));
    *cache = Rc::new(turns);
    true
}

/// Keep the virtual-list renderer pointed at the current projection without
/// keeping an `Rc` alias alive while a streaming turn is mutated. The alias is
/// detached for the duration of the append so `Rc::make_mut` can update the
/// active turn in place instead of cloning its growing body.
fn with_detached_conversation_turns_render_cache<T>(
    cache: &mut Rc<Vec<Rc<TimelineConversationTurn>>>,
    render_cache: &Rc<RefCell<Rc<Vec<Rc<TimelineConversationTurn>>>>>,
    update: impl FnOnce(&mut Rc<Vec<Rc<TimelineConversationTurn>>>) -> T,
) -> T {
    *render_cache.borrow_mut() = Rc::new(Vec::new());
    let result = update(cache);
    *render_cache.borrow_mut() = cache.clone();
    result
}

struct AgentStreamingDeltaUpdate {
    item_id: String,
    sequence: i64,
    timestamp_ms: i64,
    text: String,
    conclusion: bool,
    runtime_attribution: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct StreamingRowStateCache {
    turn_id: String,
    row_id: String,
    body_len: usize,
    /// The row body's character count, when the streaming path knows it.
    ///
    /// The output estimate grows by characters, and a row that a coalesced run
    /// replaces carries its whole text — so the count the previous update left
    /// here is what saves each new one from scanning the text it replaces.
    /// `None` means the count has to be derived from the body once.
    body_chars: Option<usize>,
}

struct AgentStreamingCacheUpdate {
    turn_id: String,
    row_id: String,
    previous_body_len: usize,
    body_len: usize,
    output_char_delta: usize,
}

fn timeline_item_runtime_attribution(item: &TimelineItem) -> Option<String> {
    item.execution_attribution.as_ref().map(|attribution| {
        format!(
            "{} · {} · {}",
            attribution.agent_label, attribution.auth_source_label, attribution.model_label
        )
    })
}

fn timeline_live_event_is_well_formed(event: &TimelineLiveEvent) -> bool {
    event.sequence == event.item.sequence && event.session_id == event.item.session_id
}

fn timeline_live_event_updates_sidebar_timestamp(event: &TimelineLiveEvent) -> bool {
    if !timeline_live_event_is_well_formed(event) {
        return false;
    }
    match &event.item.payload {
        // Streaming deltas are presentation buffers. Updating the sidebar's
        // sort key for every chunk makes unrelated sessions repaint while the
        // active Agent is thinking or writing.
        TimelinePayload::AgentMessageDelta(_) => false,
        TimelinePayload::Reasoning(reasoning) => reasoning.is_final,
        _ => true,
    }
}

fn agent_streaming_delta_updates(
    events: &[TimelineLiveEvent],
) -> Option<Vec<AgentStreamingDeltaUpdate>> {
    let mut updates = Vec::with_capacity(events.len());
    for event in events {
        if !timeline_live_event_is_well_formed(event) {
            return None;
        }
        let TimelinePayload::AgentMessageDelta(delta) = &event.item.payload else {
            return None;
        };
        if delta.text_delta.contains("Reconnecting... ") {
            return None;
        }
        updates.push(AgentStreamingDeltaUpdate {
            item_id: event.item.id.to_string(),
            sequence: event.sequence,
            timestamp_ms: event.item.timestamp_ms,
            text: delta.text_delta.clone(),
            conclusion: delta.phase == Some(AgentMessagePhase::FinalAnswer),
            runtime_attribution: timeline_item_runtime_attribution(&event.item),
        });
    }
    updates
        .windows(2)
        .all(|pair| {
            pair[1].sequence == pair[0].sequence.saturating_add(1)
                && pair[1].conclusion == pair[0].conclusion
        })
        .then_some(updates)
}

fn agent_text_append_batch(events: &[TimelineLiveEvent]) -> bool {
    !events.is_empty()
        && events.iter().all(|event| {
            matches!(
                &event.item.payload,
                TimelinePayload::AgentMessageDelta(_) | TimelinePayload::AgentMessage(_)
            )
        })
}

fn update_unread_agent_completions(
    unread_session_ids: &mut BTreeSet<String>,
    completion_watermarks: &mut BTreeMap<String, i64>,
    selected_session_id: Option<&VibexSessionId>,
    events: &[TimelineLiveEvent],
) -> bool {
    let previous_len = unread_session_ids.len();
    for event in events {
        if !timeline_live_event_is_well_formed(event) {
            continue;
        }
        if !matches!(
            &event.item.payload,
            TimelinePayload::AgentMessage(message) if message.is_final
        ) {
            continue;
        }
        let session_id = event.session_id.as_str().to_string();
        // The live stream and the polling fallback both deliver the same
        // committed item, so the final answer that ended while its session was
        // on screen can arrive a second time after the reader has switched
        // away. That replay is not a second completion: a final answer this
        // session has already accounted for — watched end, or already badged —
        // leaves the mark alone. Only an answer past the watermark can raise
        // the dot.
        if completion_watermarks
            .get(&session_id)
            .is_some_and(|watermark| event.sequence <= *watermark)
        {
            continue;
        }
        completion_watermarks.insert(session_id.clone(), event.sequence);
        if selected_session_id == Some(&event.session_id) {
            continue;
        }
        unread_session_ids.insert(session_id);
    }
    unread_session_ids.len() != previous_len
}

fn mark_agent_session_read(
    unread_session_ids: &mut BTreeSet<String>,
    session_id: &VibexSessionId,
) -> bool {
    unread_session_ids.remove(session_id.as_str())
}

/// Whether a session's row should still ask the reader for an answer.
///
/// The index of unresolved requests is built from the live stream, so it can
/// outlive the card it describes: an interrupt cancels the Agent's native
/// callback without appending a resolution item, and the request stays
/// `Pending` in the transcript. The persisted state is the tie-breaker. A
/// session parked on the user reads `NeedsInput`, and a card that arrives
/// while the provider turn is still streaming leaves the state `Running`; only
/// those two states can still be waiting on an answer. A session that settled,
/// failed, or closed has moved past the card whatever the stream said, and its
/// row must report that instead of asking forever.
fn session_awaits_user_input(
    state: AgentSessionState,
    pending_user_request_ids: &BTreeMap<String, BTreeSet<String>>,
    session_id: &str,
) -> bool {
    state == AgentSessionState::NeedsInput
        || (state == AgentSessionState::Running
            && pending_user_request_ids.contains_key(session_id))
}

/// Tracks the approval and input requests a session is still waiting on.
///
/// The request timeline item arrives while the provider turn is still open, so
/// it is the earliest reliable signal that the Agent stopped working and needs
/// the user. Resolutions arrive as their own items; a session leaves the index
/// once every request it was asked has been answered. A new prompt also
/// supersedes whatever the previous turn left unanswered: the user typed past
/// the card, so the request can no longer be the row's live question. A steer
/// joins the turn already running and does not supersede anything.
fn update_pending_user_requests(
    pending: &mut BTreeMap<String, BTreeSet<String>>,
    events: &[TimelineLiveEvent],
) -> bool {
    let mut changed = false;
    for event in events {
        if !timeline_live_event_is_well_formed(event) {
            continue;
        }
        let session_id = event.session_id.as_str();
        match &event.item.payload {
            TimelinePayload::PermissionRequest(request)
                if request.status == vibex_core::PermissionRequestStatus::Pending =>
            {
                changed |= pending
                    .entry(session_id.to_string())
                    .or_default()
                    .insert(request.id.to_string());
            }
            TimelinePayload::ElicitationRequest(request)
                if request.status == vibex_core::ElicitationRequestStatus::Pending =>
            {
                changed |= pending
                    .entry(session_id.to_string())
                    .or_default()
                    .insert(request.id.to_string());
            }
            TimelinePayload::PermissionResolution(resolution) => {
                changed |= resolve_pending_user_request(
                    pending,
                    session_id,
                    resolution.request_id.as_str(),
                );
            }
            TimelinePayload::ElicitationResolution(resolution) => {
                changed |= resolve_pending_user_request(
                    pending,
                    session_id,
                    resolution.request_id.as_str(),
                );
            }
            TimelinePayload::UserMessage(message)
                if message.delivery != vibex_core::UserMessageDelivery::Steer =>
            {
                changed |= pending.remove(session_id).is_some();
            }
            _ => {}
        }
    }
    changed
}

fn resolve_pending_user_request(
    pending: &mut BTreeMap<String, BTreeSet<String>>,
    session_id: &str,
    request_id: &str,
) -> bool {
    let Some(requests) = pending.get_mut(session_id) else {
        return false;
    };
    let removed = requests.remove(request_id);
    if requests.is_empty() {
        pending.remove(session_id);
    }
    removed
}

/// Replaces one session's entry from an authoritative timeline, so a lagged
/// stream cannot leave a resolved request looking unanswered.
///
/// The entry is scoped to the live turn: an authoritative read is the client's
/// chance to drop a request an earlier turn left behind, which the live stream
/// alone cannot do because the runtime cancels an abandoned callback without
/// appending a resolution item.
fn reset_pending_user_requests(
    pending: &mut BTreeMap<String, BTreeSet<String>>,
    session_id: &VibexSessionId,
    items: &[TimelineItem],
) {
    let requests = vibex_desktop_model::live_turn_pending_permission_ids(items);
    if requests.is_empty() {
        pending.remove(session_id.as_str());
    } else {
        pending.insert(session_id.as_str().to_string(), requests);
    }
}

fn record_timeline_row_endpoint(item_ids: &mut Vec<String>, item_id: String) {
    match item_ids.len() {
        0 => item_ids.push(item_id),
        1 if item_ids[0] != item_id => item_ids.push(item_id),
        1 => {}
        _ if item_ids.last() != Some(&item_id) => {
            item_ids.truncate(2);
            item_ids[1] = item_id;
        }
        _ => {}
    }
}

fn append_agent_streaming_deltas_to_cache(
    cache: &mut Rc<Vec<Rc<TimelineConversationTurn>>>,
    state_cache: &mut Option<StreamingRowStateCache>,
    updates: &[AgentStreamingDeltaUpdate],
) -> Option<AgentStreamingCacheUpdate> {
    if updates.is_empty() {
        return None;
    }
    let last_turn = cache.last()?;
    let conclusion = updates.first()?.conclusion;
    let last_row = if conclusion {
        last_turn.conclusion_row.as_ref()?
    } else {
        last_turn.process_rows.last()?
    };
    if last_turn.complete
        || last_row.kind != TimelineRowKind::AgentMessage
        || !last_row.streaming
        || last_row.conclusion != conclusion
        || updates.iter().any(|update| update.conclusion != conclusion)
        || updates
            .iter()
            .any(|update| update.runtime_attribution != last_row.runtime_attribution)
        || updates
            .first()
            .is_none_or(|update| update.sequence != last_row.last_sequence.saturating_add(1))
        || updates
            .windows(2)
            .any(|pair| pair[1].sequence != pair[0].sequence.saturating_add(1))
    {
        return None;
    }

    let turn_id = last_turn.id.clone();
    let row_id = last_row.id.clone();
    let previous_body_len = last_row.body.len();
    let output_char_delta = updates
        .iter()
        .map(|update| update.text.chars().count())
        .sum();

    let turns = Rc::make_mut(cache);
    let turn = Rc::make_mut(turns.last_mut().expect("cache was checked above"));
    let body_len = {
        let row = if conclusion {
            turn.conclusion_row
                .as_mut()
                .expect("streaming conclusion row was checked above")
        } else {
            turn.process_rows
                .last_mut()
                .expect("streaming process row was checked above")
        };
        for update in updates {
            row.body.push_str(&update.text);
            record_timeline_row_endpoint(&mut row.item_ids, update.item_id.clone());
            row.last_sequence = update.sequence;
            // As in the reasoning path: the same row the full projection would
            // build, reached without rebuilding it.
            row.timestamp_ms = update.timestamp_ms;
        }
        row.body.len()
    };
    turn.item_count = turn.item_count.saturating_add(updates.len());
    turn.ended_at_ms = updates.last().map(|update| update.timestamp_ms);
    for row in turn
        .user_row
        .iter_mut()
        .chain(turn.process_rows.iter_mut())
        .chain(turn.conclusion_row.iter_mut())
    {
        row.turn_item_count = turn.item_count;
    }
    *state_cache = Some(StreamingRowStateCache {
        turn_id: turn_id.clone(),
        row_id: row_id.clone(),
        body_len,
        body_chars: None,
    });
    Some(AgentStreamingCacheUpdate {
        turn_id,
        row_id,
        previous_body_len,
        body_len,
        output_char_delta,
    })
}

/// Thought chunks arrive as individual timeline items, so a thinking stream
/// would otherwise reproject the whole in-flight turn once per chunk. Mirror
/// the agent-message streaming fast path: recognise a pure run of appended
/// non-final reasoning deltas so the cached turn can be extended in place.
struct AgentReasoningDeltaUpdate {
    item_id: String,
    sequence: i64,
    timestamp_ms: i64,
    text: String,
    runtime_attribution: Option<String>,
}

/// Whether one reasoning revision replaces the whole run the view holds.
///
/// A thought's chunks are folded onto the row the run began at, so the newest
/// text can arrive as a sequence the view already holds, carrying the run's
/// whole accumulation. Replacing that row's body is then exactly the edit a
/// projection would make. A run the view still holds as several rows is not
/// that shape — each of those rows contributes its own text, and only the
/// projection can rebuild the run from them — so the batch is left to it.
fn reasoning_revision_replaces_the_run(
    items: &[TimelineItem],
    previous_end_sequence: Option<i64>,
    events: &[TimelineLiveEvent],
) -> bool {
    let [event] = events else {
        return false;
    };
    if previous_end_sequence != Some(event.sequence) {
        return false;
    }
    let TimelinePayload::Reasoning(reasoning) = &event.item.payload else {
        return false;
    };
    if reasoning.is_final {
        return false;
    }
    let mut run = items.iter().rev().take_while(|item| {
        matches!(&item.payload, TimelinePayload::Reasoning(reasoning) if !reasoning.is_final)
    });
    let Some(tail) = run.next() else {
        return false;
    };
    run.next().is_none()
        && tail.sequence == event.sequence
        && tail.provider_correlation_id == event.item.provider_correlation_id
}

fn agent_reasoning_delta_updates(
    events: &[TimelineLiveEvent],
) -> Option<Vec<AgentReasoningDeltaUpdate>> {
    let mut updates = Vec::with_capacity(events.len());
    for event in events {
        if !timeline_live_event_is_well_formed(event) {
            return None;
        }
        let TimelinePayload::Reasoning(reasoning) = &event.item.payload else {
            return None;
        };
        if reasoning.is_final {
            return None;
        }
        updates.push(AgentReasoningDeltaUpdate {
            item_id: event.item.id.to_string(),
            sequence: event.sequence,
            timestamp_ms: event.item.timestamp_ms,
            text: reasoning.text.clone(),
            runtime_attribution: timeline_item_runtime_attribution(&event.item),
        });
    }
    updates
        .windows(2)
        .all(|pair| pair[1].sequence == pair[0].sequence.saturating_add(1))
        .then_some(updates)
}

fn append_agent_reasoning_deltas_to_cache(
    cache: &mut Rc<Vec<Rc<TimelineConversationTurn>>>,
    state_cache: &mut Option<StreamingRowStateCache>,
    reasoning_display_mode: ReasoningDisplayMode,
    previous_end_sequence: Option<i64>,
    updates: &[AgentReasoningDeltaUpdate],
) -> Option<AgentStreamingCacheUpdate> {
    let first = updates.first()?;
    let last_turn = cache.last()?;
    // `live_status` is only populated while the turn tail is a run of streaming
    // reasoning, which is exactly the state this append can extend.
    let live_status = last_turn.live_status.as_ref()?;
    // A thought's chunks are folded onto the row the run began at, so the
    // newest text can arrive as the sequence the view already holds instead of
    // the one above it. A revision replaces the row's body — its payload is the
    // whole accumulation, not the chunk that grew it — while a run of new
    // sequences is appended exactly as it arrives.
    let revision = updates.len() == 1 && previous_end_sequence == Some(first.sequence);
    if last_turn.complete
        || (!revision
            && previous_end_sequence.is_none_or(|end| end.saturating_add(1) != first.sequence))
        || updates
            .windows(2)
            .any(|pair| pair[1].sequence != pair[0].sequence.saturating_add(1))
    {
        return None;
    }

    let turn_id = last_turn.id.clone();
    let previous_sequence = if revision {
        first.sequence
    } else {
        first.sequence.saturating_sub(1)
    };
    let timeline_row = (reasoning_display_mode == ReasoningDisplayMode::Timeline)
        .then(|| {
            last_turn.process_rows.last().filter(|row| {
                row.kind == TimelineRowKind::Reasoning
                    && row.streaming
                    && row.last_sequence == previous_sequence
                    && updates
                        .iter()
                        .all(|update| update.runtime_attribution == row.runtime_attribution)
            })
        })
        .flatten();
    if reasoning_display_mode == ReasoningDisplayMode::Timeline && timeline_row.is_none() {
        return None;
    }
    // A revision rewrites the body of the row it names, so the run that row
    // describes has to be that row alone: a run the projection folded out of
    // several rows has each of them contributing text, and only a projection
    // can rebuild it from them.
    if revision && timeline_row.is_some_and(|row| row.item_ids.len() != 1) {
        return None;
    }
    let row_id =
        timeline_row.map_or_else(|| format!("reasoning-live:{turn_id}"), |row| row.id.clone());
    let previous_body_len = timeline_row.map_or_else(|| live_status.len(), |row| row.body.len());
    // The count the previous update left beside the row is what keeps a growing
    // thought from rescanning its own text on every chunk. A row whose state
    // was lost is counted once here and cached again below.
    let previous_body_chars = match (row_id.as_str(), state_cache.as_ref()) {
        (row_id, Some(state)) if state.row_id == row_id => state.body_chars,
        _ => None,
    }
    .unwrap_or_else(|| {
        timeline_row.map_or_else(
            || live_status.chars().count(),
            |row| row.body.chars().count(),
        )
    });
    let appended_chars = updates
        .iter()
        .map(|update| update.text.chars().count())
        .sum::<usize>();
    let output_char_delta = if revision {
        first
            .text
            .chars()
            .count()
            .saturating_sub(previous_body_chars)
    } else {
        appended_chars
    };

    let turns = Rc::make_mut(cache);
    let turn = Rc::make_mut(turns.last_mut().expect("cache was checked above"));
    if let Some(live_status) = turn.live_status.as_mut() {
        if revision {
            live_status.clear();
            live_status.push_str(&first.text);
        } else {
            for update in updates {
                live_status.push_str(&update.text);
            }
        }
    }
    let mut body_len = turn.live_status.as_ref().map_or(0, String::len);
    if reasoning_display_mode == ReasoningDisplayMode::Timeline
        && let Some(row) = turn.process_rows.last_mut()
    {
        if revision {
            row.body.clear();
            row.body.push_str(&first.text);
        } else {
            for update in updates {
                row.body.push_str(&update.text);
            }
        }
        record_timeline_row_endpoint(&mut row.item_ids, first.item_id.clone());
        row.last_sequence = first.sequence;
        // The row is stamped where it last spoke, exactly as the full
        // projection stamps it: this path exists to reach the same rows
        // without re-projecting the timeline.
        row.timestamp_ms = first.timestamp_ms;
        body_len = row.body.len();
    }
    if !revision {
        turn.item_count = turn.item_count.saturating_add(updates.len());
    }
    turn.ended_at_ms = updates.last().map(|update| update.timestamp_ms);
    for row in turn
        .user_row
        .iter_mut()
        .chain(turn.process_rows.iter_mut())
        .chain(turn.conclusion_row.iter_mut())
    {
        row.turn_item_count = turn.item_count;
    }
    *state_cache = Some(StreamingRowStateCache {
        turn_id: turn_id.clone(),
        row_id: row_id.clone(),
        body_len,
        body_chars: Some(if revision {
            first.text.chars().count()
        } else {
            previous_body_chars.saturating_add(appended_chars)
        }),
    });
    Some(AgentStreamingCacheUpdate {
        turn_id,
        row_id,
        previous_body_len,
        body_len,
        output_char_delta,
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AgentAnswerAction {
    Copy,
    ScrollToUserMessage,
    Fork,
    Timestamp,
}

const AGENT_ANSWER_ACTION_ORDER: [AgentAnswerAction; 4] = [
    AgentAnswerAction::Copy,
    AgentAnswerAction::ScrollToUserMessage,
    AgentAnswerAction::Fork,
    AgentAnswerAction::Timestamp,
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UserMessageEditActionState {
    Hidden,
    Disabled,
    Enabled,
}

#[derive(Clone)]
struct InlineUserMessageEdit {
    turn_id: String,
    row_id: String,
    source_session_id: VibexSessionId,
    user_sequence: i64,
    expected_source_end_sequence: i64,
    attachments: Vec<InlineComposerAttachment>,
    geometry: ComposerGeometry,
}

impl InlineUserMessageEdit {
    fn matches(&self, row_id: &str, session_id: Option<&VibexSessionId>) -> bool {
        self.row_id == row_id && session_id == Some(&self.source_session_id)
    }
}

#[derive(Clone)]
struct PendingUserMessageEdit {
    source_session_id: VibexSessionId,
    user_sequence: i64,
    submitted_at_ms: i64,
    text: String,
    attachments: Vec<MessageAttachment>,
    mentions: Vec<VibexUseMention>,
}

impl PendingUserMessageEdit {
    fn cache_key(&self) -> (VibexSessionId, i64, i64) {
        (
            self.source_session_id.clone(),
            self.user_sequence,
            self.submitted_at_ms,
        )
    }

    fn projected_items(&self, timeline: &TimelineModel) -> Option<Vec<TimelineItem>> {
        if timeline.session_id.as_ref() != Some(&self.source_session_id) {
            return None;
        }
        let mut items = timeline.items.clone();
        let user_item_index = items.iter().position(|item| {
            item.sequence == self.user_sequence
                && matches!(&item.payload, TimelinePayload::UserMessage(_))
        })?;
        let user_item = items.get_mut(user_item_index)?;
        let TimelinePayload::UserMessage(message) = &mut user_item.payload else {
            return None;
        };
        message.text.clone_from(&self.text);
        message.attachments.clone_from(&self.attachments);
        message.mentions.clone_from(&self.mentions);
        user_item.timestamp_ms = self.submitted_at_ms;
        items.truncate(user_item_index + 1);
        Some(items)
    }
}

/// Presentation-only user message retained until the authoritative timeline
/// receives the durable row. The backend remains the source of truth.
#[derive(Clone)]
struct OptimisticUserMessage {
    session_id: VibexSessionId,
    item_id: TimelineItemId,
    after_sequence: i64,
    submitted_at_ms: i64,
    text: String,
    attachments: Vec<MessageAttachment>,
    mentions: Vec<VibexUseMention>,
}

impl OptimisticUserMessage {
    fn cache_key(&self) -> (VibexSessionId, String, i64) {
        (
            self.session_id.clone(),
            self.item_id.as_str().to_string(),
            self.submitted_at_ms,
        )
    }

    fn is_confirmed_by(&self, timeline: &TimelineModel) -> bool {
        timeline.session_id.as_ref() == Some(&self.session_id)
            && timeline.items.iter().any(|item| {
                item.sequence > self.after_sequence
                    && matches!(
                        &item.payload,
                        TimelinePayload::UserMessage(message)
                            if message.text.trim() == self.text.trim()
                                && message.attachments == self.attachments
                    )
            })
    }

    fn projected_items(&self, timeline: &TimelineModel) -> Option<Vec<TimelineItem>> {
        if timeline
            .session_id
            .as_ref()
            .is_some_and(|session_id| session_id != &self.session_id)
            || self.is_confirmed_by(timeline)
        {
            return None;
        }
        let mut items = timeline.items.clone();
        let payload = TimelinePayload::UserMessage(UserMessagePayload {
            text: self.text.clone(),
            attachments: self.attachments.clone(),
            mentions: self.mentions.clone(),
            ..Default::default()
        });
        items.push(TimelineItem {
            id: self.item_id.clone(),
            session_id: self.session_id.clone(),
            sequence: items
                .last()
                .map(|item| item.sequence.saturating_add(1))
                .unwrap_or(1),
            timestamp_ms: self.submitted_at_ms,
            source: TimelineSource::User,
            kind: payload.kind(),
            correlation_id: None,
            provider_correlation_id: None,
            redaction_state: TimelineRedactionState::None,
            execution_attribution: None,
            payload_depth: vibex_core::TimelinePayloadDepth::Detail,
            payload,
        });
        Some(items)
    }
}

/// The optimistic first message a live view may project ahead of the authority.
///
/// The borrowed view knows which session it belongs to before that session's
/// authoritative timeline binds the id, which is exactly the window a brand-new
/// session renders in: the id is optimistic, no item exists yet, and the turn is
/// already pending. Keying the lookup on `timeline.session_id` alone dropped the
/// user's own message there and left an item-less pending turn on screen, so the
/// view's session is the fallback key.
///
/// `projected_items` still refuses to project into a timeline that belongs to a
/// different session, so this cannot leak one session's message into another.
fn optimistic_user_message_for_view<'a>(
    timeline: &TimelineModel,
    messages: &'a BTreeMap<String, OptimisticUserMessage>,
    view_session_id: Option<&VibexSessionId>,
) -> Option<&'a OptimisticUserMessage> {
    let session_id = timeline.session_id.as_ref().or(view_session_id)?;
    messages.get(session_id.as_str())
}

fn agent_answer_actions(has_timestamp: bool) -> impl Iterator<Item = AgentAnswerAction> {
    AGENT_ANSWER_ACTION_ORDER
        .into_iter()
        .filter(move |action| has_timestamp || !matches!(action, AgentAnswerAction::Timestamp))
}

fn user_message_edit_action_state(
    latest_user_message: bool,
    turn_complete: bool,
    needs_authoritative_refetch: bool,
    session_state: Option<AgentSessionState>,
    action_pending: bool,
) -> UserMessageEditActionState {
    if !latest_user_message {
        return UserMessageEditActionState::Hidden;
    }
    if turn_complete
        && !needs_authoritative_refetch
        && !action_pending
        && matches!(
            session_state,
            Some(AgentSessionState::Idle | AgentSessionState::Error)
        )
    {
        UserMessageEditActionState::Enabled
    } else {
        UserMessageEditActionState::Disabled
    }
}

fn timeline_distance_to_bottom(offset_y: f32, max_offset_y: f32) -> f32 {
    (max_offset_y + offset_y).max(0.0)
}

/// What the viewport says about prefetching older history.
#[derive(Clone, Copy)]
struct TimelineOlderPrefetch {
    distance_to_top: f32,
    viewport_height: f32,
    has_older: bool,
    in_flight: usize,
    following_bottom: bool,
    scrollable: bool,
    loading: bool,
}

/// Whether the reader is close enough to the top to start the next page.
///
/// The trigger is deliberately not the literal top: a page takes a round trip,
/// so waiting for it would show an empty band. It is also deliberately not
/// "whenever there is history below": a reader parked at the bottom of a
/// scrollable transcript has no use for pages they will never scroll to.
///
/// A transcript that does not fill its viewport is the exception. There is no
/// scroll for the reader to make, so the window has to extend itself until
/// there is a screenful to read or the history runs out — otherwise opening a
/// turn whose rows the projection folds into a handful leaves the reader with
/// that handful and no way to ask for the rest.
fn timeline_should_prefetch_older(state: TimelineOlderPrefetch) -> bool {
    !state.loading
        && state.has_older
        && (!state.following_bottom || !state.scrollable)
        && state.in_flight < AGENT_TIMELINE_OLDER_MAX_IN_FLIGHT
        && state.viewport_height > 0.0
        && state.distance_to_top <= state.viewport_height * AGENT_TIMELINE_OLDER_PREFETCH_SCREENS
}

fn timeline_should_resume_follow_after_scroll_idle(
    scrolled_toward_bottom: bool,
    distance_to_bottom: f32,
    scrollbar_interaction_active: bool,
) -> bool {
    scrolled_toward_bottom
        && !scrollbar_interaction_active
        && distance_to_bottom <= AGENT_TIMELINE_NEAR_BOTTOM_THRESHOLD_PX
}

fn timeline_should_show_bottom_control(
    scrollable: bool,
    following_bottom: bool,
    distance_to_bottom: f32,
    currently_visible: bool,
) -> bool {
    scrollable
        && !following_bottom
        && distance_to_bottom > AGENT_TIMELINE_NEAR_BOTTOM_THRESHOLD_PX
        && (currently_visible
            || distance_to_bottom >= AGENT_TIMELINE_BOTTOM_CONTROL_REVEAL_THRESHOLD_PX)
}

fn timeline_should_auto_follow_content(
    following_bottom: bool,
    scroll_wheel_active: bool,
    scrollbar_interaction_active: bool,
    content_extent_changed: bool,
) -> bool {
    following_bottom
        && !scroll_wheel_active
        && !scrollbar_interaction_active
        && content_extent_changed
}

/// Locate the virtual timeline row under the viewport top for a scroll offset.
///
/// `offset_y` is the raw [`ScrollHandle`] offset (zero at the top, negative
/// while scrolled down) and `padding_top` is the list's own top padding, which
/// scrolls with the content. The returned offset is how far the viewport top
/// sits below the row's top, so it is negative while the list is parked above
/// the first row. Capturing this anchor lets a session switch or an
/// authoritative replacement put the same conversation content back under the
/// viewport after the virtual row extents changed.
fn timeline_scroll_anchor_from_offset(
    row_heights: &[f32],
    offset_y: f32,
    padding_top: f32,
) -> Option<(usize, f32)> {
    let viewport_top = -offset_y - padding_top;
    let mut row_top = 0.0;
    for (index, height) in row_heights.iter().enumerate() {
        if row_top + height > viewport_top {
            return Some((index, viewport_top - row_top));
        }
        row_top += height;
    }
    row_heights
        .len()
        .checked_sub(1)
        .map(|index| (index, row_heights[index]))
}

/// The timeline rows the pane's viewport currently shows.
///
/// `offset_y` is the raw [`ScrollHandle`] offset (zero at the top, negative
/// while scrolled down) and `padding_top` is the list's own top padding, which
/// scrolls with the content — the same pair [`timeline_scroll_anchor_from_offset`]
/// resolves the viewport's top row with. A row counts while any of it is on
/// screen, and the viewport's own height is measured from the scroll handle's
/// bounds, so a viewport that straddles a turn boundary reports both turns.
/// That is what lets the turn preview rail keep every turn the reader can
/// actually see lit at once instead of only the one the pointer names.
fn timeline_visible_row_range(
    row_heights: impl IntoIterator<Item = f32>,
    offset_y: f32,
    padding_top: f32,
    viewport_height: f32,
) -> Range<usize> {
    if !(viewport_height.is_finite() && viewport_height > 0.0) {
        // Before the first layout reports the pane there is no viewport to
        // intersect, and lighting a guessed row would be worse than none.
        return 0..0;
    }
    let viewport_top = -offset_y - padding_top;
    let viewport_bottom = viewport_top + viewport_height;
    let mut visible: Option<Range<usize>> = None;
    let mut row_top = 0.0;
    for (index, height) in row_heights.into_iter().enumerate() {
        let row_bottom = row_top + height;
        if row_bottom > viewport_top && row_top < viewport_bottom {
            match visible.as_mut() {
                Some(visible) => visible.end = index + 1,
                None => visible = Some(index..index + 1),
            }
        }
        row_top = row_bottom;
    }
    visible.unwrap_or(0..0)
}

/// Scroll offset that puts `row_index`'s top `offset_in_row` below the viewport
/// top. The inverse of [`timeline_scroll_anchor_from_offset`], so an unchanged
/// row table maps an offset back to itself.
fn timeline_scroll_offset_for_anchor(
    row_heights: &[f32],
    row_index: usize,
    offset_in_row: f32,
    padding_top: f32,
) -> Option<f32> {
    if row_index >= row_heights.len() {
        return None;
    }
    let row_top: f32 = row_heights[..row_index].iter().sum();
    Some(-(padding_top + row_top + offset_in_row))
}

/// The sequence range a turn covers, as an anchor identity.
///
/// Every row of the turn carries its own range, so the turn's span is the union
/// of the rows it still holds. A turn whose rows are all empty has no identity
/// to anchor on and reports `None`.
fn timeline_turn_anchor_span(turn: &TimelineConversationTurn) -> Option<TimelineAnchorSpan> {
    let rows = turn
        .user_row
        .iter()
        .chain(turn.process_rows.iter())
        .chain(turn.conclusion_row.iter());
    let mut span: Option<TimelineAnchorSpan> = None;
    for row in rows {
        span = Some(match span {
            Some(current) => TimelineAnchorSpan {
                first_sequence: current.first_sequence.min(row.first_sequence),
                last_sequence: current.last_sequence.max(row.last_sequence),
            },
            None => TimelineAnchorSpan {
                first_sequence: row.first_sequence,
                last_sequence: row.last_sequence,
            },
        });
    }
    span
}

fn stable_streaming_timeline_height(
    previous_height: Option<f32>,
    measured_height: f32,
    preserve_streaming_extent: bool,
) -> f32 {
    if preserve_streaming_extent {
        previous_height
            .unwrap_or(measured_height)
            .max(measured_height)
    } else {
        measured_height
    }
}

fn streaming_extent_is_preserved(
    preserve_streaming_extent: bool,
    previous_layout_signature: Option<u64>,
    current_layout_signature: Option<u64>,
) -> bool {
    preserve_streaming_extent
        && current_layout_signature.is_some()
        && previous_layout_signature == current_layout_signature
}

fn stable_streaming_timeline_height_for_layout(
    previous_height: Option<f32>,
    measured_height: f32,
    preserve_streaming_extent: bool,
    previous_layout_signature: Option<u64>,
    current_layout_signature: Option<u64>,
) -> f32 {
    stable_streaming_timeline_height(
        previous_height,
        measured_height,
        streaming_extent_is_preserved(
            preserve_streaming_extent,
            previous_layout_signature,
            current_layout_signature,
        ),
    )
}

fn measured_timeline_layout_signature(
    previous_height: Option<f32>,
    measured_height: f32,
    previous_signature: Option<u64>,
    signature: Option<u64>,
) -> Option<u64> {
    // A windowed process run can still reserve its old extent in the frame
    // that measures a changed disclosure. Keep the shrink guard released until
    // the turn reports the new extent, including after nested measurement.
    if previous_signature.is_none()
        && previous_height.is_some_and(|height| (height - measured_height).abs() < 1.0)
    {
        None
    } else {
        signature
    }
}

/// A repeatable smaller intrinsic measurement observed while the streaming
/// preserve policy still owns a turn's virtual extent.
///
/// The policy holds the previous extent on the first observation because
/// incomplete Markdown can reparse into a shorter document for a frame or two.
/// A candidate that keeps repeating while the turn reshapes nothing, however,
/// is real content reduction - a collapsed card, merged process rows, or
/// activity grouped into one summary line. Holding that back forever is what
/// leaves a blank band under the last row, so a settled candidate replaces the
/// held extent.
#[derive(Debug, Clone, Copy, PartialEq)]
struct StreamingShrinkCandidate {
    height: f32,
    observed_at: Instant,
    confirmations: u8,
}

impl StreamingShrinkCandidate {
    /// Fold one smaller measurement into the candidate. A different height
    /// restarts the window: a still growing document is not settling.
    fn observe(previous: Option<Self>, measured_height: f32, now: Instant) -> Self {
        match previous.filter(|candidate| {
            (candidate.height - measured_height).abs() < AGENT_TIMELINE_STREAMING_SHRINK_EPSILON_PX
        }) {
            Some(previous) => Self {
                height: measured_height,
                observed_at: previous.observed_at,
                confirmations: previous.confirmations.saturating_add(1),
            },
            None => Self {
                height: measured_height,
                observed_at: now,
                confirmations: 1,
            },
        }
    }

    fn is_settled(&self, now: Instant) -> bool {
        self.confirmations >= AGENT_TIMELINE_STREAMING_SHRINK_CONFIRMATIONS
            && now.saturating_duration_since(self.observed_at)
                >= AGENT_TIMELINE_STREAMING_SHRINK_SETTLE
    }
}

/// Resolve a measurement taken while the preserve policy holds a turn's extent.
///
/// Returns the extent to keep plus the shrink candidate that survives the
/// frame: an unsettled candidate keeps the held extent and stays queued so the
/// next paint can confirm it; a settled one releases the extent to the freshly
/// measured content so bottom-follow can reclaim the freed space.
fn settle_streaming_timeline_shrink(
    previous_height: Option<f32>,
    raw_measured_height: f32,
    stable_height: f32,
    preserve_streaming_extent: bool,
    candidate: Option<StreamingShrinkCandidate>,
    now: Instant,
) -> (f32, Option<StreamingShrinkCandidate>) {
    let is_shrinking = preserve_streaming_extent
        && previous_height.is_some_and(|previous| {
            raw_measured_height < previous - AGENT_TIMELINE_STREAMING_SHRINK_EPSILON_PX
        });
    if !is_shrinking {
        return (stable_height, None);
    }

    let candidate = StreamingShrinkCandidate::observe(candidate, raw_measured_height, now);
    if candidate.is_settled(now) {
        (raw_measured_height, None)
    } else {
        (stable_height, Some(candidate))
    }
}

fn timeline_layout_width_changed(previous: Option<f32>, current: Option<f32>) -> bool {
    match (previous, current) {
        (Some(previous), Some(current)) => {
            (previous - current).abs() >= AGENT_TIMELINE_LAYOUT_WIDTH_EPSILON_PX
        }
        _ => true,
    }
}

fn timeline_turn_duration_end(turn_complete: bool, ended_at_ms: Option<i64>) -> Option<i64> {
    turn_complete.then_some(ended_at_ms).flatten()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AgentGenerationPhase {
    Preparing,
    Thinking,
    CallingTool,
    Generating,
    WaitingForApproval,
}

#[derive(Debug)]
struct AgentGenerationStats {
    turn_id: String,
    started_at_ms: i64,
    output_token_baseline: Option<u64>,
    estimated_output_chars: Option<usize>,
    compaction_count: Option<usize>,
    last_generated_tokens: Option<u64>,
    last_token_sample_at: Instant,
    tokens_per_second: Option<f32>,
}

impl AgentGenerationStats {
    fn new(
        turn_id: String,
        started_at_ms: i64,
        output_token_baseline: Option<u64>,
        compaction_count: usize,
    ) -> Self {
        Self {
            turn_id,
            started_at_ms,
            output_token_baseline,
            estimated_output_chars: None,
            compaction_count: Some(compaction_count),
            last_generated_tokens: None,
            last_token_sample_at: Instant::now(),
            tokens_per_second: None,
        }
    }
}

fn agent_generation_phase(turn: &TimelineConversationTurn) -> AgentGenerationPhase {
    if turn.pending_permission {
        return AgentGenerationPhase::WaitingForApproval;
    }

    let latest_streaming_row = turn
        .conclusion_row
        .iter()
        .chain(turn.process_rows.iter().rev())
        .find(|row| row.streaming);
    match latest_streaming_row.map(|row| row.kind) {
        Some(TimelineRowKind::AgentMessage) => AgentGenerationPhase::Generating,
        Some(
            TimelineRowKind::ToolCall
            | TimelineRowKind::Command
            | TimelineRowKind::FileOperation
            | TimelineRowKind::WebSearch
            | TimelineRowKind::Collaboration
            | TimelineRowKind::ImageGeneration,
        ) => AgentGenerationPhase::CallingTool,
        Some(TimelineRowKind::Reasoning) => AgentGenerationPhase::Thinking,
        Some(_) | None if turn.live_status.is_some() => AgentGenerationPhase::Thinking,
        Some(_) | None => AgentGenerationPhase::Preparing,
    }
}

/// The plain word a running turn's phase reads as.
///
/// This is the fixed vocabulary. The information bar above the composer draws
/// these words as they stand — `准备中`, `思考中`, `调用工具`, `生成中` — and
/// the timeline's pending row closes them with the single ellipsis that marks
/// work still going. Keeping the mark out of the table is what lets the row
/// wear it exactly once, and it is the whole set of words the bar may state:
/// the runtime's own line is deliberately not one of them.
///
/// The waiting-for-approval arm is a stopped turn rather than an in-progress
/// one, and neither surface renders it: an unanswered request is answered from
/// `agent_waiting_confirmation` first, by the bar and by the row.
fn agent_generation_phase_label(
    phase: AgentGenerationPhase,
    locale: locale::ResolvedLocale,
) -> &'static str {
    match (phase, locale) {
        (AgentGenerationPhase::Preparing, locale::ResolvedLocale::En) => "Preparing",
        (AgentGenerationPhase::Preparing, locale::ResolvedLocale::ZhCn) => "准备中",
        (AgentGenerationPhase::Preparing, locale::ResolvedLocale::ZhTw) => "準備中",
        (AgentGenerationPhase::Thinking, locale::ResolvedLocale::En) => "Thinking",
        (AgentGenerationPhase::Thinking, locale::ResolvedLocale::ZhCn) => "思考中",
        (AgentGenerationPhase::Thinking, locale::ResolvedLocale::ZhTw) => "思考中",
        (AgentGenerationPhase::CallingTool, locale::ResolvedLocale::En) => "Calling tool",
        (AgentGenerationPhase::CallingTool, locale::ResolvedLocale::ZhCn) => "调用工具",
        (AgentGenerationPhase::CallingTool, locale::ResolvedLocale::ZhTw) => "呼叫工具",
        (AgentGenerationPhase::Generating, locale::ResolvedLocale::En) => "Generating",
        (AgentGenerationPhase::Generating, locale::ResolvedLocale::ZhCn) => "生成中",
        (AgentGenerationPhase::Generating, locale::ResolvedLocale::ZhTw) => "生成中",
        (AgentGenerationPhase::WaitingForApproval, locale::ResolvedLocale::En) => {
            "Waiting for approval"
        }
        (AgentGenerationPhase::WaitingForApproval, locale::ResolvedLocale::ZhCn) => "等待确认",
        (AgentGenerationPhase::WaitingForApproval, locale::ResolvedLocale::ZhTw) => "等待確認",
    }
}

/// The words a running turn does its work in, as the timeline's pending row
/// draws them.
///
/// The runtime's own line when it has written one, the turn's phase otherwise.
/// The row is the surface that says work is still arriving, so it closes this
/// unbounded wording with the one ellipsis its pending indicator wears
/// ([`agent_progress_label`]).
///
/// The information bar above the composer deliberately does not read this
/// projection. The runtime's line streams the model's own words while it
/// thinks, and a bar that echoed them would draw a half-written sentence of
/// reasoning where the reader expects the turn's phase; it states the fixed
/// vocabulary alone ([`agent_generation_status_label`]).
fn agent_live_progress_text(
    turn: &TimelineConversationTurn,
    locale: locale::ResolvedLocale,
) -> String {
    if turn.pending_permission {
        // Waiting on the reader replaces the phase: nothing is progressing
        // until the request is answered.
        return locale::strings(locale)
            .agent_waiting_confirmation
            .to_string();
    }
    match turn.live_status.as_deref().map(str::trim) {
        Some(activity) if !activity.is_empty() => activity.to_string(),
        _ => agent_generation_phase_label(agent_generation_phase(turn), locale).to_string(),
    }
}

/// The fixed word the information bar above the composer states for `turn`.
///
/// The bar is the phase surface, not the activity surface: it names one of the
/// words in [`agent_generation_phase_label`] and never the runtime's own line.
/// That line carries the model's half-written words while it thinks, and a cut
/// sentence of its reasoning belongs to the timeline's pending row
/// ([`agent_live_progress_text`]) — the two surfaces read differently on
/// purpose, so the bar is never mistaken for the row's loading text.
///
/// Waiting on the reader is the one phrase that is not a phase word: the turn
/// has stopped, and nothing progresses until the request is answered. The bar
/// states it plainly, without the mark the row wears.
fn agent_generation_status_label(
    turn: &TimelineConversationTurn,
    locale: locale::ResolvedLocale,
) -> String {
    if turn.pending_permission {
        return locale::strings(locale)
            .agent_waiting_confirmation
            .trim_end_matches(['.', '…'])
            .trim_end()
            .to_string();
    }
    agent_generation_phase_label(agent_generation_phase(turn), locale).to_string()
}

fn agent_generation_tool_call_count(turn: &TimelineConversationTurn) -> usize {
    turn.process_rows
        .iter()
        .filter(|row| {
            matches!(
                row.kind,
                TimelineRowKind::ToolCall
                    | TimelineRowKind::Command
                    | TimelineRowKind::FileOperation
                    | TimelineRowKind::WebSearch
                    | TimelineRowKind::Collaboration
                    | TimelineRowKind::ImageGeneration
            )
        })
        .count()
}

fn agent_generation_compaction_count(
    turn: &TimelineConversationTurn,
    timeline_items: &[TimelineItem],
) -> usize {
    let Some((start_sequence, projected_end_sequence)) = timeline_turn_sequence_range(turn) else {
        return 0;
    };
    let end_sequence = if timeline_turn_finished(turn) {
        projected_end_sequence
    } else {
        timeline_items
            .last()
            .map_or(projected_end_sequence, |item| {
                projected_end_sequence.max(item.sequence)
            })
    };
    let start_index = timeline_items.partition_point(|item| item.sequence < start_sequence);
    let end_index = timeline_items.partition_point(|item| item.sequence <= end_sequence);
    timeline_items[start_index..end_index]
        .iter()
        .filter(|item| {
            matches!(
                &item.payload,
                TimelinePayload::SystemNotice(notice) if notice.is_context_compaction()
            )
        })
        .count()
}

fn timeline_turn_file_changes_cache_sequence(turn: &TimelineConversationTurn) -> i64 {
    turn.process_rows
        .iter()
        .chain(turn.conclusion_row.iter())
        .filter(|row| row.kind == TimelineRowKind::FileOperation)
        .map(|row| row.last_sequence)
        .max()
        .unwrap_or_default()
}

fn turn_file_changes_line_counts(summary: &TurnFileChangesSummary) -> Option<(usize, usize)> {
    summary
        .files
        .iter()
        .any(|file| file.has_line_counts)
        .then_some((
            summary.files.iter().map(|file| file.added_lines).sum(),
            summary.files.iter().map(|file| file.removed_lines).sum(),
        ))
}

fn estimated_agent_output_chars(turn: &TimelineConversationTurn) -> Option<usize> {
    // Reasoning deltas are model output too. In Timeline mode they stream into
    // `process_rows`; in LatestAtBottom mode streaming reasoning rows are
    // filtered out and the text only accumulates in `live_status`. The two
    // sources overlap, so `live_status` is counted only when no reasoning row
    // already carries the stream, otherwise the tail would be double-counted.
    let mut streaming_reasoning_row_present = false;
    let mut output_chars = 0usize;
    for row in turn.process_rows.iter().chain(turn.conclusion_row.iter()) {
        match row.kind {
            TimelineRowKind::AgentMessage => output_chars += row.body.chars().count(),
            TimelineRowKind::Reasoning => {
                streaming_reasoning_row_present |= row.streaming;
                output_chars += row.body.chars().count();
            }
            _ => {}
        }
    }
    if !streaming_reasoning_row_present && let Some(status) = turn.live_status.as_deref() {
        output_chars += status.chars().count();
    }
    (output_chars > 0).then_some(output_chars)
}

#[cfg(test)]
fn estimated_agent_output_tokens(turn: &TimelineConversationTurn) -> Option<u64> {
    estimated_agent_output_chars(turn)
        .map(|output_chars| (output_chars as u64).saturating_add(3) / 4)
}

#[cfg(test)]
fn agent_generation_output_tokens(
    turn: &TimelineConversationTurn,
    output_tokens: Option<u64>,
    output_token_baseline: Option<u64>,
) -> Option<u64> {
    let reported = match (output_tokens, output_token_baseline) {
        (Some(current), Some(baseline)) => {
            current.checked_sub(baseline).filter(|tokens| *tokens > 0)
        }
        (Some(current), None) if current > 0 => Some(current),
        _ => None,
    };
    reported.or_else(|| estimated_agent_output_tokens(turn))
}

fn agent_generation_token_rate(
    previous_tokens: Option<u64>,
    current_tokens: Option<u64>,
    elapsed: Duration,
) -> Option<f32> {
    let (Some(previous), Some(current)) = (previous_tokens, current_tokens) else {
        return None;
    };
    let elapsed_seconds = elapsed.as_secs_f32();
    (current > previous && elapsed_seconds > 0.0)
        .then_some((current - previous) as f32 / elapsed_seconds)
}

fn timeline_session_state_for_render(
    selected_session_id: Option<&VibexSessionId>,
    timeline_session_id: Option<&VibexSessionId>,
    agent_loading: bool,
    session_state: Option<AgentSessionState>,
) -> Option<AgentSessionState> {
    if agent_loading || selected_session_id != timeline_session_id {
        None
    } else {
        session_state
    }
}

/// Whether the turn is over for display.
///
/// A superseded turn never receives another item — a queued message was
/// steered into it or interrupted it — so it must stop counting time and stop
/// showing the live indicator even though it has no terminal response of its
/// own.
fn timeline_turn_finished(turn: &TimelineConversationTurn) -> bool {
    turn.complete || turn.superseded
}

fn timeline_turn_process_expanded(
    turn: &TimelineConversationTurn,
    explicit_expansion: Option<bool>,
) -> bool {
    // A superseded turn keeps its process visible: the work it already did is
    // the only record of what the queued message replaced.
    explicit_expansion.unwrap_or(
        timeline_turn_conclusion_row(turn).is_none() && (!turn.complete || turn.superseded),
    )
}

fn timeline_turn_conclusion_row(turn: &TimelineConversationTurn) -> Option<&TimelineRow> {
    turn.conclusion_row
        .as_ref()
        .filter(|row| !row.body.trim().is_empty())
}

/// Placeholder rows for the session-search overlay while its index is cold.
///
/// The index is built by fetching every stale session's timeline, which takes
/// seconds on a long history, so without this the body claims "no results" for
/// a query that is still being indexed. Rows reuse
/// [`COMMAND_PALETTE_SESSION_ROW_HEIGHT`], the pitch of the virtual list that
/// replaces them. An empty query is answered synchronously from the in-memory
/// session list, so it never reaches this.
fn skeleton_session_search(cx: &App) -> AnyElement {
    /// Title and detail length per row, as fractions of the row body.
    const TITLES: [f32; 5] = [0.46, 0.62, 0.38, 0.54, 0.44];
    const DETAILS: [f32; 5] = [0.78, 0.56, 0.84, 0.62, 0.70];
    v_flex()
        .flex_1()
        .min_h_0()
        .w_full()
        .overflow_hidden()
        .children((0..COMMAND_PALETTE_LOADING_ROWS).map(|row| {
            h_flex()
                .w_full()
                .min_w_0()
                .h(px(COMMAND_PALETTE_SESSION_ROW_HEIGHT))
                .flex_none()
                .items_center()
                .gap_3()
                .px_4()
                .child(skeleton::skeleton_bar(16.0, 0.05, cx))
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap_2()
                        .child(skeleton::skeleton_bar(12.0, TITLES[row % TITLES.len()], cx))
                        .child(skeleton::skeleton_bar(
                            10.0,
                            DETAILS[row % DETAILS.len()],
                            cx,
                        )),
                )
        }))
        .into_any_element()
}

/// Placeholder turns for a cold session open.
///
/// `select_session_with_history` clears the timeline and sets `agent_loading`,
/// so the center pane holds nothing until the authoritative fetch lands. A
/// cached switch never reaches this: `restore_agent_session_view` renders the
/// cached turns and clears the flag instead. Turn heights are measured and
/// virtualized, so the placeholder approximates a short conversation rather
/// than predicting it — it must never write into the row-size table.
fn skeleton_conversation(
    content_max_width: Option<f32>,
    strings: &'static Strings,
    cx: &App,
) -> AnyElement {
    /// Per turn: the User bubble's width, then the Agent answer's line widths,
    /// as fractions of the content column. A zero ends the answer.
    const TURNS: [(f32, [f32; 3]); 2] = [(0.42, [0.94, 0.86, 0.52]), (0.56, [0.90, 0.72, 0.0])];
    let mut column = v_flex().w_full().min_w_0().gap_8();
    for (bubble_width, answer_widths) in TURNS {
        column = column
            .child(
                v_flex().w_full().min_w_0().items_end().child(
                    v_flex()
                        .w(relative(bubble_width))
                        .min_w_0()
                        .gap_2()
                        .child(skeleton::skeleton_bar(12.0, 1.0, cx))
                        .child(skeleton::skeleton_bar(12.0, 0.66, cx)),
                ),
            )
            .child(
                v_flex().w_full().min_w_0().items_start().gap_2().children(
                    answer_widths
                        .into_iter()
                        .filter(|width| *width > 0.0)
                        .map(|width| skeleton::skeleton_bar(12.0, width, cx)),
                ),
            );
    }
    v_flex()
        .size_full()
        .min_h_0()
        .min_w_0()
        .overflow_hidden()
        .px_4()
        .py_4()
        .gap_3()
        .child(
            // The placeholder explains the shape; this line says which wait it
            // is, and carries the state for assistive technology.
            h_flex()
                .w_full()
                .flex_none()
                .items_center()
                .gap_2()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(Spinner::new().xsmall())
                .child(strings.agent_loading_session),
        )
        .child(
            h_flex().w_full().min_w_0().justify_center().child(
                v_flex()
                    .w_full()
                    .min_w_0()
                    .when_some(content_max_width, |this, max| this.max_w(px(max)))
                    .child(column),
            ),
        )
        .into_any_element()
}

fn timeline_streaming_agent_row<'a>(
    turn: &'a TimelineConversationTurn,
    row_id: &str,
) -> Option<&'a TimelineRow> {
    turn.conclusion_row
        .iter()
        .chain(turn.process_rows.iter().rev())
        .find(|row| row.id == row_id && row.kind == TimelineRowKind::AgentMessage && row.streaming)
}

fn timeline_streaming_reasoning_row<'a>(
    turn: &'a TimelineConversationTurn,
    row_id: &str,
) -> Option<&'a TimelineRow> {
    turn.process_rows
        .iter()
        .rev()
        .find(|row| row.id == row_id && row.kind == TimelineRowKind::Reasoning && row.streaming)
}

fn streaming_timeline_row_body_len(
    turn: &TimelineConversationTurn,
    state: &StreamingRowStateCache,
) -> Option<usize> {
    if state.row_id == format!("reasoning-live:{}", turn.id) {
        return turn.live_status.as_ref().map(String::len);
    }
    timeline_streaming_agent_row(turn, &state.row_id)
        .or_else(|| timeline_streaming_reasoning_row(turn, &state.row_id))
        .map(|row| row.body.len())
}

fn show_agent_answer_actions(conversation_conclusion: bool, row: &TimelineRow) -> bool {
    conversation_conclusion && !row.streaming && !row.body.is_empty()
}

/// Whether a row holds conversation text the find bar and the session search
/// index may match.
///
/// Search covers prose only: what the user wrote, what the agent answered, and
/// the reasoning or plan text behind it. Tool calls, commands, file operations,
/// notices and the cards around them are activity, not searchable content, so a
/// query never lands on a tool name or a command line.
fn timeline_row_is_search_text(kind: TimelineRowKind) -> bool {
    matches!(
        kind,
        TimelineRowKind::UserMessage
            | TimelineRowKind::AgentMessage
            | TimelineRowKind::Reasoning
            | TimelineRowKind::Plan
    )
}

fn session_search_documents(items: &[TimelineItem]) -> Vec<SessionSearchDocument> {
    let timestamps = items
        .iter()
        .map(|item| (item.id.to_string(), item.timestamp_ms))
        .collect::<BTreeMap<_, _>>();
    let mut documents = Vec::new();
    for turn in timeline_conversation_turns(items, Some(AgentSessionState::Idle), false) {
        for row in turn
            .user_row
            .into_iter()
            .chain(turn.process_rows)
            .chain(turn.conclusion_row)
        {
            if !timeline_row_is_search_text(row.kind) {
                continue;
            }
            let text = session_search_row_text(&row);
            if text.is_empty() {
                continue;
            }
            let item_id = row.item_ids.last().cloned();
            let timestamp_ms = item_id
                .as_deref()
                .and_then(|id| timestamps.get(id).copied())
                .unwrap_or_default();
            documents.push(SessionSearchDocument {
                turn_id: turn.id.clone(),
                item_id,
                first_sequence: row.first_sequence,
                timestamp_ms,
                text,
            });
        }
    }
    documents
}

/// Scans one query over a snapshot of the search index.
///
/// Pure, so the dialog can run it off the UI thread: the walk covers every
/// indexed document, and doing it in `render` meant paying it once per frame.
/// `sessions` arrives already ordered by recency, and `query` is already
/// normalized by [`normalized_session_search_query`].
fn session_search_scan(
    query: &str,
    sessions: &[SessionSearchScanSession],
) -> Vec<SessionSearchResult> {
    let mut results = Vec::new();
    for session in sessions {
        if query.is_empty() {
            results.push(SessionSearchResult {
                session_id: session.session_id.clone(),
                agent_id: session.agent_id.clone(),
                session_title: session.session_title.clone(),
                project_name: session.project_name.clone(),
                last_message_at_ms: session.last_message_at_ms,
                excerpt: None,
                target: None,
            });
            continue;
        }
        if !session_search_match_ranges(&session.session_title, query).is_empty() {
            results.push(SessionSearchResult {
                session_id: session.session_id.clone(),
                agent_id: session.agent_id.clone(),
                session_title: session.session_title.clone(),
                project_name: session.project_name.clone(),
                last_message_at_ms: session.last_message_at_ms,
                excerpt: None,
                target: None,
            });
            if results.len() >= SESSION_SEARCH_RESULT_LIMIT {
                return results;
            }
        }
        for document in session.documents.iter().rev() {
            let Some(excerpt) = session_search_excerpt(&document.text, query) else {
                continue;
            };
            results.push(SessionSearchResult {
                session_id: session.session_id.clone(),
                agent_id: session.agent_id.clone(),
                session_title: session.session_title.clone(),
                project_name: session.project_name.clone(),
                last_message_at_ms: if document.timestamp_ms > 0 {
                    document.timestamp_ms
                } else {
                    session.last_message_at_ms
                },
                excerpt: Some(excerpt),
                target: Some(SessionSearchTarget {
                    session_id: session.session_id.clone(),
                    turn_id: document.turn_id.clone(),
                    item_id: document.item_id.clone(),
                    first_sequence: document.first_sequence,
                }),
            });
            if results.len() >= SESSION_SEARCH_RESULT_LIMIT {
                return results;
            }
        }
    }
    results
}

fn session_search_row_text(row: &TimelineRow) -> String {
    let title = row.title.trim();
    let body = row.body.trim();
    match (title.is_empty(), body.is_empty(), title == body) {
        (true, true, _) => String::new(),
        (false, true, _) | (false, false, true) => title.to_string(),
        (true, false, _) => body.to_string(),
        (false, false, false) => format!("{title} {body}"),
    }
}

fn normalized_session_search_query(query: &str) -> String {
    query
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase()
}

fn session_search_match_ranges_with_limit(
    text: &str,
    query: &str,
    limit: usize,
) -> Vec<Range<usize>> {
    if text.is_empty() || query.is_empty() || limit == 0 {
        return Vec::new();
    }

    let folded_query = query.to_lowercase();
    if folded_query.is_empty() {
        return Vec::new();
    }

    // Case folding only moves offsets for cased characters, and most indexed
    // text is either ASCII or has no case at all (CJK). Searching in place
    // avoids copying the whole document plus a per-character offset map for
    // every document a scan touches.
    if text.is_ascii() && folded_query.is_ascii() {
        return ascii_case_insensitive_match_ranges(text, folded_query.as_bytes(), limit);
    }
    if !text.chars().any(char::is_uppercase) {
        return merge_session_search_ranges(
            text.match_indices(&folded_query)
                .take(limit)
                .map(|(start, matched)| start..start + matched.len()),
        );
    }

    session_search_folded_match_ranges(text, &folded_query, limit)
}

/// Byte ranges of the first `limit` case-insensitive occurrences of an ASCII
/// `folded_query` in an ASCII `text`.
fn ascii_case_insensitive_match_ranges(
    text: &str,
    folded_query: &[u8],
    limit: usize,
) -> Vec<Range<usize>> {
    let haystack = text.as_bytes();
    let mut ranges: Vec<Range<usize>> = Vec::new();
    let mut index = 0;
    while ranges.len() < limit && index + folded_query.len() <= haystack.len() {
        if haystack[index..index + folded_query.len()].eq_ignore_ascii_case(folded_query) {
            ranges.push(index..index + folded_query.len());
            index += folded_query.len();
        } else {
            index += 1;
        }
    }
    ranges
}

fn merge_session_search_ranges(ranges: impl Iterator<Item = Range<usize>>) -> Vec<Range<usize>> {
    let mut merged: Vec<Range<usize>> = Vec::new();
    for next in ranges {
        if let Some(last) = merged.last_mut()
            && last.end >= next.start
        {
            last.end = last.end.max(next.end);
        } else {
            merged.push(next);
        }
    }
    merged
}

/// Folds the whole document before searching, for text where case folding can
/// change offsets. Only mixed-case non-ASCII documents reach this path.
fn session_search_folded_match_ranges(
    text: &str,
    folded_query: &str,
    limit: usize,
) -> Vec<Range<usize>> {
    let mut folded_text = String::new();
    let mut character_ranges = Vec::new();
    for (original_start, character) in text.char_indices() {
        let folded_start = folded_text.len();
        folded_text.extend(character.to_lowercase());
        character_ranges.push((
            folded_start..folded_text.len(),
            original_start..original_start + character.len_utf8(),
        ));
    }

    let mut ranges: Vec<Range<usize>> = Vec::new();
    for (folded_start, _) in folded_text.match_indices(folded_query).take(limit) {
        let folded_end = folded_start + folded_query.len();
        let first_character =
            character_ranges.partition_point(|(folded, _)| folded.end <= folded_start);
        let last_character =
            character_ranges.partition_point(|(folded, _)| folded.start < folded_end);
        if first_character >= character_ranges.len() || last_character == 0 {
            continue;
        }
        let next =
            character_ranges[first_character].1.start..character_ranges[last_character - 1].1.end;
        if let Some(last) = ranges.last_mut()
            && last.end >= next.start
        {
            last.end = last.end.max(next.end);
        } else {
            ranges.push(next);
        }
    }
    ranges
}

/// Every case-insensitive occurrence of `query` in `text`.
///
/// Shared with the code workbench, whose previews search their rendered text
/// with the folding the conversation's find already uses.
pub(crate) fn session_search_match_ranges(text: &str, query: &str) -> Vec<Range<usize>> {
    session_search_match_ranges_with_limit(text, query, usize::MAX)
}

/// Collapses whitespace runs without the intermediate word vector that
/// `split_whitespace().collect::<Vec<_>>().join(" ")` builds per document.
fn compact_session_search_text(text: &str) -> String {
    let mut compact = String::with_capacity(text.len());
    for word in text.split_whitespace() {
        if !compact.is_empty() {
            compact.push(' ');
        }
        compact.push_str(word);
    }
    compact
}

fn session_search_excerpt(text: &str, normalized_query: &str) -> Option<String> {
    let compact = compact_session_search_text(text);
    if compact.is_empty() {
        return None;
    }
    let match_range = session_search_match_ranges_with_limit(&compact, normalized_query, 1)
        .into_iter()
        .next()?;
    let match_char = compact[..match_range.start].chars().count();
    let query_chars = compact[match_range].chars().count();
    let chars = compact.chars().collect::<Vec<_>>();
    let context = SESSION_SEARCH_EXCERPT_MAX_CHARS.saturating_sub(query_chars) / 2;
    let start = match_char.saturating_sub(context);
    let end = (match_char + query_chars + context).min(chars.len());
    let mut excerpt = chars[start..end].iter().collect::<String>();
    if start > 0 {
        excerpt.insert_str(0, "...");
    }
    if end < chars.len() {
        excerpt.push_str("...");
    }
    Some(excerpt)
}

fn session_search_highlighted_text(
    text: String,
    query: &str,
    highlight: HighlightStyle,
) -> StyledText {
    let highlights = session_search_match_ranges(&text, query)
        .into_iter()
        .map(|range| (range, highlight));
    StyledText::new(text).with_highlights(highlights)
}

/// Style painted behind one matched keyword.
///
/// Only the keyword is tinted — never the message around it — and the find
/// bar's current match is painted stronger than the other hits, so the row the
/// bar scrolled to stays identifiable inside a wall of text.
pub(crate) fn session_search_keyword_highlight(active: bool, cx: &App) -> HighlightStyle {
    HighlightStyle {
        background_color: Some(cx.theme().warning.opacity(if active { 0.65 } else { 0.42 })),
        font_weight: Some(FontWeight::BOLD),
        ..Default::default()
    }
}

/// Where one match sits inside a row's text, as a 0..=1 fraction.
///
/// A row taller than the viewport cannot be revealed whole, so the reveal aims
/// at this position rather than at the row's top: the keyword a long answer
/// buries in its middle is exactly what the find bar is looking for.
/// `ordinal` is which occurrence inside the row the find bar is on, so stepping
/// through several hits in one message walks down the message.
fn session_search_match_aim(text: &str, query: &str, ordinal: usize) -> f32 {
    let ranges = session_search_match_ranges(text, query);
    let Some(range) = ranges.get(ordinal).or_else(|| ranges.first()) else {
        return 0.0;
    };
    // Characters, not bytes: a byte offset would overstate how far into a CJK
    // row the match sits, and those rows are the common case here.
    let characters_before = text[..range.start].chars().count();
    let total = text.chars().count();
    if total == 0 {
        return 0.0;
    }
    characters_before as f32 / total as f32
}

/// The smallest vertical scroll delta that puts a match row in view, leaving a
/// margin so the revealed row is not flush against the edge.
///
/// `aim` is where inside the row the keyword sits (see
/// [`session_search_match_aim`]). A row taller than the viewport cannot be
/// shown whole, so the keyword is placed in the upper quarter instead of the
/// row's top. `px(0.0)` means the row is already visible.
fn session_search_reveal_delta(
    bounds: Bounds<Pixels>,
    viewport: Bounds<Pixels>,
    aim: f32,
) -> Pixels {
    const REVEAL_MARGIN: f32 = 24.0;
    /// How far down the viewport an aimed keyword lands.
    const REVEAL_AIM_FRACTION: f32 = 0.25;
    let margin = px(REVEAL_MARGIN);
    let visible_top = viewport.top() + margin;
    let visible_bottom = viewport.bottom() - margin;
    let visible_height = visible_bottom - visible_top;
    if bounds.size.height > visible_height {
        let aimed = bounds.top() + bounds.size.height * aim.clamp(0.0, 1.0);
        return visible_top + visible_height * REVEAL_AIM_FRACTION - aimed;
    }
    if bounds.top() < visible_top {
        visible_top - bounds.top()
    } else if bounds.bottom() > visible_bottom {
        visible_bottom - bounds.bottom()
    } else {
        px(0.0)
    }
}

fn agent_turn_is_active(
    agent_turn_pending: bool,
    session_state: Option<AgentSessionState>,
) -> bool {
    agent_turn_pending
        || matches!(
            session_state,
            Some(AgentSessionState::Running | AgentSessionState::NeedsInput)
        )
}

fn reorder_composer_queue_message(
    queue: &mut Vec<ComposerQueueMessage>,
    message_id: u64,
    target_id: u64,
    after: bool,
) -> bool {
    if message_id == target_id {
        return false;
    }
    let Some(source_index) = queue.iter().position(|message| message.id == message_id) else {
        return false;
    };
    let Some(target_session_id) = queue
        .iter()
        .find(|message| message.id == target_id)
        .map(|message| message.session_id.clone())
    else {
        return false;
    };
    if queue[source_index].session_id != target_session_id {
        return false;
    }
    let message = queue.remove(source_index);
    let Some(target_index) = queue.iter().position(|queued| queued.id == target_id) else {
        queue.push(message);
        return false;
    };
    queue.insert(target_index + usize::from(after), message);
    true
}

fn promote_composer_queue_message(
    queue: &mut Vec<ComposerQueueMessage>,
    message_id: u64,
) -> Option<VibexSessionId> {
    let source_index = queue.iter().position(|message| message.id == message_id)?;
    let mut message = queue.remove(source_index);
    // Promoting a message is the explicit send-now action. The queue is one
    // ordered list, so the message the reader sent now becomes its head instead
    // of the first row of its own session: an explicit send is the one thing
    // that is allowed to jump the order, and it has to jump all of it.
    message.scheduled_at_ms = None;
    let session_id = message.session_id.clone();
    queue.insert(0, message);
    Some(session_id)
}

fn composer_queue_auto_send_enabled(
    manual_session_ids: &BTreeSet<String>,
    session_id: &VibexSessionId,
) -> bool {
    !manual_session_ids.contains(session_id.as_str())
}

fn composer_queue_dispatch_enabled(
    manual_session_ids: &BTreeSet<String>,
    session_id: &VibexSessionId,
    behavior: ComposerQueueDispatchBehavior,
) -> bool {
    matches!(
        behavior,
        ComposerQueueDispatchBehavior::ForceNext | ComposerQueueDispatchBehavior::AfterInterrupt
    ) || composer_queue_auto_send_enabled(manual_session_ids, session_id)
}

fn composer_queue_session_blocks_dispatch(
    behavior: ComposerQueueDispatchBehavior,
    local_turn_pending: bool,
    session_state: Option<AgentSessionState>,
) -> bool {
    let session_blocks = match behavior {
        // A schedule is a promise about a moment in time, so only a turn that
        // is actually occupying the Agent — or a session that can no longer
        // take work — may hold it back. `Initializing` and an unknown snapshot
        // are not work in progress: a deferred new session waits in exactly
        // that state until its first message is submitted, and treating it as
        // busy stranded the very message that would start it.
        ComposerQueueDispatchBehavior::Scheduled => matches!(
            session_state,
            Some(
                AgentSessionState::Running
                    | AgentSessionState::NeedsInput
                    | AgentSessionState::Closed
                    | AgentSessionState::Archived
            )
        ),
        ComposerQueueDispatchBehavior::AfterInterrupt => false,
        // The submission handoff is no longer allowed to guess that a lagging
        // `Running` snapshot is stale: the queue waits for a turn that actually
        // ended normally, and the dispatch fence is what proves a turn already
        // finished when the snapshot is the only thing still saying otherwise.
        ComposerQueueDispatchBehavior::AfterCompletion
        | ComposerQueueDispatchBehavior::Automatic
        | ComposerQueueDispatchBehavior::ForceNext
        | ComposerQueueDispatchBehavior::ExplicitSend => {
            matches!(
                session_state,
                Some(AgentSessionState::Running | AgentSessionState::NeedsInput)
            )
        }
    };
    local_turn_pending || session_blocks
}

/// Whether an auto-dispatched queued message must wait for the latest turn to
/// settle.
///
/// `cached_turn_status` is the completion probe for the session's current
/// revision:
/// - `None` means the outcome has not been observed yet. Auto-send waits rather
///   than guessing, so a session that stopped abnormally can never auto-send.
/// - `Some(None)` means the session has no conversational turn to continue.
/// - `Some(Some(ended_normally))` is the probe's answer.
///
/// Waiting only defers the message: the queue stays armed and is re-evaluated
/// once a later turn is confirmed to have completed normally. It never pauses
/// the queue, because that state is reserved for an explicit user interrupt.
///
/// Explicit actions (`ForceNext`, `AfterInterrupt`, `ExplicitSend`) bypass the
/// wait because the user asked for that message to go out.
fn composer_queue_waits_for_continuation(
    behavior: ComposerQueueDispatchBehavior,
    session_state: Option<AgentSessionState>,
    cached_turn_status: Option<Option<bool>>,
) -> bool {
    if !matches!(
        behavior,
        ComposerQueueDispatchBehavior::Automatic | ComposerQueueDispatchBehavior::AfterCompletion
    ) {
        return false;
    }
    let Some(state) = session_state else {
        return false;
    };
    if !matches!(state, AgentSessionState::Idle | AgentSessionState::Error) {
        return false;
    }
    match cached_turn_status {
        // This session revision has not been probed yet. Wait for the probe
        // instead of risking an auto-send after an abnormal stop.
        None => true,
        // The probe found no conversational turn, so there is nothing to wait for.
        Some(None) => false,
        // Only a confirmed normal completion may auto-send.
        Some(Some(ended_normally)) => !ended_normally,
    }
}

/// Whether a dispatch behavior is the reader's own instruction about one
/// message.
///
/// An explicit send is the one gesture allowed to overtake the queue and its
/// dispatch fence. A head that carries a deadline is always dispatched as
/// `Scheduled`, so a schedule never inherits this bypass and always waits for
/// the entries in front of it.
fn composer_queue_behavior_is_explicit(behavior: ComposerQueueDispatchBehavior) -> bool {
    matches!(
        behavior,
        ComposerQueueDispatchBehavior::ForceNext
            | ComposerQueueDispatchBehavior::AfterInterrupt
            | ComposerQueueDispatchBehavior::ExplicitSend
    )
}

/// Whether the message the pre-send queue handed over last is still holding it
/// back.
///
/// The queue is one ordered list and advances one message at a time: after an
/// entry leaves it, the entries behind it wait while that message's turn still
/// occupies its session — a local submission in flight, a running or parked
/// Agent, or a session that has not settled yet. The judgment is the session's
/// own state, never an asynchronous probe: a fence the workbench cannot resolve
/// would strand every message behind it, including messages of other sessions,
/// which is exactly what the queue must never do. A settled session
/// (`Idle`/`Error`), a closed or archived one, and one the workbench no longer
/// tracks all stop holding the queue.
fn composer_queue_fence_waits(
    turn_pending: bool,
    session_state: Option<AgentSessionState>,
) -> bool {
    if turn_pending {
        return true;
    }
    match session_state {
        Some(AgentSessionState::Idle | AgentSessionState::Error) => false,
        Some(AgentSessionState::Closed | AgentSessionState::Archived) => false,
        // Running, `NeedsInput` and Initializing all mean a turn is, or is
        // about to be, occupying the session.
        Some(_) => true,
        None => false,
    }
}

/// How the timeline should record a queued message that is dispatched now.
///
/// The queue's resend action cancels the running turn before it delivers the
/// message, so the user item keeps that history instead of reading as an
/// ordinary prompt that happened to follow an interrupted turn.
fn composer_queue_message_delivery(behavior: ComposerQueueDispatchBehavior) -> UserMessageDelivery {
    match behavior {
        ComposerQueueDispatchBehavior::AfterInterrupt => UserMessageDelivery::Resend,
        ComposerQueueDispatchBehavior::Automatic
        | ComposerQueueDispatchBehavior::Scheduled
        | ComposerQueueDispatchBehavior::ForceNext
        | ComposerQueueDispatchBehavior::AfterCompletion
        | ComposerQueueDispatchBehavior::ExplicitSend => UserMessageDelivery::Prompt,
    }
}

#[allow(clippy::too_many_arguments)]
fn auto_continue_should_start(
    enabled: bool,
    session_state: AgentSessionState,
    latest_turn_ended_normally: Option<bool>,
    session_turn_pending: bool,
    current_turn_paused: bool,
    handled_turn_updated_at_ms: Option<i64>,
    session_updated_at_ms: i64,
    paused: bool,
) -> bool {
    enabled
        && agent_session_turn_requires_continuation(session_state, latest_turn_ended_normally)
        && !session_turn_pending
        && !current_turn_paused
        && handled_turn_updated_at_ms != Some(session_updated_at_ms)
        && !paused
}

fn restored_auto_continue_session_ids(state: &SessionUiState) -> BTreeSet<String> {
    state
        .auto_continue_session_overrides
        .iter()
        .filter(|(_, enabled)| **enabled)
        .map(|(session_id, _)| session_id.clone())
        .collect()
}

/// The one line a failover prompt reads as.
///
/// It names both Providers and the countdown, and deliberately asks nothing:
/// silence is the default, so the line states what will happen rather than
/// waiting for a reply it may never get.
fn failover_prompt_label(
    locale: locale::ResolvedLocale,
    model: &str,
    from_name: &str,
    to_name: &str,
    remaining_seconds: u8,
) -> String {
    match locale {
        locale::ResolvedLocale::En => format!(
            "Provider {from_name} failed. Switching {model} to {to_name} in {remaining_seconds}s."
        ),
        locale::ResolvedLocale::ZhCn => format!(
            "供应商 {from_name} 请求异常，{remaining_seconds} 秒后将 {model} 切换到 {to_name}。"
        ),
        locale::ResolvedLocale::ZhTw => format!(
            "供應商 {from_name} 請求異常，{remaining_seconds} 秒後將 {model} 切換到 {to_name}。"
        ),
    }
}

/// The line a completed switch leaves in the conversation.
fn failover_switched_label(
    locale: locale::ResolvedLocale,
    model: &str,
    from_name: &str,
    to_name: &str,
) -> String {
    match locale {
        locale::ResolvedLocale::En => {
            format!("Route group switched {model} from {from_name} to {to_name}.")
        }
        locale::ResolvedLocale::ZhCn => {
            format!("路由组已将 {model} 从 {from_name} 切换到 {to_name}。")
        }
        locale::ResolvedLocale::ZhTw => {
            format!("路由組已將 {model} 從 {from_name} 切換到 {to_name}。")
        }
    }
}

fn auto_continue_countdown_label(locale: locale::ResolvedLocale, remaining_seconds: u8) -> String {
    match locale {
        locale::ResolvedLocale::En => format!("Continue ({remaining_seconds}s)"),
        locale::ResolvedLocale::ZhCn => format!("继续（{remaining_seconds} 秒）"),
        locale::ResolvedLocale::ZhTw => format!("繼續（{remaining_seconds} 秒）"),
    }
}

#[derive(Clone)]
struct SidebarSessionDrag {
    session_id: VibexSessionId,
    session_ids: Vec<String>,
    workspace_id: String,
    project_id: String,
    label: SharedString,
    agent_id: String,
    pinned: bool,
    /// The group whose member row the drag started on, if any.
    ///
    /// A group paints its members from its own order, so a drag that starts on
    /// one of those rows reorders the group rather than the band of rows the
    /// placement tree puts behind it.
    group_id: Option<String>,
}

impl Render for SidebarSessionDrag {
    fn render(&mut self, _window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        h_flex()
            .w(px(SIDEBAR_DRAG_PREVIEW_WIDTH))
            .h(px(SIDEBAR_REORDER_ROW_HEIGHT))
            .min_w_0()
            .gap_2()
            .px_2()
            .rounded(px(8.0))
            .border_1()
            .border_color(cx.theme().drag_border)
            .bg(cx.theme().sidebar)
            .text_color(cx.theme().sidebar_foreground)
            .shadow_lg()
            .opacity(0.94)
            .when(self.pinned, |this| {
                this.child(
                    sidebar_icon("icons/vibex/pin.svg")
                        .size(px(12.0))
                        .text_color(cx.theme().warning),
                )
            })
            .child(sidebar_agent_logo(&self.agent_id, false, cx))
            .child(
                div()
                    .min_w_0()
                    .flex_1()
                    .truncate()
                    .text_sm()
                    .child(self.label.clone()),
            )
            .when(self.session_ids.len() > 1, |this| {
                this.child(sidebar_drag_count_badge(self.session_ids.len(), cx))
            })
    }
}

