    fn delete_sidebar_worktree(
        &mut self,
        workspace: WorkspaceRecord,
        remove_git: bool,
        cx: &mut Context<Self>,
    ) {
        let workspace_key = workspace.id.as_str().to_string();
        if self.pending_worktree_rename_ids.contains(&workspace_key) {
            return;
        }
        if !self
            .pending_worktree_deletion_ids
            .insert(workspace_key.clone())
        {
            return;
        }
        let session_ids = self
            .sessions
            .iter()
            .filter(|session| session.workspace_id == workspace.id)
            .map(|session| session.id.clone())
            .collect::<Vec<_>>();
        let session_id_set = session_ids
            .iter()
            .map(|session_id| session_id.as_str().to_string())
            .collect::<BTreeSet<_>>();
        if !session_id_set.is_empty() {
            self.optimistically_remove_sessions(&session_id_set, SidebarSessionRemoval::Delete);
        }
        let folder_ids = self
            .ui_state
            .sidebar
            .organization
            .folders
            .iter()
            .filter(|(_, folder)| folder.workspace_id.as_deref() == Some(workspace.id.as_str()))
            .map(|(id, _)| id.clone())
            .collect::<Vec<_>>();
        for folder_id in folder_ids {
            self.ui_state.sidebar.organization.delete_folder(&folder_id);
        }
        self.workspaces
            .retain(|(_, candidate)| candidate.id != workspace.id);
        self.workspace_contexts.remove(workspace.id.as_str());
        self.ui_state
            .sidebar
            .collapsed_workspace_ids
            .remove(workspace.id.as_str());
        if self.ui_state.workbench.selected_workspace_id.as_deref() == Some(workspace.id.as_str()) {
            self.ui_state.workbench.selected_workspace_id = None;
        }
        self.queue_ui_state();
        self.reconcile_sidebar_state();
        self.publish_sidebar_invalidation();
        let Some(backend) = self.backend.clone() else {
            self.pending_worktree_deletion_ids.remove(&workspace_key);
            cx.notify();
            return;
        };
        let workspace_id = workspace.id.clone();
        let workspace_id_for_title = workspace_id.clone();
        let worktree_path = workspace.root_path.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            for session_id in session_ids {
                backend
                    .agent()
                    .delete_session(MutationRequest::new(session_id))
                    .await?;
            }
            if remove_git {
                let draft = GitWorktreeDiscardRequest {
                    workspace_id: workspace_id.clone(),
                    worktree_path,
                    force: true,
                    delete_branch: true,
                    expected_head: None,
                    preflight_revision: None,
                };
                let preflight = backend
                    .git()
                    .git_worktree_discard_preflight(draft.clone())
                    .await?;
                if !preflight.allowed {
                    return Err(BackendError::conflict(
                        "worktree_preflight_blocked",
                        "Git Worktree deletion is blocked by its current lifecycle state",
                    ));
                }
                let mut confirmed = draft;
                confirmed.expected_head = preflight.source_head;
                confirmed.preflight_revision = Some(preflight.revision);
                backend
                    .git()
                    .git_worktree_discard(MutationRequest::new(confirmed))
                    .await?;
            }
            backend
                .workspace()
                .delete_workspace(MutationRequest::new(workspace_id))
                .await
        });
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    this.pending_worktree_deletion_ids.remove(&workspace_key);
                    match outcome {
                        Ok(Ok(())) => {
                            this.ui_state
                                .sidebar
                                .worktree_titles
                                .remove(workspace_id_for_title.as_str());
                            this.queue_ui_state();
                            this.optimistic_session_deletion_reconciliation_pending = true;
                            this.load_agent_overview(cx);
                            this.refresh_workspace_contexts(cx);
                        }
                        Ok(Err(error)) => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                            this.optimistic_session_deletion_reconciliation_pending = true;
                            this.load_agent_overview(cx);
                            this.refresh_workspace_contexts(cx);
                        }
                        Err(error) => {
                            this.agent_error = Some(format!("worktree deletion failed: {error}"));
                            this.optimistic_session_deletion_reconciliation_pending = true;
                            this.load_agent_overview(cx);
                            this.refresh_workspace_contexts(cx);
                        }
                    }
                    cx.notify();
                });
            },
        )
        .detach();
        cx.notify();
    }

    fn delete_project(&mut self, project_id: ProjectId, cx: &mut Context<Self>) {
        let project_key = project_id.as_str().to_string();
        if !self
            .pending_project_deletion_ids
            .insert(project_key.clone())
        {
            return;
        }
        // The authority owns project deletion, so it rides the backend facade
        // and works identically against a local runtime or a paired remote one.
        let Some(backend) = self.backend.clone() else {
            self.pending_project_deletion_ids.remove(&project_key);
            self.agent_error = Some(
                locale::text(
                    "Project deletion is unavailable because no runtime is connected.",
                    "未连接运行时，无法删除项目。",
                    "未連線執行階段，無法刪除專案。",
                )
                .to_string(),
            );
            cx.notify();
            return;
        };
        // The sidebar drops the project (and its sessions) in the same
        // transaction that schedules the authoritative deletion, so the row
        // disappears immediately instead of waiting for the database commit
        // plus the overview reload.
        self.optimistically_remove_project(project_id.as_str());
        let generation = self.session_generation;
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .workspace()
                .delete_project(MutationRequest::new(project_id))
                .await
                .map_err(remote_error_into_vibex)
        });
        self.finish_project_deletion(generation, project_key, runner, cx);
    }

    fn finish_project_deletion(
        &mut self,
        generation: u64,
        project_key: String,
        runner: Task<Result<Result<(), vibex_core::VibexError>, tokio::task::JoinError>>,
        cx: &mut Context<Self>,
    ) {
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    this.pending_project_deletion_ids.remove(&project_key);
                    let active = this.session_generation == generation;
                    let should_reconcile = this.pending_project_deletion_ids.is_empty();
                    if should_reconcile {
                        // The cascade also removed the project's sessions
                        // server-side, so the authoritative overview is the
                        // reconciliation point for both optimistic sets. A
                        // failed deletion restores every removed row here.
                        this.optimistic_project_deletion_reconciliation_pending = true;
                        this.optimistic_session_deletion_reconciliation_pending = true;
                        this.load_agent_overview(cx);
                        this.refresh_workspace_contexts(cx);
                    }
                    match outcome {
                        Ok(Ok(())) => {}
                        Ok(Err(error)) if active => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) if active => {
                            this.agent_error = Some(format!("project deletion failed: {error}"));
                        }
                        Ok(Err(_)) | Err(_) => {}
                    }
                    cx.notify();
                });
            },
        )
        .detach();
    }

    fn optimistically_remove_project(&mut self, project_id: &str) {
        self.agent_overview_generation = self.agent_overview_generation.wrapping_add(1);
        self.optimistically_removed_project_ids
            .insert(project_id.to_string());
        let workspace_ids = self
            .workspaces
            .iter()
            .filter(|(project, _)| project.id.as_str() == project_id)
            .map(|(_, workspace)| workspace.id.clone())
            .collect::<Vec<_>>();
        let removed_session_ids = self
            .sessions
            .iter()
            .chain(self.delegated_sessions.values())
            .filter(|session| session.project_id.as_str() == project_id)
            .map(|session| session.id.as_str().to_string())
            .chain(
                self.ui_state
                    .sidebar
                    .organization
                    .groups
                    .values()
                    .filter(|group| group.project_id == project_id)
                    .flat_map(|group| group.member_session_ids.iter().cloned()),
            )
            .collect::<BTreeSet<_>>();
        self.workspaces
            .retain(|(project, _)| project.id.as_str() != project_id);
        if !removed_session_ids.is_empty() {
            self.optimistically_remove_sessions(
                &removed_session_ids,
                SidebarSessionRemoval::Delete,
            );
        }
        for workspace_id in &workspace_ids {
            self.workspace_contexts.remove(workspace_id.as_str());
            self.ui_state
                .sidebar
                .collapsed_workspace_ids
                .remove(workspace_id.as_str());
            self.ui_state
                .sidebar
                .worktree_titles
                .remove(workspace_id.as_str());
            if self.ui_state.workbench.selected_workspace_id.as_deref()
                == Some(workspace_id.as_str())
            {
                self.ui_state.workbench.selected_workspace_id = None;
            }
        }
        let folder_ids = self
            .ui_state
            .sidebar
            .organization
            .folders
            .iter()
            .filter(|(_, folder)| folder.project_id.as_deref() == Some(project_id))
            .map(|(id, _)| id.clone())
            .collect::<Vec<_>>();
        for folder_id in folder_ids {
            self.ui_state.sidebar.organization.delete_folder(&folder_id);
        }
        self.ui_state.sidebar.project_appearances.remove(project_id);
        self.ui_state
            .sidebar
            .project_location_preferences
            .remove(project_id);
        self.auto_continue_default_project_ids.remove(project_id);
        if self.sidebar_project_appearance_popover.as_deref() == Some(project_id) {
            self.sidebar_project_appearance_popover = None;
        }
        self.reconcile_sidebar_state();
        self.queue_agent_ui_state();
        self.publish_sidebar_invalidation();
    }

    fn finish_optimistic_session_deletion(
        &mut self,
        generation: u64,
        session_ids: BTreeSet<String>,
        runner: Task<Result<Result<(), vibex_core::VibexError>, tokio::task::JoinError>>,
        cx: &mut Context<Self>,
    ) {
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    let committed = matches!(outcome, Ok(Ok(())));
                    this.settle_optimistic_session_deletion(&session_ids, committed);
                    let active = this.session_generation == generation;
                    let should_reconcile = this.pending_session_deletion_ids.is_empty();
                    if should_reconcile {
                        this.optimistic_session_deletion_reconciliation_pending = true;
                        this.load_agent_overview(cx);
                    }
                    // The archived page is the surface that can still show the
                    // rows: the teardown took them off that list optimistically,
                    // so the runtime's answer decides whether they stay off (a
                    // committed deletion) or come back (a failed one). A batch of
                    // rows settles once, and the page is refreshed once with it.
                    if this.archived_sessions.is_some() {
                        this.archived_sessions = None;
                        this.load_archived_sessions(cx);
                    }
                    match outcome {
                        Ok(Ok(())) => {}
                        Ok(Err(error)) if active => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) if active => {
                            this.agent_error = Some(format!("session mutation failed: {error}"));
                        }
                        Ok(Err(_)) | Err(_) => {}
                    }
                    cx.notify();
                });
            },
        )
        .detach();
    }

    /// Applies the answer to a deletion batch to the optimistic state.
    ///
    /// A committed deletion is permanent, so its ids move into
    /// [`Self::deleted_session_ids`] and stay hidden for the rest of the
    /// process: reads that were already in flight when the runtime committed
    /// the deletion still describe the row, and the sidebar must not rebuild it
    /// from them. A failed deletion is only an optimistic removal, so the ids
    /// stop being hidden and the authoritative reload puts the rows back.
    fn settle_optimistic_session_deletion(
        &mut self,
        session_ids: &BTreeSet<String>,
        committed: bool,
    ) {
        self.pending_session_deletion_ids
            .retain(|session_id| !session_ids.contains(session_id));
        if committed {
            self.deleted_session_ids.extend(session_ids.iter().cloned());
        } else {
            self.optimistically_removed_session_ids
                .retain(|session_id| !session_ids.contains(session_id));
        }
    }

    /// Moves a session out of the sidebar without destroying it.
    ///
    /// Archive is the reversible half of removal: the row leaves the list, the
    /// runtime is released, and the timeline stays where it is, so the archived
    /// page can put it back. The row is dropped optimistically and only
    /// restored when the mutation fails.
    fn archive_session(&mut self, session_id: VibexSessionId, cx: &mut Context<Self>) {
        self.begin_session_archive(vec![session_id], cx);
    }

    /// Archives every session a right click or the batch bar selected.
    ///
    /// The rows leave the sidebar the way a deletion takes them, so the
    /// selection those rows were part of stops with them. Archive is
    /// reversible, so nothing is confirmed here: the archived page is where a
    /// mistaken archive is undone.
    fn archive_sessions(&mut self, session_ids: Vec<String>, cx: &mut Context<Self>) {
        self.sidebar_batch_mode = false;
        self.sidebar_state.clear_selection();
        self.clear_sidebar_move_selection();
        let session_ids = session_ids
            .into_iter()
            .filter_map(|session_id| VibexSessionId::parse(&session_id).ok())
            .collect::<Vec<_>>();
        self.begin_session_archive(session_ids, cx);
    }

    /// Archives every session the batch bar holds.
    fn archive_selected_sessions(&mut self, cx: &mut Context<Self>) {
        let session_ids = self
            .sidebar_state
            .selected_ids
            .iter()
            .cloned()
            .collect::<Vec<_>>();
        self.archive_sessions(session_ids, cx);
    }

    /// Archives the named sessions and drops their rows optimistically.
    ///
    /// The rows leave before the runtime answers; a failure reconciles the list
    /// back, and a success refreshes the page that holds what was archived.
    fn begin_session_archive(&mut self, session_ids: Vec<VibexSessionId>, cx: &mut Context<Self>) {
        let session_ids = session_ids
            .into_iter()
            .filter(|session_id| {
                !self
                    .pending_session_archive_ids
                    .contains(session_id.as_str())
            })
            .collect::<Vec<_>>();
        if session_ids.is_empty() {
            cx.notify();
            return;
        }
        let Some(backend) = self.backend.clone() else {
            cx.notify();
            return;
        };
        let session_id_set = session_ids
            .iter()
            .map(|session_id| session_id.as_str().to_string())
            .collect::<BTreeSet<_>>();
        self.pending_session_archive_ids
            .extend(session_id_set.iter().cloned());
        self.optimistically_remove_sessions(&session_id_set, SidebarSessionRemoval::Archive);
        self.queue_agent_ui_state();
        cx.notify();
        let generation = self.session_generation;
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let mut first_error = None;
            for session_id in session_ids {
                if let Err(error) = backend
                    .agent()
                    .archive_session(MutationRequest::new(session_id))
                    .await
                    && first_error.is_none()
                {
                    first_error = Some(remote_error_into_vibex(error));
                }
            }
            if let Some(error) = first_error {
                return Err(error);
            }
            Ok::<(), vibex_core::VibexError>(())
        });
        self.finish_optimistic_session_archive(generation, session_id_set, runner, cx);
    }

    fn finish_optimistic_session_archive(
        &mut self,
        generation: u64,
        session_ids: BTreeSet<String>,
        runner: Task<Result<Result<(), vibex_core::VibexError>, tokio::task::JoinError>>,
        cx: &mut Context<Self>,
    ) {
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    this.pending_session_archive_ids
                        .retain(|session_id| !session_ids.contains(session_id));
                    // The archive has settled, so the row stops being hidden
                    // locally: the ordinary session list omits an archived
                    // session on its own, and a restore is free to bring the
                    // row back. This runs even for a superseded generation —
                    // a stale load must not leave the id marked forever.
                    this.settle_optimistic_session_archive(&session_ids);
                    let active = this.session_generation == generation;
                    match outcome {
                        Ok(Ok(())) => {
                            // The archived page is the only surface that reads
                            // the archived list, so it is refreshed rather than
                            // reconciled with the sidebar's own load.
                            this.archived_sessions = None;
                            this.load_archived_sessions(cx);
                        }
                        Ok(Err(error)) if active => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                            this.load_agent_overview(cx);
                        }
                        Err(error) if active => {
                            this.agent_error = Some(format!("session mutation failed: {error}"));
                            this.load_agent_overview(cx);
                        }
                        Ok(Err(_)) | Err(_) => {}
                    }
                    cx.notify();
                });
            },
        )
        .detach();
    }

    /// Stops hiding the rows of an archive the runtime has answered.
    ///
    /// An archive removes the row from the sidebar without destroying it, so
    /// the local removal only lives as long as the mutation it belongs to.
    /// Leaving the ids behind would keep the session out of every later
    /// authoritative list — including the one a restore produces.
    fn settle_optimistic_session_archive(&mut self, session_ids: &BTreeSet<String>) {
        self.optimistically_archived_session_ids
            .retain(|session_id| !session_ids.contains(session_id));
    }

    /// Puts an archived session back on the sidebar.
    ///
    /// The restore is not optimistic: the authoritative snapshot decides where
    /// the row lands in recency order, so the list is reloaded once the runtime
    /// answers instead of being patched by the client.
    fn unarchive_session(&mut self, session_id: VibexSessionId, cx: &mut Context<Self>) {
        if self
            .pending_session_restore_ids
            .contains(session_id.as_str())
        {
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.pending_session_restore_ids
            .insert(session_id.as_str().to_string());
        cx.notify();
        let restore_id = session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .unarchive_session(MutationRequest::new(session_id))
                .await
                .map_err(remote_error_into_vibex)
        });
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    match outcome {
                        Ok(Ok(session)) => {
                            this.pending_session_restore_ids.remove(session.id.as_str());
                            this.archived_sessions = None;
                            this.load_archived_sessions(cx);
                            this.load_agent_overview(cx);
                        }
                        Ok(Err(error)) => {
                            this.pending_session_restore_ids.remove(restore_id.as_str());
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            this.pending_session_restore_ids.remove(restore_id.as_str());
                            this.agent_error = Some(format!("session mutation failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        )
        .detach();
    }

    /// Loads the archived-session page from the runtime.
    fn load_archived_sessions(&mut self, cx: &mut Context<Self>) {
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.archived_sessions_generation = self.archived_sessions_generation.wrapping_add(1);
        let generation = self.archived_sessions_generation;
        self.archived_sessions_loading = true;
        self.archived_sessions_error = None;
        cx.notify();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .list_archived_sessions(ARCHIVED_SESSION_PAGE_LIMIT)
                .await
        });
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.archived_sessions_generation != generation {
                        return;
                    }
                    this.archived_sessions_loading = false;
                    match outcome {
                        Ok(Ok(sessions)) => {
                            // This page is as stale-able as the sidebar list: a
                            // read issued before a deletion still carries the
                            // row, and a deleted session must not come back
                            // through the archived surface either.
                            this.archived_sessions = Some(this.filter_hidden_sessions(sessions));
                            this.archived_sessions_error = None;
                        }
                        Ok(Err(error)) => {
                            this.archived_sessions_error =
                                Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            this.archived_sessions_error =
                                Some(format!("archived sessions failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        )
        .detach();
    }

    /// Sessions the inactivity window applies to, in sidebar order.
    ///
    /// A pinned session is a deliberate keep, a session with a live turn is
    /// still working, and a delegated child belongs to its parent's timeline —
    /// none of them are candidates.
    fn auto_archive_eligible_sessions(&self) -> impl Iterator<Item = &AgentSession> {
        self.sessions
            .iter()
            .filter(|session| session.archived_at_ms.is_none() && session.deleted_at_ms.is_none())
            .filter(|session| {
                matches!(
                    session.state,
                    AgentSessionState::Idle | AgentSessionState::Error | AgentSessionState::Closed
                )
            })
            .filter(|session| !self.sidebar_state.pinned_ids.contains(session.id.as_str()))
            .filter(|session| {
                !self
                    .pending_agent_turn_session_ids
                    .contains(session.id.as_str())
            })
    }

    /// The eligible sessions that have already passed the window.
    fn auto_archive_candidates(&self, now_ms: i64) -> Vec<VibexSessionId> {
        let Some(days) = self.ui_state.session.auto_archive_after_days else {
            return Vec::new();
        };
        let cutoff_ms = now_ms.saturating_sub(i64::from(days) * AUTO_ARCHIVE_MILLIS_PER_DAY);
        self.auto_archive_eligible_sessions()
            .filter(|session| session.last_message_at_ms.max(session.created_at_ms) <= cutoff_ms)
            .map(|session| session.id.clone())
            .collect()
    }

    /// Applies the configured inactivity window once. Returns whether any
    /// session was asked to archive.
    fn apply_auto_archive_sessions(&mut self, now_ms: i64, cx: &mut Context<Self>) -> bool {
        let candidates = self.auto_archive_candidates(now_ms);
        if candidates.is_empty() {
            return false;
        }
        let archived = candidates.len();
        for session_id in candidates {
            self.archive_session(session_id, cx);
        }
        // Remembered for the page a reader is most likely to be looking at: a
        // window that was just narrowed retires its whole backlog at once, and
        // a bare list of fresh rows does not say the window is what moved them.
        if let Some(window_days) = self.ui_state.session.auto_archive_after_days {
            self.auto_archive_last_pass = Some(AutoArchivePassReport {
                window_days,
                archived,
                at_ms: now_ms,
            });
        }
        true
    }

    /// What the inactivity window is doing right now: the days it covers, how
    /// old the oldest session it can act on is, and what the last pass retired.
    ///
    /// The pass is silent by design, so an empty Archived page is otherwise
    /// indistinguishable from a window that never runs. The page reads this
    /// instead of leaving the reader to guess.
    fn auto_archive_status(&self, now_ms: i64) -> Option<AutoArchiveStatus> {
        let window_days = self.ui_state.session.auto_archive_after_days?;
        let mut eligible_sessions = 0usize;
        let mut oldest_idle_days: Option<i64> = None;
        for session in self.auto_archive_eligible_sessions() {
            eligible_sessions += 1;
            let activity_ms = session.last_message_at_ms.max(session.created_at_ms);
            let idle_days = now_ms.saturating_sub(activity_ms) / AUTO_ARCHIVE_MILLIS_PER_DAY;
            oldest_idle_days =
                Some(oldest_idle_days.map_or(idle_days, |oldest| oldest.max(idle_days)));
        }
        Some(AutoArchiveStatus {
            window_days,
            eligible_sessions,
            oldest_idle_days,
            // A report describes the window that produced it, and nothing
            // else: a reader who has since widened the window is back to
            // "nothing archived yet" rather than reading an older batch.
            last_pass: self
                .auto_archive_last_pass
                .filter(|pass| pass.window_days == window_days),
        })
    }

    /// Deletes every session the archived page is holding.
    ///
    /// The page is bounded, so "all" means all of the page the reader is
    /// looking at; the confirmation names the same count. The rows leave in one
    /// batch rather than as one deletion per row: the batch owns a single
    /// pending set, one optimistic removal and one reconciliation, so the rows
    /// go together and the page is refreshed once. Firing them individually
    /// used to leave the page depending on every request winning its own race.
    fn delete_all_archived_sessions(&mut self, cx: &mut Context<Self>) {
        let Some(sessions) = self.archived_sessions.clone() else {
            return;
        };
        let session_ids = sessions
            .into_iter()
            .map(|session| session.id.to_string())
            .collect::<Vec<_>>();
        self.delete_sessions(session_ids, cx);
    }

    fn set_auto_archive_after_days(&mut self, days: Option<u8>, cx: &mut Context<Self>) {
        if self.ui_state.session.auto_archive_after_days == days {
            return;
        }
        self.ui_state.session.auto_archive_after_days = days.filter(|days| *days > 0);
        self.queue_ui_state();
        // Turning the window on applies it immediately: the reader who picked
        // "after 30 days" is asking about the sessions that are already older
        // than that, not only about the ones that will be. The pending pass is
        // cleared so the reload that follows a failure does not repeat it.
        self.auto_archive_pass_pending = false;
        self.apply_auto_archive_sessions(unix_timestamp_ms(), cx);
        cx.notify();
    }

    fn conversation_find_matches(&self, cx: &App) -> Vec<SessionSearchTarget> {
        let query =
            normalized_session_search_query(self.conversation_find.read(cx).value().as_ref());
        if query.is_empty() {
            return Vec::new();
        }
        let Some(session_id) = self.selected_session_id.clone() else {
            return Vec::new();
        };
        session_search_documents(&self.timeline.items)
            .into_iter()
            .flat_map(|document| {
                let match_count = session_search_match_ranges(&document.text, &query).len();
                std::iter::repeat_n(
                    SessionSearchTarget {
                        session_id: session_id.clone(),
                        turn_id: document.turn_id,
                        item_id: document.item_id,
                        first_sequence: document.first_sequence,
                    },
                    match_count,
                )
            })
            .collect()
    }

    /// Whether the workbench is showing a session's conversation rather than
    /// the new-session flow or another tab.
    ///
    /// Commands that act on "the conversation" — find, terminal mode — and the
    /// palette rows that offer them share this one predicate, so a disabled row
    /// and a refused command can never disagree.
    fn conversation_context_active(&self) -> bool {
        self.ui_state.workbench.active_tab == "agent"
            && !self.new_session_open
            && self.selected_session_id.is_some()
    }

    /// Opens find on whichever surface holds the keyboard.
    ///
    /// The file editor, the rendered Markdown preview and the embedded browser
    /// all bind the same chord for their own find, but a workbench binding is
    /// registered after the component's and so outranks it: with a file editor
    /// focused, the conversation's find opened over the file the user was
    /// reading. Find follows focus — those surfaces answer for themselves here,
    /// and only a conversation that actually has the keyboard falls through to
    /// the session search.
    fn open_conversation_find(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let code_workbench = self.code_workbench.clone();
        if code_workbench.update(cx, |workbench, cx| {
            workbench.open_focused_markdown_find(window, cx)
                || workbench.open_focused_editor_find(window, cx)
                || workbench.open_focused_browser_find(window, cx)
        }) {
            return;
        }
        if !self.conversation_context_active() {
            return;
        }
        self.conversation_find_open = true;
        self.conversation_find
            .update(cx, |input, cx| input.focus(window, cx));
        self.reveal_active_conversation_find_match(cx);
        cx.notify();
    }

    fn close_conversation_find(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.conversation_find_open = false;
        self.conversation_find_active_item_id = None;
        self.pending_session_search_reveal_item_id = None;
        self.focus_handle.focus(window, cx);
        cx.notify();
    }

    fn select_next_conversation_find_match(&mut self, delta: isize, cx: &mut Context<Self>) {
        let count = self.conversation_find_matches(cx).len();
        if count == 0 {
            self.conversation_find_active_index = 0;
            self.conversation_find_active_item_id = None;
            self.conversation_find_active_match_ordinal = 0;
            self.pending_session_search_reveal_item_id = None;
            cx.notify();
            return;
        }
        self.conversation_find_active_index = if delta < 0 {
            self.conversation_find_active_index
                .checked_sub(delta.unsigned_abs())
                .unwrap_or(count - 1)
        } else {
            (self.conversation_find_active_index + delta as usize) % count
        };
        self.reveal_active_conversation_find_match(cx);
    }

    fn reveal_active_conversation_find_match(&mut self, cx: &mut Context<Self>) {
        let matches = self.conversation_find_matches(cx);
        if matches.is_empty() {
            self.conversation_find_active_index = 0;
            self.conversation_find_active_item_id = None;
            self.conversation_find_active_match_ordinal = 0;
            self.pending_session_search_reveal_item_id = None;
            cx.notify();
            return;
        }
        self.conversation_find_active_index = self
            .conversation_find_active_index
            .min(matches.len().saturating_sub(1));
        for target in &matches {
            self.timeline_process_expansion
                .insert(target.turn_id.clone(), true);
            self.invalidate_timeline_turn_measurement(&target.turn_id);
        }
        self.rebuild_timeline_sizes();
        let target = &matches[self.conversation_find_active_index];
        self.conversation_find_active_item_id = target.item_id.clone();
        // A row can hold several hits, and the entries for one row are adjacent,
        // so counting back to the row's first entry says which hit is current.
        self.conversation_find_active_match_ordinal = matches
            [..self.conversation_find_active_index]
            .iter()
            .rev()
            .take_while(|candidate| {
                candidate.item_id == target.item_id && candidate.turn_id == target.turn_id
            })
            .count();
        // The turn-level scroll below only guarantees the turn is on screen;
        // the row itself is revealed once it has been laid out.
        self.pending_session_search_reveal_item_id = target.item_id.clone();
        if let Some(turn_index) = self
            .conversation_turns()
            .iter()
            .position(|turn| turn.id == target.turn_id)
        {
            self.timeline_scroll_wheel_idle_task = None;
            self.timeline_follow.set_following_bottom(false);
            self.timeline_scroll_to_latest_pending = false;
            self.timeline_scroll_anchor_pending = false;
            self.timeline_scroll
                .scroll_to_item(turn_index, ScrollStrategy::Center);
        }
        cx.notify();
    }

    /// Opens the palette on a fresh query, or closes it when it is already up.
    fn toggle_command_palette(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.command_palette_open {
            self.close_command_palette(window, cx);
            return;
        }
        // A dialog or sheet is the topmost decision layer; the palette is a
        // workbench surface and does not stack on top of one.
        if window.has_active_dialog(cx) || window.has_active_sheet(cx) {
            return;
        }
        self.open_command_palette(window, cx);
    }

    fn open_command_palette(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.command_palette_open {
            return;
        }
        self.command_palette_open = true;
        self.command_palette_query.clear();
        self.session_search_highlight_item_id = None;
        self.session_search_highlight_query = None;
        // A fresh open resets the field rather than inheriting the query the
        // last visit was abandoned with. `set_value` suppresses its own change
        // event, so the query is written through to the component here too.
        self.command_palette_input.update(cx, |input, cx| {
            input.set_value("", window, cx);
            input.focus(window, cx);
        });
        self.command_palette
            .update(cx, |state, cx| state.set_query("", window, cx));
        // Opening shows the recent list, which only needs the sessions.
        self.ensure_session_search_results();
        // The index survives closing the palette; this refreshes the sessions
        // that changed since it was built and is a no-op otherwise.
        self.refresh_session_search_index(cx);
        cx.notify();
    }

    fn close_command_palette(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if !self.command_palette_open {
            return;
        }
        self.command_palette_open = false;
        self.session_search_generation = self.session_search_generation.saturating_add(1);
        self.session_search_index_task = None;
        self.session_search_index_loading = false;
        // The index itself stays warm: rebuilding it reads every session's
        // full timeline, which is far more expensive than keeping the
        // documents around until the next open refreshes what changed.
        self.session_search_scan_generation = self.session_search_scan_generation.wrapping_add(1);
        self.session_search_scan_task = None;
        self.session_search_results = Rc::new(Vec::new());
        self.session_search_results_query = None;
        // A confirmed action may have opened a dialog of its own; focus belongs
        // there, not back on the workbench behind it.
        if !window.has_active_dialog(cx) && !window.has_active_sheet(cx) {
            self.focus_handle.focus(window, cx);
        }
        cx.notify();
    }

    fn clear_session_search_highlight(&mut self, cx: &mut Context<Self>) {
        let had_item = self.session_search_highlight_item_id.take().is_some();
        let had_query = self.session_search_highlight_query.take().is_some();
        let had_reveal = self.pending_session_search_reveal_item_id.take().is_some();
        if had_item || had_query || had_reveal {
            cx.notify();
        }
    }

    fn refresh_session_search_index(&mut self, cx: &mut Context<Self>) {
        // Session search indexes authoritative timelines, so it reads them
        // through the backend facade and works against a paired runtime too.
        let Some(runtime) = self.backend.clone() else {
            return;
        };
        let live_session_ids = self
            .sessions
            .iter()
            .map(|session| session.id.as_str().to_string())
            .collect::<BTreeSet<_>>();
        self.session_search_index
            .retain(|session_id, _| live_session_ids.contains(session_id));
        let mut stale_sessions = self
            .sessions
            .iter()
            .filter(|session| {
                self.session_search_index
                    .get(session.id.as_str())
                    .is_none_or(|entry| entry.session_updated_at_ms != session.updated_at_ms)
            })
            .cloned()
            .collect::<Vec<_>>();
        stale_sessions.sort_by_key(|session| std::cmp::Reverse(session.updated_at_ms));
        self.session_search_generation = self.session_search_generation.saturating_add(1);
        let generation = self.session_search_generation;
        if stale_sessions.is_empty() {
            self.session_search_index_loading = false;
            self.session_search_index_task = None;
            return;
        }
        self.session_search_index_loading = true;
        let (signal_tx, mut signal_rx) = mpsc::unbounded_channel();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            for session in stale_sessions {
                let Ok(items) =
                    fetch_authoritative_timeline_via_backend(runtime.clone(), session.id.clone())
                        .await
                else {
                    continue;
                };
                // Projecting a whole session into search documents is pure CPU
                // over everything it contains. It runs on the blocking pool so
                // it does not hold one of the two shared Tokio workers that
                // every other async caller in the workbench depends on.
                let Ok(documents) =
                    tokio::task::spawn_blocking(move || session_search_documents(&items)).await
                else {
                    continue;
                };
                let signal = SessionSearchIndexSignal::Indexed(SessionSearchIndexEntry {
                    session_id: session.id,
                    session_updated_at_ms: session.updated_at_ms,
                    documents: Arc::new(documents),
                });
                if signal_tx.send(signal).is_err() {
                    return;
                }
            }
            let _ = signal_tx.send(SessionSearchIndexSignal::Finished);
        });
        self.session_search_index_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                while let Some(signal) = signal_rx.recv().await {
                    let finished = matches!(signal, SessionSearchIndexSignal::Finished);
                    let _ = entity.update(cx, |this, cx| {
                        if this.session_search_generation != generation {
                            return;
                        }
                        match signal {
                            SessionSearchIndexSignal::Indexed(entry) => {
                                this.session_search_index
                                    .insert(entry.session_id.as_str().to_string(), entry);
                                // An open dialog is searching a growing index;
                                // rescan so it sees the sessions that just
                                // landed without waiting for the whole pass.
                                if this.command_palette_open
                                    && !normalized_session_search_query(
                                        this.command_palette_query.as_str(),
                                    )
                                    .is_empty()
                                {
                                    this.schedule_session_search_scan(
                                        SESSION_SEARCH_INDEX_SCAN_DEBOUNCE,
                                        cx,
                                    );
                                }
                            }
                            SessionSearchIndexSignal::Finished => {
                                this.session_search_index_loading = false;
                                this.session_search_index_task = None;
                            }
                        }
                        cx.notify();
                    });
                    if finished {
                        break;
                    }
                }
                let _ = runner.await;
            },
        ));
    }

    /// Resolves everything the result scan reads against the workbench.
    ///
    /// This is the only part that has to stay on the UI thread; the scan
    /// itself is [`session_search_scan`] over the returned snapshot.
    fn session_search_scan_sessions(&self) -> Vec<SessionSearchScanSession> {
        let mut sessions = self.sessions.iter().collect::<Vec<_>>();
        sessions.sort_by_key(|session| std::cmp::Reverse(session.last_message_at_ms));
        sessions
            .into_iter()
            .map(|session| {
                let selected = self.selected_session_id.as_ref() == Some(&session.id);
                let selected_runtime = selected.then(|| self.selected_runtime_selection());
                let selected_desired_agent_id = selected_runtime
                    .as_ref()
                    .and_then(|selection| selection.as_ref().map(|selection| &selection.agent_id));
                let cached_desired_agent_id = self.session_desired_agent_id(session.id.as_str());
                let agent_id = sidebar_session_agent_id(
                    &session.agent_id,
                    selected_desired_agent_id,
                    cached_desired_agent_id,
                );
                let project_name = self
                    .workspaces
                    .iter()
                    .find(|(_, workspace)| workspace.id == session.workspace_id)
                    .map(|(project, _)| project.name.clone())
                    .unwrap_or_else(|| workspace_display_name(&session.workspace_root));
                SessionSearchScanSession {
                    session_id: session.id.clone(),
                    agent_id,
                    session_title: session.title.clone(),
                    project_name,
                    last_message_at_ms: session.last_message_at_ms,
                    documents: self
                        .session_search_index
                        .get(session.id.as_str())
                        .map(|entry| entry.documents.clone())
                        .unwrap_or_default(),
                }
            })
            .collect()
    }

    /// The scan for the palette's current query, recomputed on the UI thread
    /// when a scheduled scan has not landed yet.
    fn ensure_session_search_results(&mut self) -> Rc<Vec<SessionSearchResult>> {
        let query = normalized_session_search_query(self.command_palette_query.as_str());
        if self.session_search_results_query.as_deref() != Some(query.as_str()) {
            let sessions = self.session_search_scan_sessions();
            self.session_search_results = Rc::new(session_search_scan(&query, &sessions));
            self.session_search_results_query = Some(query);
            // A pending scan would only recompute what this call just did.
            self.session_search_scan_generation =
                self.session_search_scan_generation.wrapping_add(1);
            self.session_search_scan_task = None;
        }
        self.session_search_results.clone()
    }

    /// Recomputes the palette's session results away from the UI thread.
    fn schedule_session_search_scan(&mut self, delay: Duration, cx: &mut Context<Self>) {
        self.session_search_scan_generation = self.session_search_scan_generation.wrapping_add(1);
        let generation = self.session_search_scan_generation;
        self.session_search_scan_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                if !delay.is_zero() {
                    cx.background_executor().timer(delay).await;
                }
                let request = entity
                    .update(cx, |this, _| {
                        if this.session_search_scan_generation != generation {
                            return None;
                        }
                        Some((
                            normalized_session_search_query(this.command_palette_query.as_str()),
                            this.session_search_scan_sessions(),
                        ))
                    })
                    .ok()
                    .flatten();
                let Some((query, sessions)) = request else {
                    return;
                };
                let scanned_query = query.clone();
                let results = cx
                    .background_executor()
                    .spawn(async move { session_search_scan(&scanned_query, &sessions) })
                    .await;
                let _ = entity.update(cx, |this, cx| {
                    if this.session_search_scan_generation != generation {
                        return;
                    }
                    this.session_search_results = Rc::new(results);
                    this.session_search_results_query = Some(query);
                    this.session_search_scan_task = None;
                    cx.notify();
                });
            },
        ));
    }

    /// Moves the palette's highlight by one row, wrapping around and skipping
    /// the rows that cannot run.
    ///
    /// The component moves its own highlight from a key binding, but a
    /// single-line field shadows that binding with caret movement, so the
    /// palette resolves the step and hands the component the row to highlight.
    fn move_command_palette_selection(
        &mut self,
        step: isize,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let strings = self.strings();
        let query = normalized_session_search_query(self.command_palette_query.as_str());
        let rows = command_palette_selectable_rows(&self.command_palette_sections(&query, strings));
        if rows.is_empty() {
            return;
        }
        let current = self.command_palette.read(cx).selected_index();
        let next = match current.and_then(|index| rows.iter().position(|row| *row == index)) {
            Some(position) => (position as isize + step).rem_euclid(rows.len() as isize) as usize,
            // Nothing highlighted yet: the first step enters from the end the
            // step comes from.
            None if step >= 0 => 0,
            None => rows.len() - 1,
        };
        self.command_palette.update(cx, |state, cx| {
            state.set_selected_index(Some(rows[next]), window, cx)
        });
    }

    /// Empties the palette's query, as its first Escape does.
    fn clear_command_palette_query(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.command_palette_input
            .update(cx, |input, cx| input.set_value("", window, cx));
        self.command_palette
            .update(cx, |state, cx| state.set_query("", window, cx));
        self.on_command_palette_query_changed(String::new(), cx);
    }

    /// Adopts a query typed into the palette: the recent list needs no document
    /// scan, so an empty query is answered in this frame, while anything else
    /// waits out the debounce.
    fn on_command_palette_query_changed(&mut self, query: String, cx: &mut Context<Self>) {
        self.command_palette_query = query;
        if normalized_session_search_query(self.command_palette_query.as_str()).is_empty() {
            self.ensure_session_search_results();
        } else {
            self.schedule_session_search_scan(SESSION_SEARCH_DEBOUNCE, cx);
        }
        cx.notify();
    }

    /// Confirms the palette's highlighted row, which is addressed by the
    /// `Command`'s index path: `section` indexes the group and `row` the item
    /// inside it, matching the order [`Self::command_palette_sections`] builds.
    fn on_command_palette_confirm(
        &mut self,
        index: IndexPath,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let strings = self.strings();
        let query = normalized_session_search_query(self.command_palette_query.as_str());
        let sections = self.command_palette_sections(&query, strings);
        let entry = sections
            .get(index.section)
            .and_then(|section| section.entries.get(index.row))
            .cloned();
        match entry {
            Some(CommandPaletteEntry::Session(result)) => {
                self.activate_command_palette_session(result, window, cx)
            }
            Some(CommandPaletteEntry::Agent(candidate)) => {
                self.activate_command_palette_agent(candidate, window, cx)
            }
            Some(CommandPaletteEntry::Setting(candidate)) => {
                self.activate_command_palette_setting(candidate, window, cx)
            }
            // The row's Action already ran during the same confirm; the palette
            // only has to get out of its way.
            Some(CommandPaletteEntry::Action(..)) | None => self.close_command_palette(window, cx),
        }
    }

    /// Opens the Config Center on a matched Agent's configuration.
    fn activate_command_palette_agent(
        &mut self,
        candidate: CommandPaletteAgentCandidate,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.close_command_palette(window, cx);
        self.open_agent_auth_management(candidate.agent_id, cx);
    }

    /// Opens a session result and jumps to the message it matched.
    fn activate_command_palette_session(
        &mut self,
        result: SessionSearchResult,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let query = normalized_session_search_query(self.command_palette_query.as_str());
        let target = result.target;
        self.session_search_highlight_item_id = None;
        self.session_search_highlight_query = target
            .as_ref()
            .and_then(|_| (!query.is_empty()).then_some(query));
        self.pending_session_search_jump = target;
        self.close_command_palette(window, cx);
        self.select_session(result.session_id, cx);
        self.apply_pending_session_search_jump(cx);
    }

    /// Opens Settings on a matched entry's section and highlights that entry.
    fn activate_command_palette_setting(
        &mut self,
        candidate: SettingsSearchCandidate,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.close_command_palette(window, cx);
        self.open_settings(window, cx);
        self.settings_view.update(cx, |settings, cx| {
            settings.activate_settings_section(candidate.section, cx);
            settings.shortcut_note = None;
            settings
                .settings_render_context
                .target_title
                .borrow_mut()
                .replace(candidate.title.to_string());
            settings
                .settings_render_context
                .highlighted_title
                .borrow_mut()
                .replace(candidate.title.to_string());
            cx.notify();
        });
        cx.notify();
    }

    fn apply_pending_session_search_jump(&mut self, cx: &mut Context<Self>) -> bool {
        let Some(target) = self.pending_session_search_jump.clone() else {
            return false;
        };
        if self.selected_session_id.as_ref() != Some(&target.session_id)
            || self.timeline.session_id.as_ref() != Some(&target.session_id)
        {
            return false;
        }
        let turns = self.conversation_turns();
        let Some((turn_index, turn)) = turns.iter().enumerate().find(|(_, turn)| {
            turn.id == target.turn_id
                || turn
                    .user_row
                    .iter()
                    .chain(turn.process_rows.iter())
                    .chain(turn.conclusion_row.iter())
                    .any(|row| {
                        target.item_id.as_ref().is_some_and(|item_id| {
                            row.item_ids.iter().any(|candidate| candidate == item_id)
                        }) || (row.first_sequence..=row.last_sequence)
                            .contains(&target.first_sequence)
                    })
        }) else {
            return false;
        };
        let turn_id = turn.id.clone();
        self.pending_session_search_jump = None;
        self.session_search_highlight_item_id = target.item_id.clone();
        // Centering the turn is not enough: the matched row has to report its
        // own bounds before the offset can be nudged onto it.
        self.pending_session_search_reveal_item_id = target.item_id;
        self.timeline_process_expansion
            .insert(turn_id.clone(), true);
        self.invalidate_timeline_turn_measurement(&turn_id);
        self.timeline_scroll_wheel_idle_task = None;
        self.timeline_follow.set_following_bottom(false);
        self.timeline_scroll_to_latest_pending = false;
        self.timeline_scroll_anchor_pending = false;
        self.rebuild_timeline_sizes();
        self.timeline_scroll
            .scroll_to_item(turn_index, ScrollStrategy::Center);
        cx.notify();
        true
    }

    fn selected_session(&self) -> Option<&AgentSession> {
        let selected = self.selected_session_id.as_ref()?;
        self.registered_session(selected.as_str())
    }

    /// The Agent that owns a session.
    ///
    /// The embedded browser's tab strip names the Agent session behind a page
    /// and asks here for the Agent itself, so the mark is the operating
    /// Agent's own icon instead of a generic robot. A session this client has
    /// not loaded answers `None`, which leaves the generic mark in place.
    pub(crate) fn agent_id_for_session(&self, session_id: &VibexSessionId) -> Option<&AgentId> {
        self.registered_session(session_id.as_str())
            .map(|session| &session.agent_id)
    }

    /// The workspace state key the persisted UI state was written under.
    ///
    /// The session list is not loaded yet on the first frame, so project scope
    /// falls back to the workspace the state was saved with.
    fn restored_workspace_state_owner(&self) -> Option<String> {
        if self.ui_state.workbench.workspace_state_scope.is_session() {
            return self
                .selected_session_id
                .as_ref()
                .map(|session_id| session_id.as_str().to_string());
        }
        self.selected_session()
            .map(|session| session.workspace_id.as_str().to_string())
            .or_else(|| self.ui_state.workbench.selected_workspace_id.clone())
    }

    /// The key that scopes the workbench state `session` restores.
    ///
    /// In project scope the key is the session's project checkout, so every
    /// session looking at the same files shares one right-hand column; in
    /// session scope the key is the session itself.
    fn workspace_state_owner(&self, session: &AgentSession) -> String {
        let scope = self.ui_state.workbench.workspace_state_scope;
        if scope.is_session() {
            return session.id.as_str().to_string();
        }
        if scope.is_group()
            && let Some(group_id) = self
                .ui_state
                .sidebar
                .organization
                .group_of_session(session.id.as_str())
        {
            // The right rail and the preview tabs belong to the group, not to
            // the pane: switching panes must not swap the files being read.
            return format!("group:{group_id}");
        }
        session.workspace_id.as_str().to_string()
    }

    /// The workspace state key for a workspace that is being activated.
    ///
    /// Only the selected session of that workspace owns the state. Activating
    /// any other workspace leaves the key empty, so relative paths from one
    /// workspace can never render against another.
    fn workspace_state_owner_for_workspace(
        &self,
        workspace_id: &vibex_core::WorkspaceId,
    ) -> Option<String> {
        self.selected_session()
            .filter(|session| &session.workspace_id == workspace_id)
            .map(|session| self.workspace_state_owner(session))
    }

    /// The right-hand column as it is on screen now.
    fn current_workspace_layout(&self) -> WorkspaceLayoutState {
        WorkspaceLayoutState {
            right_rail_visible: self.ui_state.workbench.right_rail_visible,
            right_rail_width: self.ui_state.workbench.right_rail_width,
            right_rail_activity_id: self.ui_state.right_rail.selected_activity_id.clone(),
            preview_visible: self.ui_state.workbench.preview_visible,
            preview_width: self.ui_state.workbench.preview_width,
        }
    }

    /// Park the right-hand column of the scope that is on screen and install
    /// the one parked for `owner`.
    ///
    /// The rail and the editor are two halves of the same column, so
    /// they move together: switching sessions in project scope keeps both, and
    /// in session scope restores what that session last had open.
    fn switch_workspace_layout_owner(&mut self, owner: Option<String>, cx: &mut Context<Self>) {
        if self.workspace_layout_owner == owner {
            return;
        }
        // A column opened while no session owned it belongs to the workspace on
        // screen: the first session of that workspace inherits it when it has
        // nothing parked of its own, and a parked column always wins.
        let unowned = (self.workspace_layout_owner.is_none() && owner.is_some())
            .then(|| self.current_workspace_layout())
            .filter(|layout| !layout.is_empty());
        if let Some(previous) = self.workspace_layout_owner.take() {
            let layout = self.current_workspace_layout();
            if !layout.is_empty() {
                self.ui_state.workspace_layouts.insert(previous, layout);
            }
        }
        self.workspace_layout_owner = owner.clone();
        let parked = owner.and_then(|owner| self.ui_state.workspace_layouts.remove(&owner));
        self.apply_workspace_layout(parked.or(unowned).unwrap_or_default(), cx);
        self.queue_ui_state();
    }

    /// Install a parked right-hand column without parking the current one.
    fn apply_workspace_layout(&mut self, layout: WorkspaceLayoutState, cx: &mut Context<Self>) {
        self.ui_state.workbench.right_rail_visible = layout.right_rail_visible;
        self.ui_state.workbench.right_rail_width = layout.right_rail_width;
        self.ui_state.workbench.preview_visible = layout.preview_visible;
        self.ui_state.workbench.preview_width = layout.preview_width;
        let mode = right_rail_mode_from_activity_id(layout.right_rail_activity_id.as_deref());
        self.right_rail_mode = mode;
        self.ui_state.right_rail.selected_activity_id = layout.right_rail_activity_id;
        self.code_workbench.update(cx, |workbench, cx| {
            workbench.right_rail_mode = mode;
            cx.notify();
        });
        self.code_right_rail
            .update(cx, |right_rail, cx| right_rail.set_mode(mode, cx));
        self.set_code_preview_visible(layout.preview_visible, cx);
        // A docked panel is governed by its visibility flag; a narrow window
        // shows the same choice as an overlay instead.
        self.right_rail_overlay_open =
            !self.last_visibility.right_rail_docked && layout.right_rail_visible;
        self.preview_overlay_open = !self.last_visibility.preview_docked && layout.preview_visible;
        cx.notify();
    }

    /// Switch the setting that decides how much of the right-hand column is
    /// shared between sessions.
    fn set_workspace_state_scope(&mut self, scope: WorkspaceStateScope, cx: &mut Context<Self>) {
        if self.ui_state.workbench.workspace_state_scope == scope {
            return;
        }
        self.ui_state.workbench.workspace_state_scope = scope;
        // Every parked column was keyed by the previous scope, so none of them
        // can be matched to a scope under the new one. The live column stays on
        // screen and becomes the selected session's state under the new key.
        self.ui_state.workspace_layouts.clear();
        self.workspace_layout_owner = self
            .selected_session()
            .map(|session| self.workspace_state_owner(session));
        let owner = self.workspace_layout_owner.clone();
        self.code_workbench
            .update(cx, |workbench, cx| workbench.reset_state_scopes(owner, cx));
        self.queue_ui_state();
        cx.notify();
    }

    fn session_agent_id(&self, session_id: &VibexSessionId) -> Option<AgentId> {
        self.registered_session(session_id.as_str())
            .map(|session| session.agent_id.clone())
    }

    fn toggle_session_pin(&mut self, session_id: &VibexSessionId, cx: &mut Context<Self>) {
        let pinned = !self.sidebar_state.pinned_ids.contains(session_id.as_str());
        self.set_sessions_pinned(
            std::slice::from_ref(&session_id.as_str().to_string()),
            pinned,
            cx,
        );
    }

    /// Pins or unpins every session of a menu selection as one setting.
    ///
    /// The menu shows one pin state for the selection, so the command applies
    /// that state to all of it rather than flipping each row against the rest.
    fn set_sessions_pinned(
        &mut self,
        session_ids: &[String],
        pinned: bool,
        cx: &mut Context<Self>,
    ) {
        let mut changed = false;
        for session_id in session_ids {
            changed |= if pinned {
                self.sidebar_state.pinned_ids.insert(session_id.clone())
            } else {
                self.sidebar_state.pinned_ids.remove(session_id)
            };
        }
        if !changed {
            return;
        }
        self.invalidate_sidebar_projection_cache();
        self.queue_agent_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn toggle_collapse_all_projects(&mut self, cx: &mut Context<Self>) {
        let project_ids = self
            .workspaces
            .iter()
            .map(|(project, _)| project.id.as_str().to_string())
            .collect::<BTreeSet<_>>();
        toggle_sidebar_project_collapse_all(
            &mut self.sidebar_state.collapsed_ids,
            &mut self.collapsed_project_restore,
            &project_ids,
        );
        self.queue_agent_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn reveal_sidebar_organization_ancestors(&mut self, item: SidebarOrganizationItem) -> bool {
        let mut current = item;
        let mut seen = BTreeSet::new();
        let mut revealed = false;
        while let Some(parent_id) = self.ui_state.sidebar.organization.parent_of(&current) {
            if !seen.insert(parent_id.clone()) {
                break;
            }
            revealed |= self
                .ui_state
                .sidebar
                .organization
                .collapsed_folder_ids
                .remove(&parent_id);
            current = SidebarOrganizationItem::Folder(parent_id);
        }
        revealed
    }

    fn locate_selected_session(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(session) = self.selected_session().cloned() else {
            return;
        };
        let mut revealed = reveal_sidebar_session(
            &mut self.sidebar_state.collapsed_ids,
            &mut self.ui_state.sidebar.collapsed_workspace_ids,
            session.project_id.as_str(),
            session.workspace_id.as_str(),
            self.ui_state.sidebar.hierarchy_mode,
        );
        revealed |= self.reveal_sidebar_organization_ancestors(SidebarOrganizationItem::Project(
            session.project_id.as_str().to_string(),
        ));
        revealed |= self.reveal_sidebar_organization_ancestors(SidebarOrganizationItem::Session(
            session.id.as_str().to_string(),
        ));
        if revealed {
            self.collapsed_project_restore = None;
            self.queue_agent_ui_state();
            self.publish_sidebar_invalidation();
        }
        let selected_session_scroll_anchor = self.selected_session_scroll_anchor.clone();
        let sidebar_scroll = self.sidebar_scroll.clone();
        let scroll_to_selected = move |window: &mut Window, cx: &mut App| {
            selected_session_scroll_anchor.scroll_to(window, cx);
            window.on_next_frame(move |_, _| {
                let offset = sidebar_scroll.offset();
                // ScrollAnchor targets both axes. The session row starts after the
                // sidebar padding, so keep this vertical-only list at x = 0.
                sidebar_scroll.set_offset(point(px(0.0), offset.y));
            });
        };
        if revealed {
            // Let the expanded project/workspace render before reading the row anchor.
            window.on_next_frame(scroll_to_selected);
        } else {
            scroll_to_selected(window, cx);
        }
        cx.notify();
    }

    fn toggle_sidebar_hierarchy_mode(&mut self, cx: &mut Context<Self>) {
        self.ui_state.sidebar.hierarchy_mode = match self.ui_state.sidebar.hierarchy_mode {
            SidebarHierarchyMode::Compact => SidebarHierarchyMode::Detailed,
            SidebarHierarchyMode::Detailed => SidebarHierarchyMode::Compact,
        };
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn queue_ui_state(&mut self) {
        if let Some(writer) = self.ui_writer.as_mut() {
            writer.queue(self.ui_state.clone(), unix_timestamp_ms());
            if let Err(error) = writer.flush_if_due(unix_timestamp_ms()) {
                self.persistence_note = Some(format!("UI state flush failed: {error}"));
            }
        }
    }

    fn queue_agent_ui_state(&mut self) {
        self.ui_state.workbench.selected_session_id = self
            .selected_session_id
            .as_ref()
            .map(|session_id| session_id.as_str().to_string());
        self.ui_state.sidebar.session_order = self.sidebar_state.row_order.clone();
        self.ui_state.sidebar.pinned_session_ids = self.sidebar_state.pinned_ids.clone();
        self.ui_state.sidebar.collapsed_project_ids = self.sidebar_state.collapsed_ids.clone();
        self.queue_ui_state();
    }

    pub(crate) fn persist_code_workbench_state(
        &mut self,
        state: CodeWorkbenchPersistedState,
        cx: &mut Context<Self>,
    ) {
        self.apply_code_workbench_state(state);
        let previous_note = self.persistence_note.clone();
        self.queue_ui_state();
        if self.persistence_note != previous_note {
            cx.notify();
        }
    }

    fn apply_code_workbench_state(&mut self, state: CodeWorkbenchPersistedState) {
        if !self.ui_state.workbench.remember_layout {
            return;
        }
        self.ui_state.preview.layout = state.preview;
        self.ui_state.preview.layout_scopes = state.preview_layouts;
        if let Some(recovery) = state.recovery {
            self.ui_state.preview.editor_recovery = recovery;
        }
        self.ui_state.preview.editor_soft_wrap = state.editor_soft_wrap;
        self.ui_state.preview.editor_show_whitespaces = state.editor_show_whitespaces;
        self.ui_state.preview.editor_autosave = state.editor_autosave;
        self.ui_state.preview.editor_autosave_delay_ms = state.editor_autosave_delay_ms;
        self.ui_state.workbench.selected_workspace_id = state.workspace_id;
        self.ui_state.workbench.selected_file_path = state.selected_file_path;
        self.ui_state.workbench.selected_git_path = state.selected_git_path;
        self.ui_state.terminal.selected_terminal_id = state.selected_terminal_id;
    }

    fn sync_agent_streaming_surface_visibility(&mut self) {
        let visible = self.ui_state.workbench.active_tab == "agent" && !self.new_session_open;
        let was_visible = self
            .agent_streaming_surface_visible
            .swap(visible, Ordering::Release);
        if visible != was_visible {
            // The event bridge may discard presentation-only chunks while the
            // Agent surface is hidden. Force one authoritative catch-up when
            // the surface changes visibility in either direction so startup
            // on a non-Agent tab is covered as well. Every stored view is
            // marked, not just the borrowed one, because a group pane can be
            // showing a session the sidebar did not select.
            self.timeline.mark_lagged();
            for view in self.session_views.values_mut() {
                view.timeline.mark_lagged();
            }
            for state in self.child_agent_timelines.values_mut() {
                state.timeline.mark_lagged();
            }
        }
        if !visible {
            self.agent_poll_task = None;
        }
    }

    fn current_workbench_route(&self) -> WorkbenchRoute {
        let mut route = workbench_route(&self.ui_state, self.selected_session_id.as_ref());
        route.usage_session_id = self
            .usage_session_filter
            .as_ref()
            .map(|id| id.as_str().to_string());
        route
    }

    fn sync_current_navigation_entry(&mut self) {
        let route = self.current_workbench_route();
        self.navigation_history.replace(route);
    }

    fn push_current_navigation_entry(&mut self) {
        let route = self.current_workbench_route();
        self.navigation_history.push(route);
    }

    fn apply_workbench_route(
        &mut self,
        route: WorkbenchRoute,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.home_arena.update(cx, |arena, cx| arena.close(cx));
        let right_rail_activity_id = route_right_rail_activity_id(&route.right_rail);
        let selected_file_path = route.selected_file_path.clone();
        let selected_git_path = route.selected_git_path.clone();
        let selected_terminal_id = route.selected_terminal_id.clone();
        self.ui_state.workbench.active_tab = match route.primary_tab.as_str() {
            "management" => "management".to_string(),
            "usage" => "usage".to_string(),
            _ => "agent".to_string(),
        };
        self.sync_agent_streaming_surface_visibility();
        if self.ui_state.workbench.active_tab != "agent" {
            self.clear_suggestions();
        }
        self.usage_session_filter = route
            .usage_session_id
            .as_deref()
            .and_then(|id| VibexSessionId::parse(id.to_string()).ok());
        self.ui_state.workbench.selected_workspace_id = route.workspace_id;
        self.ui_state.workbench.selected_file_path = selected_file_path.clone();
        self.ui_state.workbench.selected_git_path = selected_git_path.clone();
        self.ui_state.terminal.selected_terminal_id = selected_terminal_id.clone();
        self.ui_state.workbench.right_rail_visible = right_rail_activity_id.is_some();
        if let Some(activity_id) = right_rail_activity_id {
            let mode = right_rail_mode_from_activity_id(Some(&activity_id));
            self.ui_state.right_rail.selected_activity_id = Some(activity_id);
            self.right_rail_mode = mode;
            self.code_workbench.update(cx, |workbench, cx| {
                workbench.right_rail_mode = mode;
                cx.notify();
            });
            self.code_right_rail
                .update(cx, |right_rail, cx| right_rail.set_mode(mode, cx));
        }

        if let Some(session_id) = route
            .session_id
            .as_deref()
            .and_then(|session_id| VibexSessionId::parse(session_id).ok())
            .filter(|session_id| {
                self.sessions
                    .iter()
                    .any(|session| &session.id == session_id)
            })
        {
            self.select_session_with_history(session_id, false, cx);
        }
        self.code_workbench.update(cx, |workbench, cx| {
            workbench.restore_navigation_selection(
                selected_file_path,
                selected_git_path,
                selected_terminal_id,
                window,
                cx,
            )
        });

        if self.ui_state.workbench.active_tab == "management" {
            if let Some(runtime) = self.runtime.clone() {
                self.management_view.update(cx, |management, cx| {
                    management.set_runtime(runtime.clone(), cx)
                });
            }
            self.sync_management_agent_ordering(cx);
            self.sync_management_pairing_context(cx);
        } else if self.ui_state.workbench.active_tab == "usage" {
            let session_filter = self.usage_session_filter.clone();
            self.usage_view
                .update(cx, |usage, cx| usage.activate(session_filter, cx));
        }
        self.queue_ui_state();
        cx.notify();
    }

    fn navigate_back(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
        let route = self.navigation_history.back().cloned();
        if let Some(route) = route {
            self.apply_workbench_route(route, window, cx);
            true
        } else {
            false
        }
    }

    fn navigate_forward(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
        let route = self.navigation_history.forward().cloned();
        if let Some(route) = route {
            self.apply_workbench_route(route, window, cx);
            true
        } else {
            false
        }
    }

    fn sidebar_panel_width(&self, visibility: WorkbenchVisibility) -> f32 {
        clamp_sidebar_panel_width(
            self.ui_state.workbench.sidebar_width,
            visibility.layout.viewport_width,
        )
    }

    /// The width the sidebar takes away from the preview panel.
    fn preview_sidebar_reservation(&self, visibility: WorkbenchVisibility) -> f32 {
        if visibility.sidebar_docked && self.ui_state.workbench.sidebar_visible {
            self.sidebar_panel_width(visibility)
        } else {
            0.0
        }
    }

    /// The width the window's right edge takes away from the preview panel.
    fn preview_right_edge_reservation(&self, visibility: WorkbenchVisibility) -> f32 {
        if visibility.right_rail_docked && self.ui_state.workbench.right_rail_visible {
            self.right_rail_panel_width(visibility)
        } else {
            RIGHT_ACTIVITY_BAR_WIDTH
        }
    }

    /// The width the docked preview panel is drawn at.
    ///
    /// The stored width is the reader's own choice, made with the panel's left
    /// seam, so every docked shell honours it. A Medium window used to pin the
    /// panel to the shell's own minimum instead: the seam then moved a number
    /// nothing painted, while the session page beside it kept every pixel the
    /// pinned panel did not use and could not be dragged any narrower. Compact
    /// still follows the shell, because the panel is a sheet there and draws no
    /// seam of its own.
    fn preview_panel_width(&self, visibility: WorkbenchVisibility) -> f32 {
        match visibility.layout.kind {
            ShellKind::Wide | ShellKind::Medium => resolved_preview_panel_width(
                self.ui_state.workbench.preview_width,
                visibility.layout.viewport_width as f32,
                visibility.layout.preview_min_width,
                self.preview_sidebar_reservation(visibility),
                self.preview_right_edge_reservation(visibility),
            ),
            ShellKind::Compact => visibility.layout.preview_min_width,
        }
    }

    fn right_rail_panel_width(&self, visibility: WorkbenchVisibility) -> f32 {
        self.ui_state.workbench.right_rail_width.clamp(
            RIGHT_RAIL_PANEL_MIN_WIDTH,
            right_rail_panel_max_width(visibility.layout.viewport_width),
        )
    }

    fn workbench_auto_collapse(
        &self,
        visibility: WorkbenchVisibility,
        _cx: &Context<Self>,
    ) -> WorkbenchAutoCollapseState {
        let new_session_open = self.new_session_open;
        let preview_fullscreen = !new_session_open && self.preview_fullscreen_active;
        let agent_workbench_active = self.ui_state.workbench.active_tab == "agent";
        let management_open = self.ui_state.workbench.active_tab == "management";
        let usage_open = self.ui_state.workbench.active_tab == "usage";
        let preview_side_open = agent_workbench_active
            && visibility.preview_docked
            && self.ui_state.workbench.preview_visible
            && !preview_fullscreen
            && !new_session_open;
        // Full screen moves the panel into the workbench column, so the rail
        // keeps its width and the auto-collapse has to count it.
        let right_rail_open = agent_workbench_active
            && visibility.right_rail_docked
            && self.ui_state.workbench.right_rail_visible
            && !new_session_open;
        let sidebar_open = (agent_workbench_active || management_open || usage_open)
            && visibility.sidebar_docked
            && self.ui_state.workbench.sidebar_visible;

        calculate_workbench_auto_collapse(
            visibility.layout.viewport_width,
            sidebar_open,
            right_rail_open,
            preview_side_open,
            self.sidebar_panel_width(visibility),
            self.right_rail_panel_width(visibility),
        )
    }

    fn right_rail_docks_when_open(&self, _cx: &Context<Self>) -> bool {
        let visibility = WorkbenchVisibility::resolve(
            self.last_visibility.layout.viewport_width,
            self.last_visibility.layout.viewport_height,
        );
        let new_session_open = self.new_session_open;
        visibility.right_rail_docked
            && self.ui_state.workbench.active_tab == "agent"
            && !new_session_open
    }

    fn sidebar_resize_limits(
        &self,
        visibility: WorkbenchVisibility,
        _cx: &Context<Self>,
    ) -> Option<(f32, f32)> {
        if !visibility.sidebar_docked {
            return None;
        }
        Some((
            SIDEBAR_PANEL_MIN_WIDTH,
            sidebar_panel_max_width(visibility.layout.viewport_width),
        ))
    }

    fn update_sidebar_resize(&mut self, window_x: f32, cx: &mut Context<Self>) {
        let Some(drag) = self.sidebar_resize_drag else {
            return;
        };
        let width = (drag.start_width + window_x - drag.start_window_x)
            .round()
            .clamp(drag.min_width, drag.max_width);
        if (width - self.ui_state.workbench.sidebar_width).abs() < f32::EPSILON {
            return;
        }
        self.ui_state.workbench.sidebar_width = width;
        cx.notify();
    }

    fn finish_sidebar_resize(&mut self, cx: &mut Context<Self>) {
        let Some(drag) = self.sidebar_resize_drag.take() else {
            return;
        };
        if (self.ui_state.workbench.sidebar_width - drag.start_width).abs() >= 1.0 {
            self.queue_ui_state();
        }
        cx.notify();
    }

    fn update_composer_terminal_resize(&mut self, window_y: f32, cx: &mut Context<Self>) {
        let Some(drag) = self.composer_terminal_resize_drag else {
            return;
        };
        // The handle sits on the terminal's top edge: dragging up grows it.
        let height = (drag.start_height - (window_y - drag.start_window_y))
            .round()
            .clamp(drag.min_height, drag.max_height);
        if (height - self.composer_terminal_height).abs() < f32::EPSILON {
            return;
        }
        self.composer_terminal_height = height;
        cx.notify();
    }

    fn finish_composer_terminal_resize(&mut self, cx: &mut Context<Self>) {
        if self.composer_terminal_resize_drag.take().is_some() {
            cx.notify();
        }
    }

    fn composer_terminal_height_limits(&self) -> (f32, f32) {
        let min_height = COMPOSER_TERMINAL_MIN_HEIGHT_PX;
        let viewport_height = self.last_visibility.layout.viewport_height as f32;
        let max_height = (viewport_height - COMPOSER_TERMINAL_MAX_HEIGHT_INSET_PX).max(min_height);
        (min_height, max_height)
    }

    fn adjust_sidebar_width(&mut self, delta: f32, cx: &mut Context<Self>) {
        let Some((min_width, max_width)) = self.sidebar_resize_limits(self.last_visibility, cx)
        else {
            return;
        };
        let width = (self.sidebar_panel_width(self.last_visibility) + delta)
            .round()
            .clamp(min_width, max_width);
        if (width - self.ui_state.workbench.sidebar_width).abs() < f32::EPSILON {
            return;
        }
        self.ui_state.workbench.sidebar_width = width;
        self.queue_ui_state();
        cx.notify();
    }

    fn on_sidebar_resize_key_down(
        &mut self,
        event: &KeyDownEvent,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let delta = match event.keystroke.key.as_str() {
            "left" => -SIDEBAR_RESIZE_KEYBOARD_STEP,
            "right" => SIDEBAR_RESIZE_KEYBOARD_STEP,
            _ => return,
        };
        self.adjust_sidebar_width(delta, cx);
        cx.stop_propagation();
    }

    fn right_panel_resize_limits(
        &self,
        panel: RightPanelKind,
        visibility: WorkbenchVisibility,
        _cx: &Context<Self>,
    ) -> Option<(f32, f32)> {
        let panel_visible = match panel {
            RightPanelKind::Preview => {
                visibility.preview_docked && self.ui_state.workbench.preview_visible
            }
            RightPanelKind::RightRail => {
                (visibility.right_rail_docked && self.ui_state.workbench.right_rail_visible)
                    || (!visibility.right_rail_docked && self.right_rail_overlay_open)
            }
        };
        // Full screen puts the panel in the workbench column, so its own
        // resize handle is gone while the rail beside it keeps working.
        let preview_panel_fullscreen =
            matches!(panel, RightPanelKind::Preview) && self.preview_fullscreen_active;
        if !panel_visible || self.new_session_open || preview_panel_fullscreen {
            return None;
        }
        match panel {
            RightPanelKind::Preview => Some(preview_panel_width_limits(
                visibility.layout.viewport_width as f32,
                visibility.layout.preview_min_width,
                self.preview_sidebar_reservation(visibility),
                self.preview_right_edge_reservation(visibility),
            )),
            RightPanelKind::RightRail => Some((
                RIGHT_RAIL_PANEL_MIN_WIDTH,
                right_rail_panel_max_width(visibility.layout.viewport_width),
            )),
        }
    }

    fn right_panel_width(&self, panel: RightPanelKind, visibility: WorkbenchVisibility) -> f32 {
        match panel {
            RightPanelKind::Preview => self.preview_panel_width(visibility),
            RightPanelKind::RightRail => self.right_rail_panel_width(visibility),
        }
    }

    fn set_right_panel_width(&mut self, panel: RightPanelKind, width: f32) {
        match panel {
            RightPanelKind::Preview => self.ui_state.workbench.preview_width = width,
            RightPanelKind::RightRail => self.ui_state.workbench.right_rail_width = width,
        }
    }

    fn update_right_panel_resize(&mut self, window_x: f32, cx: &mut Context<Self>) {
        let Some(drag) = self.right_panel_resize_drag else {
            return;
        };
        let width = resized_right_panel_width(
            drag.start_width,
            drag.start_window_x,
            window_x,
            drag.min_width,
            drag.max_width,
        );
        if (width - self.right_panel_width(drag.panel, self.last_visibility)).abs() < f32::EPSILON {
            return;
        }
        self.set_right_panel_width(drag.panel, width);
        cx.notify();
    }

    fn finish_right_panel_resize(&mut self, cx: &mut Context<Self>) {
        let Some(drag) = self.right_panel_resize_drag.take() else {
            return;
        };
        if (self.right_panel_width(drag.panel, self.last_visibility) - drag.start_width).abs()
            >= 1.0
        {
            self.queue_ui_state();
        }
        cx.notify();
    }

    fn drag_fps_hud(
        &mut self,
        cursor: Point<Pixels>,
        viewport: Size<Pixels>,
        cx: &mut Context<Self>,
    ) {
        let Some(drag) = self.fps_hud_drag else {
            return;
        };
        if !cx.has_active_drag() {
            // The pointer left the window without a mouse up reaching the
            // workbench, so the HUD stops following it.
            self.fps_hud_drag = None;
            return;
        }
        let offset = dragged_fps_hud_offset(drag.offset, drag.start_cursor, cursor, viewport);
        if offset == self.fps_hud_offset {
            return;
        }
        self.fps_hud_offset = offset;
        cx.notify();
    }

    fn finish_fps_hud_drag(&mut self, cx: &mut Context<Self>) {
        if self.fps_hud_drag.take().is_none() {
            return;
        }
        cx.notify();
    }

    fn set_fps_monitor_enabled(&mut self, enabled: bool, window: &Window, cx: &mut Context<Self>) {
        self.ui_state.developer.show_fps_monitor = enabled;
        if enabled {
            // Every open starts from the middle of the window rather than
            // wherever the last drag left the HUD.
            self.fps_hud_offset = FpsHudOffset::default();
            self.start_fps_monitor_recording(window.window_handle().window_id(), cx);
        } else {
            // Dropping the monitor releases GPUI's frame trace and the HUD's
            // resource sampler; dropping the recorder stops the sampling task.
            self.fps_monitor = None;
            self.fps_hud_drag = None;
            self.fps_monitor_recorder = None;
        }
        self.queue_ui_state();
        cx.notify();
    }

    /// Records what the developer FPS HUD measures into the diagnostics folder,
    /// once per [`performance_log::SAMPLE_INTERVAL`], until the HUD is switched
    /// off or the write fails.
    fn start_fps_monitor_recording(&mut self, window_id: WindowId, cx: &mut Context<Self>) {
        if self.fps_monitor_recorder.is_some() {
            return;
        }
        let Some(path) = self
            .config
            .as_ref()
            .map(|config| performance_log::fps_monitor_log_path(&config.home_dir))
        else {
            return;
        };
        let workbench = cx.weak_entity();
        self.fps_monitor_recorder = Some(cx.spawn(async move |_, cx| {
            let mut recorder = performance_log::FpsMonitorRecorder::new(window_id, path);
            loop {
                cx.background_executor()
                    .timer(performance_log::SAMPLE_INTERVAL)
                    .await;
                // Context that decides how the interval should be read: an
                // inactive window is throttled, and the same build costs more
                // in a large session than in an empty one.
                let context = workbench
                    .update(cx, |this, _| performance_log::FpsMonitorContext {
                        window_active: !motion::window_is_inactive(),
                        session_count: this.sessions.len() as u32,
                        timeline_rows: this.timeline.items.len() as u32,
                    })
                    .unwrap_or_default();
                recorder.set_context(context);
                let Some(line) = recorder.sample_line() else {
                    continue;
                };
                let path = recorder.path().to_path_buf();
                let write = cx.background_spawn(async move {
                    performance_log::append_sample_line(&path, &line)
                });
                if let Err(error) = write.await {
                    // Writing is the whole point of the recording, so a failure
                    // ends it and says so rather than losing samples quietly.
                    let _ = workbench.update(cx, |this, cx| {
                        this.persistence_note = Some(format!(
                            "FPS monitor samples could not be written ({error})"
                        ));
                        cx.notify();
                    });
                    return;
                }
            }
        }));
    }

    fn adjust_right_panel_width(
        &mut self,
        panel: RightPanelKind,
        delta: f32,
        cx: &mut Context<Self>,
    ) {
        let Some((minimum, maximum)) =
            self.right_panel_resize_limits(panel, self.last_visibility, cx)
        else {
            return;
        };
        let width = (self.right_panel_width(panel, self.last_visibility) + delta)
            .round()
            .clamp(minimum, maximum);
        self.set_right_panel_width(panel, width);
        self.queue_ui_state();
        cx.notify();
    }

    fn sidebar_active_visible(&self) -> bool {
        (self.last_visibility.sidebar_docked && self.ui_state.workbench.sidebar_visible)
            || self.sidebar_overlay_open
    }

    fn close_sidebar_hover_preview(&mut self) {
        self.sidebar_hover_preview_close_task = None;
        self.sidebar_hover_preview_open = false;
        // The menu entity that armed the latch is gone; clear it so a stale
        // latch can never keep a future preview permanently open.
        self.sidebar_menu_hover_latch = false;
    }

    fn retain_sidebar_hover_preview(&mut self) {
        self.sidebar_hover_preview_close_task = None;
    }

    fn set_sidebar_context_menu_target(
        &mut self,
        target: SidebarContextMenuTarget,
        cx: &mut Context<Self>,
    ) {
        if self.sidebar_context_menu_target.as_ref() != Some(&target) {
            self.sidebar_context_menu_target = Some(target);
            cx.notify();
        }
    }

    fn clear_sidebar_context_menu_target(&mut self, cx: &mut Context<Self>) {
        if self.sidebar_context_menu_target.take().is_some() {
            cx.notify();
        }
    }

    fn set_sidebar_project_appearance_popover(
        &mut self,
        project_id: Option<String>,
        cx: &mut Context<Self>,
    ) {
        if self.sidebar_project_appearance_popover != project_id {
            self.sidebar_project_appearance_popover = project_id;
            cx.notify();
        }
    }

    fn sidebar_project_appearance(&self, project_id: &str) -> SidebarProjectAppearance {
        self.ui_state
            .sidebar
            .project_appearances
            .get(project_id)
            .cloned()
            .unwrap_or_default()
    }

    fn store_sidebar_project_appearance(
        &mut self,
        project_id: String,
        appearance: SidebarProjectAppearance,
        cx: &mut Context<Self>,
    ) {
        if appearance == SidebarProjectAppearance::default() {
            self.ui_state
                .sidebar
                .project_appearances
                .remove(&project_id);
        } else {
            self.ui_state
                .sidebar
                .project_appearances
                .insert(project_id, appearance);
        }
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn set_sidebar_project_logo(
        &mut self,
        project_id: String,
        logo: SidebarProjectLogo,
        cx: &mut Context<Self>,
    ) {
        let mut appearance = self.sidebar_project_appearance(&project_id);
        if appearance.logo == logo && appearance.custom_logo_file.is_none() {
            return;
        }
        appearance.logo = logo;
        appearance.custom_logo_file = None;
        self.store_sidebar_project_appearance(project_id, appearance, cx);
    }

    fn set_sidebar_project_logo_color(
        &mut self,
        project_id: String,
        color: SidebarProjectLogoColor,
        cx: &mut Context<Self>,
    ) {
        let mut appearance = self.sidebar_project_appearance(&project_id);
        if appearance.color == color {
            return;
        }
        appearance.color = color;
        self.store_sidebar_project_appearance(project_id, appearance, cx);
    }

    fn clear_sidebar_project_custom_logo(&mut self, project_id: String, cx: &mut Context<Self>) {
        let mut appearance = self.sidebar_project_appearance(&project_id);
        if appearance.custom_logo_file.take().is_some() {
            self.store_sidebar_project_appearance(project_id, appearance, cx);
        }
    }

    fn choose_sidebar_project_custom_logo(
        &mut self,
        project_id: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.sidebar_project_logo_upload_task.is_some() {
            return;
        }
        let Some(home) = self.config.as_ref().map(|config| config.home_dir.clone()) else {
            hint_layer::push(
                window,
                hint_notification(
                    NotificationType::Error,
                    locale::text(
                        "Project icon storage is unavailable",
                        "项目图标存储不可用",
                        "專案圖示儲存空間無法使用",
                    ),
                ),
                cx,
            );
            return;
        };
        let picker = gpui_tokio::Tokio::spawn(cx, async move {
            let Some(file) = rfd::AsyncFileDialog::new()
                .set_title(locale::text(
                    "Choose project icon",
                    "选择项目图标",
                    "選擇專案圖示",
                ))
                .add_filter(
                    "Images",
                    &[
                        "png", "jpg", "jpeg", "webp", "gif", "bmp", "tif", "tiff", "ico", "svg",
                    ],
                )
                .pick_file()
                .await
            else {
                return Ok(None);
            };
            import_sidebar_project_logo(file.path(), &home).map(Some)
        });
        self.sidebar_project_logo_upload_task =
            Some(cx.spawn_in(window, async move |entity, cx| {
                let outcome = picker.await;
                let _ = entity.update_in(cx, |this, window, cx| {
                    this.sidebar_project_logo_upload_task = None;
                    match outcome {
                        Ok(Ok(Some(file_name))) => {
                            let mut appearance = this.sidebar_project_appearance(&project_id);
                            appearance.custom_logo_file = Some(file_name);
                            this.store_sidebar_project_appearance(
                                project_id.clone(),
                                appearance,
                                cx,
                            );
                        }
                        Ok(Ok(None)) => {}
                        Ok(Err(error)) => {
                            hint_layer::push(
                                window,
                                hint_notification(
                                    NotificationType::Error,
                                    format!(
                                        "{}: {error}",
                                        locale::text(
                                            "Could not use project icon",
                                            "无法使用项目图标",
                                            "無法使用專案圖示",
                                        )
                                    ),
                                ),
                                cx,
                            );
                        }
                        Err(error) => {
                            hint_layer::push(
                                window,
                                hint_notification(
                                    NotificationType::Error,
                                    format!(
                                        "{}: {error}",
                                        locale::text(
                                            "Could not open project icon",
                                            "无法打开项目图标",
                                            "無法開啟專案圖示",
                                        )
                                    ),
                                ),
                                cx,
                            );
                        }
                    }
                    cx.notify();
                });
            }));
    }

    fn dismiss_sidebar_for_navigation(&mut self) {
        self.sidebar_project_appearance_popover = None;
        let hover_preview_was_open = self.sidebar_hover_preview_open;
        let next = sidebar_display_after_navigation(
            self.ui_state.workbench.sidebar_visible,
            hover_preview_was_open,
        );
        let requested_open_changed = self.ui_state.workbench.sidebar_visible != next.requested_open;
        self.ui_state.workbench.sidebar_visible = next.requested_open;
        self.sidebar_overlay_open = next.drawer_open;
        if hover_preview_was_open {
            self.suppress_sidebar_hover_preview();
        } else {
            self.close_sidebar_hover_preview();
        }
        if requested_open_changed {
            self.queue_ui_state();
        }
    }

    fn suppress_sidebar_hover_preview(&mut self) {
        self.sidebar_hover_preview_suppressed_until =
            Some(Instant::now() + SIDEBAR_HOVER_PREVIEW_SUPPRESS_DELAY);
        self.close_sidebar_hover_preview();
    }

    fn open_sidebar_hover_preview(&mut self, cx: &mut Context<Self>) {
        self.sidebar_hover_preview_close_task = None;
        if self.sidebar_active_visible() {
            self.sidebar_hover_preview_open = false;
            return;
        }
        if let Some(suppressed_until) = self.sidebar_hover_preview_suppressed_until {
            if Instant::now() < suppressed_until {
                return;
            }
            self.sidebar_hover_preview_suppressed_until = None;
        }
        if !self.sidebar_hover_preview_open {
            self.sidebar_hover_preview_open = true;
            cx.notify();
        }
    }

    fn schedule_sidebar_hover_preview_close(&mut self, cx: &mut Context<Self>) {
        if !self.sidebar_hover_preview_open
            || self.sidebar_picker_task.is_some()
            || self.sidebar_rename_target.is_some()
            || self.sidebar_menu_hover_latch
        {
            return;
        }
        self.sidebar_hover_preview_close_task = None;
        self.sidebar_hover_preview_close_task = Some(cx.spawn(async move |entity, cx| {
            cx.background_executor()
                .timer(SIDEBAR_HOVER_PREVIEW_CLOSE_DELAY)
                .await;
            let _ = entity.update(cx, |this, cx| {
                this.sidebar_hover_preview_close_task = None;
                if this.sidebar_hover_preview_open {
                    this.sidebar_hover_preview_open = false;
                    cx.notify();
                }
            });
        }));
    }

    fn handle_sidebar_hover(&mut self, hovered: bool, cx: &mut Context<Self>) {
        if hovered {
            self.open_sidebar_hover_preview(cx);
        } else {
            self.schedule_sidebar_hover_preview_close(cx);
        }
    }

    /// Arms the menu latch for a sidebar popup menu. While latched, the hover
    /// preview stays open even when the pointer moves onto the popup menu
    /// (which occludes the sidebar panel and fires `on_hover(false)`).
    fn begin_sidebar_menu_hover(&mut self, cx: &mut Context<Self>) {
        self.sidebar_menu_hover_latch = true;
        self.retain_sidebar_hover_preview();
        cx.notify();
    }

    /// Releases the menu latch when the popup menu dismisses. Re-arms the
    /// auto-close only when the pointer has not returned to the sidebar.
    fn end_sidebar_menu_hover(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.sidebar_menu_hover_latch = false;
        if !self.sidebar_hover_preview_open {
            return;
        }
        let viewport_width = self.last_visibility.layout.viewport_width;
        let position = window.mouse_position();
        let over_trigger = position.x <= px(TITLE_BAR_COLLAPSED_SIDEBAR_WIDTH)
            && position.y <= px(TITLE_BAR_HEIGHT);
        let over_panel = position.y >= px(TITLE_BAR_HEIGHT)
            && position.x <= px(sidebar_floating_width(viewport_width));
        if !over_trigger && !over_panel {
            self.schedule_sidebar_hover_preview_close(cx);
        }
    }

    /// Subscribes to the popup menu's dismiss event so the latch is released
    /// on every dismissal path (item click, Escape, click outside). The
    /// subscription is detached because it is bound to the menu entity itself,
    /// which drops when the menu closes.
    fn hold_sidebar_hover_preview_for_menu(
        menu: &Entity<PopupMenu>,
        entity: &WeakEntity<Self>,
        window: &mut Window,
        cx: &mut App,
    ) {
        let latch_entity = entity.clone();
        let subscription = window.subscribe(
            menu,
            cx,
            move |_: Entity<PopupMenu>, _: &DismissEvent, window, cx| {
                let _ = latch_entity.update(cx, |this, cx| {
                    this.end_sidebar_menu_hover(window, cx);
                });
            },
        );
        subscription.detach();
    }

    fn toggle_sidebar(&mut self, cx: &mut Context<Self>) {
        let docked = self.last_visibility.sidebar_docked;
        let was_closing =
            self.sidebar_overlay_open || (docked && self.ui_state.workbench.sidebar_visible);
        let next = toggled_sidebar_display(
            docked,
            self.ui_state.workbench.sidebar_visible,
            self.sidebar_overlay_open,
        );
        let visibility_changed = self.ui_state.workbench.sidebar_visible != next.requested_open;
        self.ui_state.workbench.sidebar_visible = next.requested_open;
        self.sidebar_overlay_open = next.drawer_open;
        if visibility_changed {
            self.queue_ui_state();
        }
        if was_closing {
            self.suppress_sidebar_hover_preview();
        } else {
            self.close_sidebar_hover_preview();
        }
        cx.notify();
    }

    fn toggle_preview(&mut self, cx: &mut Context<Self>) {
        if self.preview_panel_open() {
            self.collapse_code_preview(cx);
            return;
        }
        if self.last_visibility.preview_docked {
            self.ui_state.workbench.preview_visible = true;
            self.queue_ui_state();
        } else {
            (self.preview_overlay_open, self.right_rail_overlay_open) =
                toggle_exclusive_overlay(self.preview_overlay_open, self.right_rail_overlay_open);
        }
        if self.ui_state.workbench.preview_window_mode.is_window()
            && let Some(window_handle) = self.window_handle
        {
            self.detach_preview_window(window_handle, cx);
        }
        cx.notify();
    }

    /// Opens the editor panel where the user configured it to open.
    pub(crate) fn reveal_code_preview(&mut self, cx: &mut Context<Self>) {
        self.show_code_preview_inline(cx);
        if self.ui_state.workbench.preview_window_mode.is_window()
            && let Some(window_handle) = self.window_handle
        {
            self.detach_preview_window(window_handle, cx);
        }
    }

    /// Makes the panel visible without moving it between hosts.
    ///
    /// The dock, detach, and hand-back paths use this: they have already
    /// decided where the panel lives, and re-reading the preference there would
    /// undo the move they are in the middle of.
    fn show_code_preview_inline(&mut self, cx: &mut Context<Self>) {
        let visibility_changed = !self.ui_state.workbench.preview_visible;
        self.ui_state.workbench.preview_visible = true;
        if !self.last_visibility.preview_docked {
            self.preview_overlay_open = true;
            self.right_rail_overlay_open = false;
        }
        if visibility_changed {
            self.queue_ui_state();
        }
        cx.notify();
    }

    /// Collapses the editor panel without touching its tabs.
    ///
    /// The rail's logo button and the panel header's close button both land
    /// here, so hiding the panel means one thing wherever it is asked for: the
    /// tabs stay open and the panel comes back exactly as it was left.
    ///
    /// Collapsing the panel closes its window too; the workbench clears the
    /// handle first so the window teardown does not read as "dock it back".
    pub(crate) fn collapse_code_preview(&mut self, cx: &mut Context<Self>) {
        if !self.preview_panel_open() {
            return;
        }
        if self.last_visibility.preview_docked {
            self.ui_state.workbench.preview_visible = false;
            self.queue_ui_state();
        } else {
            self.preview_overlay_open = false;
        }
        self.code_workbench
            .update(cx, |workbench, cx| workbench.exit_fullscreen(cx));
        self.close_preview_window(cx);
        cx.notify();
    }

    pub(crate) fn reveal_file_in_right_rail(&mut self, cx: &mut Context<Self>) {
        self.open_right_rail_mode(RightRailMode::Files, cx);
    }

    pub(crate) fn close_right_rail(&mut self, cx: &mut Context<Self>) {
        let visibility_changed = self.ui_state.workbench.right_rail_visible;
        self.ui_state.workbench.right_rail_visible = false;
        self.right_rail_overlay_open = false;
        self.child_agent_panel_active = false;
        if visibility_changed {
            self.queue_ui_state();
        }
        cx.notify();
    }

    fn open_child_agent_timeline(&mut self, session_id: VibexSessionId, cx: &mut Context<Self>) {
        if !self.child_agent_tabs.contains(&session_id) {
            self.child_agent_tabs.push(session_id.clone());
        }
        self.child_agent_active_tab = Some(session_id.clone());
        self.ensure_child_agent_timeline(session_id, false, cx);
        self.open_child_agent_panel(cx);
    }

    fn open_child_agent_panel(&mut self, cx: &mut Context<Self>) {
        if self.child_agent_tabs.is_empty() {
            let child_session_id = self.timeline.rows().into_iter().rev().find_map(|row| {
                timeline_row_delegation(&row, &self.timeline.items)
                    .map(|delegation| delegation.child_session_id)
            });
            let Some(child_session_id) = child_session_id else {
                return;
            };
            self.child_agent_tabs.push(child_session_id.clone());
            self.child_agent_active_tab = Some(child_session_id.clone());
            self.ensure_child_agent_timeline(child_session_id, false, cx);
        }
        self.child_agent_panel_active = true;
        let visibility_changed = !self.ui_state.workbench.right_rail_visible;
        self.ui_state.workbench.right_rail_visible = true;
        if !self.right_rail_docks_when_open(cx) {
            self.right_rail_overlay_open = true;
            self.preview_overlay_open = false;
        } else {
            self.right_rail_overlay_open = false;
        }
        if visibility_changed {
            self.queue_ui_state();
        }
        cx.notify();
    }

    fn toggle_child_agent_panel(&mut self, cx: &mut Context<Self>) {
        if self.right_rail_panel_open() && self.child_agent_panel_active {
            self.close_right_rail(cx);
        } else {
            self.open_child_agent_panel(cx);
        }
    }

    fn select_child_agent_tab(&mut self, session_id: VibexSessionId, cx: &mut Context<Self>) {
        if self.child_agent_tabs.contains(&session_id) {
            self.child_agent_active_tab = Some(session_id.clone());
            self.ensure_child_agent_timeline(session_id, false, cx);
            cx.notify();
        }
    }

    fn close_child_agent_tab(&mut self, session_id: &VibexSessionId, cx: &mut Context<Self>) {
        let Some(index) = self
            .child_agent_tabs
            .iter()
            .position(|candidate| candidate == session_id)
        else {
            return;
        };
        self.child_agent_tabs.remove(index);
        // The tab's retained text views and scroll state go with it: nothing
        // paints those surfaces again until the child is reopened, and a rail
        // that keeps every child it ever showed pays for timelines nobody
        // reads.
        self.child_agent_markdown_states.remove(session_id.as_str());
        self.child_agent_timeline_scrollers
            .remove(session_id.as_str());
        self.child_agent_timeline_scroller_revisions
            .remove(session_id.as_str());
        if self.child_agent_active_tab.as_ref() == Some(session_id) {
            self.child_agent_active_tab = self
                .child_agent_tabs
                .get(index)
                .cloned()
                .or_else(|| self.child_agent_tabs.last().cloned());
        }
        if self.child_agent_tabs.is_empty() {
            self.child_agent_panel_active = false;
            self.close_right_rail(cx);
            return;
        }
        cx.notify();
    }

    fn open_right_rail_mode(&mut self, mode: RightRailMode, cx: &mut Context<Self>) {
        if mode == RightRailMode::Git && !self.selected_session_supports_git() {
            return;
        }
        self.child_agent_panel_active = false;
        let activity_id = right_rail_activity_id(mode).to_string();
        let mode_changed =
            self.ui_state.right_rail.selected_activity_id.as_ref() != Some(&activity_id);
        self.right_rail_mode = mode;
        self.code_workbench.update(cx, |workbench, cx| {
            workbench.right_rail_mode = mode;
            cx.notify();
        });
        self.code_right_rail
            .update(cx, |right_rail, cx| right_rail.set_mode(mode, cx));
        self.ui_state.right_rail.selected_activity_id = Some(activity_id);
        let visibility_changed = !self.ui_state.workbench.right_rail_visible;
        self.ui_state.workbench.right_rail_visible = true;
        if !self.right_rail_docks_when_open(cx) {
            self.right_rail_overlay_open = true;
            self.preview_overlay_open = false;
        } else {
            self.right_rail_overlay_open = false;
        }
        if visibility_changed || mode_changed {
            self.queue_ui_state();
        }
        cx.notify();
    }

    fn toggle_right_rail_mode(&mut self, mode: RightRailMode, cx: &mut Context<Self>) {
        let current_mode = self.right_rail_mode;
        let panel_open = if self.last_visibility.right_rail_docked {
            self.ui_state.workbench.right_rail_visible
        } else {
            self.right_rail_overlay_open
        };
        if panel_open && current_mode == mode {
            self.close_right_rail(cx);
        } else {
            self.open_right_rail_mode(mode, cx);
        }
    }

    fn toggle_right_rail(&mut self, cx: &mut Context<Self>) {
        let panel_open = if self.last_visibility.right_rail_docked {
            self.ui_state.workbench.right_rail_visible
        } else {
            self.right_rail_overlay_open
        };
        if panel_open {
            self.close_right_rail(cx);
            return;
        }
        if self.child_agent_panel_active {
            self.open_child_agent_panel(cx);
            return;
        }
        let mode = self.right_rail_mode;
        self.open_right_rail_mode(mode, cx);
    }

    fn right_rail_panel_open(&self) -> bool {
        if self.child_agent_panel_active {
            return if self.last_visibility.right_rail_docked {
                self.ui_state.workbench.right_rail_visible
            } else {
                self.right_rail_overlay_open
            };
        }
        if self.right_rail_mode == RightRailMode::Git && !self.selected_session_supports_git() {
            return false;
        }
        if self.last_visibility.right_rail_docked {
            self.ui_state.workbench.right_rail_visible
        } else {
            self.right_rail_overlay_open
        }
    }

    /// Whether the editor panel is on screen right now.
    ///
    /// A docked panel follows its visibility flag; a window too narrow to dock
    /// it shows the same choice as an overlay, exactly like the right rail.
    fn preview_panel_open(&self) -> bool {
        if self.last_visibility.preview_docked {
            self.ui_state.workbench.preview_visible
        } else {
            self.preview_overlay_open
        }
    }

    fn selected_session_supports_git(&self) -> bool {
        self.selected_session()
            .and_then(|session| self.workspace_contexts.get(session.workspace_id.as_str()))
            .is_some_and(|context| context.git_available)
    }

    /// The right rail's active panel.
    ///
    /// Both panels are cached views of their own, so nothing here runs during
    /// the workbench's render pass — the panel that owns an element tree also
    /// owns its frame requests. See [`ChildAgentRailView`].
    fn render_right_rail_panel(&mut self, cx: &mut Context<Self>) -> AnyElement {
        if self.child_agent_panel_active {
            // The rail owns its element tree: see [`ChildAgentRailView`]. It is
            // embedded here rather than built inline because everything the rail
            // mounts that animates would otherwise repaint the whole workbench.
            self.ensure_child_agent_rail_view(cx)
                .cached(StyleRefinement::default().size_full())
                .into_any_element()
        } else {
            self.code_right_rail
                .clone()
                .cached(StyleRefinement::default().size_full())
                .into_any_element()
        }
    }

    /// The activity bar buttons in the reader's order.
    fn right_rail_activity_order(&self) -> Vec<RightRailActivity> {
        resolved_right_rail_activity_order(&self.ui_state.right_rail.activity_order)
    }

    /// Remembers which side of a button a dragged activity would land on.
    fn track_right_rail_activity_drop(
        &mut self,
        activity: RightRailActivity,
        bounds: gpui::Bounds<gpui::Pixels>,
        position: gpui::Point<gpui::Pixels>,
        cx: &mut Context<Self>,
    ) {
        let position = if position.y < bounds.origin.y + bounds.size.height * 0.5 {
            RightRailActivityDropPosition::Before
        } else {
            RightRailActivityDropPosition::After
        };
        let next = RightRailActivityDropTarget { activity, position };
        if self.right_rail_activity_drop_target.as_ref() != Some(&next) {
            self.right_rail_activity_drop_target = Some(next);
            cx.notify();
        }
    }

    /// Moves a dropped activity button beside the one it landed on.
    fn drop_right_rail_activity(
        &mut self,
        dragged: RightRailActivity,
        target: RightRailActivity,
        position: RightRailActivityDropPosition,
        cx: &mut Context<Self>,
    ) {
        self.right_rail_activity_drop_target = None;
        let order = reordered_right_rail_activities(
            &self.right_rail_activity_order(),
            dragged,
            target,
            position,
        );
        let next = order
            .iter()
            .map(|activity| activity.id().to_string())
            .collect::<Vec<_>>();
        if self.ui_state.right_rail.activity_order != next {
            self.ui_state.right_rail.activity_order = next;
            self.queue_ui_state();
        }
        cx.notify();
    }

    fn render_right_rail_activity_bar(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let git_available = self.selected_session_supports_git();
        let active_mode = if git_available {
            self.right_rail_mode
        } else {
            RightRailMode::Files
        };
        let panel_open = self.right_rail_panel_open();
        let preview_open = self.preview_panel_open();
        let pending_commit_count = self.git_pending_commit_count;
        let show_git_badge =
            self.ui_state.workbench.show_git_change_count && pending_commit_count > 0;
        let child_agents_available = has_managed_child_agent_delegations(&self.timeline.items)
            || !self.child_agent_tabs.is_empty();
        // The insertion line only draws while a drag is in flight, so a
        // finished or cancelled drag cannot leave one behind.
        let drop_target = cx
            .has_active_drag()
            .then(|| self.right_rail_activity_drop_target.clone())
            .flatten();

        let mut activities = Vec::with_capacity(RightRailActivity::ALL.len());
        for activity in self.right_rail_activity_order() {
            let available = match activity {
                RightRailActivity::Git => git_available,
                RightRailActivity::ChildAgents => child_agents_available,
                _ => true,
            };
            if !available {
                continue;
            }
            let button = match activity {
                RightRailActivity::Editor => {
                    right_rail_activity_button("activity-preview", activity.icon())
                        .tooltip(if preview_open {
                            locale::text("Collapse editor", "收起编辑器", "收起編輯器")
                        } else {
                            locale::text("Open editor", "打开编辑器", "開啟編輯器")
                        })
                        .selected(preview_open)
                        .on_click(cx.listener(|this, _, _, cx| this.toggle_preview(cx)))
                        .into_any_element()
                }
                RightRailActivity::Files => right_rail_activity_button(
                    "activity-files",
                    right_rail_mode_icon(RightRailMode::Files),
                )
                .tooltip(locale::text("Files", "文件", "檔案"))
                .selected(panel_open && active_mode == RightRailMode::Files)
                .on_click(cx.listener(|this, _, _, cx| {
                    this.toggle_right_rail_mode(RightRailMode::Files, cx)
                }))
                .into_any_element(),
                RightRailActivity::Git => {
                    let git = right_rail_activity_button(
                        "activity-git",
                        right_rail_mode_icon(RightRailMode::Git),
                    )
                    .tooltip("Git")
                    .selected(panel_open && active_mode == RightRailMode::Git)
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.toggle_right_rail_mode(RightRailMode::Git, cx)
                    }));
                    div()
                        .relative()
                        .child(git)
                        .when(show_git_badge, |this| {
                            this.child(git_activity_badge(pending_commit_count, cx))
                        })
                        .into_any_element()
                }
                RightRailActivity::ChildAgents => {
                    right_rail_activity_button("activity-child-agents", Icon::new(IconName::Bot))
                        .tooltip(locale::text(
                            "Child Agent timelines",
                            "子 Agent 时间线",
                            "子 Agent 時間線",
                        ))
                        .selected(panel_open && self.child_agent_panel_active)
                        .on_click(cx.listener(|this, _, _, cx| this.toggle_child_agent_panel(cx)))
                        .into_any_element()
                }
            };
            let drop_position = drop_target
                .as_ref()
                .filter(|target| target.activity == activity)
                .map(|target| target.position);
            activities.push(
                div()
                    .id(format!("right-rail-activity-slot-{}", activity.id()))
                    .relative()
                    .flex_none()
                    .child(button)
                    // Dragging a button past its neighbours reorders the bar;
                    // the order is persisted, so it survives a restart.
                    .on_drag(RightRailActivityDrag { activity }, |drag, _, _, cx| {
                        cx.new(|_| drag.clone())
                    })
                    .on_drag_move(cx.listener(
                        move |this, event: &DragMoveEvent<RightRailActivityDrag>, _, cx| {
                            if !event.bounds.contains(&event.event.position) {
                                return;
                            }
                            this.track_right_rail_activity_drop(
                                activity,
                                event.bounds,
                                event.event.position,
                                cx,
                            );
                        },
                    ))
                    .on_drop(
                        cx.listener(move |this, drag: &RightRailActivityDrag, _, cx| {
                            let position = this
                                .right_rail_activity_drop_target
                                .as_ref()
                                .filter(|target| target.activity == activity)
                                .map(|target| target.position)
                                .unwrap_or(RightRailActivityDropPosition::Before);
                            this.drop_right_rail_activity(drag.activity, activity, position, cx);
                            cx.stop_propagation();
                        }),
                    )
                    .when_some(drop_position, |this, position| {
                        this.child(right_rail_activity_drop_line(position, cx))
                    })
                    .into_any_element(),
            );
        }

        v_flex()
            .id("right-rail-activity-bar")
            .w(px(RIGHT_ACTIVITY_BAR_WIDTH))
            .h_full()
            .flex_none()
            .items_center()
            .gap(px(RIGHT_ACTIVITY_ITEM_GAP))
            // The seam belongs to the open panel: with every rail surface
            // collapsed the workbench edge stays unbroken.
            .when(panel_open, |this| {
                this.border_l_1().border_color(cx.theme().border)
            })
            .bg(cx.theme().background)
            // Clear the floating chrome.
            .pt(px(TITLE_BAR_HEIGHT + RIGHT_ACTIVITY_BAR_VERTICAL_PADDING))
            .pb(px(RIGHT_ACTIVITY_BAR_VERTICAL_PADDING))
            .children(activities)
            .child(div().flex_1())
            .into_any_element()
    }

    fn open_management(&mut self, cx: &mut Context<Self>) {
        let sidebar_was_open = self.sidebar_overlay_open || self.sidebar_hover_preview_open;
        self.dismiss_sidebar_for_navigation();
        self.home_arena.update(cx, |arena, cx| arena.close(cx));
        self.new_session_open = false;
        self.new_session_error = None;
        self.clear_suggestions();
        if self.ui_state.workbench.active_tab == "management" {
            if sidebar_was_open {
                cx.notify();
            }
            return;
        }
        self.sync_current_navigation_entry();
        self.usage_session_filter = None;
        self.ui_state.workbench.active_tab = "management".to_string();
        self.sync_agent_streaming_surface_visibility();
        self.queue_ui_state();
        if let Some(runtime) = self.runtime.clone() {
            self.management_view.update(cx, |management, cx| {
                management.set_runtime(runtime.clone(), cx)
            });
        }
        self.sync_management_agent_ordering(cx);
        self.sync_management_pairing_context(cx);
        // The cards carry the persisted per-Agent tool answers, and the local
        // authority may have been replaced since they were last pushed.
        self.sync_agent_tool_state(cx);
        self.push_current_navigation_entry();
        cx.notify();
    }

    fn open_usage(&mut self, session_filter: Option<VibexSessionId>, cx: &mut Context<Self>) {
        let sidebar_was_open = self.sidebar_overlay_open || self.sidebar_hover_preview_open;
        self.dismiss_sidebar_for_navigation();
        self.home_arena.update(cx, |arena, cx| arena.close(cx));
        self.new_session_open = false;
        self.new_session_error = None;
        self.clear_suggestions();
        if self.ui_state.workbench.active_tab == "usage"
            && self.usage_session_filter == session_filter
        {
            if sidebar_was_open {
                cx.notify();
            }
            return;
        }
        self.sync_current_navigation_entry();
        self.ui_state.workbench.active_tab = "usage".to_string();
        self.usage_session_filter = session_filter.clone();
        self.sync_agent_streaming_surface_visibility();
        self.queue_ui_state();
        self.usage_view
            .update(cx, |usage, cx| usage.activate(session_filter, cx));
        self.push_current_navigation_entry();
        cx.notify();
    }

    fn open_management_and_discover_agents(&mut self, cx: &mut Context<Self>) {
        self.open_management(cx);
        self.management_view.update(cx, |management, cx| {
            management.request_local_agent_discovery(cx);
        });
    }

    fn sync_management_pairing_context(&mut self, cx: &mut Context<Self>) {
        let context = self
            .selected_session()
            .map(|session| {
                (
                    Some(session.workspace_root.clone()),
                    Some(session.workspace_id.clone()),
                    Some(session.id.as_str().to_string()),
                    session.workspace_mode,
                )
            })
            .or_else(|| {
                let selected_workspace_id =
                    self.ui_state.workbench.selected_workspace_id.as_deref()?;
                self.workspaces
                    .iter()
                    .find(|(_, workspace)| workspace.id.as_str() == selected_workspace_id)
                    .map(|(_, workspace)| {
                        (
                            Some(workspace.root_path.clone()),
                            Some(workspace.id.clone()),
                            None,
                            workspace.mode,
                        )
                    })
            });
        let (workspace, workspace_id, session_id, workspace_mode) =
            context.unwrap_or((None, None, None, WorkspaceMode::CurrentCheckout));
        let mode = match workspace_mode {
            WorkspaceMode::CurrentCheckout => "current_checkout",
            WorkspaceMode::VibexWorktree => "vibex_worktree",
        };
        self.management_view.update(cx, |management, cx| {
            management.set_pairing_context(workspace, workspace_id, session_id, mode, cx)
        });
    }

