        if self.ui_state.session.reasoning_expanded_by_default == expanded {
            return;
        }
        self.ui_state.session.reasoning_expanded_by_default = expanded;
        self.reasoning_expansion.clear();
        self.invalidate_timeline_layout_measurements();
