#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NotificationKind {
    Completed,
    NeedsInput,
    Failed,
}

fn timeline_notification_tone(kind: NotificationKind) -> NotificationType {
    match kind {
        NotificationKind::Completed => NotificationType::Success,
        NotificationKind::NeedsInput => NotificationType::Info,
        NotificationKind::Failed => NotificationType::Error,
    }
}

fn timeline_notification_body(kind: Option<NotificationKind>, agent_label: &str) -> Option<String> {
    let locale = locale::current_locale();
    match kind {
        Some(NotificationKind::Failed) => Some(match locale {
            locale::ResolvedLocale::En => format!("{agent_label} encountered an error"),
            locale::ResolvedLocale::ZhCn => format!("{agent_label} 出现错误"),
            locale::ResolvedLocale::ZhTw => format!("{agent_label} 出現錯誤"),
        }),
        Some(NotificationKind::NeedsInput) => Some(match locale {
            locale::ResolvedLocale::En => format!("{agent_label} needs your confirmation"),
            locale::ResolvedLocale::ZhCn => format!("{agent_label} 需要你确认内容"),
            locale::ResolvedLocale::ZhTw => format!("{agent_label} 需要你確認內容"),
        }),
        Some(NotificationKind::Completed) => Some(match locale {
            locale::ResolvedLocale::En => format!("{agent_label} completed work"),
            locale::ResolvedLocale::ZhCn | locale::ResolvedLocale::ZhTw => {
                format!("{agent_label} 工作完成")
            }
        }),
        None => None,
    }
}

/// Splits a batch into the events past `previous` (the session's last announced
/// sequence) and the watermark that batch advances to. The live event stream
/// and the polling fallback both deliver the same committed item, so only the
/// first delivery is past the mark.
fn new_timeline_notification_events(
    events: &[TimelineLiveEvent],
    previous: Option<i64>,
) -> (Vec<&TimelineLiveEvent>, Option<i64>) {
    let max_sequence = events.iter().map(|event| event.sequence).max();
    let fresh = events
        .iter()
        .filter(|event| previous.is_none_or(|previous| event.sequence > previous))
        .collect();
    let watermark = match (previous, max_sequence) {
        (Some(previous), Some(max_sequence)) => Some(previous.max(max_sequence)),
        (None, max_sequence) => max_sequence,
        (previous, None) => previous,
    };
    (fresh, watermark)
}

fn timeline_notification_kind(
    events: &[&TimelineLiveEvent],
    preferences: &DesktopBehaviorUiState,
) -> Option<NotificationKind> {
    if preferences.notify_agent_failed
        && events
            .iter()
            .any(|event| matches!(event.item.payload, TimelinePayload::Error(_)))
    {
        return Some(NotificationKind::Failed);
    }
    if preferences.notify_agent_needs_input
        && events.iter().any(|event| {
            matches!(
                event.item.payload,
                TimelinePayload::PermissionRequest(_) | TimelinePayload::ElicitationRequest(_)
            )
        })
    {
        return Some(NotificationKind::NeedsInput);
    }
    (preferences.notify_agent_completed
        && events.iter().any(|event| {
            matches!(
                &event.item.payload,
                TimelinePayload::AgentMessage(message) if message.is_final
            )
        }))
    .then_some(NotificationKind::Completed)
}

const FOUNDATION_SHORTCUTS: &[(&str, &str)] = &[
    ("toggle_sidebar", "cmd-b"),
    ("toggle_preview", "cmd-shift-p"),
    ("toggle_right_rail", "cmd-shift-r"),
    ("toggle_composer_mode", "cmd-shift-t"),
    ("open_settings", "cmd-,"),
    ("open_runtime_manager", "cmd-shift-o"),
    ("open_conversation_find", "cmd-f"),
    ("open_command_palette", "cmd-k"),
    ("retry_runtime", "cmd-r"),
    ("save_active_file", "cmd-s"),
    ("goto_line_in_editor", "ctrl-g"),
    ("navigate_back", "alt-left"),
    ("navigate_forward", "alt-right"),
    ("undo_image_edit", UNDO_IMAGE_EDIT_SHORTCUT),
    ("redo_image_edit", REDO_IMAGE_EDIT_SHORTCUT),
];

// The image editor mirrors the text-input undo/redo chords so muscle memory carries over, and the
// text input itself binds `cmd-z` on macOS while every other platform binds `ctrl-z`.
#[cfg(target_os = "macos")]
const UNDO_IMAGE_EDIT_SHORTCUT: &str = "cmd-z";
#[cfg(not(target_os = "macos"))]
const UNDO_IMAGE_EDIT_SHORTCUT: &str = "ctrl-z";
#[cfg(target_os = "macos")]
const REDO_IMAGE_EDIT_SHORTCUT: &str = "cmd-shift-z";
#[cfg(not(target_os = "macos"))]
const REDO_IMAGE_EDIT_SHORTCUT: &str = "ctrl-shift-z";

/// The user-facing name of a foundation action.
///
/// One label serves the shortcuts settings page, the settings search results,
/// and the command palette's quick actions, so the same command cannot be named
/// two different things in two places. Every entry is localized — an English
/// label here would surface as mixed-language copy on an otherwise translated
/// page.
fn shortcut_action_label(action: &str, strings: &'static Strings) -> &'static str {
    let locale = strings.locale;
    match action {
        "toggle_sidebar" => locale::text_for(locale, "Toggle sidebar", "切换侧栏", "切換側邊欄"),
        "toggle_preview" => locale::text_for(locale, "Toggle editor", "切换编辑器", "切換編輯器"),
        "toggle_right_rail" => {
            locale::text_for(locale, "Toggle right rail", "切换右侧栏", "切換右側欄")
        }
        "toggle_composer_mode" => locale::text_for(
            locale,
            "Toggle conversation / terminal",
            "切换对话/终端模式",
            "切換對話/終端機模式",
        ),
        "open_settings" => locale::text_for(locale, "Open settings", "打开设置", "開啟設定"),
        "open_runtime_manager" => {
            locale::text_for(locale, "Open runtimes", "打开运行时", "開啟執行階段")
        }
        "open_conversation_find" => locale::text_for(
            locale,
            "Find in conversation",
            "在当前会话中查找",
            "在目前會話中尋找",
        ),
        "open_command_palette" => locale::text_for(locale, "Global search", "全局搜索", "全域搜尋"),
        "retry_runtime" => locale::text_for(locale, "Retry runtime", "重试运行时", "重試執行階段"),
        "save_active_file" => {
            locale::text_for(locale, "Save active file", "保存当前文件", "儲存目前檔案")
        }
        "goto_line_in_editor" => {
            locale::text_for(locale, "Go to line in editor", "跳转到行", "跳轉到行")
        }
        "navigate_back" => locale::text_for(locale, "Navigate back", "后退", "返回"),
        "navigate_forward" => locale::text_for(locale, "Navigate forward", "前进", "前進"),
        "undo_image_edit" => {
            locale::text_for(locale, "Undo image edit", "撤销图片编辑", "復原圖片編輯")
        }
        "redo_image_edit" => {
            locale::text_for(locale, "Redo image edit", "重做图片编辑", "重做圖片編輯")
        }
        _ => locale::text_for(locale, "Shortcut", "快捷键", "快速鍵"),
    }
}

/// The group a foundation action belongs to, shown as the row's supporting line.
///
/// "Vibex" is the fallback for an action this table has not classified; it is a
/// product name rather than a category, so it stays untranslated.
fn shortcut_action_group(action: &str, strings: &'static Strings) -> &'static str {
    let locale = strings.locale;
    let navigation = || locale::text_for(locale, "Navigation", "导航", "導覽");
    match action {
        "toggle_sidebar" | "toggle_preview" | "toggle_right_rail" | "open_runtime_manager" => {
            locale::text_for(locale, "Workbench", "工作台", "工作台")
        }
        "toggle_composer_mode" => locale::text_for(locale, "Composer", "输入框", "輸入框"),
        "open_settings" | "open_conversation_find" | "open_command_palette" => navigation(),
        "retry_runtime" => locale::text_for(locale, "Runtime", "运行时", "執行階段"),
        "save_active_file" | "goto_line_in_editor" => {
            locale::text_for(locale, "Editor", "编辑器", "編輯器")
        }
        "navigate_back" | "navigate_forward" => navigation(),
        "undo_image_edit" | "redo_image_edit" => {
            locale::text_for(locale, "Image editor", "图片编辑器", "圖片編輯器")
        }
        _ => "Vibex",
    }
}

fn effective_shortcut<'a>(
    overrides: &'a BTreeMap<String, String>,
    action: &str,
) -> Option<&'a str> {
    overrides.get(action).map(String::as_str).or_else(|| {
        FOUNDATION_SHORTCUTS
            .iter()
            .find(|(name, _)| *name == action)
            .map(|(_, key)| *key)
    })
}

fn rebind_foundation_action(
    cx: &mut App,
    action: &str,
    previous: Option<&str>,
    current: Option<&str>,
) {
    if previous == current {
        return;
    }
    let mut bindings = Vec::new();
    if let Some(previous) = previous {
        bindings.push(KeyBinding::new(
            previous,
            Unbind(action_name(action).into()),
            None,
        ));
    }
    if let Some(current) = current {
        bind_action(&mut bindings, current, action, false);
    }
    cx.bind_keys(bindings);
}

fn clear_shortcut_overrides(overrides: &mut BTreeMap<String, String>, cx: &mut App) {
    let previous = std::mem::take(overrides);
    for (action, default) in FOUNDATION_SHORTCUTS {
        let old_effective = effective_shortcut(&previous, action);
        rebind_foundation_action(cx, action, old_effective, Some(default));
    }
}

fn settings_section_for_query(query: &str) -> Option<SettingsSection> {
    if query.is_empty() {
        return None;
    }
    let matches = |terms: &[&str]| {
        terms
            .iter()
            .any(|term| term.contains(query) || query.contains(term))
    };
    if matches(&[
        "general",
        "startup",
        "notification",
        "language",
        // The same-machine client switch lives on General, so a reader looking
        // for it by the client it serves is sent there too.
        "tui",
        "local client",
        "terminal client",
        "常规",
        "启动",
        "通知",
        "一般",
        "啟動",
        "本机客户端",
        "本機用戶端",
    ]) {
        Some(SettingsSection::General)
    } else if matches(&[
        "appearance",
        "theme",
        "font",
        "scale",
        "zoom",
        "缩放",
        "縮放",
        "contrast",
        "motion",
        "外观",
        "主题",
        "字体",
        "對比",
        "動效",
    ]) {
        Some(SettingsSection::Appearance)
    } else if matches(&[
        "workbench",
        "layout",
        "sidebar",
        "worktree",
        "工作台",
        "布局",
        "侧栏",
        "版面",
        "側欄",
    ]) {
        Some(SettingsSection::Workbench)
    } else if matches(&[
        "connection",
        "connections",
        "ssh",
        "remote",
        "host",
        "连接",
        "連線",
        "远程",
        "遠端",
        "主机",
        "主機",
    ]) {
        Some(SettingsSection::Connections)
    } else if matches(&[
        "archived", "archive", "restore", "归档", "封存", "復原", "复原",
    ]) {
        Some(SettingsSection::Archived)
    } else if matches(&[
        "session", "agent", "queue", "send", "会话", "消息", "队列", "會話", "訊息", "佇列",
    ]) {
        Some(SettingsSection::Session)
    } else if matches(&[
        "terminal",
        "shell",
        "cwd",
        "终端",
        "終端機",
        "工作目录",
        "工作目錄",
    ]) {
        Some(SettingsSection::Terminal)
    } else if matches(&[
        "browser",
        "web",
        "start page",
        "home page",
        "search engine",
        "search",
        "浏览器",
        "瀏覽器",
        "起始页",
        "首頁",
        "搜索引擎",
        "搜尋引擎",
    ]) {
        Some(SettingsSection::Browser)
    } else if matches(&[
        "computer",
        "computer use",
        "desktop",
        "driver",
        "approval",
        "电脑操作",
        "電腦操作",
        "桌面",
        "驱动",
        "驅動",
        "审批",
        "審批",
    ]) {
        Some(SettingsSection::Computer)
    } else if matches(&[
        "shortcut",
        "key",
        "input mode",
        "快捷键",
        "快速鍵",
        "输入模式",
        "輸入模式",
    ]) {
        Some(SettingsSection::Shortcuts)
    } else if matches(&[
        "data",
        "diagnostic",
        "storage",
        "backup",
        "数据",
        "诊断",
        "資料",
        "診斷",
    ]) {
        Some(SettingsSection::Data)
    } else if matches(&[
        "developer",
        "fps",
        "frame",
        "performance",
        "profiling",
        "开发者",
        "開發者",
        "帧率",
        "幀率",
    ]) {
        Some(SettingsSection::Developer)
    } else if matches(&[
        "about",
        "version",
        "license",
        "release",
        "关于",
        "版本",
        "许可证",
        "關於",
        "授權",
    ]) {
        Some(SettingsSection::About)
    } else {
        None
    }
}

const fn settings_search_candidate(
    section: SettingsSection,
    title: &'static str,
    description: &'static str,
    keywords: &'static [&'static str],
) -> SettingsSearchCandidate {
    SettingsSearchCandidate {
        section,
        title,
        description,
        keywords,
    }
}

