fn settings_search_candidates_for_query(
    query: &str,
    strings: &'static Strings,
) -> Vec<SettingsSearchCandidate> {
    let query = query.trim().to_lowercase();
    if query.is_empty() {
        return Vec::new();
    }
    settings_search_candidates(strings)
        .into_iter()
        .filter(|candidate| {
            std::iter::once(candidate.title)
                .chain(std::iter::once(candidate.description))
                .chain(std::iter::once(settings_section_label(candidate.section)))
                .chain(candidate.keywords.iter().copied())
                .any(|term| {
                    let term = term.to_lowercase();
                    term.contains(&query) || query.contains(&term)
                })
        })
        .take(SETTINGS_SEARCH_RESULT_LIMIT)
        .collect()
}

/// The palette's label for a quick action.
///
/// The foundation actions already carry localized labels in
/// [`shortcut_action_label`]; only the two the palette introduces on its own
/// need wording here.
fn command_palette_action_label(action: &'static str, strings: &'static Strings) -> &'static str {
    match action {
        "new_session" => locale::text("New session", "新建会话", "新增工作階段"),
        "pair_mobile_device" => strings.pair_mobile,
        other => shortcut_action_label(other, strings),
    }
}

/// Extra search terms for a quick action, on top of its label.
///
/// The English action name is always included, so a user typing `rail` finds
/// "Toggle right rail" even in a Chinese or Taiwanese locale where the label
/// carries no Latin words.
fn command_palette_action_keywords(action: &'static str) -> Vec<&'static str> {
    let mut keywords = action.split('_').collect::<Vec<_>>();
    keywords.push(match action {
        "new_session" => "chat create",
        "pair_mobile_device" => "phone qr link",
        "open_settings" => "preferences",
        "open_runtime_manager" => "provider model auth",
        "open_conversation_find" => "find message",
        "toggle_sidebar" => "rail projects",
        "toggle_composer_mode" => "terminal shell",
        "toggle_preview" => "browser web",
        "toggle_right_rail" => "panel files git",
        "navigate_back" => "history previous",
        "navigate_forward" => "history next",
        _ => "",
    });
    keywords
}

/// The `Action` a quick action row dispatches.
///
/// `None` means the action is not registered yet, which is a programming error
/// rather than a state: the palette would then render a row that silently does
/// nothing. The row is dropped instead.
fn command_palette_action(action: &'static str) -> Option<Box<dyn gpui::Action>> {
    Some(match action {
        "new_session" => Box::new(NewSession),
        "open_settings" => Box::new(OpenSettings),
        "open_runtime_manager" => Box::new(OpenRuntimeManager),
        "open_conversation_find" => Box::new(OpenConversationFind),
        "toggle_sidebar" => Box::new(ToggleSidebar),
        "toggle_composer_mode" => Box::new(ToggleComposerMode),
        "toggle_preview" => Box::new(TogglePreview),
        "toggle_right_rail" => Box::new(ToggleRightRail),
        "navigate_back" => Box::new(NavigateBack),
        "navigate_forward" => Box::new(NavigateForward),
        "pair_mobile_device" => Box::new(PairMobileDevice),
        _ => return None,
    })
}

/// Whether a quick action can run right now.
///
/// The handlers already refuse when their precondition is unmet; a disabled row
/// says so before the click instead of leaving the user with a command that
/// silently did nothing.
fn command_palette_action_enabled(action: &str, workbench: &VibexWorkbench) -> bool {
    match action {
        "new_session" => !workbench.agent_action_pending && workbench.sidebar_picker_task.is_none(),
        // Find and terminal mode both act on the open conversation.
        "open_conversation_find" | "toggle_composer_mode" => {
            workbench.conversation_context_active()
        }
        "navigate_back" => workbench.navigation_history.can_go_back(),
        "navigate_forward" => workbench.navigation_history.can_go_forward(),
        _ => true,
    }
}

/// The palette's leading glyph for a quick action.
fn command_palette_action_icon(action: &'static str) -> Icon {
    match action {
        "new_session" => Icon::new(IconName::Plus),
        "open_settings" => Icon::new(IconName::Settings),
        "open_runtime_manager" => Icon::default().path(RUNTIME_MANAGER_ICON),
        "open_conversation_find" => Icon::new(IconName::Search),
        "toggle_sidebar" => Icon::new(IconName::PanelLeftClose),
        "toggle_composer_mode" => Icon::new(IconName::SquareTerminal),
        "toggle_preview" => Icon::new(IconName::Frame),
        "toggle_right_rail" => Icon::new(IconName::PanelRightClose),
        "navigate_back" => Icon::new(IconName::ArrowLeft),
        "navigate_forward" => Icon::new(IconName::ArrowRight),
        "pair_mobile_device" => Icon::new(IconName::Network),
        _ => Icon::new(IconName::Asterisk),
    }
}

/// Every Agent Vibex ships with, in catalog order, as palette candidates.
///
/// The Config Center lists the same set — installed or not — because an Agent
/// that has not been added yet is exactly the one whose configuration the user
/// needs to reach. A configured Agent contributes its live label so a rename
/// is searchable, and `builtin_agent_definitions` supplies the rest.
fn command_palette_agent_candidates(
    live_agents: &[AgentSnapshotEntry],
) -> Vec<CommandPaletteAgentCandidate> {
    vibex_core::builtin_agent_definitions()
        .into_iter()
        .filter(|definition| vibex_core::is_user_visible_agent(&definition.id))
        .map(|definition| CommandPaletteAgentCandidate {
            label: live_agents
                .iter()
                .find(|agent| agent.id == definition.id)
                .map(|agent| agent.label.clone())
                .unwrap_or(definition.label),
            agent_id: definition.id,
        })
        .collect()
}

/// Whether an Agent survives the palette's query.
///
/// Only in the direction the user types: the query has to sit inside the name
/// or the stable id, so `claude` finds Claude Code and `claudecode` finds it
/// too, while an unrelated sentence that happens to contain `pi` does not drag
/// the Pi Agent into the results.
fn command_palette_agent_matches(candidate: &CommandPaletteAgentCandidate, query: &str) -> bool {
    let query = query.to_lowercase();
    if query.is_empty() {
        return false;
    }
    let compact_query = compact_agent_search_term(&query);
    let agent_id = candidate.agent_id.as_str();
    [candidate.label.as_str(), agent_id]
        .into_iter()
        .any(|term| {
            let term = term.to_lowercase();
            term.contains(&query)
                || (!compact_query.is_empty()
                    && compact_agent_search_term(&term).contains(&compact_query))
        })
}

/// Lowercases and drops separators so `open code`, `open-code`, and `opencode`
/// all collapse into the same search term.
fn compact_agent_search_term(value: &str) -> String {
    value
        .chars()
        .filter(|character| character.is_ascii_alphanumeric())
        .collect()
}

/// Whether a quick action survives the palette's query.
///
/// The same rule the settings entries use: a case-insensitive substring over
/// the label and every keyword, in either direction, so a short query still
/// finds a longer term.
fn command_palette_action_matches(
    action: &'static str,
    query: &str,
    strings: &'static Strings,
) -> bool {
    if query.is_empty() {
        return true;
    }
    let query = query.to_lowercase();
    let mut terms = vec![command_palette_action_label(action, strings).to_lowercase()];
    terms.extend(
        command_palette_action_keywords(action)
            .into_iter()
            .filter(|keyword| !keyword.is_empty())
            .map(str::to_lowercase),
    );
    terms
        .iter()
        .any(|term| term.contains(&query) || query.contains(term.as_str()))
}

/// Whether a palette row can be confirmed.
fn command_palette_entry_enabled(entry: &CommandPaletteEntry) -> bool {
    match entry {
        CommandPaletteEntry::Action(_, enabled) => *enabled,
        CommandPaletteEntry::Session(_)
        | CommandPaletteEntry::Agent(_)
        | CommandPaletteEntry::Setting(_) => true,
    }
}

/// The rows the palette's highlight can land on, in list order.
///
/// The component skips a disabled item when it moves its own highlight; the
/// palette resolves the same list so both agree on where the next press lands.
fn command_palette_selectable_rows(sections: &[CommandPaletteSection]) -> Vec<IndexPath> {
    sections
        .iter()
        .enumerate()
        .flat_map(|(section, group)| {
            group
                .entries
                .iter()
                .enumerate()
                .filter(|(_, entry)| command_palette_entry_enabled(entry))
                .map(move |(row, _)| IndexPath::new(row).section(section))
        })
        .collect()
}

/// The highlight a palette row paints over the part of its text that matched.
fn palette_match_highlight(cx: &App) -> HighlightStyle {
    HighlightStyle {
        background_color: Some(cx.theme().warning.opacity(0.42)),
        font_weight: Some(FontWeight::BOLD),
        ..Default::default()
    }
}

/// One palette row.
///
/// A session, an Agent, or a settings entry draws its own two-line layout,
/// because what a row is and where it lives is what the user is choosing
/// between. A quick action keeps the component's single-line menu geometry,
/// which is also what lets the row show the keybinding its Action resolves to.
fn command_palette_row(
    entry: &CommandPaletteEntry,
    query: &str,
    strings: &'static Strings,
    locale: locale::ResolvedLocale,
) -> CommandItem {
    match entry {
        CommandPaletteEntry::Session(result) => {
            let agent_id = result.agent_id.as_str().to_string();
            let title = result.session_title.clone();
            let detail = result
                .excerpt
                .clone()
                .map(|excerpt| format!("{} · {excerpt}", result.project_name))
                .unwrap_or_else(|| result.project_name.clone());
            let timestamp = format_sidebar_session_time(result.last_message_at_ms, locale, strings);
            let query = query.to_string();
            CommandItem::new()
                .label(title.clone())
                .keywords([agent_id.clone(), result.project_name.clone()])
                .child(move |_window, cx| {
                    let highlight = palette_match_highlight(cx);
                    h_flex()
                        .w_full()
                        .min_w_0()
                        .items_center()
                        .gap_3()
                        // The scrollbar paints over the list's trailing edge, so
                        // the row keeps that lane clear.
                        .pr(px(COMMAND_PALETTE_ROW_LANE))
                        .child(
                            div()
                                .size(px(28.0))
                                .flex_none()
                                .flex()
                                .items_center()
                                .justify_center()
                                .rounded(px(6.0))
                                .bg(cx.theme().muted.opacity(0.55))
                                .child(agent_brand_icon(&agent_id, px(16.0), None)),
                        )
                        .child(
                            v_flex()
                                .min_w_0()
                                .flex_1()
                                .gap(px(3.0))
                                .child(div().min_w_0().truncate().text_sm().font_medium().child(
                                    session_search_highlighted_text(
                                        title.clone(),
                                        &query,
                                        highlight,
                                    ),
                                ))
                                .child(
                                    div()
                                        .min_w_0()
                                        .truncate()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child(session_search_highlighted_text(
                                            detail.clone(),
                                            &query,
                                            highlight,
                                        )),
                                ),
                        )
                        .child(
                            div()
                                .flex_none()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(timestamp.clone()),
                        )
                        .into_any_element()
                })
        }
        CommandPaletteEntry::Agent(candidate) => {
            let agent_id = candidate.agent_id.as_str().to_string();
            let title = candidate.label.clone();
            let hint = strings.command_palette_agent_config_hint;
            let query = query.to_string();
            CommandItem::new()
                .label(title.clone())
                .keywords([agent_id.clone(), hint.to_string()])
                .child(move |_window, cx| {
                    let highlight = palette_match_highlight(cx);
                    h_flex()
                        .w_full()
                        .min_w_0()
                        .items_center()
                        .gap_3()
                        // Matches the other two-line rows, so every kind of
                        // result ends on the same trailing spine.
                        .pr(px(COMMAND_PALETTE_ROW_LANE))
                        .child(
                            div()
                                .size(px(28.0))
                                .flex_none()
                                .flex()
                                .items_center()
                                .justify_center()
                                .rounded(px(6.0))
                                .bg(cx.theme().muted.opacity(0.55))
                                .child(agent_brand_icon(&agent_id, px(16.0), None)),
                        )
                        .child(
                            v_flex()
                                .min_w_0()
                                .flex_1()
                                .gap(px(3.0))
                                .child(div().min_w_0().truncate().text_sm().font_medium().child(
                                    session_search_highlighted_text(
                                        title.clone(),
                                        &query,
                                        highlight,
                                    ),
                                ))
                                .child(
                                    div()
                                        .min_w_0()
                                        .truncate()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child(hint),
                                ),
                        )
                        .into_any_element()
                })
        }
        CommandPaletteEntry::Setting(candidate) => {
            let title = candidate.title;
            let description = candidate.description;
            let section = settings_section_label(candidate.section);
            CommandItem::new()
                .label(title)
                .keywords([section, description])
                .child(move |_window, cx| {
                    h_flex()
                        .w_full()
                        .min_w_0()
                        .items_center()
                        .gap_3()
                        // Matches the session rows, so both kinds of two-line
                        // row end on the same trailing spine.
                        .pr(px(COMMAND_PALETTE_ROW_LANE))
                        .child(
                            div()
                                .size(px(28.0))
                                .flex_none()
                                .flex()
                                .items_center()
                                .justify_center()
                                .rounded(px(6.0))
                                .bg(cx.theme().muted.opacity(0.55))
                                .child(Icon::new(IconName::Settings2).size(px(16.0))),
                        )
                        .child(
                            v_flex()
                                .min_w_0()
                                .flex_1()
                                .gap(px(3.0))
                                .child(
                                    div()
                                        .min_w_0()
                                        .truncate()
                                        .text_sm()
                                        .font_medium()
                                        .child(title),
                                )
                                .child(
                                    div()
                                        .min_w_0()
                                        .truncate()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child(section),
                                ),
                        )
                        .into_any_element()
                })
        }
        CommandPaletteEntry::Action(action, enabled) => {
            let item = CommandItem::new()
                .label(command_palette_action_label(action, strings))
                .keywords(command_palette_action_keywords(action))
                .icon(command_palette_action_icon(action))
                .disabled(!enabled);
            match command_palette_action(action) {
                Some(dispatched) => item.action(dispatched),
                // A curated entry without a registered Action would render a row
                // that silently does nothing; leave it as an inert label rather
                // than pretending it is a command.
                None => item,
            }
        }
    }
}

fn wrap_settings_search_selection(index: usize, delta: isize, count: usize) -> usize {
    if count == 0 {
        return 0;
    }
    if delta < 0 {
        let steps = delta.unsigned_abs() % count;
        (index + count - steps) % count
    } else {
        index.saturating_add(delta as usize) % count
    }
}

fn settings_search_result_scroll_index(
    candidates: &[SettingsSearchCandidate],
    selected_index: usize,
) -> usize {
    if candidates.is_empty() {
        return 0;
    }
    let selected_index = selected_index.min(candidates.len() - 1);
    let section_heading_count = (0..=selected_index)
        .filter(|&index| index == 0 || candidates[index].section != candidates[index - 1].section)
        .count();
    selected_index + section_heading_count
}

fn settings_row_id(title: &str) -> String {
    let mut id = String::from("settings-row-");
    let mut separator = false;
    for character in title.chars() {
        if character.is_alphanumeric() {
            id.push(character.to_ascii_lowercase());
            separator = false;
        } else if !separator {
            id.push('-');
            separator = true;
        }
    }
    let id = id.trim_end_matches('-');
    if id == "settings-row" {
        "settings-row-item".to_string()
    } else {
        id.to_string()
    }
}

fn format_bytes(bytes: u64) -> String {
    const UNITS: [&str; 4] = ["B", "KiB", "MiB", "GiB"];
    /// `U+00A0`, so a size that wraps onto a second line keeps its unit: a
    /// value read as "33.4" / "MiB" is a value the reader has to reassemble.
    const NO_BREAK_SPACE: char = '\u{00A0}';
    let mut value = bytes as f64;
    let mut unit = 0usize;
    while value >= 1024.0 && unit < UNITS.len() - 1 {
        value /= 1024.0;
        unit += 1;
    }
    if unit == 0 {
        format!("{bytes}{NO_BREAK_SPACE}{}", UNITS[unit])
    } else {
        format!("{value:.1}{NO_BREAK_SPACE}{}", UNITS[unit])
    }
}

/// The figures under one import source's name.
///
/// Counts and a size only: the dialog never names a site, because the list of
/// sites a reader is signed in to is itself private.
fn browser_source_detail(source: &BrowserProfileSource) -> String {
    format!(
        "{} {} · {} {} · {} {}",
        source.cookie_count,
        locale::text("cookies", "条 Cookie", "條 Cookie"),
        source.site_count,
        locale::text("sites", "个站点", "個站點"),
        format_bytes(source.local_storage_bytes),
        locale::text("localStorage", "localStorage", "localStorage"),
    )
}

/// What the import notification says: counts only.
///
/// A cookie value is a live credential, so it has no representation in
/// interface copy or anywhere else that leaves the browser stores.
fn browser_import_success(report: &BrowserLoginImportReport) -> String {
    let mut summary = format!(
        "{} · {} {} · {} {} · {} {} · {} {}",
        locale::text("Login state imported", "登录状态已导入", "登入狀態已匯入"),
        report.cookies_imported,
        locale::text("cookies", "条 Cookie", "條 Cookie"),
        report.sites_imported,
        locale::text("sites", "个站点", "個站點"),
        report.local_storage_entries,
        locale::text("localStorage entries", "条 localStorage", "條 localStorage"),
        report.local_storage_origins,
        locale::text("origins", "个来源", "個來源"),
    );
    if report.local_storage_origins_skipped > 0 {
        summary.push_str(&format!(
            " · {} {}",
            report.local_storage_origins_skipped,
            locale::text("origins skipped", "个来源已跳过", "個來源已略過"),
        ));
    }
    summary
}

/// What the clear notification says.
fn browser_clear_success(report: &BrowserDataClearReport) -> String {
    format!(
        "{} · {} {}",
        locale::text(
            "Browser data cleared",
            "浏览器数据已清除",
            "瀏覽器資料已清除"
        ),
        report.removed_files,
        locale::text("files", "个文件", "個檔案"),
    )
}

fn storage_cleanup_dialog(kind: StorageCleanupKind) -> (&'static str, &'static str) {
    match kind {
        StorageCleanupKind::SessionsAndAttachments => (
            locale::text(
                "Clear sessions and attachments?",
                "清理会话与附件？",
                "清理會話與附件？",
            ),
            locale::text(
                "This removes all local session history and uploaded or edited attachment files. It cannot be undone.",
                "这会删除所有本地会话历史以及已上传或编辑的附件文件，且无法撤销。",
                "這會刪除所有本機會話記錄以及已上傳或編輯的附件檔案，且無法復原。",
            ),
        ),
        StorageCleanupKind::Terminals => (
            locale::text("Clear terminal data?", "清理终端数据？", "清理終端機資料？"),
            locale::text(
                "This stops active terminals and removes their local history. It cannot be undone.",
                "这会停止活动终端并删除本地终端记录，且无法撤销。",
                "這會停止作用中的終端機並刪除本機終端機記錄，且無法復原。",
            ),
        ),
        StorageCleanupKind::Diagnostics => (
            locale::text("Clear diagnostic data?", "清理诊断数据？", "清理診斷資料？"),
            locale::text(
                "This removes diagnostic records, exported diagnostics and local backups. It cannot be undone.",
                "这会删除诊断记录、导出的诊断文件和本地备份，且无法撤销。",
                "這會刪除診斷記錄、匯出的診斷檔案與本機備份，且無法復原。",
            ),
        ),
    }
}

fn storage_cleanup_success(kind: StorageCleanupKind, report: StorageCleanupReport) -> String {
    let detail = match kind {
        StorageCleanupKind::SessionsAndAttachments => format!(
            "{} {} · {} {}",
            report.removed_records,
            locale::text("sessions", "个会话", "個會話"),
            report.removed_files,
            locale::text("files", "个文件", "個檔案"),
        ),
        StorageCleanupKind::Terminals => format!(
            "{} {}",
            report.removed_records,
            locale::text("terminals", "个终端", "個終端機"),
        ),
        StorageCleanupKind::Diagnostics => format!(
            "{} {} · {} {}",
            report.removed_records,
            locale::text("records", "条记录", "筆記錄"),
            report.removed_files,
            locale::text("files", "个文件", "個檔案"),
        ),
    };
    format!(
        "{} · {detail}",
        match kind {
            StorageCleanupKind::SessionsAndAttachments => {
                locale::text(
                    "Sessions and attachments cleared",
                    "会话与附件已清理",
                    "會話與附件已清理",
                )
            }
            StorageCleanupKind::Terminals => {
                locale::text(
                    "Terminal data cleared",
                    "终端数据已清理",
                    "終端機資料已清理",
                )
            }
            StorageCleanupKind::Diagnostics => {
                locale::text(
                    "Diagnostic data cleared",
                    "诊断数据已清理",
                    "診斷資料已清理",
                )
            }
        }
    )
}

