    fn set_terminal_open_mode(&mut self, mode: TerminalOpenMode, cx: &mut Context<Self>) {
        let _ = self.workbench.update(cx, |this, cx| {
            if this.ui_state.terminal_preferences.open_mode == mode {
                return;
            }
            this.ui_state.terminal_preferences.open_mode = mode;
            // The armed host no longer matches the preference. Put the terminal
            // away rather than leaving it on screen in the way the reader just
            // turned off; the Composer's terminal button puts it back in the
            // new host.
            if mode.replaces_composer() {
                // The Composer is about to draw the terminal itself, so the
                // panel goes outright instead of animating out beside the card
                // that replaces it.
                this.composer_terminal_panel_open = false;
                this.composer_terminal_panel_mounted = false;
                this.composer_terminal_panel_close_task = None;
            } else {
                this.composer_terminal_mode = false;
                this.composer_terminal_expanded = false;
            }
            this.sync_composer_terminal_surface_activity(cx);
            this.queue_ui_state();
            cx.notify();
        });
        cx.notify();
    }

    fn set_shortcut(&mut self, action: String, keystroke: String, cx: &mut Context<Self>) -> bool {
        let applied = self
            .workbench
            .update(cx, |this, cx| {
                let keystroke = keystroke.trim().to_ascii_lowercase();
                let old_effective = effective_shortcut(&this.ui_state.keyboard.shortcuts, &action)
                    .map(str::to_string);
                let default = FOUNDATION_SHORTCUTS
                    .iter()
                    .find(|(known_action, _)| *known_action == action)
                    .map(|(_, default)| *default);
                let desired = if keystroke.is_empty() {
                    default
                } else {
                    Some(keystroke.as_str())
                };
                let conflicts = desired.is_some_and(|desired| {
                    FOUNDATION_SHORTCUTS
                        .iter()
                        .filter(|(other_action, _)| *other_action != action)
                        .any(|(other_action, _)| {
                            effective_shortcut(&this.ui_state.keyboard.shortcuts, other_action)
                                == Some(desired)
                        })
                });
                let valid = default.is_some()
                    && (keystroke.is_empty() || shortcut_is_valid(&keystroke))
                    && !conflicts;
                if valid {
                    if keystroke.is_empty() {
                        this.ui_state.keyboard.shortcuts.remove(&action);
                    } else {
                        this.ui_state
                            .keyboard
                            .shortcuts
                            .insert(action.clone(), keystroke);
                    }
                    let new_effective =
                        effective_shortcut(&this.ui_state.keyboard.shortcuts, &action);
                    rebind_foundation_action(cx, &action, old_effective.as_deref(), new_effective);
                    this.queue_ui_state();
                }
                cx.notify();
                valid
            })
            .unwrap_or(false);
        self.shortcut_note = (!applied).then(|| {
            locale::text(
                "Shortcut is invalid or already in use",
                "快捷键无效或已被占用",
                "快速鍵無效或已被占用",
            )
            .to_string()
        });
        cx.notify();
        applied
    }

