    #[test]
    fn reasoning_delta_fast_path_matches_full_projection() {
        for mode in [
            ReasoningDisplayMode::Timeline,
            ReasoningDisplayMode::LatestAtBottom,
        ] {
            let session_id = VibexSessionId::parse("session_reasoning_delta").unwrap();
            let mut items = vec![
                timeline_item_with_payload(
                    &session_id,
                    1,
                    TimelineSource::User,
                    TimelinePayload::UserMessage(UserMessagePayload {
                        text: "question".into(),
                        attachments: Vec::new(),
                        ..Default::default()
                    }),
                ),
                timeline_item_with_payload(
                    &session_id,
                    2,
                    TimelineSource::Agent,
                    TimelinePayload::Reasoning(ReasoningPayload {
                        text: "  first thought ".into(),
                        is_final: false,
                    }),
                ),
            ];
            let mut timeline = TimelineModel::default();
            timeline.replace_authoritative(session_id.clone(), items.clone());
            let mut cache: Rc<Vec<Rc<TimelineConversationTurn>>> = Rc::new(
                timeline_conversation_turns_with_reasoning_mode(
                    &timeline.items,
                    Some(AgentSessionState::Running),
                    true,
                    mode,
                )
                .into_iter()
                .map(Rc::new)
                .collect(),
            );
            let render_cache = Rc::new(RefCell::new(cache.clone()));
            let active_turn_ptr = Rc::as_ptr(cache.last().expect("reasoning turn is cached"));

            let next = timeline_item_with_payload(
                &session_id,
                3,
                TimelineSource::Agent,
                TimelinePayload::Reasoning(ReasoningPayload {
                    text: "and the next one".into(),
                    is_final: false,
                }),
            );
            let events = [TimelineLiveEvent {
                session_id: session_id.clone(),
                sequence: 3,
                item: next.clone(),
            }];
            assert!(agent_streaming_delta_updates(&events).is_none());
            let updates = agent_reasoning_delta_updates(&events)
                .expect("a trailing thought chunk is an append-only reasoning delta");

            let mut state_cache = None;
            let update =
                with_detached_conversation_turns_render_cache(&mut cache, &render_cache, |cache| {
                    append_agent_reasoning_deltas_to_cache(
                        cache,
                        &mut state_cache,
                        mode,
                        Some(2),
                        &updates,
                    )
                })
                .expect("the streaming reasoning tail can be extended in place");
            assert_eq!(
                active_turn_ptr,
                Rc::as_ptr(cache.last().expect("appended turn stays cached")),
                "streaming append must reuse the active turn allocation"
            );
            assert!(Rc::ptr_eq(
                render_cache
                    .borrow()
                    .last()
                    .expect("render cache stays synchronized"),
                cache.last().expect("appended turn stays cached")
            ));

            items.push(next);
            let expected: Vec<Rc<TimelineConversationTurn>> =
                timeline_conversation_turns_with_reasoning_mode(
                    &items,
                    Some(AgentSessionState::Running),
                    true,
                    mode,
                )
                .into_iter()
                .map(Rc::new)
                .collect();
            assert_eq!(cache.as_ref(), &expected, "mode {mode:?}");

            let turn = cache.last().expect("the appended turn stays cached");
            assert_eq!(update.turn_id, turn.id);
            assert_eq!(
                streaming_timeline_row_body_len(turn, &state_cache.clone().unwrap()),
                Some(update.body_len)
            );
            assert!(update.previous_body_len < update.body_len);

            // A gap in the timeline tail must fall back to the full projection.
            assert!(
                append_agent_reasoning_deltas_to_cache(
                    &mut cache,
                    &mut state_cache,
                    mode,
                    Some(7),
                    &updates,
                )
                .is_none()
            );
        }
    }

    /// A coalesced thought arrives as a revision of the row the view holds.
    ///
    /// The store folds a thought's chunks onto one row, so the newest text
    /// comes back at the sequence the run already has instead of the one above
    /// it. The row's body is then the store's text — the whole accumulation —
    /// and the append path must replace it rather than grow it again.
    #[test]
    fn a_coalesced_thought_revision_replaces_the_row_body() {
        for mode in [
            ReasoningDisplayMode::Timeline,
            ReasoningDisplayMode::LatestAtBottom,
        ] {
            let session_id = VibexSessionId::parse("session_reasoning_revision").unwrap();
            let question = timeline_item_with_payload(
                &session_id,
                1,
                TimelineSource::User,
                TimelinePayload::UserMessage(UserMessagePayload {
                    text: "question".into(),
                    attachments: Vec::new(),
                    ..Default::default()
                }),
            );
            let run = timeline_item_with_payload(
                &session_id,
                2,
                TimelineSource::Agent,
                TimelinePayload::Reasoning(ReasoningPayload {
                    text: "one two ".into(),
                    is_final: false,
                }),
            );
            let mut timeline = TimelineModel::default();
            timeline.replace_authoritative(session_id.clone(), vec![question.clone(), run.clone()]);
            let projection = |items: &[TimelineItem]| {
                timeline_conversation_turns_with_reasoning_mode(
                    items,
                    Some(AgentSessionState::Running),
                    true,
                    mode,
                )
                .into_iter()
                .map(Rc::new)
                .collect::<Vec<Rc<TimelineConversationTurn>>>()
            };
            let mut cache: Rc<Vec<Rc<TimelineConversationTurn>>> =
                Rc::new(projection(&timeline.items));
            let render_cache = Rc::new(RefCell::new(cache.clone()));
            let active_turn_ptr = Rc::as_ptr(cache.last().expect("reasoning turn is cached"));

            let revision = TimelineItem {
                payload: TimelinePayload::Reasoning(ReasoningPayload {
                    text: "one two three".into(),
                    is_final: false,
                }),
                ..run.clone()
            };
            let events = [TimelineLiveEvent {
                session_id: session_id.clone(),
                sequence: 2,
                item: revision.clone(),
            }];
            assert!(
                reasoning_revision_replaces_the_run(&timeline.items, Some(2), &events),
                "the view holds the run as the one row the revision names"
            );
            let updates = agent_reasoning_delta_updates(&events)
                .expect("a revised thought is a reasoning delta at the row's own sequence");

            let mut state_cache = None;
            let update =
                with_detached_conversation_turns_render_cache(&mut cache, &render_cache, |cache| {
                    append_agent_reasoning_deltas_to_cache(
                        cache,
                        &mut state_cache,
                        mode,
                        Some(2),
                        &updates,
                    )
                })
                .expect("a coalesced revision is applied in place");
            assert_eq!(
                active_turn_ptr,
                Rc::as_ptr(cache.last().expect("revised turn stays cached")),
                "a revision must reuse the active turn allocation"
            );
            assert_eq!(
                update.body_len,
                "one two three".len(),
                "the row's body is the store's text, not the text grown again"
            );
            let turn = cache.last().expect("the revised turn stays cached");
            assert_eq!(turn.item_count, 2, "a revision is not another item");
            if mode == ReasoningDisplayMode::Timeline {
                assert_eq!(
                    turn.process_rows.last().map(|row| row.last_sequence),
                    Some(2),
                    "the row keeps the sequence the store folded onto"
                );
            } else {
                assert_eq!(turn.live_status.as_deref(), Some("one two three"));
            }

            timeline.replace_authoritative(session_id.clone(), vec![question, revision]);
            let expected = projection(&timeline.items);
            assert_eq!(
                cache.as_ref(),
                &expected,
                "mode {mode:?}: the revision lands where a projection would"
            );
        }
    }

    #[test]
    fn unread_completion_tracks_only_final_messages_from_background_sessions() {
        let selected_session_id = VibexSessionId::new();
        let background_session_id = VibexSessionId::new();
        let final_item = indexed_timeline_item(&background_session_id, 1, "done");
        let final_event = TimelineLiveEvent {
            session_id: background_session_id.clone(),
            sequence: final_item.sequence,
            item: final_item,
        };
        let streaming_item = timeline_item_with_payload(
            &background_session_id,
            2,
            TimelineSource::Agent,
            TimelinePayload::AgentMessage(AgentMessagePayload {
                text: "still working".into(),
                is_final: false,
            }),
        );
        let streaming_event = TimelineLiveEvent {
            session_id: background_session_id.clone(),
            sequence: streaming_item.sequence,
            item: streaming_item,
        };
        let mut unread = BTreeSet::new();
        let mut watermarks = BTreeMap::new();

        assert!(!update_unread_agent_completions(
            &mut unread,
            &mut watermarks,
            Some(&selected_session_id),
            &[streaming_event]
        ));
        assert!(update_unread_agent_completions(
            &mut unread,
            &mut watermarks,
            Some(&selected_session_id),
            std::slice::from_ref(&final_event)
        ));
        assert!(unread.contains(background_session_id.as_str()));
        assert!(!update_unread_agent_completions(
            &mut unread,
            &mut watermarks,
            Some(&selected_session_id),
            std::slice::from_ref(&final_event)
        ));
        assert!(mark_agent_session_read(&mut unread, &background_session_id));
        assert!(unread.is_empty());

        let selected_item = indexed_timeline_item(&selected_session_id, 1, "visible");
        assert!(!update_unread_agent_completions(
            &mut unread,
            &mut watermarks,
            Some(&selected_session_id),
            &[TimelineLiveEvent {
                session_id: selected_session_id.clone(),
                sequence: selected_item.sequence,
                item: selected_item,
            }]
        ));
        assert!(unread.is_empty());
    }

    /// A completion the reader watched end in the selected session is not news
    /// once they switch away.
    ///
    /// The live stream and the polling fallback both deliver the same committed
    /// final answer, so the item that ended on screen arrives again after the
    /// selection has moved. The replay is not a second completion, and badging
    /// it left a dot on a session on which the reader had just seen the turn
    /// finish.
    #[test]
    fn a_replayed_completion_watched_on_screen_does_not_badge_after_switching_away() {
        let watched_session_id = VibexSessionId::new();
        let other_session_id = VibexSessionId::new();
        let final_item = indexed_timeline_item(&watched_session_id, 7, "done");
        let final_event = TimelineLiveEvent {
            session_id: watched_session_id.clone(),
            sequence: final_item.sequence,
            item: final_item,
        };
        let mut unread = BTreeSet::new();
        let mut watermarks = BTreeMap::new();

        // The final answer lands while its session is the selected one, so it
        // is read by the fact of being on screen.
        assert!(!update_unread_agent_completions(
            &mut unread,
            &mut watermarks,
            Some(&watched_session_id),
            std::slice::from_ref(&final_event)
        ));
        assert!(unread.is_empty());

        // The reader switches away, and the poll replays the same item: no dot.
        assert!(!update_unread_agent_completions(
            &mut unread,
            &mut watermarks,
            Some(&other_session_id),
            std::slice::from_ref(&final_event)
        ));
        assert!(unread.is_empty());

        // A genuinely later turn in that session is news, so it badges.
        let later_item = indexed_timeline_item(&watched_session_id, 9, "second answer");
        assert!(update_unread_agent_completions(
            &mut unread,
            &mut watermarks,
            Some(&other_session_id),
            &[TimelineLiveEvent {
                session_id: watched_session_id.clone(),
                sequence: later_item.sequence,
                item: later_item,
            }]
        ));
        assert!(unread.contains(watched_session_id.as_str()));
    }

    #[test]
    fn pending_user_requests_clear_only_when_the_session_answers_every_request() {
        let session_id = VibexSessionId::new();
        let first_request_id = RequestId::new();
        let second_request_id = RequestId::new();
        let request_event = |request_id: &RequestId, sequence: i64| TimelineLiveEvent {
            session_id: session_id.clone(),
            sequence,
            item: timeline_item_with_payload(
                &session_id,
                sequence,
                TimelineSource::Provider,
                TimelinePayload::ElicitationRequest(vibex_core::ElicitationRequest {
                    id: request_id.clone(),
                    session_id: session_id.clone(),
                    provider_request_id: None,
                    tool_call_id: None,
                    message: "Which environment?".into(),
                    title: None,
                    description: None,
                    fields: Vec::new(),
                    status: vibex_core::ElicitationRequestStatus::Pending,
                    requested_at_ms: sequence,
                }),
            ),
        };
        let resolution_event = |request_id: &RequestId, sequence: i64| TimelineLiveEvent {
            session_id: session_id.clone(),
            sequence,
            item: timeline_item_with_payload(
                &session_id,
                sequence,
                TimelineSource::User,
                TimelinePayload::ElicitationResolution(vibex_core::ElicitationResolution {
                    request_id: request_id.clone(),
                    session_id: session_id.clone(),
                    action: ElicitationResolutionAction::Accept,
                    answers: BTreeMap::new(),
                    responder_device_id: None,
                    resolved_at_ms: sequence,
                }),
            ),
        };
        let mut pending = BTreeMap::new();

        assert!(update_pending_user_requests(
            &mut pending,
            &[
                request_event(&first_request_id, 1),
                request_event(&second_request_id, 2)
            ]
        ));
        assert_eq!(pending.get(session_id.as_str()).map(BTreeSet::len), Some(2));
        assert!(!update_pending_user_requests(
            &mut pending,
            &[request_event(&second_request_id, 2)]
        ));
        assert!(update_pending_user_requests(
            &mut pending,
            &[resolution_event(&first_request_id, 3)]
        ));
        assert_eq!(pending.get(session_id.as_str()).map(BTreeSet::len), Some(1));
        assert!(update_pending_user_requests(
            &mut pending,
            &[resolution_event(&second_request_id, 4)]
        ));
        assert!(pending.is_empty());
        assert!(!update_pending_user_requests(
            &mut pending,
            &[resolution_event(&second_request_id, 4)]
        ));
    }

    /// A prompt the reader sends past a card supersedes it.
    ///
    /// The row must stop asking for an answer the reader already typed over.
    /// A steer is not a new prompt, so it leaves the live card in place.
    #[test]
    fn a_new_prompt_clears_the_previous_turns_unanswered_request() {
        let session_id = VibexSessionId::new();
        let request_id = RequestId::new();
        let request_event = TimelineLiveEvent {
            session_id: session_id.clone(),
            sequence: 1,
            item: timeline_item_with_payload(
                &session_id,
                1,
                TimelineSource::Provider,
                TimelinePayload::ElicitationRequest(vibex_core::ElicitationRequest {
                    id: request_id.clone(),
                    session_id: session_id.clone(),
                    provider_request_id: None,
                    tool_call_id: None,
                    message: "Which environment?".into(),
                    title: None,
                    description: None,
                    fields: Vec::new(),
                    status: vibex_core::ElicitationRequestStatus::Pending,
                    requested_at_ms: 1,
                }),
            ),
        };
        let prompt_event = |sequence: i64, delivery: UserMessageDelivery| TimelineLiveEvent {
            session_id: session_id.clone(),
            sequence,
            item: timeline_item_with_payload(
                &session_id,
                sequence,
                TimelineSource::User,
                TimelinePayload::UserMessage(UserMessagePayload {
                    text: "keep going".into(),
                    attachments: Vec::new(),
                    delivery,
                    ..Default::default()
                }),
            ),
        };

        let mut pending = BTreeMap::new();
        assert!(update_pending_user_requests(
            &mut pending,
            std::slice::from_ref(&request_event)
        ));
        assert!(pending.contains_key(session_id.as_str()));

        assert!(!update_pending_user_requests(
            &mut pending,
            &[prompt_event(2, UserMessageDelivery::Steer)]
        ));
        assert!(
            pending.contains_key(session_id.as_str()),
            "a steer joins the running turn and does not supersede its card"
        );

        assert!(update_pending_user_requests(
            &mut pending,
            &[prompt_event(3, UserMessageDelivery::Prompt)]
        ));
        assert!(
            pending.is_empty(),
            "a new prompt is the reader moving past the card"
        );
    }

    /// The persisted state breaks a tie the live index cannot resolve.
    #[test]
    fn an_unanswerable_request_does_not_pin_a_settled_row_to_needs_input() {
        let session_id = VibexSessionId::new();
        let mut pending = BTreeMap::new();
        pending.insert(
            session_id.as_str().to_string(),
            BTreeSet::from(["request_abandoned".to_string()]),
        );

        assert!(session_awaits_user_input(
            AgentSessionState::NeedsInput,
            &pending,
            session_id.as_str()
        ));
        assert!(session_awaits_user_input(
            AgentSessionState::Running,
            &pending,
            session_id.as_str()
        ));
        for settled in [
            AgentSessionState::Idle,
            AgentSessionState::Error,
            AgentSessionState::Closed,
            AgentSessionState::Archived,
        ] {
            assert!(
                !session_awaits_user_input(settled, &pending, session_id.as_str()),
                "a {settled:?} session cannot still be parked on a card"
            );
        }
        assert!(!session_awaits_user_input(
            AgentSessionState::Idle,
            &BTreeMap::new(),
            session_id.as_str()
        ));
    }

