    #[test]
    fn streaming_markdown_snapshot_keeps_source_and_revision_in_sync() {
        let mut cache = BTreeMap::new();
        let mut row = TimelineRow {
            id: "agent:streaming-markdown".into(),
            kind: TimelineRowKind::AgentMessage,
            item_ids: vec!["timeline_1".into()],
            turn_id: Some("turn:streaming-markdown".into()),
            turn_item_count: 1,
            turn_failed: false,
            turn_pending_permission: false,
            conclusion: false,
            first_sequence: 1,
            last_sequence: 1,
            timestamp_ms: 1_700_000_000_000,
            title: "Agent".into(),
            body: "first".into(),
            streaming: true,
            collapsible: false,
            pending_permission: false,
            failed: false,
            runtime_attribution: None,
            file_path: None,
        };
        let started_at = Instant::now();
        let (first_source, first_sequence) = timeline_markdown_source_snapshot(
            &mut cache,
            row.id.as_str(),
            row.body.as_str(),
            row.last_sequence,
            row.streaming,
            started_at,
            false,
        );
        assert_eq!(first_source.as_ref(), "first");
        assert_eq!(first_sequence, 1);

        row.body.push_str(" chunk");
        row.last_sequence = 2;
        let (throttled_source, throttled_sequence) = timeline_markdown_source_snapshot(
            &mut cache,
            row.id.as_str(),
            row.body.as_str(),
            row.last_sequence,
            row.streaming,
            started_at + TIMELINE_STREAMING_MARKDOWN_REFRESH_INTERVAL / 2,
            true,
        );
        assert!(Arc::ptr_eq(&first_source, &throttled_source));
        assert_eq!(throttled_sequence, first_sequence);

        let (refreshed_source, refreshed_sequence) = timeline_markdown_source_snapshot(
            &mut cache,
            row.id.as_str(),
            row.body.as_str(),
            row.last_sequence,
            row.streaming,
            started_at + TIMELINE_STREAMING_MARKDOWN_REFRESH_INTERVAL,
            true,
        );
        assert_eq!(refreshed_source.as_ref(), "first chunk");
        assert_eq!(refreshed_sequence, 2);

        row.body.push_str(" final");
        row.last_sequence = 3;
        row.streaming = false;
        let (final_source, final_sequence) = timeline_markdown_source_snapshot(
            &mut cache,
            row.id.as_str(),
            row.body.as_str(),
            row.last_sequence,
            row.streaming,
            started_at + TIMELINE_STREAMING_MARKDOWN_REFRESH_INTERVAL,
            false,
        );
        assert_eq!(final_source.as_ref(), "first chunk final");
        assert_eq!(final_sequence, 3);

        row.body = "replacement".into();
        row.last_sequence = 4;
        row.streaming = true;
        let (replacement_source, replacement_sequence) = timeline_markdown_source_snapshot(
            &mut cache,
            row.id.as_str(),
            row.body.as_str(),
            row.last_sequence,
            row.streaming,
            started_at + TIMELINE_STREAMING_MARKDOWN_REFRESH_INTERVAL,
            false,
        );
        assert_eq!(replacement_source.as_ref(), "replacement");
        assert_eq!(replacement_sequence, 4);
    }

    #[test]
    fn timeline_item_index_tracks_append_replace_and_session_switch() {
        let first_session = VibexSessionId::parse("session_index_first").unwrap();
        let first = indexed_timeline_item(&first_session, 1, "first");
        let second = indexed_timeline_item(&first_session, 2, "second");
        let first_id = first.id.to_string();
        let second_id = second.id.to_string();
        let mut timeline = TimelineModel::default();
        timeline.replace_authoritative(first_session.clone(), [first, second]);

        let mut index = TimelineItemIndex::default();
        index.sync(&timeline);
        assert_eq!(index.positions.get(&first_id), Some(&0));
        assert_eq!(index.positions.get(&second_id), Some(&1));

        let appended = indexed_timeline_item(&first_session, 3, "appended");
        let appended_id = appended.id.to_string();
        assert!(timeline.apply_live(TimelineLiveEvent {
            session_id: first_session.clone(),
            sequence: appended.sequence,
            item: appended,
        }));
        index.sync(&timeline);
        assert_eq!(index.positions.get(&appended_id), Some(&2));

        let replacement = indexed_timeline_item(&first_session, 2, "replacement");
        let replacement_id = replacement.id.to_string();
        assert!(timeline.apply_live(TimelineLiveEvent {
            session_id: first_session,
            sequence: replacement.sequence,
            item: replacement,
        }));
        index.sync(&timeline);
        assert!(!index.positions.contains_key(&second_id));
        assert_eq!(index.positions.get(&replacement_id), Some(&1));

        let next_session = VibexSessionId::parse("session_index_next").unwrap();
        let next = indexed_timeline_item(&next_session, 1, "next");
        let next_id = next.id.to_string();
        timeline.replace_authoritative(next_session, [next]);
        index.sync(&timeline);
        assert_eq!(index.positions.len(), 1);
        assert_eq!(index.positions.get(&next_id), Some(&0));
    }

    #[test]
    fn composer_plan_identity_survives_updates_and_changes_for_a_new_plan() {
        let session_id = VibexSessionId::parse("session_plan_identity").unwrap();
        let item = |sequence, payload: TimelinePayload, source| TimelineItem {
            id: TimelineItemId::new(),
            session_id: session_id.clone(),
            sequence,
            timestamp_ms: sequence,
            source,
            kind: payload.kind(),
            correlation_id: None,
            provider_correlation_id: None,
            redaction_state: TimelineRedactionState::None,
            execution_attribution: None,
            payload_depth: vibex_core::TimelinePayloadDepth::Detail,
            payload,
        };
        let step = |status| PlanStepPayload {
            title: "Implement".into(),
            status,
        };
        let mut items = vec![
            item(
                1,
                TimelinePayload::UserMessage(UserMessagePayload {
                    text: "Implement".into(),
                    attachments: Vec::new(),
                    ..Default::default()
                }),
                TimelineSource::User,
            ),
            item(
                2,
                TimelinePayload::Plan(PlanPayload {
                    title: "Initial plan".into(),
                    steps: vec![step(PlanStepStatus::Running)],
                }),
                TimelineSource::Agent,
            ),
            item(
                3,
                TimelinePayload::TodoUpdate(TodoUpdatePayload {
                    title: "Initial plan".into(),
                    items: vec![step(PlanStepStatus::Completed)],
                    raw_extension: None,
                }),
                TimelineSource::Agent,
            ),
        ];
        let updated_plan = current_agent_plan(&items).unwrap();
        let dismissed_identity = composer_plan_identity(&session_id, &updated_plan, &items);
        assert_eq!(dismissed_identity.plan_sequence, 2);

        items.push(item(
            4,
            TimelinePayload::Plan(PlanPayload {
                title: "Follow-up plan".into(),
                steps: vec![step(PlanStepStatus::Running)],
            }),
            TimelineSource::Agent,
        ));
        let new_plan = current_agent_plan(&items).unwrap();
        let new_identity = composer_plan_identity(&session_id, &new_plan, &items);

        assert_eq!(new_identity.plan_sequence, 4);
        assert_ne!(dismissed_identity, new_identity);
    }

