    #[test]
    fn batch_session_delete_exits_selection_and_updates_the_sidebar_optimistically() {
        let source = include_str!("app.rs");
        // The batch bar and a shift/ctrl selection share one deletion path, and
        // it leaves selection mode before it removes anything.
        let deletion = source
            .split_once("    fn delete_sessions(")
            .and_then(|(_, tail)| tail.split_once("\n    fn optimistically_remove_sessions("))
            .map(|(body, _)| body)
            .expect("session deletion should remain inspectable");
        let exit_batch = deletion
            .find("self.sidebar_batch_mode = false;")
            .expect("batch deletion should exit selection mode");
        let optimistic_remove = deletion
            .find("self.optimistically_remove_sessions(&session_id_set, SidebarSessionRemoval::Delete);")
            .expect("deletion should remove deleted rows locally");
        let repaint = deletion
            .find("cx.notify();\n        let generation")
            .expect("deletion should repaint before background deletion");
        let background_delete = deletion
            .find("let runner = gpui_tokio::Tokio::spawn")
            .expect("authoritative deletion should remain asynchronous");
        assert!(exit_batch < optimistic_remove);
        assert!(optimistic_remove < repaint);
        assert!(repaint < background_delete);
        assert!(deletion.contains("self.finish_optimistic_session_deletion("));
        assert!(deletion.contains("self.pending_session_deletion_ids"));
        assert!(!deletion.contains("self.agent_action_pending = true;"));
        assert!(!deletion.contains("!self.optimistically_removed_session_ids.is_empty()"));

        let optimistic_state = source
            .split_once("    fn optimistically_remove_sessions(")
            .and_then(|(_, tail)| tail.split_once("\n    fn forget_session_row("))
            .map(|(body, _)| body)
            .expect("optimistic session removal should remain inspectable");
        // The row is hidden by the set that matches the removal: a deletion's
        // bookkeeping outlives the mutation, an archive's does not. The teardown
        // itself is shared with the live snapshot an archive elsewhere arrives
        // as, so it lives in `forget_session_row` below.
        assert!(optimistic_state.contains("optimistically_removed_session_ids"));
        assert!(optimistic_state.contains("optimistically_archived_session_ids"));
        assert!(optimistic_state.contains("self.forget_session_row(session_id);"));
        assert!(optimistic_state.contains("self.reconcile_sidebar_state();"));
        assert!(optimistic_state.contains("self.publish_sidebar_invalidation();"));

        let teardown = source
            .split_once("    fn forget_session_row(")
            .and_then(|(_, tail)| tail.split_once("\n    fn confirm_delete_project("))
            .map(|(body, _)| body)
            .expect("the session row teardown should remain inspectable");
        assert!(teardown.contains("self.sessions\n            .retain"));
        assert!(teardown.contains(
            "self.session_views
            .retain"
        ));
        assert!(teardown.contains(
            "self.session_view_lru
            .retain"
        ));
        assert!(teardown.contains("self.selected_session_id = None;"));
        assert!(teardown.contains("self.session_views\n            .retain"));
        // A removal that takes the page the reader is on hands the workbench
        // the New Session home, and only from the tab that was showing it.
        let selection_cleared = teardown
            .find("self.selected_session_id = None;")
            .expect("removal should clear the removed session's selection");
        let home_opened = teardown
            .find("self.new_session_open = true;")
            .expect("removal should open the New Session home");
        let deferred = teardown
            .find("self.session_removal_new_session_pending = true;")
            .expect("the window-aware half of the navigation should be deferred");
        assert!(selection_cleared < home_opened);
        assert!(home_opened < deferred);
        assert!(teardown.contains("session_removal_opens_new_session_home("));

        let completion = source
            .split_once("    fn finish_optimistic_session_deletion(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Applies the answer to a deletion batch")
            })
            .map(|(body, _)| body)
            .expect("optimistic deletion completion should remain inspectable");
        assert!(completion.contains(".detach();"));
        assert!(
            completion.contains("this.optimistic_session_deletion_reconciliation_pending = true;")
        );
        assert!(completion.contains("this.settle_optimistic_session_deletion("));
        assert!(completion.contains("let committed = matches!(outcome, Ok(Ok(())));"));
        assert!(completion.contains("if should_reconcile {"));
        assert!(!completion.contains("this.agent_action_pending = false;"));
        assert!(completion.contains("this.load_agent_overview(cx);"));
        // The archived page is a second list holding the same rows, so a
        // settled deletion re-reads it whether the batch committed or failed.
        assert!(completion.contains("this.archived_sessions = None;"));
        assert!(completion.contains("this.load_archived_sessions(cx);"));
        assert!(
            !completion.contains("Ok(Ok(())) => {\n"),
            "a committed batch must not be the only case that refreshes the page"
        );

        // The answer decides the tombstone: a committed deletion is permanent,
        // a failed one only ever hid its rows optimistically.
        let settle = source
            .split_once("    fn settle_optimistic_session_deletion(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Moves a session out of the sidebar"))
            .map(|(body, _)| body)
            .expect("the deletion settle should remain inspectable");
        assert!(settle.contains("self.pending_session_deletion_ids"));
        assert!(settle.contains(".retain("));
        assert!(settle.contains("self.deleted_session_ids"));
        assert!(settle.contains("self.optimistically_removed_session_ids"));
        assert!(settle.contains("if committed {"));

        // "Delete all" is a batch, not a loop of single deletions. A batch owns
        // one pending set, one optimistic removal and one reconciliation, so no
        // row of the page depends on its own request winning a race with the
        // rest; the page the reader confirmed is read back once when it settles.
        let delete_all = source
            .split_once("    fn delete_all_archived_sessions(")
            .and_then(|(_, tail)| tail.split_once("\n    fn set_auto_archive_after_days("))
            .map(|(body, _)| body)
            .expect("the archived page's delete-all should remain inspectable");
        assert!(delete_all.contains("self.delete_sessions(session_ids, cx);"));
        assert!(
            !delete_all.contains("self.delete_session("),
            "delete-all must not fan out into one deletion request per row"
        );

        // The teardown takes the row off the archived page too: it is a list of
        // its own, and a row deleted from it is gone from every list at once.
        assert!(teardown.contains("self.archived_sessions.as_mut()"));
        assert!(teardown.contains("archived.retain("));
    }

    fn child_agent_session(session_id: &VibexSessionId, state: AgentSessionState) -> AgentSession {
        AgentSession {
            id: session_id.clone(),
            title: "Child Agent".into(),
            project_id: ProjectId::new(),
            workspace_id: WorkspaceId::new(),
            workspace_root: "/tmp/vibex-child-agent".into(),
            workspace_mode: WorkspaceMode::CurrentCheckout,
            agent_id: AgentId::parse("codex").unwrap(),
            state,
            safety: AgentSessionSafety::workspace_write_ask_on_risk(),
            created_at_ms: 1,
            updated_at_ms: 2,
            last_message_at_ms: 2,
            archived_at_ms: None,
            deleted_at_ms: None,
        }
    }

    /// A child Agent's timeline is folded from every item the child holds, and
    /// a subagent run reaches tens of thousands of them. The rail renders on
    /// every streamed chunk of every session, so the fold has to be reused
    /// until the child's own content moves.
    #[test]
    fn child_agent_projection_is_reused_until_the_timeline_changes() {
        let session_id = VibexSessionId::parse("session_child_projection").expect("session id");
        let mut state = ChildAgentTimelineState::new(session_id.clone());
        state.session = Some(child_agent_session(&session_id, AgentSessionState::Idle));
        state.timeline.replace_authoritative(
            session_id.clone(),
            [
                timeline_item_with_payload(
                    &session_id,
                    1,
                    TimelineSource::User,
                    TimelinePayload::UserMessage(UserMessagePayload {
                        text: "read the readme".into(),
                        ..Default::default()
                    }),
                ),
                timeline_item_with_payload(
                    &session_id,
                    2,
                    TimelineSource::Agent,
                    TimelinePayload::AgentMessage(AgentMessagePayload {
                        text: "done".into(),
                        is_final: true,
                    }),
                ),
            ],
        );

        let first = state.turns_projection(ReasoningDisplayMode::LatestAtBottom);
        let second = state.turns_projection(ReasoningDisplayMode::LatestAtBottom);
        assert_eq!(first.len(), 1);
        assert!(Rc::ptr_eq(&first, &second));

        state.timeline.apply_live(TimelineLiveEvent {
            session_id: session_id.clone(),
            sequence: 3,
            item: timeline_item_with_payload(
                &session_id,
                3,
                TimelineSource::Agent,
                TimelinePayload::Reasoning(ReasoningPayload {
                    text: "checking".into(),
                    is_final: false,
                }),
            ),
        });
        let streamed = state.turns_projection(ReasoningDisplayMode::LatestAtBottom);
        assert!(!Rc::ptr_eq(&first, &streamed));

        // The rows half answers a different question and keeps its own key, so
        // a rail that never asked for rows still has none cached.
        assert!(state.rows_projection().len() >= 2);
        assert!(state.projection.rows.is_some());
    }

    /// The rail renders turns and a delegation preview renders rows. Folding
    /// the other half cost as much as the half being read.
    #[test]
    fn child_agent_snapshot_projects_only_the_half_that_was_asked_for() {
        let session_id = VibexSessionId::parse("session_child_parts").expect("session id");
        let mut state = ChildAgentTimelineState::new(session_id.clone());
        state.session = Some(child_agent_session(&session_id, AgentSessionState::Idle));
        state.timeline.replace_authoritative(
            session_id.clone(),
            [timeline_item_with_payload(
                &session_id,
                1,
                TimelineSource::Agent,
                TimelinePayload::AgentMessage(AgentMessagePayload {
                    text: "done".into(),
                    is_final: true,
                }),
            )],
        );

        let turns = child_agent_snapshot_from_state(
            &mut state,
            ChildAgentSnapshotParts::Turns,
            ReasoningDisplayMode::LatestAtBottom,
        );
        assert_eq!(turns.turns.len(), 1);
        assert!(turns.rows.is_empty());
        assert!(state.projection.rows.is_none());

        let rows = child_agent_snapshot_from_state(
            &mut state,
            ChildAgentSnapshotParts::Rows,
            ReasoningDisplayMode::LatestAtBottom,
        );
        assert_eq!(rows.rows.len(), 1);
        assert!(rows.turns.is_empty());
    }

    #[test]
    fn timeline_item_at_sequence_finds_only_the_item_at_that_sequence() {
        let session_id = VibexSessionId::parse("session_sequence_lookup").expect("session id");
        let items = [3, 5, 8]
            .into_iter()
            .map(|sequence| {
                timeline_item_with_payload(
                    &session_id,
                    sequence,
                    TimelineSource::Agent,
                    TimelinePayload::AgentMessage(AgentMessagePayload {
                        text: format!("item {sequence}"),
                        is_final: true,
                    }),
                )
            })
            .collect::<Vec<_>>();

        assert_eq!(
            timeline_item_at_sequence(&items, 5).map(|item| item.sequence),
            Some(5)
        );
        assert!(timeline_item_at_sequence(&items, 4).is_none());
        assert!(timeline_item_at_sequence(&items, 9).is_none());
        assert!(timeline_item_at_sequence(&items, 0).is_none());
    }

