    #[test]
    fn sidebar_animation_keeps_content_mounted_until_close_finishes() {
        let mut state = SidebarAnimationState::new(320.0, 0.0, true);

        assert!(state.needs_update(320.0, 0.0, false, true));
        let request = state.update_target(320.0, 0.0, false, true).unwrap();

        assert_eq!(state.from_value, 320.0);
        assert_eq!(state.target_value, 0.0);
        assert_eq!(state.from_opacity, 1.0);
        assert_eq!(state.target_opacity, 0.0);
        assert!(state.render_child);
        assert!(state.hide_scheduled);
        assert!(!state.finish_hide(request.wrapping_add(1)));
        assert!(state.finish_hide(request));
        assert!(!state.render_child);
    }

    #[test]
    fn sidebar_animation_cancels_pending_hide_when_reopened() {
        let mut state = SidebarAnimationState::new(320.0, 0.0, true);
        let request = state.update_target(320.0, 0.0, false, true).unwrap();

        assert_eq!(state.update_target(320.0, 0.0, true, true), None);
        assert_eq!(state.from_value, 0.0);
        assert_eq!(state.target_value, 320.0);
        assert_eq!(state.from_opacity, 0.0);
        assert_eq!(state.target_opacity, 1.0);
        assert!(state.render_child);
        assert!(!state.hide_scheduled);
        assert!(!state.finish_hide(request));
    }

    #[test]
    fn reduced_motion_updates_sidebar_visibility_immediately() {
        let mut state = SidebarAnimationState::new(320.0, 0.0, true);

        assert_eq!(state.update_target(320.0, 0.0, false, false), None);
        assert_eq!(state.target_value, 0.0);
        assert_eq!(state.target_opacity, 0.0);
        assert!(!state.render_child);
        assert!(!state.hide_scheduled);

        assert_eq!(state.update_target(320.0, 0.0, true, false), None);
        assert_eq!(state.target_value, 320.0);
        assert_eq!(state.target_opacity, 1.0);
        assert!(state.render_child);
    }

    #[test]
    fn floating_sidebar_slides_in_and_keeps_its_mode_while_closing() {
        let mut state = SidebarFloatingAnimationState::new(320.0, None);
        let hover_preview = Some(SidebarFloatingPresentation::HoverPreview);

        assert!(state.needs_update(320.0, hover_preview, true));
        assert_eq!(state.update_target(320.0, hover_preview, true), None,);
        assert_eq!(state.animation.from_value, -320.0);
        assert_eq!(state.animation.target_value, 0.0);
        assert_eq!(state.animation.from_opacity, 0.0);
        assert_eq!(state.animation.target_opacity, 1.0);
        assert!(state.animation.render_child);

        assert_eq!(
            state.update_target(320.0, Some(SidebarFloatingPresentation::Drawer), true),
            None,
        );
        let request = state.update_target(320.0, None, true).unwrap();
        assert_eq!(state.animation.from_value, 0.0);
        assert_eq!(state.animation.target_value, -320.0);
        assert_eq!(state.presentation, SidebarFloatingPresentation::Drawer);
        assert!(state.animation.render_child);
        assert!(state.finish_hide(request));
        assert!(!state.animation.render_child);
    }

