    #[test]
    fn the_preview_seam_moves_the_width_every_docked_shell_draws() {
        let medium = vibex_ui::ShellLayout::resolve(954, 875);
        assert_eq!(medium.kind, ShellKind::Medium);
        assert_eq!(medium.preview_min_width, 300.0);
        let (minimum, maximum) = preview_panel_width_limits(
            954.0,
            medium.preview_min_width,
            0.0,
            RIGHT_ACTIVITY_BAR_WIDTH,
        );
        // The seam's floor is the width the panel is actually drawn at, so the
        // handle cannot advertise a bound the shell then ignores.
        assert_eq!(minimum, medium.preview_min_width);
        assert!(maximum > minimum);
        assert_eq!(
            resolved_preview_panel_width(
                520.0,
                954.0,
                medium.preview_min_width,
                0.0,
                RIGHT_ACTIVITY_BAR_WIDTH,
            ),
            520.0
        );
        // A stored width wider than the window allows lands on the ceiling
        // instead of on the pinned minimum the Medium shell used to impose.
        assert_eq!(
            resolved_preview_panel_width(
                PREVIEW_PANEL_MAX_WIDTH,
                954.0,
                medium.preview_min_width,
                0.0,
                RIGHT_ACTIVITY_BAR_WIDTH,
            ),
            maximum
        );
    }

    #[test]
    fn a_preview_drag_stops_before_the_session_page_loses_its_minimum() {
        let wide = vibex_ui::ShellLayout::resolve(1_440, 900);
        assert_eq!(wide.kind, ShellKind::Wide);
        let (_, maximum) =
            preview_panel_width_limits(1_440.0, wide.preview_min_width, 260.0, 320.0);
        // Sidebar (260) + session page (240) + right rail (320) leave the panel
        // its ceiling; the 62% viewport share and the panel's own maximum are
        // both wider than that here.
        assert_eq!(maximum, 620.0);
        assert_eq!(
            1_440.0 - 260.0 - 320.0 - maximum,
            WORKBENCH_PREVIEW_MIN_CENTER_WIDTH
        );
    }

    #[test]
    fn new_session_uses_only_available_agents_and_preserves_valid_runtime_preference() {
        let mut agents = vibex_core::builtin_agent_definitions()
            .iter()
            .map(|definition| AgentSnapshotEntry::from_definition(definition, None, None))
            .collect::<Vec<_>>();
        assert_eq!(default_new_session_agent_id(&agents, None), None);

        agents
            .iter_mut()
            .find(|agent| agent.id.as_str() == "codex")
            .unwrap()
            .installed = true;
        assert_eq!(
            default_new_session_agent_id(&agents, None)
                .unwrap()
                .as_str(),
            "codex"
        );

        let catalog = SessionRuntimeOptionCatalog {
            revision: 1,
            agents: Vec::new(),
            auth_sources: Vec::new(),
            options: vec![
                new_session_runtime_option("claude", "Claude Code"),
                new_session_runtime_option("codex", "Codex"),
            ],
        };
        assert_eq!(
            new_session_runtime_selection_for_agent(&catalog, None, None),
            None
        );
        let default = default_new_session_runtime_selection(&catalog, None).unwrap();
        assert_eq!(default.agent_id.as_str(), "codex");

        let mut preferred = catalog.options[0].selection.clone();
        preferred.reasoning_effort = Some("high".into());
        let resolved = default_new_session_runtime_selection(&catalog, Some(&preferred)).unwrap();
        assert_eq!(resolved, preferred);
        let claude = AgentId::parse("claude").unwrap();
        assert_eq!(
            new_session_runtime_selection_for_agent(&catalog, Some(&claude), None)
                .unwrap()
                .agent_id,
            claude
        );
    }

    #[test]
    fn new_session_runtime_preferences_are_remembered_per_agent() {
        let codex = AgentId::parse("codex").unwrap();
        let claude = AgentId::parse("claude").unwrap();
        let mut codex_selection = new_session_runtime_option("codex", "Codex").selection;
        codex_selection.reasoning_effort = Some("high".into());
        let mut claude_selection = new_session_runtime_option("claude", "Claude Code").selection;
        claude_selection.mode_id = Some("plan".into());
        let remembered = BTreeMap::from([
            (codex.clone(), codex_selection.clone()),
            (claude.clone(), claude_selection.clone()),
        ]);

        assert_eq!(
            new_session_runtime_preference_for_agent(
                &codex,
                Some(&claude_selection),
                &remembered,
                None,
            ),
            Some(codex_selection)
        );
        let provisional_codex = new_session_runtime_option("codex", "Codex").selection;
        assert_eq!(
            new_session_runtime_preference_for_agent(
                &codex,
                Some(&provisional_codex),
                &remembered,
                None,
            )
            .and_then(|selection| selection.reasoning_effort),
            Some("high".into())
        );
        let mut view_local_codex = remembered.get(&codex).unwrap().clone();
        view_local_codex
            .config_values
            .insert("instructions".into(), "keep while open".into());
        assert_eq!(
            new_session_runtime_preference_for_agent(
                &codex,
                Some(&view_local_codex),
                &remembered,
                None,
            ),
            Some(view_local_codex)
        );
        assert_eq!(
            new_session_runtime_preference_for_agent(
                &claude,
                Some(&claude_selection),
                &remembered,
                None,
            ),
            Some(claude_selection)
        );
    }

    #[test]
    fn stale_runtime_switch_completion_cannot_replace_a_newer_preference() {
        let codex = AgentId::parse("codex").unwrap();
        let claude = AgentId::parse("claude").unwrap();
        let mut fence = RuntimePreferenceWriteFence::default();

        let first_codex = fence.begin(&codex);
        let claude_epoch = fence.begin(&claude);
        assert!(fence.is_current(&codex, first_codex));
        assert!(fence.is_current(&claude, claude_epoch));

        let newer_codex = fence.begin(&codex);
        assert!(!fence.is_current(&codex, first_codex));
        assert!(fence.is_current(&codex, newer_codex));
        assert!(fence.is_current(&claude, claude_epoch));
    }

    #[test]
    fn provisional_catalog_fallback_does_not_hide_an_enriched_preference() {
        let enriched_option = new_session_runtime_option("codex", "Codex");
        let agent_id = enriched_option.selection.agent_id.clone();
        let mut remembered_selection = enriched_option.selection.clone();
        remembered_selection.reasoning_effort = Some("high".into());
        let remembered = BTreeMap::from([(agent_id.clone(), remembered_selection.clone())]);
        let mut provisional_option = enriched_option.clone();
        provisional_option.reasoning_efforts.clear();
        let provisional_catalog = SessionRuntimeOptionCatalog {
            revision: 1,
            agents: Vec::new(),
            auth_sources: Vec::new(),
            options: vec![provisional_option],
        };

        let provisional = new_session_runtime_selection_for_agent(
            &provisional_catalog,
            Some(&agent_id),
            Some(&remembered_selection),
        )
        .unwrap();
        assert_eq!(provisional.reasoning_effort, None);

        let preferred = new_session_runtime_preference_for_agent(
            &agent_id,
            Some(&provisional),
            &remembered,
            None,
        )
        .unwrap();
        let enriched_catalog = SessionRuntimeOptionCatalog {
            revision: 2,
            agents: Vec::new(),
            auth_sources: Vec::new(),
            options: vec![enriched_option],
        };
        let restored = new_session_runtime_selection_for_agent(
            &enriched_catalog,
            Some(&agent_id),
            Some(&preferred),
        )
        .unwrap();

        assert_eq!(restored, remembered_selection);
        assert_eq!(remembered.get(&agent_id), Some(&remembered_selection));
    }

