    #[test]
    fn runtime_selection_validation_rejects_stale_feature_ids_and_values() {
        let mut option = new_session_runtime_option("codex", "Codex");
        option.features = vec![SessionRuntimeFeature {
            id: "approval_mode".into(),
            label: "Approval mode".into(),
            description: None,
            kind: SessionRuntimeFeatureKind::Select,
            current_value: Some(SessionConfigValue {
                value: "ask".into(),
                label: Some("Ask".into()),
            }),
            default_value: None,
            values: vec![
                SessionConfigValue {
                    value: "ask".into(),
                    label: Some("Ask".into()),
                },
                SessionConfigValue {
                    value: "auto".into(),
                    label: Some("Automatic".into()),
                },
            ],
        }];
        option
            .selection
            .config_values
            .insert("approval_mode".into(), "ask".into());
        let catalog = SessionRuntimeOptionCatalog {
            revision: 4,
            agents: Vec::new(),
            auth_sources: Vec::new(),
            options: vec![option],
        };
        let mut selection = catalog.options[0].selection.clone();
        assert!(catalog_has_runtime_selection(&catalog, &selection));

        selection
            .config_values
            .insert("approval_mode".into(), "invalid".into());
        assert!(!catalog_has_runtime_selection(&catalog, &selection));
        selection.config_values.clear();
        selection
            .config_values
            .insert("removed_feature".into(), "true".into());
        assert!(!catalog_has_runtime_selection(&catalog, &selection));
    }

    #[test]
    fn new_session_agent_order_completes_reorders_and_discards_stale_ids() {
        let mut order = vec![
            "claude".to_string(),
            "stale".to_string(),
            "claude".to_string(),
        ];
        complete_string_order(
            &mut order,
            ["codex", "claude", "gemini"]
                .into_iter()
                .map(str::to_string)
                .collect(),
        );
        assert_eq!(order, ["claude", "codex", "gemini"]);

        assert!(move_string_relative(&mut order, "gemini", "claude", false,));
        assert_eq!(order, ["gemini", "claude", "codex"]);
    }

    #[test]
    fn sidebar_reorder_preview_supports_fast_motion_and_release() {
        let ids = ["a", "b", "c", "d"]
            .into_iter()
            .map(str::to_string)
            .collect::<Vec<_>>();
        let target = reorder_target_from_cursor_offset(
            &ids,
            "b",
            SIDEBAR_REORDER_ROW_HEIGHT / 2.0
                + 2.0 * (SIDEBAR_REORDER_ROW_HEIGHT + SIDEBAR_SESSION_REORDER_GAP),
            SIDEBAR_REORDER_ROW_HEIGHT,
            SIDEBAR_SESSION_REORDER_GAP,
        );
        assert_eq!(target, Some(("d".to_string(), true)));

        let preview = reordered_string_ids(&ids, "b", "d", true);
        assert_eq!(preview, ["a", "c", "d", "b"]);
        assert_eq!(
            reorder_target_from_preview(&ids, &preview, "b"),
            Some(("d".to_string(), true))
        );
        assert_eq!(sidebar_reorder_row_offset(&ids, &preview, "b"), Some(-2));
        assert_eq!(sidebar_reorder_row_offset(&ids, &preview, "c"), Some(1));

        let moving = ["b".to_string(), "d".to_string()];
        let preview = reordered_string_ids_many(&ids, &moving, "c", true);
        assert_eq!(preview, ["a", "c", "b", "d"]);
        assert_eq!(
            reorder_target_from_preview_many(&ids, &preview, &moving),
            Some(("c".to_string(), true))
        );
        let mut committed = ids.clone();
        assert!(move_strings_relative(&mut committed, &moving, "c", true));
        assert_eq!(committed, preview);
    }

