    #[test]
    fn sidebar_project_logo_import_is_square_and_content_addressed() {
        let home = tempfile::tempdir().unwrap();
        let source = home.path().join("source.png");
        image::RgbaImage::from_fn(32, 16, |x, y| image::Rgba([x as u8, y as u8, 128, 255]))
            .save(&source)
            .unwrap();

        let file_name = import_sidebar_project_logo(&source, home.path()).unwrap();
        let installed = sidebar_project_logo_path(home.path(), &file_name).unwrap();
        assert_eq!(file_name.len(), 68);
        assert_eq!(image::image_dimensions(&installed).unwrap(), (256, 256));
        assert_eq!(
            import_sidebar_project_logo(&source, home.path()).unwrap(),
            file_name
        );
        assert!(sidebar_project_logo_path(home.path(), "../outside.png").is_none());
    }

    #[test]
    fn sidebar_project_logo_import_rasterizes_svg_to_managed_png() {
        let home = tempfile::tempdir().unwrap();
        let source = home.path().join("source.svg");
        std::fs::write(
            &source,
            r##"<svg xmlns="http://www.w3.org/2000/svg" width="32" height="16" viewBox="0 0 32 16"><rect width="32" height="16" fill="#1273de"/></svg>"##,
        )
        .unwrap();

        let file_name = import_sidebar_project_logo(&source, home.path()).unwrap();
        let installed = sidebar_project_logo_path(home.path(), &file_name).unwrap();
        assert!(file_name.ends_with(".png"));
        assert_eq!(image::image_dimensions(&installed).unwrap(), (256, 256));
        assert_eq!(
            image::open(installed)
                .unwrap()
                .to_rgba8()
                .get_pixel(128, 128),
            &image::Rgba([0x12, 0x73, 0xde, 0xff])
        );
    }

    #[test]
    fn sidebar_project_logo_import_rejects_invalid_or_oversized_svg() {
        let home = tempfile::tempdir().unwrap();
        let invalid = home.path().join("invalid.svg");
        std::fs::write(&invalid, b"not an svg").unwrap();
        assert!(import_sidebar_project_logo(&invalid, home.path()).is_err());

        let oversized = home.path().join("oversized.svg");
        std::fs::write(
            &oversized,
            r#"<svg xmlns="http://www.w3.org/2000/svg" width="10000" height="10000"/>"#,
        )
        .unwrap();
        assert_eq!(
            import_sidebar_project_logo(&oversized, home.path()).unwrap_err(),
            "the selected image dimensions are too large"
        );
    }

    #[test]
    fn sidebar_drag_targets_are_owned_by_concrete_hitboxes() {
        let source = include_str!("app.rs");
        let folder = source
            .split_once("    fn render_sidebar_folder(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_sidebar_project("))
            .map(|(body, _)| body)
            .expect("folder renderer should remain inspectable");
        let project = source
            .split_once("    fn render_sidebar_project(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_sidebar_workspace("))
            .map(|(body, _)| body)
            .expect("project renderer should remain inspectable");
        let project_row = project
            .split_once("        let project_row = div()")
            .and_then(|(_, tail)| tail.split_once("\n        let mut session_elements"))
            .map(|(body, _)| body)
            .expect("project row should remain inspectable");
        let project_container = project
            .split_once("        let project = v_flex()")
            .map(|(_, body)| body)
            .expect("project container should remain inspectable");
        let session = source
            .split_once("    fn render_sidebar_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_choice_popover("))
            .map(|(body, _)| body)
            .expect("session renderer should remain inspectable");

        // Each row owns one handler per drag type it accepts: a project row
        // takes projects, folders, sessions and groups; a folder row takes the
        // same four, because a group files like a session does.
        assert_eq!(project_row.matches(".on_drag_move(").count(), 4);
        assert!(!project_container.contains(".on_drag_move("));
        assert_eq!(
            folder
                .matches("if !event.bounds.contains(&event.event.position)")
                .count(),
            4
        );
        assert!(session.contains("if !inside_target"));
        assert!(session.contains("if !event.bounds.contains(&event.event.position)"));
        assert!(source.contains(".id(\"sidebar-root-drop-target\")"));
    }

