    #[test]
    fn sidebar_session_status_is_rendered_on_the_right_for_all_views() {
        let source = include_str!("app.rs");
        let workspace_toggle = source
            .split_once("    fn activate_and_toggle_sidebar_workspace(")
            .and_then(|(_, tail)| tail.split_once("\n    fn set_sidebar_organization_drop_target("))
            .map(|(body, _)| body)
            .expect("workspace toggle should remain inspectable");
        assert!(workspace_toggle.contains("let was_collapsed = self"));
        assert!(workspace_toggle.contains("if was_collapsed {"));
        assert!(workspace_toggle.contains("for (_, candidate) in &self.workspaces"));
        assert!(workspace_toggle.contains("candidate.project_id == project_id"));
        assert!(
            workspace_toggle.contains("collapsed_workspace_ids\n                        .insert")
        );

        let sidebar_session = source
            .split_once("    fn render_sidebar_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_new_session_runtime_choice("))
            .map(|(body, _)| body)
            .expect("sidebar session renderer should remain inspectable");

        assert!(sidebar_session.contains("self.sidebar_session_row_state(session)"));
        assert!(source.contains("const SIDEBAR_SESSION_ROW_HEIGHT: f32 = 40.0;"));
        assert!(sidebar_session.contains(".h(px(SIDEBAR_SESSION_ROW_HEIGHT))"));
        assert!(sidebar_session.contains(".min_h(px(SIDEBAR_SESSION_ROW_HEIGHT))"));
        assert_eq!(
            sidebar_session
                .matches(".pl(px(SIDEBAR_WORKSPACE_SESSION_CARD_OVERHANG))")
                .count(),
            2,
            "normal and inline-rename rows should preserve the logo inset"
        );
        assert!(sidebar_session.contains(".top(px(8.0))"));
        assert!(sidebar_session.contains("sidebar_unselected_session_foreground("));
        assert!(sidebar_session.contains("cx.theme().sidebar_foreground,"));
        assert!(sidebar_session.contains(
            "sidebar_selected_session_background(cx.theme().sidebar_accent, cx.theme().is_dark())"
        ));
        assert!(sidebar_session.contains(".opacity(if selected { 1.0 } else { 0.90 })"));
        assert!(sidebar_session.contains(".group_hover(&hover_group, |style| style.opacity(1.0))"));
        assert!(
            sidebar_session.contains("sidebar_agent_logo(sidebar_agent_id.as_str(), true, cx)")
        );
        assert!(sidebar_session.contains(".when(selected, |this| this.font_semibold())"));
        assert!(sidebar_session.contains(".group_hover(&hover_group, |style| {"));
        assert!(sidebar_session.contains("style.text_color(cx.theme().sidebar_foreground)"));
        assert!(!sidebar_session.contains("selected, self.agent_turn_pending"));
        assert!(!sidebar_session.contains("let branch_path ="));
        assert!(!sidebar_session.contains(".when_some(branch_path"));
        assert!(
            sidebar_session
                .contains("let session_generating = display_state == AgentSessionState::Running")
        );
        assert!(sidebar_session.contains("sidebar-session-actions-{session_id_string}"));
        assert!(sidebar_session.contains(".group_hover(&hover_group, |style| style.visible())"));
        assert!(!sidebar_session.contains("Icon::new(IconName::LoaderCircle)"));
        assert!(!sidebar_session.contains("sidebar-session-error-{session_id_string}"));
        assert!(!sidebar_session.contains(".child(strings.sidebar_state_error)"));

        // The status column is not the row's own: the row hands the shared
        // builder its session's resolved state, and the builder paints every
        // row that lists one.
        assert!(sidebar_session.contains("SidebarSessionStatusColumn {"));
        assert!(sidebar_session.contains("prefix: \"sidebar-session\","));
        assert!(sidebar_session.contains("self.render_sidebar_status_column("));
        assert!(
            sidebar_session.contains("let scheduled_at_ms = self.scheduled_message_at_for_row(")
        );
        assert!(sidebar_session.contains(".child(status_column)"));
        assert!(sidebar_session.contains("icons/vibex/pin.svg"));
        assert!(sidebar_session.contains(".icon(if pinned {"));
        assert!(!sidebar_session.contains("sidebar_session_state_label("));
        assert!(!sidebar_session.contains("session_status_mark_for("));
        assert!(!sidebar_session.contains("sidebar_status_dot("));
        assert!(!sidebar_session.contains("format_sidebar_session_time("));

        // One column builder answers for every row: the mark, its label or
        // time, the marks that are not the session's state, and the yield to a
        // hover action cluster.
        let status_column = source
            .split_once("    fn render_sidebar_status_column(")
            .and_then(|(_, tail)| tail.split_once("\n    #[allow(clippy::too_many_arguments)]"))
            .map(|(body, _)| body)
            .expect("the session status column should remain inspectable");
        assert!(
            status_column
                .contains("let awaiting_user = display_state == AgentSessionState::NeedsInput")
        );
        assert!(
            status_column.contains("let generating = display_state == AgentSessionState::Running")
        );
        assert!(
            status_column.contains("let has_error = display_state == AgentSessionState::Error")
        );
        assert!(source.contains(".color(if auto_continue_enabled {"));
        assert!(source.contains("cx.theme().success"));
        // The column resolves its own state mark through the shared gate, which
        // owns the attention arm, the unread and failure exclusions, and the
        // rule that a settled session earns no mark.
        assert!(status_column.contains("let status_mark = if let Some(at_ms) = scheduled_at_ms {"));
        assert!(status_column.contains("sidebar_session_state_mark("));
        let gate = source
            .split_once("fn sidebar_session_state_mark(")
            .and_then(|(_, tail)| tail.split_once("\n/// Projects the state a sidebar row shows."))
            .map(|(body, _)| body)
            .expect("the shared state gate should remain inspectable");
        assert!(gate.contains("let has_error = display_state == AgentSessionState::Error"));
        assert!(gate.contains("sidebar_attention_icon("));
        assert!(gate.contains("needs_input_tooltip"));
        assert!(gate.contains("has_unread_completion"));
        assert!(gate.contains("display_state == AgentSessionState::Idle"));
        assert!(status_column.contains("!pinned && !awaiting_user && !generating"));
        assert!(status_column.contains("state_label.is_none()"));
        assert!(status_column.contains("|this| this.child(time_label)"));
        assert!(status_column.contains(".when_some(status_mark, |this, mark| this.child(mark))"));
        assert!(
            status_column.contains("this.group_hover(&hover_group, |style| style.invisible())")
        );
        assert!(status_column.contains("format!(\"{prefix}-status-{session_id}\")"));
        // Every mark the column mounts keeps an id scoped to the row that paints
        // it: the debug selector, the paused icon and the unread dot are the
        // column's own, and the attention and activity marks take theirs from
        // the gate, which scopes them by the same `prefix`.
        assert_eq!(
            status_column.matches("format!(\"{prefix}-").count(),
            3,
            "the column's own ids should all be scoped to the row that paints them"
        );
        assert_eq!(
            gate.matches("format!(\"{prefix}-").count(),
            2,
            "the gate's attention and activity ids should be scoped too"
        );
        // The pin mark owns the trailing slot of the status column: a pinned
        // session reports its own state in the lane to the mark's left, and the
        // unread and failure dots sit left of the pin too.
        let status_mark = status_column
            .find(".when_some(status_mark, |this, mark| this.child(mark))")
            .expect("the status column should draw the session state mark");
        let pin_mark = status_column
            .find(".when(pinned, |this| {")
            .expect("the status column should draw the pin mark");
        assert!(pin_mark > status_mark);
        assert!(status_column[pin_mark..].contains("icons/vibex/pin.svg"));
        assert!(status_column[..pin_mark].contains(".when(has_unread_completion, |this| {"));
        assert!(status_column[..pin_mark].contains(".when(has_error, |this| {"));
        assert!(
            status_column[..pin_mark].contains(".child(sidebar_status_dot(cx.theme().danger))")
        );
    }

    /// The running cue reaches the session title: a row whose Agent is
    /// generating sweeps the shared timeline light across its title, and every
    /// other row keeps a static title that asks for no animation frames.
    #[test]
    fn sidebar_running_session_titles_shimmer_with_the_shared_timeline_sweep() {
        let source = include_str!("app.rs");
        let sidebar_session = source
            .split_once("    fn render_sidebar_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_new_session_runtime_choice("))
            .map(|(body, _)| body)
            .expect("sidebar session renderer should remain inspectable");
        let title = sidebar_session
            .split_once("        let row_title: AnyElement = if session_generating {")
            .and_then(|(_, tail)| tail.split_once("        };\n"))
            .map(|(body, _)| body)
            .expect("the session title should keep its own running gate");

        assert!(title.contains("ShimmerText::new(row_title)"));
        assert!(title.contains("format!(\"sidebar-session-title-{session_id_string}\")"));
        assert!(title.contains("TIMELINE_SHIMMER_SWEEP"));
        assert!(title.contains("TIMELINE_SHIMMER_SPREAD"));
        // The sweep repeats for as long as it is mounted, so it takes the same
        // gate the row's status column uses for "the Agent is working" — a
        // parked, scheduled or idle row must not drive frames.
        assert!(title.contains("} else {\n            row_title.into_any_element()\n"));
        assert!(
            sidebar_session
                .contains("let session_generating = display_state == AgentSessionState::Running")
        );
        assert_eq!(
            sidebar_session.matches(".child(row_title)").count(),
            1,
            "the title element is what the row's text column shows"
        );
    }

    #[test]
    fn active_agent_turn_uses_the_stop_action_until_the_turn_finishes() {
        assert!(agent_turn_is_active(
            false,
            Some(AgentSessionState::Running)
        ));
        assert!(agent_turn_is_active(
            false,
            Some(AgentSessionState::NeedsInput)
        ));
        assert!(agent_turn_is_active(true, Some(AgentSessionState::Idle)));
        assert!(!agent_turn_is_active(false, Some(AgentSessionState::Idle)));
        assert!(!agent_turn_is_active(false, None));
    }

    #[test]
    fn timeline_follow_resumes_only_after_scroll_is_idle_near_bottom() {
        assert_eq!(timeline_distance_to_bottom(-900.0, 1_000.0), 100.0);
        assert_eq!(timeline_distance_to_bottom(-1_010.0, 1_000.0), 0.0);
        assert!(timeline_should_resume_follow_after_scroll_idle(
            true,
            AGENT_TIMELINE_NEAR_BOTTOM_THRESHOLD_PX,
            false,
        ));
        assert!(!timeline_should_resume_follow_after_scroll_idle(
            true,
            AGENT_TIMELINE_NEAR_BOTTOM_THRESHOLD_PX + 1.0,
            false,
        ));
        assert!(!timeline_should_resume_follow_after_scroll_idle(
            true, 0.0, true
        ));
        // A short timeline can be within the near-bottom threshold even at its
        // top. Scrolling upward must preserve that explicit reading position.
        assert!(!timeline_should_resume_follow_after_scroll_idle(
            false,
            AGENT_TIMELINE_NEAR_BOTTOM_THRESHOLD_PX / 2.0,
            false,
        ));
    }

    #[test]
    fn sending_a_message_lands_the_timeline_on_the_new_turn() {
        let source = include_str!("app.rs");

        // Every send path -- local, remote, native steer and the new-session
        // panel's first message -- installs the optimistic user message, so the
        // resume hangs off that install rather than one composer entry point.
        let install = source
            .split_once("    fn install_optimistic_user_message(")
            .and_then(|(_, tail)| tail.split_once("\n    fn discard_optimistic_user_message("))
            .map(|(body, _)| body)
            .expect("optimistic user message install should remain inspectable");
        let rebuild = install
            .find("self.rebuild_timeline_sizes();")
            .expect("the new turn should be sized before the scroll is asked for");
        let focus = install
            .find("self.focus_timeline_on_sent_message();")
            .expect("a sent message should move the timeline to its own turn");
        assert!(rebuild < focus);

        let focus = source
            .split_once("    fn focus_timeline_on_sent_message(")
            .and_then(|(_, tail)| tail.split_once("\n    fn apply_pending_timeline_scroll("))
            .map(|(body, _)| body)
            .expect("the sent-message scroll should remain inspectable");
        // The wheel-idle task carries the decision made before the send, and it
        // would restore that decision the moment it fires.
        let cancel_idle = focus
            .find("self.timeline_scroll_wheel_idle_task = None;")
            .expect("the pre-send wheel decision should be dropped");
        let clear_anchor = focus
            .find("self.timeline_scroll_anchor_pending = false;")
            .expect("a preserved anchor would fight the turn that was just sent");
        let follow = focus
            .find("self.timeline_follow.set_following_bottom(true);")
            .expect("sending resumes following the bottom");
        let request = focus
            .find("self.request_timeline_scroll_to_latest();")
            .expect("the resumed follow should ask for the bottom scroll");
        assert!(cancel_idle < clear_anchor && clear_anchor < follow && follow < request);
    }

