    #[test]
    fn a_reasoning_window_caps_the_body_at_its_row_budget() {
        // A thought the window holds: the body is as tall as the thought.
        let short = reasoning_window_height("checking the parser", 80);
        assert!(short < REASONING_WINDOW_HEIGHT);

        // A thought it does not: the body is the cap, and nothing above the
        // window is charged for or drawn.
        let long = "reasoning row ".repeat(200);
        assert_eq!(reasoning_window_height(&long, 80), REASONING_WINDOW_HEIGHT);

        // The same body measured against a wider pane is still capped: the
        // window is a row count, so it is the wrapped line count that decides.
        assert_eq!(reasoning_window_height(&long, 400), REASONING_WINDOW_HEIGHT);
    }

    #[test]
    fn only_a_streaming_body_opens_a_reasoning_window_and_the_choice_reshapes_rows() {
        let source = include_str!("app.rs");

        // The policy: the window is for a body that is still arriving, and only
        // while the reader's choice asks for one.
        let policy = source
            .split_once("    fn reasoning_window(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_live_reasoning("))
            .map(|(body, _)| body)
            .expect("the window policy should remain inspectable");
        assert!(policy.contains("live_reasoning_uses_window(streaming)"));
        assert!(policy.contains("reasoning_window_height("));

        let rule = source
            .split_once("    fn live_reasoning_uses_window(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Flip a reasoning row between open and closed.")
            })
            .map(|(body, _)| body)
            .expect("the live window rule should remain inspectable");
        assert!(rule.contains("streaming"));
        assert!(rule.contains("ReasoningExpansionMode::Window"));

        // Nothing opens itself: the reader's own answer wins, and without one
        // the default-expansion preference decides for a settled thought and a
        // thought the Agent is still on alike.
        let open = source
            .split_once("    fn reasoning_row_open(")
            .and_then(|(_, tail)| {
                tail.split_once(
                    "\n    /// Whether a thought that is still arriving is drawn in the fixed window.",
                )
            })
            .map(|(body, _)| body)
            .expect("the open rule should remain inspectable");
        assert!(open.contains("self.reasoning_expansion.get(row_id).copied()"));
        assert!(open.contains("reasoning_expanded_by_default"));
        assert!(!open.contains("live_reasoning_uses_window"));
        assert!(!open.contains("streaming"));

        // Both surfaces that draw a live body ask for the window, and the
        // timeline row asks with the row's own streaming flag rather than
        // assuming one.
        let row = source
            .split_once("    fn render_reasoning_row(")
            .and_then(|(_, tail)| {
                tail.split_once("\n        let summary = timeline_reasoning_summary_cached_at(")
            })
            .map(|(body, _)| body)
            .expect("the reasoning row renderer should remain inspectable");
        assert!(
            row.contains("let (remaining_source, hidden_body_bytes) =")
                && row.contains("self.reasoning_row_body_source(row, remaining_source)"),
            "a settled thought's body is folded before it is laid out"
        );
        assert!(
            row.contains("let arriving = self.row_is_arriving(row);")
                && row.contains(
                    "let window = self.reasoning_window(arriving, remaining_source.as_deref());"
                ),
            "the window answers to the turn's liveness, not to a stale row flag"
        );
        assert!(row.contains("render_expanded_reasoning_layout("));

        let live = source
            .split_once("    fn render_live_reasoning(")
            .and_then(|(_, tail)| tail.split_once("\n        let sequence = i64::try_from("))
            .map(|(body, _)| body)
            .expect("the live reasoning renderer should remain inspectable");
        assert!(live.contains("let window = self.reasoning_window(true, remaining_source);"));

        // A window reshapes an expanded row from the whole thought to a fixed
        // box, so choosing the mode drops the measurements taken against the old
        // shape instead of repainting over them.
        let setter = source
            .split_once("    fn set_reasoning_expansion_mode(")
            .and_then(|(_, tail)| tail.split_once("\n    fn set_reasoning_expanded_by_default("))
            .map(|(body, _)| body)
            .expect("the expansion mode setter should remain inspectable");
        assert!(setter.contains("self.invalidate_timeline_layout_measurements();"));
        assert!(setter.contains("self.rebuild_timeline_sizes();"));
        assert!(setter.contains("self.queue_ui_state();"));

        // The mode is part of every fingerprint that decides whether a measured
        // turn is still the shape it was measured as.
        let shape_key = source
            .split_once("    fn timeline_turn_shape_key(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    fn timeline_turn_layout_signature_uncached(")
            })
            .map(|(body, _)| body)
            .expect("the turn shape key should remain inspectable");
        assert!(shape_key.contains(".reasoning_expansion_mode"));
        let signature = source
            .split_once("    fn timeline_turn_layout_signature_uncached(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Cheap fingerprint of every input"))
            .map(|(body, _)| body)
            .expect("the turn layout signature should remain inspectable");
        assert!(signature.contains(".reasoning_expansion_mode"));
        let estimate = source
            .split_once("    fn timeline_turn_estimate_signature(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Parks a turn height prepaint observed")
            })
            .map(|(body, _)| body)
            .expect("the estimate signature should remain inspectable");
        assert!(estimate.contains(".reasoning_expansion_mode"));
    }

    #[test]
    fn active_turn_duration_uses_wall_clock_and_ticks_once_per_second() {
        assert_eq!(timeline_turn_duration_end(false, Some(12_345)), None);
        assert_eq!(timeline_turn_duration_end(true, Some(12_345)), Some(12_345));
        assert_eq!(AGENT_TURN_DURATION_TICK_INTERVAL, Duration::from_secs(1));

        let source = include_str!("app.rs");
        let scheduler = source
            .split_once("    fn sync_timeline_duration_tick(")
            .and_then(|(_, tail)| tail.split_once("\n    fn request_timeline_scroll_to_latest("))
            .map(|(body, _)| body)
            .expect("timeline duration scheduler should remain inspectable");
        assert!(scheduler.contains(".timer(AGENT_TURN_DURATION_TICK_INTERVAL)"));
        assert!(scheduler.contains("this.timeline_duration_tick_task = None;"));
        assert!(scheduler.contains("cx.notify();"));

        let workbench = source
            .split_once("    fn render_agent_workbench(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_controls("))
            .map(|(body, _)| body)
            .expect("agent workbench renderer should remain inspectable");
        assert!(workbench.contains("let turns_summary = self.conversation_turns_summary;"));
        assert!(
            workbench.contains(
                "self.sync_timeline_duration_tick(turns_summary.has_incomplete_turn, cx);"
            )
        );

        let turn_renderer = source
            .split_once("    fn render_timeline_turn(")
            .and_then(|(_, tail)| tail.split_once("\n    fn timeline_turn_execution_attribution("))
            .map(|(body, _)| body)
            .expect("timeline turn renderer should remain inspectable");
        assert!(turn_renderer.contains(
            "timeline_turn_duration_end(timeline_turn_finished(turn), turn.ended_at_ms)"
        ));
        assert!(turn_renderer.contains("!timeline_turn_finished(turn)"));
    }

    #[test]
    fn agent_generation_status_projects_phase_tools_and_token_rate() {
        let row = |id: &str, kind: TimelineRowKind, streaming: bool, body: &str| TimelineRow {
            id: id.to_string(),
            kind,
            item_ids: vec![id.to_string()],
            turn_id: Some("turn:generation".to_string()),
            turn_item_count: 0,
            turn_failed: false,
            turn_pending_permission: false,
            conclusion: kind == TimelineRowKind::AgentMessage,
            first_sequence: 1,
            last_sequence: 1,
            timestamp_ms: 1_700_000_000_000,
            title: String::new(),
            body: body.to_string(),
            streaming,
            collapsible: false,
            pending_permission: false,
            failed: false,
            runtime_attribution: None,
            file_path: None,
        };
        let turn = |process_rows: Vec<TimelineRow>,
                    conclusion_row: Option<TimelineRow>,
                    live_status: Option<&str>,
                    pending_permission: bool| TimelineConversationTurn {
            id: "turn:generation".to_string(),
            user_row: None,
            process_rows,
            process_activity_groups: Vec::new(),
            process_activity_groups_with_commands: Vec::new(),
            process_activity_groups_with_file_operations: Vec::new(),
            process_activity_groups_with_commands_and_file_operations: Vec::new(),
            live_status: live_status.map(str::to_string),
            conclusion_row,
            runtime_attribution: None,
            complete: false,
            failed: false,
            pending_permission,
            item_count: 0,
            started_at_ms: 1_000,
            ended_at_ms: None,
            superseded: false,
        };

        assert_eq!(
            agent_generation_phase(&turn(
                vec![row("tool", TimelineRowKind::ToolCall, true, "")],
                None,
                None,
                false,
            )),
            AgentGenerationPhase::CallingTool
        );
        assert_eq!(
            agent_generation_phase(&turn(
                vec![],
                Some(row("answer", TimelineRowKind::AgentMessage, true, "answer")),
                None,
                false,
            )),
            AgentGenerationPhase::Generating
        );
        assert_eq!(
            agent_generation_phase(&turn(vec![], None, Some("thinking"), false)),
            AgentGenerationPhase::Thinking
        );
        assert_eq!(
            agent_generation_phase(&turn(vec![], None, None, true)),
            AgentGenerationPhase::WaitingForApproval
        );
        assert_eq!(
            agent_generation_phase(&turn(vec![], None, None, false)),
            AgentGenerationPhase::Preparing
        );

        let activity_turn = turn(
            vec![
                row("tool", TimelineRowKind::ToolCall, false, ""),
                row("command", TimelineRowKind::Command, false, ""),
                row("reasoning", TimelineRowKind::Reasoning, true, ""),
            ],
            None,
            None,
            false,
        );
        assert_eq!(agent_generation_tool_call_count(&activity_turn), 2);

        let mut file_change_turn = turn(
            vec![
                row("file", TimelineRowKind::FileOperation, false, "edit"),
                row("thought", TimelineRowKind::Reasoning, true, "working"),
            ],
            None,
            Some("working"),
            false,
        );
        file_change_turn.process_rows[0].last_sequence = 7;
        file_change_turn.process_rows[1].last_sequence = 8;
        assert_eq!(
            timeline_turn_file_changes_cache_sequence(&file_change_turn),
            7
        );

        let compaction_turn = turn(
            vec![row(
                "reasoning",
                TimelineRowKind::Reasoning,
                true,
                "Working",
            )],
            None,
            None,
            false,
        );
        let compaction_session_id = VibexSessionId::parse("session_generation_compaction").unwrap();
        let compaction_items = vec![
            timeline_item_with_payload(
                &compaction_session_id,
                2,
                TimelineSource::Provider,
                TimelinePayload::SystemNotice(vibex_core::SystemNoticePayload {
                    level: vibex_core::SystemNoticeLevel::Info,
                    message: "*Context compacted".into(),
                }),
            ),
            timeline_item_with_payload(
                &compaction_session_id,
                3,
                TimelineSource::Provider,
                TimelinePayload::SystemNotice(vibex_core::SystemNoticePayload {
                    level: vibex_core::SystemNoticeLevel::Info,
                    message: "ACP agent switched to mode default".into(),
                }),
            ),
            timeline_item_with_payload(
                &compaction_session_id,
                4,
                TimelineSource::Provider,
                TimelinePayload::SystemNotice(vibex_core::SystemNoticePayload {
                    level: vibex_core::SystemNoticeLevel::Info,
                    message: "Context window compacted.".into(),
                }),
            ),
        ];
        assert_eq!(
            agent_generation_compaction_count(&compaction_turn, &compaction_items),
            2
        );

        let file_summary = TurnFileChangesSummary {
            files: vec![
                TurnFileChange {
                    display_path: "src/lib.rs".into(),
                    actionable_path: Some("src/lib.rs".into()),
                    review_path: None,
                    review_staged: false,
                    added_lines: 8,
                    removed_lines: 3,
                    has_line_counts: true,
                },
                TurnFileChange {
                    display_path: "src/main.rs".into(),
                    actionable_path: Some("src/main.rs".into()),
                    review_path: None,
                    review_staged: false,
                    added_lines: 2,
                    removed_lines: 0,
                    has_line_counts: true,
                },
            ],
        };
        assert_eq!(turn_file_changes_line_counts(&file_summary), Some((10, 3)));
        assert_eq!(
            turn_file_changes_line_counts(&TurnFileChangesSummary::default()),
            None
        );

        let output_turn = turn(
            vec![row("answer", TimelineRowKind::AgentMessage, true, "hello")],
            None,
            None,
            false,
        );
        assert_eq!(estimated_agent_output_tokens(&output_turn), Some(2));
        assert_eq!(
            agent_generation_output_tokens(&output_turn, Some(12), Some(10)),
            Some(2)
        );

        let reasoning_row_turn = turn(
            vec![row(
                "thought",
                TimelineRowKind::Reasoning,
                true,
                "thinking text",
            )],
            None,
            Some("thinking text"),
            false,
        );
        // Timeline mode: the reasoning body counts; the overlapping
        // live_status stream must not be double-counted.
        assert_eq!(
            estimated_agent_output_tokens(&reasoning_row_turn),
            Some(4) // ceil(13 / 4)
        );

        let completed_reasoning_with_live_status = turn(
            vec![row(
                "completed-thought",
                TimelineRowKind::Reasoning,
                false,
                "old",
            )],
            None,
            Some("new"),
            false,
        );
        assert_eq!(
            estimated_agent_output_tokens(&completed_reasoning_with_live_status),
            Some(2) // ceil(6 / 4)
        );

        let live_status_turn = turn(vec![], None, Some("thinking text"), false);
        // LatestAtBottom mode: the stream lives only in live_status.
        assert_eq!(estimated_agent_output_tokens(&live_status_turn), Some(4));
        assert_eq!(
            agent_generation_output_tokens(&live_status_turn, None, None),
            Some(4)
        );

        assert_eq!(
            agent_generation_token_rate(Some(10), Some(30), Duration::from_secs(2)),
            Some(10.0)
        );
        assert_eq!(
            agent_generation_token_rate(Some(30), Some(30), Duration::from_secs(2)),
            None
        );
    }

    #[test]
    fn timeline_height_measurements_are_batched_before_the_next_render() {
        let source = include_str!("app.rs");
        let recorder = source
            .split_once("    fn record_timeline_turn_height(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Apply every height observed during the prior prepaint")
            })
            .map(|(body, _)| body)
            .expect("timeline height recorder should remain inspectable");
        assert!(recorder.contains("self.timeline_pending_turn_heights"));
        assert!(!recorder.contains("Rc::make_mut"));
        assert!(!recorder.contains("self.rebuild_timeline_sizes()"));

        let batch = source
            .split_once("    fn apply_pending_timeline_row_heights(")
            .and_then(|(_, tail)| tail.split_once("\n    fn timeline_distance_to_bottom("))
            .map(|(body, _)| body)
            .expect("timeline height batch should remain inspectable");
        assert_eq!(batch.matches("Rc::make_mut").count(), 1);

        let workbench = source
            .split_once("    fn render_agent_workbench(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_controls("))
            .map(|(body, _)| body)
            .expect("agent workbench renderer should remain inspectable");
        let apply = workbench
            .find("self.apply_pending_timeline_row_heights();")
            .expect("batched heights should be applied before rendering");
        let scroll = workbench
            .find("self.apply_pending_timeline_scroll();")
            .expect("pending bottom scroll should remain applied");
        assert!(apply < scroll);
        let rebuild = workbench
            .find("self.rebuild_timeline_sizes();")
            .expect("the virtual row table should be rebuilt before rendering");
        assert!(apply < rebuild && rebuild < scroll);
    }

