    #[test]
    fn pending_command_permissions_render_as_one_blocked_command_card() {
        let source = include_str!("app.rs");
        let process_rows = source
            .split_once("    fn timeline_process_units(")
            .and_then(|(_, tail)| tail.split_once("\n    fn timeline_process_run_layout("))
            .map(|(body, _)| body)
            .expect("timeline process unit walk should remain inspectable");
        assert!(process_rows.contains("Some(permission_row)"));
        assert!(process_rows.contains("row_index += 2"));

        let command_card = source
            .split_once("    fn render_command_execution_card(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_file_operation_card("))
            .map(|(body, _)| body)
            .expect("command renderer should remain inspectable");
        assert!(command_card.contains("permission_request_is_pending"));
        assert!(command_card.contains("agent_waiting_confirmation"));
        assert!(command_card.contains("!waiting_for_confirmation"));
        assert!(command_card.contains("render_permission_request_panel"));
        assert!(command_card.contains(".unwrap_or(false)"));
        assert!(!command_card.contains(".unwrap_or(command.status"));

        let image_card = source
            .split_once("    fn render_image_generation_card(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_error_row("))
            .map(|(body, _)| body)
            .expect("image renderer should remain inspectable");
        assert!(image_card.contains(".unwrap_or(false)"));
        assert!(!image_card.contains(".unwrap_or(in_progress || image.image_reference.is_some())"));

        let turn = source
            .split_once("    fn render_timeline_turn(")
            .and_then(|(_, tail)| tail.split_once("\n    fn timeline_turn_execution_attribution("))
            .map(|(body, _)| body)
            .expect("timeline turn renderer should remain inspectable");
        // The pending row is the surface that reads the runtime's live words
        // rather than deciding for itself, and it closes them with the mark of
        // work still arriving.
        assert!(turn.contains("agent_live_progress_text(turn, self.resolved_locale())"));
        assert!(turn.contains("agent_progress_label(&pending_text"));
        assert!(!turn.contains("agent_generation_status_label"));
        assert!(!turn.contains("if turn.pending_permission"));

        let surface = source
            .split_once("fn agent_live_progress_text(")
            .and_then(|(_, tail)| tail.split_once("\nfn agent_generation_tool_call_count("))
            .map(|(body, _)| body)
            .expect("the live projections should remain inspectable");
        let (progress, bar_label) = surface
            .split_once("fn agent_generation_status_label(")
            .expect("the bar's fixed projection should remain inspectable");

        assert!(progress.contains("if turn.pending_permission"));
        assert!(progress.contains("agent_waiting_confirmation"));
        assert!(progress.contains("turn.live_status"));
        assert!(
            progress.contains("agent_generation_phase_label(agent_generation_phase(turn), locale)")
        );
        assert_eq!(
            locale::strings(locale::ResolvedLocale::ZhCn).agent_waiting_confirmation,
            "等待确认中..."
        );

        // The bar over the composer is the phase surface: it names one of the
        // fixed words and never the runtime's own line, which carries the
        // model's half-written reasoning while it thinks.
        assert!(!bar_label.contains("turn.live_status"));
        assert!(bar_label.contains("if turn.pending_permission"));
        assert!(bar_label.contains("agent_waiting_confirmation"));
        assert!(
            bar_label
                .contains("agent_generation_phase_label(agent_generation_phase(turn), locale)")
        );

        let bar = source
            .split_once("    fn render_agent_generation_status(")
            .and_then(|(_, tail)| tail.split_once("\n    fn agent_token_usage_metrics("))
            .map(|(body, _)| body)
            .expect("the generation status renderer should remain inspectable");
        assert!(
            bar.contains("agent_generation_status_label(&turn, locale)"),
            "the information bar opens with the fixed phase word"
        );
        assert!(!bar.contains("agent_live_progress_text"));
        assert!(!bar.contains("agent_pending_response"));

        let table = source
            .split_once("fn agent_generation_phase_label(")
            .and_then(|(_, tail)| {
                tail.split_once("\n/// The words a running turn does its work in")
            })
            .map(|(body, _)| body)
            .expect("the phase vocabulary should remain inspectable");
        assert!(
            !table.contains("..."),
            "the shared phase table must not carry the row's mark"
        );
    }

    #[test]
    fn permission_alert_jumps_to_its_card_and_dismissal_refreshes_the_session_state() {
        let source = include_str!("app.rs");
        let alert = source
            .split_once(
                "// Tauri parity: \"Permission waiting for review\" alert above the timeline.",
            )
            .and_then(|(_, tail)| tail.split_once(".child(timeline_surface)"))
            .map(|(body, _)| body)
            .expect("permission alert should remain inspectable");
        // The alert is both the jump affordance and the dismissal control, so
        // closing it must not run the body's own click handler.
        assert!(alert.contains("this.reveal_pending_permission_card(cx)"));
        assert!(alert.contains("Button::new(\"permission-alert-dismiss\")"));
        assert!(alert.contains("cx.stop_propagation();"));
        assert!(alert.contains("this.dismiss_pending_permission_alert(cx)"));

        let reveal = source
            .split_once("    fn reveal_pending_permission_card(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// The newest pending request the alert covers")
            })
            .map(|(body, _)| body)
            .expect("permission reveal should remain inspectable");
        // The virtual list only scrolls whole turns, so the card is revealed
        // once its row has been laid out.
        assert!(reveal.contains("self.pending_permission_reveal_item_id = Some(target.item_id);"));
        assert!(reveal.contains("self.timeline_scroll"));
        assert!(reveal.contains("ScrollStrategy::Center"));

        let dismiss = source
            .split_once("    fn dismiss_pending_permission_alert(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Whether the alert stays hidden"))
            .map(|(body, _)| body)
            .expect("permission dismissal should remain inspectable");
        // Closing only puts the alert away: the sidebar is refreshed against
        // the session's latest state instead of being told the request is gone.
        assert!(dismiss.contains("self.load_agent_overview(cx);"));
        assert!(dismiss.contains("self.refresh_selected_agent_timeline(cx);"));
        assert!(!dismiss.contains("pending_user_request_ids"));
        // The dismissal rides the persisted UI state, so a restart does not
        // bring the alert back.
        assert!(dismiss.contains("dismissed_permission_alerts"));
        assert!(dismiss.contains("self.queue_ui_state();"));

        // A dismissal only holds while the same requests are pending, so the
        // next request shows the alert again.
        let dismissed = source
            .split_once("    fn permission_alert_is_dismissed(")
            .and_then(|(_, tail)| tail.split_once("\n    /// The pending-request set"))
            .map(|(body, _)| body)
            .expect("alert dismissal state should remain inspectable");
        assert!(dismissed.contains("dismissed_permission_alerts"));
        assert!(dismissed.contains("pending_permission_alert_signature"));
    }

    #[test]
    fn permission_projection_keeps_action_context_and_hides_transport_metadata() {
        let request = vibex_core::PermissionRequest {
            id: RequestId::new(),
            session_id: VibexSessionId::parse("session_permission_projection").unwrap(),
            project_id: None,
            workspace_id: None,
            provider_request_id: Some("provider-request-7".into()),
            risk_category: vibex_core::PermissionRiskCategory::Command,
            title: "execute".into(),
            details: vec![
                vibex_core::PermissionActionDetail {
                    label: "tool".into(),
                    value: "terminal".into(),
                },
                vibex_core::PermissionActionDetail {
                    label: "toolCallId".into(),
                    value: "tool-call-7".into(),
                },
                vibex_core::PermissionActionDetail {
                    label: "requestId".into(),
                    value: "request-7".into(),
                },
                vibex_core::PermissionActionDetail {
                    label: "input".into(),
                    value: serde_json::json!({
                        "cmd": "date '+ACP permission preview'",
                        "workdir": "/repo"
                    })
                    .to_string(),
                },
                vibex_core::PermissionActionDetail {
                    label: "options".into(),
                    value: "allow_once,reject_once".into(),
                },
                vibex_core::PermissionActionDetail {
                    label: "optionKinds".into(),
                    value: "allow_once,reject_once".into(),
                },
            ],
            allowed_responses: vec![
                PermissionResponseKind::Approve,
                PermissionResponseKind::Deny,
            ],
            response_options: Vec::new(),
            status: vibex_core::PermissionRequestStatus::Pending,
            requested_at_ms: 1,
            expires_at_ms: None,
        };

        let projection = permission_card_projection(&request);
        assert_eq!(
            projection.action.as_deref(),
            Some("date '+ACP permission preview'")
        );
        assert_eq!(projection.details, vec![("cwd".into(), "/repo".into())]);
        let projection_debug = format!("{projection:?}");
        for internal_value in [
            "terminal",
            "tool-call-7",
            "request-7",
            "allow_once",
            "provider-request-7",
        ] {
            assert!(!projection_debug.contains(internal_value));
        }
    }

