    #[test]
    fn composer_surfaces_match_the_connected_two_surface_visual_contract() {
        for is_dark in [false, true] {
            let composer = composer_surface_background(is_dark);
            let queue = composer_queue_surface_background(is_dark);
            assert_eq!(composer, theme::semantic_color("composer-surface", is_dark));
            assert_eq!(composer.a, 1.0);
            assert_eq!(queue.a, COMPOSER_EXTENSION_SURFACE_OPACITY);
            assert_eq!(
                queue,
                theme::semantic_color("composer-queue", is_dark)
                    .opacity(COMPOSER_EXTENSION_SURFACE_OPACITY)
            );
            assert_ne!(composer, queue);
        }
        assert!(theme::semantic_token("composer-backdrop", true).is_none());
        assert_eq!(
            theme::semantic_token("composer-queue", true).unwrap().hex,
            "#181818"
        );
        assert_eq!(
            theme::semantic_token("composer-surface", true).unwrap().hex,
            "#141414"
        );
        assert_eq!(
            AGENT_CONTENT_NARROW_MAX_WIDTH - COMPOSER_QUEUE_HORIZONTAL_INSET * 2.0,
            728.0
        );
        assert_eq!(COMPOSER_SURFACE_MIN_HEIGHT, 112.0);
        assert_eq!(ACTIVE_COMPOSER_SURFACE_MIN_HEIGHT, 136.0);
        assert_eq!(ACTIVE_COMPOSER_TEXT_AREA_MIN_HEIGHT, 80.0);
        assert_eq!(COMPOSER_QUEUE_HEADER_HEIGHT, 36.0);
        assert_eq!(COMPOSER_QUEUE_ROW_HEIGHT, 28.0);
        assert_eq!(COMPOSER_SURFACE_RADIUS, 20.0);

        let source = include_str!("app.rs");
        let input_setup = source
            .split_once("        let composer_input =")
            .and_then(|(_, tail)| tail.split_once("\n        let new_session_input ="))
            .map(|(body, _)| body)
            .expect("composer input setup should remain inspectable");
        assert!(input_setup.contains(".auto_grow(2, 8)"));

        let composer = source
            .split_once("    fn render_composer(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_failure("))
            .map(|(body, _)| body)
            .expect("composer renderer should remain inspectable");
        assert!(composer.contains(".bg(composer_background)"));
        assert!(!composer.contains(".bg(cx.theme().background)"));
        assert!(composer.contains("session_content_max_width"));
        assert!(!composer.contains("COMPOSER_MAX_WIDTH"));
        assert!(composer.contains("toggle-composer-expanded"));
        assert!(composer.contains("this.flex_1().min_h(px(240.0))"));
        assert!(composer.contains("this.flex_1().min_h_0()"));
        assert!(composer.contains("ACTIVE_COMPOSER_SURFACE_MIN_HEIGHT"));
        assert!(composer.contains("ACTIVE_COMPOSER_TEXT_AREA_MIN_HEIGHT"));
        assert!(composer.contains(".min_h(px(ACTIVE_COMPOSER_TEXT_AREA_MIN_HEIGHT))"));
        assert!(composer.contains(".when(self.composer_expanded, |this| this.pt_4())"));
        let fullscreen_button = composer
            .find("toggle-composer-expanded")
            .expect("composer fullscreen control should remain present");
        let terminal_button = composer
            .find("self.render_composer_terminal_menu(cx)")
            .expect("composer terminal control should remain present");
        assert!(fullscreen_button < terminal_button);
        assert!(composer.contains(".pb_1()"));
        assert!(composer.contains(".when(composer_extension_visible, |this|"));
        assert!(composer.contains("px(-2.0)"));
        assert!(composer.contains(".blur_radius(px(6.0))"));
        assert!(composer.contains(".px(px(COMPOSER_QUEUE_HORIZONTAL_INSET))"));
        let plan_position = composer
            .find(".when_some(composer_plan, |this, plan|")
            .expect("the active plan should render above the composer");
        let queue_position = composer
            .find(".when_some(composer_queue, |this, queue|")
            .expect("the queued messages should remain attached to the composer");
        assert!(plan_position < queue_position);
        let goal_position = composer
            .find(".when_some(composer_goal, |this, goal|")
            .expect("the active goal should render below the queued messages");
        assert!(queue_position < goal_position);
        let generation_status_position = composer
            .find(".when_some(generation_status, |this, status|")
            .expect("the live generation status should remain attached to the composer");
        assert!(generation_status_position < plan_position);
        assert!(source.contains("agent-generation-status"));
        assert!(source.contains("when(tool_count > 0"));
        assert!(source.contains("when(added_lines > 0 || removed_lines > 0"));
        assert!(source.contains("agent_generation_compaction_count"));
        assert!(source.contains("when_some(tokens_per_second"));

        let plan = source
            .split_once("    fn render_composer_plan(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_composer_queue("))
            .map(|(body, _)| body)
            .expect("composer plan renderer should remain inspectable");
        assert!(plan.contains("current_agent_plan(&self.timeline.items)"));
        assert!(plan.contains("ProgressCircle::new"));
        assert!(plan.contains("Tooltip::element"));
        assert!(plan.contains("let complete = plan.is_complete()"));
        assert!(plan.contains("IconName::CircleCheck"));
        assert!(!plan.contains("with_animation"));
        assert!(!plan.contains("if plan.is_complete()"));
        assert!(plan.contains("toggle-composer-plan-expanded"));
        assert!(plan.contains("dismiss-composer-plan"));
        assert!(plan.contains("tooltip_show_delay(COMPOSER_PLAN_TOOLTIP_DELAY)"));
        assert!(plan.contains("COMPOSER_PLAN_EXPANDED_MAX_HEIGHT"));

        let goal = source
            .split_once("    fn render_composer_goal_row(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_composer_plan("))
            .map(|(body, _)| body)
            .expect("composer goal renderer should remain inspectable");
        assert!(goal.contains("current_active_goal(&self.timeline.items)"));
        assert!(goal.contains("composer-goal-edit"));
        assert!(goal.contains("composer-goal-pause"));
        assert!(goal.contains("composer-goal-resume"));
        assert!(goal.contains("composer-goal-clear"));
        // Editing happens in the bar itself: the pencil opens the inline
        // editor and saving issues a goal control, never a composer draft.
        assert!(goal.contains("begin_composer_goal_edit"));
        assert!(goal.contains("composer-goal-editor"));
        assert!(goal.contains("save-composer-goal-edit"));
        assert!(!goal.contains("/goal edit"));
        assert!(!goal.contains("apply_composer_history_text"));
        let goal_editor = source
            .split_once("    fn save_composer_goal_edit(")
            .and_then(|(_, tail)| tail.split_once("\n    fn save_composer_queue_edit("))
            .map(|(body, _)| body)
            .expect("goal editor save path should remain inspectable");
        assert!(goal_editor.contains("GoalAction::Set"));
        assert!(goal_editor.contains("GoalAction::Edit"));
        assert!(goal_editor.contains("control_session_goal(action, Some(objective), cx)"));
        // A `/goal` prompt wears its badge on the bubble's lower edge, in the
        // same reaction region as a queued delivery — never inline in the body.
        assert!(source.contains("render_user_message_goal_button"));
        assert!(source.contains("goal-message-badge:"));
        assert!(source.contains("render_user_message_edge_reactions"));
        // The goal row is the last row of the queued-message surface, so the
        // two extension bars share one silhouette.
        assert!(source.contains(
            "fn render_composer_queue(\n        &mut self,\n        goal_row: Option<AnyElement>,"
        ));
        assert!(source.contains(".child(goal_row)"));

        let plan_details = source
            .split_once("fn render_composer_plan_details(")
            .and_then(|(_, tail)| tail.split_once("\nfn partition_terminal_sessions("))
            .map(|(body, _)| body)
            .expect("shared composer plan details should remain inspectable");
        assert!(plan_details.contains("composer_plan_step_status_label"));
        assert!(plan_details.contains("PlanStepStatus::Pending"));
        assert!(plan_details.contains("PlanStepStatus::Running"));
        assert!(plan_details.contains("PlanStepStatus::Completed"));
        assert!(plan_details.contains("PlanStepStatus::Failed"));

        let queue = source
            .split_once("    fn render_composer_queue(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_composer("))
            .map(|(body, _)| body)
            .expect("composer queue renderer should remain inspectable");
        assert!(queue.contains(".bg(composer_queue_surface_background("));
        assert!(queue.contains("composer-queue-header"));
        assert!(queue.contains("COMPOSER_QUEUE_HEADER_HEIGHT"));
        assert!(queue.contains("toggle-composer-queue-send-mode"));
        assert!(queue.contains("clear-composer-queue"));
        assert!(queue.contains("IconName::Inbox"));
        assert!(queue.contains("IconName::Play"));
        assert!(!queue.contains("message_count"));
        assert!(!queue.contains("if paused {"));
        assert!(queue.contains(".min_h(px(COMPOSER_QUEUE_ROW_HEIGHT))"));
        assert!(queue.contains("COMPOSER_QUEUE_EDIT_ROW_HEIGHT"));
        assert!(queue.contains(".rounded_tl(px(COMPOSER_SURFACE_RADIUS))"));
        assert!(queue.contains(".rounded_tr(px(COMPOSER_SURFACE_RADIUS))"));
        assert!(queue.contains(".border_b_0()"));
        assert!(queue.contains(".border_b_1()"));
    }

    #[test]
    fn composer_queue_previews_clamp_message_text_to_three_lines_outside_edit_mode() {
        let source = include_str!("app.rs");
        let preview = source
            .split_once("    fn render_composer_queue_inline_content(")
            .and_then(|(_, tail)| tail.split_once("\n    fn delete_composer_queue_message("))
            .map(|(body, _)| body)
            .expect("queued message preview renderer should remain inspectable");
        assert!(preview.contains(".max_h(px(COMPOSER_QUEUE_PREVIEW_MAX_HEIGHT))"));
        assert!(preview.contains(".overflow_hidden()"));
        assert!(preview.contains(".overflow_y_scroll()"));
        assert!(preview.contains("composer-queue-content-"));
        // The clamp only guards the non-editing preview; editing keeps the
        // multi-line input.
        assert!(!preview.contains("COMPOSER_QUEUE_EDIT_ROW_HEIGHT"));

        assert_eq!(COMPOSER_QUEUE_PREVIEW_MAX_LINES, 3);
        assert_eq!(COMPOSER_QUEUE_PREVIEW_MAX_HEIGHT, 63.0);
    }

