    /// The fullscreen composer is an input box, not just a taller surface: the
    /// whole box stays editable. The textarea used to keep the `auto_grow(2, 8)`
    /// row cap after expanding, so a long draft stayed clipped to roughly eight
    /// rows while the rest of the surface was dead space.
    #[gpui::test]
    fn expanded_composer_keeps_the_whole_surface_editable(cx: &mut TestAppContext) {
        cx.update(gpui_component::init);
        const DRAFT_LINES: usize = 20;
        let mut measured = Vec::new();
        for expanded in [false, true] {
            let surface_height = Rc::new(Cell::new(0.0));
            let input_row_height = Rc::new(Cell::new(0.0));
            let input_slot_height = Rc::new(Cell::new(0.0));
            let input_slot = Rc::new(RefCell::new(None));
            let (_, cx) = cx.add_window_view(|window, cx| {
                let input = cx.new(|cx| TextareaState::new(window, cx).auto_grow(2, 8));
                *input_slot.borrow_mut() = Some(input.clone());
                ComposerFullscreenLayoutProbe {
                    input,
                    expanded,
                    surface_height: surface_height.clone(),
                    input_row_height: input_row_height.clone(),
                    input_slot_height: input_slot_height.clone(),
                }
            });
            let input = input_slot
                .borrow()
                .clone()
                .expect("composer probe should own its textarea state");
            cx.update(|window, cx| {
                input.update(cx, |input, cx| {
                    input.replace(
                        (0..DRAFT_LINES)
                            .map(|line| format!("draft line {line}"))
                            .collect::<Vec<_>>()
                            .join("\n"),
                        window,
                        cx,
                    );
                });
                for _ in 0..2 {
                    window.simulate_next_frame(cx);
                    let _ = window.draw(cx);
                }
            });
            let visible_rows = input.read_with(cx, |input, _| input.visible_row_range());
            let visible_rows = visible_rows
                .map(|rows| rows.len())
                .expect("the composer textarea should report its laid-out rows");
            measured.push((
                surface_height.get(),
                input_row_height.get(),
                input_slot_height.get(),
                visible_rows,
            ));
        }

        let (collapsed_surface, _, collapsed_slot, collapsed_rows) = measured[0];
        let (expanded_surface, _, expanded_slot, expanded_rows) = measured[1];
        assert!(
            expanded_surface > collapsed_surface * 3.0,
            "the expanded composer should fill the workbench: collapsed {collapsed_surface}, expanded {expanded_surface}"
        );
        assert!(
            collapsed_rows < DRAFT_LINES,
            "the collapsed composer keeps its auto-grow row cap: {collapsed_rows} of {DRAFT_LINES} rows"
        );
        assert!(
            expanded_rows >= DRAFT_LINES,
            "the expanded composer should lay out every draft row: {expanded_rows} of {DRAFT_LINES} rows"
        );
        assert!(
            expanded_slot > collapsed_slot * 3.0,
            "the input slot should grow with the fullscreen surface: collapsed {collapsed_slot}, expanded {expanded_slot}"
        );

        let composer = include_str!("app.rs")
            .split_once("    fn render_composer(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_failure("))
            .map(|(body, _)| body)
            .expect("composer renderer should remain inspectable");
        // The probe only proves the height chain works; the composer itself has
        // to opt into it, so guard the two expanded-only hooks in its source.
        assert!(composer.contains("this.self_stretch()"));
        assert!(composer.contains("this.h_full()"));
    }

    #[gpui::test]
    fn composer_paste_reveals_the_cursor_after_updated_text_is_laid_out(cx: &mut TestAppContext) {
        cx.update(gpui_component::init);
        let input_slot = Rc::new(RefCell::new(None));
        let input_slot_for_view = input_slot.clone();
        let (_, cx) = cx.add_window_view(|window, cx| {
            let input = cx.new(|cx| TextareaState::new(window, cx).auto_grow(2, 8));
            *input_slot_for_view.borrow_mut() = Some(input.clone());
            let probe = cx.new(|_| ComposerPasteScrollProbe { input });
            gpui_component::Root::new(probe, window, cx)
        });
        let input = input_slot
            .borrow()
            .clone()
            .expect("composer input should be created with the root view");

        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });

        let pasted_text = (0..80)
            .map(|line| format!("pasted line {line}"))
            .collect::<Vec<_>>()
            .join("\n");
        cx.update(|window, cx| {
            // Capture handlers run before the native Input paste action.
            reveal_composer_cursor_after_layout(input.clone(), window);
            input.update(cx, |input, cx| input.replace(pasted_text, window, cx));
        });

        for _ in 0..2 {
            cx.update(|window, cx| {
                window.simulate_next_frame(cx);
                let _ = window.draw(cx);
            });
        }

        input.read_with(cx, |input, _| {
            let cursor = input.cursor();
            assert!(input.scroll_offset().y < px(0.0));
            assert!(
                input.range_to_bounds(&(cursor..cursor)).is_some(),
                "the pasted-text cursor should be inside the laid-out viewport"
            );
        });
    }

    /// A marker pasted onto a row clipped by the viewport keeps its chip.
    ///
    /// This is the shape of the reported failure: the textarea paints the marker
    /// text for a row that is only partly on screen, so if the overlay drops the
    /// chip for that row the user reads the raw `attachment_…_vbx` marker. The
    /// chip has to exist whenever the marker's box has any overlap with the
    /// textarea's own viewport.
    #[gpui::test]
    fn composer_paste_keeps_the_chip_on_a_row_clipped_by_the_viewport(cx: &mut TestAppContext) {
        cx.update(gpui_component::init);
        let input_slot = Rc::new(RefCell::new(None));
        let input_slot_for_view = input_slot.clone();
        let (_, cx) = cx.add_window_view(|window, cx| {
            // A short auto-grow cap, so the fixture's draft is taller than the
            // frame and its last row is clipped by the bottom edge.
            let input = cx.new(|cx| TextareaState::new(window, cx).auto_grow(2, 2));
            *input_slot_for_view.borrow_mut() = Some(input.clone());
            let probe = cx.new(|_| ComposerPasteScrollProbe { input });
            gpui_component::Root::new(probe, window, cx)
        });
        let input = input_slot
            .borrow()
            .clone()
            .expect("composer input should be created with the root view");
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });

        let marker = inline_composer_attachment_marker(1);
        // Seven filler rows plus the marker row: the textarea's frame shows part
        // of the eighth row, so the marker sits on the clipped bottom edge.
        let mut rows = (0..7)
            .map(|row| format!("filler row {row}"))
            .collect::<Vec<_>>();
        rows.push(marker.clone());
        let text = rows.join("\n");
        let start = text.find(&marker).expect("marker should be present");
        let range = start..start + marker.len();
        cx.update(|window, cx| {
            input.update(cx, |input, cx| input.set_value(text.clone(), window, cx));
        });

        for _ in 0..3 {
            cx.update(|window, cx| {
                window.simulate_next_frame(cx);
                let _ = window.draw(cx);
            });
        }

        input.read_with(cx, |input, _| {
            let viewport = input.input_bounds();
            let bounds = input
                .range_to_bounds(&range)
                .expect("a marker in the painted text should be laid out");

            // The fixture has to reproduce the reported shape, or it would keep
            // passing without the fix: the last row hangs over the bottom edge.
            assert!(
                bounds.bottom() > viewport.bottom(),
                "the marker row should be clipped by the viewport: \
                 marker {bounds:?} viewport {viewport:?}"
            );
            // The row is on screen, so its chip has to be painted too. The old
            // strict-containment test rejected exactly this case, leaving the
            // raw marker glyphs exposed.
            assert!(
                composer_attachment_bounds_are_visible(bounds, viewport),
                "a partly visible marker row must keep its chip: \
                 marker {bounds:?} viewport {viewport:?}"
            );
        });
    }

    #[test]
    fn composer_queue_send_mode_defaults_to_auto_and_manual_keeps_force_send_available() {
        let session = VibexSessionId::parse("session_queue_mode").unwrap();
        let mut manual_session_ids = BTreeSet::new();

        assert!(composer_queue_auto_send_enabled(
            &manual_session_ids,
            &session
        ));
        assert!(composer_queue_dispatch_enabled(
            &manual_session_ids,
            &session,
            ComposerQueueDispatchBehavior::Automatic,
        ));

        manual_session_ids.insert(session.as_str().to_string());
        assert!(!composer_queue_auto_send_enabled(
            &manual_session_ids,
            &session
        ));
        assert!(!composer_queue_dispatch_enabled(
            &manual_session_ids,
            &session,
            ComposerQueueDispatchBehavior::Automatic,
        ));
        // An explicit composer send still honors Manual send mode.
        assert!(!composer_queue_dispatch_enabled(
            &manual_session_ids,
            &session,
            ComposerQueueDispatchBehavior::ExplicitSend,
        ));
        assert!(composer_queue_dispatch_enabled(
            &manual_session_ids,
            &session,
            ComposerQueueDispatchBehavior::ForceNext,
        ));
        assert!(composer_queue_dispatch_enabled(
            &manual_session_ids,
            &session,
            ComposerQueueDispatchBehavior::AfterInterrupt,
        ));
        assert!(!composer_queue_dispatch_enabled(
            &manual_session_ids,
            &session,
            ComposerQueueDispatchBehavior::AfterCompletion,
        ));
    }

    #[test]
    fn composer_queue_dispatch_waits_for_a_running_turn_except_for_an_explicit_steer() {
        // An explicit steer is the one handoff that may deliver into the turn it
        // just interrupted; the local pending flag still fences it.
        assert!(composer_queue_session_blocks_dispatch(
            ComposerQueueDispatchBehavior::AfterInterrupt,
            true,
            Some(AgentSessionState::Running),
        ));
        assert!(!composer_queue_session_blocks_dispatch(
            ComposerQueueDispatchBehavior::AfterInterrupt,
            false,
            Some(AgentSessionState::Running),
        ));
        // A submission handoff waits for the turn to end: a snapshot that still
        // says Running is either the turn itself or a lag the fence keeps the
        // queue honest through, never a reason to hand over the next entry.
        assert!(composer_queue_session_blocks_dispatch(
            ComposerQueueDispatchBehavior::AfterCompletion,
            true,
            Some(AgentSessionState::Running),
        ));
        assert!(composer_queue_session_blocks_dispatch(
            ComposerQueueDispatchBehavior::AfterCompletion,
            false,
            Some(AgentSessionState::Running),
        ));
        assert!(composer_queue_session_blocks_dispatch(
            ComposerQueueDispatchBehavior::AfterCompletion,
            false,
            Some(AgentSessionState::NeedsInput),
        ));
        assert!(composer_queue_session_blocks_dispatch(
            ComposerQueueDispatchBehavior::Automatic,
            false,
            Some(AgentSessionState::Running),
        ));
        assert!(composer_queue_session_blocks_dispatch(
            ComposerQueueDispatchBehavior::ForceNext,
            false,
            Some(AgentSessionState::Running),
        ));
        assert!(!composer_queue_session_blocks_dispatch(
            ComposerQueueDispatchBehavior::Automatic,
            false,
            Some(AgentSessionState::Idle),
        ));
    }

    /// The queue advances one message at a time: the entries behind the message
    /// that was just dispatched wait while its turn still occupies its session.
    /// The judgment is the session's own state, so a fence can never be
    /// stranded by a probe that has not answered.
    #[test]
    fn the_pre_send_queue_waits_for_the_turn_it_handed_over() {
        // The submission itself is still in flight.
        assert!(composer_queue_fence_waits(
            true,
            Some(AgentSessionState::Idle)
        ));
        // A turn that is still occupying the Agent holds the queue.
        assert!(composer_queue_fence_waits(
            false,
            Some(AgentSessionState::Running)
        ));
        assert!(composer_queue_fence_waits(
            false,
            Some(AgentSessionState::NeedsInput)
        ));
        // A session whose turn has not settled yet holds it too.
        assert!(composer_queue_fence_waits(
            false,
            Some(AgentSessionState::Initializing)
        ));
        // A settled session releases the queue, whatever its last turn was:
        // waiting on a verdict would strand the whole queue behind a session
        // that cannot answer, and a failed stop is still a turn that is over.
        for state in [
            AgentSessionState::Idle,
            AgentSessionState::Error,
            AgentSessionState::Closed,
            AgentSessionState::Archived,
        ] {
            assert!(!composer_queue_fence_waits(false, Some(state)), "{state:?}");
        }
        // A session the workbench no longer tracks cannot hold the queue.
        assert!(!composer_queue_fence_waits(false, None));
    }

    /// An explicit send is the one gesture that may overtake the queue. A due
    /// schedule is never dispatched with one of these behaviors, so it cannot
    /// inherit the bypass from the reader's message behind it.
    #[test]
    fn only_an_explicit_send_may_overtake_the_queue_fence() {
        for behavior in [
            ComposerQueueDispatchBehavior::ForceNext,
            ComposerQueueDispatchBehavior::AfterInterrupt,
            ComposerQueueDispatchBehavior::ExplicitSend,
        ] {
            assert!(
                composer_queue_behavior_is_explicit(behavior),
                "{behavior:?}"
            );
        }
        for behavior in [
            ComposerQueueDispatchBehavior::Automatic,
            ComposerQueueDispatchBehavior::Scheduled,
            ComposerQueueDispatchBehavior::AfterCompletion,
        ] {
            assert!(
                !composer_queue_behavior_is_explicit(behavior),
                "{behavior:?}"
            );
        }
    }

    /// The queue is one list across sessions: the dispatcher asks for its head,
    /// a head that carries a deadline decides its own `Scheduled` behavior, and
    /// only then does the explicit-send bypass get a say.
    #[test]
    fn the_dispatch_head_is_the_queues_first_entry_and_a_schedule_decides_it() {
        let source = include_str!("app.rs");
        let maybe_dispatch = source
            .split_once("    fn maybe_dispatch_next_composer_queue_message(")
            .and_then(|(_, tail)| {
                tail.split_once(
                    "\n    /// Whether the pre-send queue is still waiting for the turn",
                )
            })
            .map(|(body, _)| body)
            .expect("queue dispatch should remain inspectable");
        let head = maybe_dispatch
            .find("message_schedule::next_queue_message_index(")
            .expect("the dispatcher should ask the queue for its head");
        let scheduled = maybe_dispatch
            .find("ComposerQueueDispatchBehavior::Scheduled")
            .expect("a scheduled head should decide its own behavior");
        let fence = maybe_dispatch
            .find("composer_queue_behavior_is_explicit(behavior)")
            .expect("the fence bypass should read the explicit behavior");
        assert!(head < scheduled);
        assert!(scheduled < fence);
        assert!(maybe_dispatch.contains("self.composer_queue.remove(index);"));
    }

    #[test]
    fn automatic_composer_queue_waits_for_an_incomplete_turn_continuation() {
        // An unobserved revision never auto-sends: it could be an abnormal stop.
        assert!(composer_queue_waits_for_continuation(
            ComposerQueueDispatchBehavior::Automatic,
            Some(AgentSessionState::Idle),
            None,
        ));
        assert!(composer_queue_waits_for_continuation(
            ComposerQueueDispatchBehavior::Automatic,
            Some(AgentSessionState::Error),
            None,
        ));
        // A probed abnormal stop keeps the queue paused.
        assert!(composer_queue_waits_for_continuation(
            ComposerQueueDispatchBehavior::Automatic,
            Some(AgentSessionState::Idle),
            Some(Some(false)),
        ));
        // A probed normal completion releases it.
        assert!(!composer_queue_waits_for_continuation(
            ComposerQueueDispatchBehavior::Automatic,
            Some(AgentSessionState::Idle),
            Some(Some(true)),
        ));
        assert!(!composer_queue_waits_for_continuation(
            ComposerQueueDispatchBehavior::Automatic,
            Some(AgentSessionState::Error),
            Some(Some(true)),
        ));
        // A probe that found no conversational turn has nothing to wait for.
        assert!(!composer_queue_waits_for_continuation(
            ComposerQueueDispatchBehavior::Automatic,
            Some(AgentSessionState::Idle),
            Some(None),
        ));
        // Explicit actions bypass the wait.
        assert!(!composer_queue_waits_for_continuation(
            ComposerQueueDispatchBehavior::ForceNext,
            Some(AgentSessionState::Error),
            None,
        ));
        assert!(!composer_queue_waits_for_continuation(
            ComposerQueueDispatchBehavior::AfterInterrupt,
            Some(AgentSessionState::Idle),
            None,
        ));
        // A user send from the composer advances the queue even after an
        // abnormal stop: the message is deferred, not paused.
        assert!(!composer_queue_waits_for_continuation(
            ComposerQueueDispatchBehavior::ExplicitSend,
            Some(AgentSessionState::Idle),
            Some(Some(false)),
        ));
        assert!(!composer_queue_waits_for_continuation(
            ComposerQueueDispatchBehavior::ExplicitSend,
            Some(AgentSessionState::Idle),
            None,
        ));
    }

    #[test]
    fn submitted_composer_draft_is_cleared_before_async_dispatch() {
        let source = include_str!("app.rs");
        let submit = source
            .split_once("    fn submit_composer(")
            .and_then(|(_, tail)| tail.split_once("\n    fn start_submission_poll("))
            .map(|(body, _)| body)
            .expect("composer submission should remain inspectable");
        // Both the native dispatch and the remote twin must clear the
        // captured draft before their own async dispatch begins.
        let native_clear = submit
            .find("input.set_value(\"\", window, cx)")
            .expect("the submitted draft should be cleared");
        let native_dispatch = submit
            .find("let runner = gpui_tokio::Tokio::spawn")
            .expect("message dispatch should remain asynchronous");
        assert!(native_clear < native_dispatch);

        let remote = source
            .split_once("    fn take_composer_message_remote(")
            .and_then(|(_, tail)| tail.split_once("\n    fn dispatch_composer_message_remote("))
            .map(|(body, _)| body)
            .expect("remote composer take should remain inspectable");
        let remote_clear = remote
            .find("input.set_value(\"\", window, cx)")
            .expect("the remote draft should be cleared");
        assert!(remote_clear > 0);
    }

    #[test]
    fn created_session_consumes_its_draft_before_the_initial_turn_completes() {
        let source = include_str!("app.rs");
        let submit = source
            .split_once("    fn submit_new_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn choose_runtime_selection("))
            .map(|(body, _)| body)
            .expect("new-session submission should remain inspectable");
        let session_ready = submit
            .rfind("NewSessionCreateSignal::SessionReady(")
            .expect("the authoritative session should be handled before its initial turn");
        let clear = submit
            .find("this.clear_submitted_new_session_draft(window, cx);")
            .expect("the submitted new-session draft should be consumed");
        let turn_completion = submit
            .find("let outcome = runner.await;")
            .expect("initial-turn completion should remain asynchronous");

        assert!(session_ready < clear && clear < turn_completion);
        assert!(!submit[turn_completion..].contains("clear_submitted_new_session_draft"));

        let immediate_clear = submit
            .find("self.clear_new_session_message_draft(window, cx);")
            .expect("submission should clear the captured message draft immediately");
        let dispatch = submit
            .find("let runner = gpui_tokio::Tokio::spawn")
            .expect("session creation should remain asynchronous");
        assert!(immediate_clear < dispatch);
        assert_eq!(
            submit
                .matches("self.clear_new_session_message_draft(window, cx);")
                .count(),
            1
        );
        assert_eq!(
            submit.matches("this.fail_pending_new_session(").count(),
            2,
            "both session-creation failure paths should restore the draft"
        );
        let initial_message_failure = submit
            .split_once("if let Some(error) = initial_message_error")
            .and_then(|(_, tail)| tail.split_once("this.reconcile_sidebar_state();"))
            .map(|(body, _)| body)
            .expect("initial-message failure handling should remain inspectable");
        assert!(initial_message_failure.contains("this.runtime_note"));
        assert!(
            !initial_message_failure.contains("discard_optimistic_user_message"),
            "a created session must keep the captured user message visible when initialization fails"
        );
        assert!(!initial_message_failure.contains("composer_input"));
        assert!(!initial_message_failure.contains("draft_raw_text"));
        assert!(!initial_message_failure.contains("draft_attachments"));
        assert!(!initial_message_failure.contains("draft_command_entry"));

        let clear_draft = source
            .split_once("    fn clear_submitted_new_session_draft(")
            .and_then(|(_, tail)| tail.split_once("\n    fn current_checkout_for_project("))
            .map(|(body, _)| body)
            .expect("submitted draft cleanup should remain inspectable");
        assert!(clear_draft.contains("self.clear_new_session_message_draft(window, cx);"));
        assert!(clear_draft.contains("self.new_session_draft_initialized = false;"));
        assert!(clear_draft.contains("self.new_session_workspace.reset_after_success();"));
        assert!(clear_draft.contains("self.new_session_attachments.clear();"));
        assert!(clear_draft.contains("self.new_session_command_entry = None;"));
        assert!(clear_draft.contains("input.set_value(\"\", window, cx)"));
        assert!(clear_draft.contains("self.new_session_attachments = attachments;"));
        assert!(clear_draft.contains("self.new_session_command_entry = command_entry;"));
    }

