    #[test]
    fn inline_composer_attachment_marker_reserves_the_full_token_label() {
        let marker = inline_composer_attachment_marker(7);
        let insertion = inline_composer_attachment_insertion(&marker);

        assert!(marker.starts_with("attachment_7"));
        assert!(marker.contains(COMPOSER_INLINE_ATTACHMENT_MARKER_RESERVE));
        assert!(marker.ends_with(COMPOSER_INLINE_ATTACHMENT_SUFFIX));
        assert!(
            marker.chars().all(
                |character| character.is_ascii_alphanumeric() || matches!(character, '_' | '.')
            )
        );
        assert_eq!(insertion, format!(" {marker} "));
        assert_eq!(
            inline_composer_attachment_padded_range(&insertion, 1..1 + marker.len()),
            0..insertion.len()
        );
        assert!(COMPOSER_INLINE_ATTACHMENT_MARKER_RESERVE.len() >= 8);
    }

    #[test]
    fn inline_composer_attachment_overlay_requires_visible_row_and_input_bounds() {
        let input_bounds = Bounds {
            origin: point(px(20.0), px(40.0)),
            size: Size {
                width: px(400.0),
                height: px(80.0),
            },
        };
        let visible = Bounds {
            origin: point(px(32.0), px(56.0)),
            size: Size {
                width: px(160.0),
                height: px(20.0),
            },
        };
        let above = Bounds {
            origin: point(px(32.0), px(20.0)),
            size: visible.size,
        };

        assert_eq!(
            composer_buffer_row_for_offset("first\nsecond\nthird", 13),
            2
        );
        assert!(composer_attachment_bounds_are_visible(
            visible,
            input_bounds
        ));
        assert!(!composer_attachment_bounds_are_visible(above, input_bounds));
    }

    /// A marker whose row is only partly on screen still paints its text, so it
    /// must still paint its chip.
    ///
    /// The overlay draws over the marker, and the marker is plain text the
    /// textarea paints for any row that is even partly inside the viewport. A
    /// row clipped by the top or bottom edge therefore used to keep the text and
    /// lose the chip, which is the raw `attachment_…_vbx` marker a user saw. Any
    /// vertical overlap is enough to require the chip, and only a box completely
    /// outside the viewport may drop it.
    #[test]
    fn inline_composer_attachment_overlay_covers_rows_clipped_by_the_viewport() {
        let input_bounds = Bounds {
            origin: point(px(20.0), px(40.0)),
            size: Size {
                width: px(400.0),
                height: px(80.0),
            },
        };
        let clipped_at_top = Bounds {
            origin: point(px(32.0), px(28.0)),
            size: Size {
                width: px(160.0),
                height: px(20.0),
            },
        };
        let clipped_at_bottom = Bounds {
            origin: point(px(32.0), px(112.0)),
            size: Size {
                width: px(160.0),
                height: px(20.0),
            },
        };
        let below = Bounds {
            origin: point(px(32.0), px(208.0)),
            size: Size {
                width: px(160.0),
                height: px(20.0),
            },
        };

        assert!(composer_attachment_bounds_are_visible(
            clipped_at_top,
            input_bounds
        ));
        assert!(composer_attachment_bounds_are_visible(
            clipped_at_bottom,
            input_bounds
        ));
        assert!(!composer_attachment_bounds_are_visible(below, input_bounds));
    }

