    #[test]
    fn shortcut_dialog_keeps_one_input_entity_across_dialog_repaints() {
        let source = include_str!("app.rs");
        let dialog = source
            .split_once("    fn open_shortcut_dialog(")
            .and_then(|(_, tail)| tail.split_once("\n    fn "))
            .map(|(body, _)| body)
            .expect("the shortcut dialog should remain inspectable");

        let input_creation = dialog
            .find("let input = cx.new(")
            .expect("the shortcut input should be created once");
        let dialog_open = dialog
            .find("window.open_dialog(cx")
            .expect("the shortcut dialog should open after its input exists");
        assert!(
            input_creation < dialog_open,
            "the input entity must be created outside the dialog builder"
        );
        assert!(
            !dialog[dialog_open..].contains("cx.new("),
            "the dialog builder must not replace the input entity on every repaint"
        );
        assert!(
            dialog.contains("window.on_next_frame(move |window, cx|"),
            "the input should take focus after the dialog's focus trap mounts"
        );
        assert!(
            dialog.contains("input.set_selected_range(0..input_selection_end, cx)"),
            "the current chord should be selected so typing replaces it"
        );
        assert!(
            dialog.contains("settings.shortcut_note.clone()"),
            "a rejected chord should be reported inside the dialog"
        );
    }

    /// A dialog builder is evaluated again on every repaint, so an input created
    /// inside one is replaced — focus handle and text included — as soon as the
    /// user types, which makes the field impossible to edit. Every dialog field
    /// therefore has to exist before the dialog opens and take focus after the
    /// dialog's focus trap has mounted.
    #[test]
    fn dialog_inputs_are_created_before_their_dialog_opens() {
        let source = include_str!("app.rs");
        let dialogs = [
            (
                "    fn prompt_rename_composer_terminal(",
                "\n    fn open_local_history_import_dialog(",
                "terminal rename",
                "input.set_selected_range(0..selection_end, cx)",
            ),
            (
                "    fn prompt_runtime_feature_value(",
                "\n    fn choose_new_session_agent(",
                "runtime feature value",
                "input.set_selected_range(0..selection_end, cx)",
            ),
            (
                "    fn open_custom_shell_dialog(",
                "\n    fn open_shortcut_dialog(",
                "custom shell",
                "input.focus(window, cx)",
            ),
        ];
        for (start, end, label, focus_assertion) in dialogs {
            let body = source
                .split_once(start)
                .and_then(|(_, tail)| tail.split_once(end))
                .map(|(body, _)| body)
                .unwrap_or_else(|| panic!("the {label} dialog should remain inspectable"));
            let input_creation = body
                .find("let input = cx.new(")
                .unwrap_or_else(|| panic!("the {label} input should be created once"));
            let dialog_open = body
                .find("window.open_dialog(cx")
                .unwrap_or_else(|| panic!("the {label} dialog should open after its input exists"));
            assert!(
                input_creation < dialog_open,
                "{label}: the input entity must be created outside the dialog builder"
            );
            assert!(
                !body[dialog_open..].contains("cx.new("),
                "{label}: the dialog builder must not replace the input entity on every repaint"
            );
            assert!(
                body.contains("window.on_next_frame(move |window, cx|"),
                "{label}: the input should take focus after the dialog's focus trap mounts"
            );
            assert!(
                body.contains(focus_assertion),
                "{label}: the field should be ready to type into"
            );
        }
    }

    /// One label serves the shortcuts page, the settings search, and the command
    /// palette, so an untranslated entry shows up as English copy on three
    /// otherwise translated surfaces. The palette shipped exactly that bug: the
    /// label table had hardcoded English for most actions.
    #[test]
    fn every_foundation_shortcut_is_named_in_the_active_language() {
        let en = locale::strings(locale::ResolvedLocale::En);
        for strings in [
            locale::strings(locale::ResolvedLocale::ZhCn),
            locale::strings(locale::ResolvedLocale::ZhTw),
        ] {
            for (action, _) in FOUNDATION_SHORTCUTS {
                // "Vibex" is the product name, and the one label that carries it
                // keeps it in every locale; nothing else may stay Latin.
                let label = shortcut_action_label(action, strings).replace("Vibex", "");
                assert!(
                    !label.chars().any(|c| c.is_ascii_alphabetic()),
                    "{action} still reads English in {}: {label}",
                    strings.locale.tag(),
                );
                let group = shortcut_action_group(action, strings);
                assert!(
                    !group.chars().any(|c| c.is_ascii_alphabetic()),
                    "{action} still has an English group in {}: {group}",
                    strings.locale.tag(),
                );
                assert_ne!(
                    shortcut_action_label(action, en),
                    shortcut_action_label(action, strings),
                    "{action} has one label for every locale",
                );
            }
        }
    }

    #[test]
    fn image_edit_shortcuts_bind_undo_and_redo_without_stealing_text_input_chords() {
        assert!(shortcut_is_valid(UNDO_IMAGE_EDIT_SHORTCUT));
        assert!(shortcut_is_valid(REDO_IMAGE_EDIT_SHORTCUT));

        let mut keystrokes: Vec<&str> = FOUNDATION_SHORTCUTS.iter().map(|(_, key)| *key).collect();
        let total = keystrokes.len();
        keystrokes.sort_unstable();
        keystrokes.dedup();
        assert_eq!(
            keystrokes.len(),
            total,
            "foundation shortcut defaults must stay conflict free"
        );

        let english = locale::strings(locale::ResolvedLocale::En);
        for action in ["undo_image_edit", "redo_image_edit"] {
            assert!(
                FOUNDATION_SHORTCUTS.iter().any(|(name, _)| *name == action),
                "{action} must be remappable from the shortcuts settings page"
            );
            assert_ne!(action_name(action), "vibex::NoAction");
            assert_ne!(shortcut_action_label(action, english), "Shortcut");
            assert_ne!(shortcut_action_group(action, english), "Vibex");
            let mut bindings = Vec::new();
            bind_action(&mut bindings, "ctrl-z", action, false);
            assert_eq!(bindings.len(), 1, "{action} must resolve to a key binding");
        }

        let source = include_str!("app.rs");
        let workbench = source
            .split_once(".id(\"vibex-foundation\")")
            .and_then(|(_, tail)| tail.split_once(".capture_key_down("))
            .map(|(body, _)| body)
            .expect("workbench action handlers should remain inspectable");
        assert!(workbench.contains(".on_action(cx.listener(Self::on_undo_image_edit))"));
        assert!(workbench.contains(".on_action(cx.listener(Self::on_redo_image_edit))"));

        let handlers = source
            .split_once("    fn attachment_edit_shortcuts_active(")
            .and_then(|(_, tail)| tail.split_once("\n    fn select_attachment_edit_tool("))
            .map(|(body, _)| body)
            .expect("image edit shortcut handlers should remain inspectable");
        assert!(handlers.contains("is_focused(window)"));
        assert_eq!(
            handlers.matches("cx.propagate();").count(),
            2,
            "undo and redo must both fall through when the image editor is not active"
        );
    }

