    #[test]
    fn packaged_release_channel_cannot_be_changed_at_runtime() {
        assert_eq!(
            resolve_release_channel(Some("preview"), None).unwrap(),
            ReleaseChannel::Preview
        );
        assert_eq!(
            resolve_release_channel(Some("rc"), Some("RC")).unwrap(),
            ReleaseChannel::ReleaseCandidate
        );
        assert_eq!(
            resolve_release_channel(Some("stable"), None).unwrap(),
            ReleaseChannel::Stable
        );
        let error = resolve_release_channel(Some("rc"), Some("stable")).unwrap_err();
        assert_eq!(error.code, "release_channel_override_rejected");
    }

    #[test]
    fn stable_channel_requires_an_explicit_stable_build() {
        assert_eq!(
            resolve_release_channel(None, None).unwrap(),
            ReleaseChannel::Preview
        );
        assert_eq!(
            resolve_release_channel(None, Some("rc")).unwrap(),
            ReleaseChannel::ReleaseCandidate
        );
        let error = resolve_release_channel(None, Some("stable")).unwrap_err();
        assert_eq!(error.code, "stable_channel_requires_release_build");
        let error = resolve_release_channel(Some("nightly"), None).unwrap_err();
        assert_eq!(error.code, "release_channel_invalid");
    }

