    #[test]
    fn the_tui_listener_is_a_general_setting_and_not_a_pairing_choice() {
        let source = include_str!("app.rs");

        // The switch is drawn on the General page, labelled by the client it
        // serves, and its state comes from the runtime rather than from a stored
        // preference the page could show without asking.
        let control = source
            .split_once("    fn render_local_clients_control(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_general_page("))
            .map(|(body, _)| body)
            .expect("the local-client control should remain inspectable");
        assert!(control.contains("settings-local-clients"));
        assert!(control.contains("set_local_clients_enabled"));
        assert!(control.contains("LocalClientsSettingsState::Ready(snapshot)"));
        assert!(control.contains("snapshot.listening"));
        // A switch that is inert until the runtime has answered, so it never
        // promises a change the page cannot make.
        assert!(control.contains("let disabled = busy || !actionable;"));

        let page = source
            .split_once("    fn render_general_page(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_appearance_page("))
            .map(|(body, _)| body)
            .expect("the General page should remain inspectable");
        assert!(page.contains("render_local_clients_control"));
        assert!(page.contains("Vibex TUI"));

        // Activating the section is what re-reads the listener, and the read is
        // deferred so a palette-driven switch does not update the workbench from
        // inside its own update.
        let activation = source
            .split_once("    fn activate_settings_section(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Reloads the same-machine"))
            .map(|(body, _)| body)
            .expect("section activation should remain inspectable");
        assert!(activation.contains("SettingsSection::General"));
        assert!(activation.contains("request_local_clients_refresh"));

        let refresh = source
            .split_once("    fn request_local_clients_refresh(")
            .and_then(|(_, tail)| tail.split_once("\n    fn read_local_clients("))
            .map(|(body, _)| body)
            .expect("the deferred read should remain inspectable");
        assert!(refresh.contains("cx.defer("));
        assert!(refresh.contains("read_local_clients"));

        let read = source
            .split_once("    fn read_local_clients(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Turns same-machine client"))
            .map(|(body, _)| body)
            .expect("the reader should remain inspectable");
        assert!(read.contains("remote_connectivity()"));
        assert!(read.contains("controller.snapshot().await"));
        assert!(read.contains("LocalClientsSettingsState::Unavailable"));
    }

    #[test]
    fn settings_dialog_keeps_navigation_outside_the_page_scroll_viewport() {
        assert_eq!(SETTINGS_DIALOG_MAX_WIDTH, 1160.0);
        assert_eq!(SETTINGS_DIALOG_MAX_HEIGHT, 900.0);

        let source = include_str!("app.rs");
        let open_settings = source
            .split_once("    fn open_settings(")
            .and_then(|(_, tail)| tail.split_once("\n    fn strings("))
            .map(|(body, _)| body)
            .expect("settings dialog should remain inspectable");
        assert!(open_settings.contains(".h(px(dialog_height))"));
        assert!(open_settings.contains(".content(move |content, _, _|"));
        assert!(open_settings.contains(".min_h_0()"));
        assert!(open_settings.contains(".child(settings_for_content.clone())"));
        assert!(open_settings.contains(".rounded(px(SETTINGS_DIALOG_RADIUS))"));
        assert!(!open_settings.contains("\n                .child(settings.clone())"));

        let settings = source
            .split_once("impl Render for FoundationSettings")
            .and_then(|(_, tail)| tail.split_once("\nfn locale_choices("))
            .map(|(body, _)| body)
            .expect("settings layout should remain inspectable");
        let navigation = settings
            .find(".child(navigation)")
            .expect("settings navigation should render before the page viewport");
        let page_scroll = settings
            .find(".id(\"foundation-settings-page-scroll\")")
            .expect("settings page should own a dedicated scroll viewport");
        assert!(navigation < page_scroll);
        let page_viewport = &settings[page_scroll..];
        assert!(page_viewport.contains(".h_full()"));
        assert!(page_viewport.contains(".overflow_y_scroll()"));
        assert!(!page_viewport.contains(".on_scroll_wheel(|_, _, cx| cx.stop_propagation()"));
        assert!(!page_viewport.contains(".overflow_y_scrollbar()"));
        assert!(page_viewport.contains(".track_scroll(&self.settings_render_context.scroll)"));
        // GPUI only clips children to a square, so every settings surface that
        // reaches the dialog's outline has to round those corners itself.
        assert!(page_viewport.contains(".rounded_tr(px(SETTINGS_DIALOG_CONTENT_RADIUS))"));
        assert!(page_viewport.contains(".rounded_br(px(SETTINGS_DIALOG_CONTENT_RADIUS))"));
        assert!(page_viewport.contains(".rounded_bl(px(SETTINGS_DIALOG_CONTENT_RADIUS))"));
        let settings_root = &settings[..page_scroll];
        assert!(settings_root.contains(".id(\"foundation-settings\")"));
        assert!(settings_root.contains(".overflow_hidden()"));

        let navigation = source
            .split_once("    fn render_navigation(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_general_page("))
            .map(|(body, _)| body)
            .expect("settings navigation should remain inspectable");
        assert!(navigation.contains(".overflow_hidden()"));
        assert!(!navigation.contains(".overflow_y_scrollbar()"));
        assert!(navigation.contains(".rounded_tl(px(SETTINGS_DIALOG_CONTENT_RADIUS))"));
        assert!(navigation.contains(".rounded_bl(px(SETTINGS_DIALOG_CONTENT_RADIUS))"));

        let page = source
            .split_once("fn settings_page(")
            .and_then(|(_, tail)| tail.split_once("\nfn settings_row_anchor("))
            .map(|(body, _)| body)
            .expect("settings page surface should remain inspectable");
        assert!(!page.contains(".bg(background)"));
    }

    /// The browser page is where a new tab's page and the address bar's engine
    /// are chosen, and both have to reach the workbench rather than only the
    /// settings snapshot.
    #[test]
    fn the_browser_settings_page_wires_both_choices_to_the_workbench() {
        let source = include_str!("app.rs");
        let page = source
            .split_once("    fn render_browser_page(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_shortcuts_page("))
            .map(|(body, _)| body)
            .expect("the browser settings page should remain inspectable");
        assert!(page.contains("&self.browser_start_pages"));
        assert!(page.contains("&self.browser_search_engines"));
        assert!(page.contains("BrowserStartPage::Custom"));
        assert!(page.contains("BrowserSearchEngine::Custom"));
        assert!(
            page.contains("&self.browser_start_page_input")
                && page.contains("&self.browser_search_engine_input"),
            "a custom choice needs the field its address is typed into"
        );

        // The two selects only reach the workbench through the settings
        // subscriptions; a page that rendered them without those would show a
        // choice that changes nothing.
        let subscriptions = source
            .split_once("            cx.subscribe(\n                &browser_start_pages,")
            .and_then(|(_, tail)| tail.split_once("            Self {"))
            .map(|(body, _)| body)
            .expect("the browser selects should remain inspectable");
        assert!(subscriptions.contains("this.set_browser_start_page("));
        assert!(subscriptions.contains("this.set_browser_search_engine("));
        assert!(subscriptions.contains("this.set_browser_start_page_url("));
        assert!(subscriptions.contains("this.set_browser_search_engine_url("));

        // Both fields commit on blur and Enter, like the proxy fields: a
        // half-typed URL must not be stored.
        assert!(subscriptions.contains("InputEvent::Blur | InputEvent::PressEnter"));

        assert_eq!(
            settings_section_for_query("搜索引擎"),
            Some(SettingsSection::Browser)
        );
        let english = locale::strings(locale::ResolvedLocale::En);
        assert!(
            settings_search_candidates_for_query("start page", english)
                .iter()
                .any(|candidate| candidate.section == SettingsSection::Browser)
        );
    }

