    #[test]
    fn title_bar_keeps_windows_controls_outside_the_drag_region() {
        let source = include_str!("app.rs");
        let title_bar = source
            .split_once("    fn render_title_bar(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_agent_sidebar("))
            .map(|(body, _)| body)
            .expect("title bar should remain inspectable");
        let content = title_bar
            .find(".child(\n                h_flex()")
            .expect("title-bar content region should exist");
        let drag = title_bar
            .find(".window_control_area(WindowControlArea::Drag)")
            .expect("title-bar drag region should exist");
        let left_controls = title_bar
            .find("WindowControlSide::Left")
            .expect("the left caption cluster should exist");
        let right_controls = title_bar
            .find("WindowControlSide::Right")
            .expect("the right caption cluster should exist");

        // A caption button must never sit inside the drag region, or pressing it
        // would start a window move instead of the caption command.
        assert!(left_controls < content);
        assert!(content < drag);
        assert!(drag < right_controls);
    }

    #[test]
    fn columns_that_must_not_underlap_the_chrome_reserve_its_height() {
        let source = include_str!("app.rs");
        let sidebar = source
            .split_once("    fn render_inline_sidebar(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_floating_sidebar("))
            .map(|(body, _)| body)
            .expect("inline sidebar should remain inspectable");
        assert!(sidebar.contains(".pt(px(TITLE_BAR_HEIGHT))"));

        let shell = source
            .split_once("    fn render_shell(")
            .and_then(|(_, tail)| tail.split_once("\nfn localize_network_proxy_error("))
            .map(|(body, _)| body)
            .expect("shell should remain inspectable");
        // Workbench column, editor panel, and right-rail panel each start
        // below the bar; the floating panels anchor below it as well.
        assert!(shell.matches(".pt(px(TITLE_BAR_HEIGHT))").count() >= 3);
        assert!(shell.matches(".top(px(TITLE_BAR_HEIGHT))").count() >= 2);

        let activity_bar = source
            .split_once("    fn render_right_rail_activity_bar(")
            .and_then(|(_, tail)| tail.split_once("\n    fn open_management("))
            .map(|(body, _)| body)
            .expect("activity bar should remain inspectable");
        assert!(
            activity_bar
                .contains(".pt(px(TITLE_BAR_HEIGHT + RIGHT_ACTIVITY_BAR_VERTICAL_PADDING))")
        );
        // The rail's seam belongs to an open panel: the strip itself draws no
        // divider, so a collapsed rail leaves the workbench edge unbroken.
        assert!(activity_bar.contains(".when(panel_open, |this| {"));
        assert!(!activity_bar.contains("\n            .border_l_1()"));
    }

    #[test]
    fn a_server_decorated_window_draws_no_caption_buttons() {
        // Hyprland answers the xdg-decoration negotiation with SERVER_SIDE, so
        // the compositor owns the caption and Vibex must not paint a second one.
        let layout = resolve_window_controls(
            WindowControlPlatform::Linux,
            false,
            Some("appmenu:close"),
            WindowControls::default(),
        );

        assert_eq!(layout, WindowControlLayout::default());
    }

    #[test]
    fn a_client_decorated_window_follows_the_desktop_caption_layout() {
        let layout = resolve_window_controls(
            WindowControlPlatform::Linux,
            true,
            Some("close:minimize,maximize"),
            WindowControls::default(),
        );

        assert_eq!(layout.left, vec![WindowControl::Close]);
        assert_eq!(
            layout.right,
            vec![WindowControl::Minimize, WindowControl::Maximize]
        );
    }

    #[test]
    fn a_client_decorated_window_falls_back_to_the_default_trio() {
        for desktop_layout in [
            None,
            // GTK always publishes `left:right`; anything else is not a layout
            // Vibex can honor.
            Some("minimize,maximize,close"),
        ] {
            let layout = resolve_window_controls(
                WindowControlPlatform::Linux,
                true,
                desktop_layout,
                WindowControls::default(),
            );

            assert_eq!(layout, WindowControlLayout::right_trio());
        }
    }

    #[test]
