    /// A group row must be laid out in the same column as the sessions it
    /// holds, or its avatars drift away from the Agent logos beside them.
    #[test]
    fn session_group_rows_share_the_session_column() {
        let source = include_str!("app.rs");
        let project_children = source
            .split_once("    fn render_sidebar_project_children(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    #[allow(clippy::too_many_arguments)]\n    fn render_sidebar_workspace_children(")
            })
            .map(|(body, _)| body)
            .expect("sidebar project children should remain inspectable");
        // In the workspace hierarchy a group belongs inside its workspace card,
        // next to its sessions, exactly like a session row does.
        assert!(project_children.contains(
            "SidebarOrganizationItem::Group(group_id)\n                    if parent_folder_id.is_some() || include_root_sessions =>"
        ));
        assert!(project_children.contains("| SidebarOrganizationItem::Group(_) => {}"));

        let group_row = source
            .split_once("    fn render_sidebar_group(")
            .and_then(|(_, tail)| tail.split_once("\n    fn build_sidebar_group_menu("))
            .map(|(body, _)| body)
            .expect("sidebar group renderer should remain inspectable");
        // The row starts on the session row's content column and the chevron is
        // its first laid-out child, so the chevron lands on the column a session
        // row puts its Agent logo in. The avatars follow it.
        assert!(group_row.contains(".pl(px(SIDEBAR_WORKSPACE_SESSION_CARD_OVERHANG))"));
        assert!(!group_row.contains(".left(px(SIDEBAR_ROW_ICON_SLOT_OVERHANG))"));
        let chevron = group_row
            .find("sidebar_icon(if collapsed {")
            .expect("the group row should start with its disclosure chevron");
        let avatars = group_row
            .find(".child(div().flex_none().child(avatars))")
            .expect("the avatar stack should follow the chevron");
        assert!(chevron < avatars);
        assert!(!group_row.contains(".px_2()\n                    .child(\n                        div().flex_none().size(px(14.0))"));
    }

    /// The sidebar footer is not an ownership pager.
    ///
    /// The root page describes sessions the sidebar already lists, and the
    /// background pass advances it one page at a time, so the root column has
    /// nothing to page: a full-width "Load more sessions" button under the
    /// project list read as a paged session list and did nothing visible when
    /// clicked. Branch pages keep their row, drawn inside the branch.
    #[test]
    fn sidebar_root_column_carries_no_delegated_pager() {
        let source = include_str!("app.rs");
        let sidebar = source
            .split_once("    fn render_agent_sidebar(")
            .and_then(|(_, tail)| tail.split_once("\n    fn build_sidebar_toolbar_more_menu("))
            .map(|(body, _)| body)
            .expect("sidebar renderer should remain inspectable");
        assert!(!sidebar.contains("render_delegated_page_action"));
        assert!(sidebar.contains("let group_elements = self.render_sidebar_root_children("));

        let refresh = source
            .split_once("    fn refresh_delegated_sessions(")
            .and_then(|(_, tail)| tail.split_once("\n    fn delegated_branch_hidden("))
            .map(|(body, _)| body)
            .expect("delegated refresh should remain inspectable");
        assert!(refresh.contains(
            "self.load_delegated_page(None, root_page_has_more, DelegatedPageLoad::Background, cx);"
        ));
    }

    /// Another client's creation does not wait out the ownership poll.
    ///
    /// A session the workbench cannot place marks the root page stale, and the
    /// pass that reloads it is asleep on its interval. Without a wake, a row the
    /// TUI just created appeared one poll later — the sidebars of two windows on
    /// one runtime are supposed to agree when the row exists, not eventually.
    /// The flag alone is only as prompt as the timer, so the announcement and the
    /// wake have to stay wired together.
    #[test]
    fn an_unplaceable_session_wakes_the_ownership_pass() {
        let source = include_str!("app.rs");
        let refresh = source
            .split_once("    fn refresh_delegated_sessions(")
            .and_then(|(_, tail)| tail.split_once("\n    fn delegated_branch_hidden("))
            .map(|(body, _)| body)
            .expect("delegated refresh should remain inspectable");
        assert!(
            refresh.contains("timer(DELEGATED_REFRESH_INTERVAL)"),
            "the interval stays the passive cadence of the pass"
        );
        assert!(
            refresh.contains("_ = wake.notified() => {}"),
            "the pass has to be woken out of its interval"
        );

        let snapshot = source
            .split_once("            DesktopEvent::SessionUpdated(session) => {")
            .and_then(|(_, tail)| {
                tail.split_once("            DesktopEvent::SessionsRemoved(session_ids) => {")
            })
            .map(|(body, _)| body)
            .expect("the session snapshot arm should remain inspectable");
        assert!(
            snapshot.contains("self.delegated_roots_dirty = true;"),
            "the pass only reloads the root page it is told is stale"
        );
        assert!(
            snapshot.contains("self.delegated_refresh_wake.notify_one();"),
            "an unplaceable session has to wake the pass that can place it"
        );
    }

    /// A timed ownership pass that has nothing new to say costs nothing.
    ///
    /// The pass runs on an interval, and it used to invalidate the sidebar
    /// projection and repaint on every tick whether or not its page described
    /// anything new. At the poll's cadence that rebuilt every painted row — the
    /// conversation included — a few seconds apart, which is what made the
    /// sidebar and the timeline appear to flicker while the reader did nothing.
    #[test]
    fn an_idle_ownership_pass_does_not_rebuild_the_sidebar() {
        let source = include_str!("app.rs");
        let page = source
            .split_once("    fn apply_delegated_page(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Whether a session is known to own delegated children.")
            })
            .map(|(body, _)| body)
            .expect("the delegated page applier should remain inspectable");

        assert!(
            page.contains("let mut sidebar_changed = false;"),
            "the pass has to track what it actually changed"
        );
        assert!(
            page.contains("if sidebar_changed {\n            self.invalidate_sidebar_projection_cache();\n        }"),
            "an unchanged page must not invalidate the projection"
        );
        assert!(
            !page.contains(
                "        }\n        self.invalidate_sidebar_projection_cache();\n        if self\n            .delegated_reveal_target"
            ),
            "the invalidation has to stay behind the change flag"
        );
        // A row the tree describes differently is a change; the same row twice
        // is not.
        assert!(
            page.contains(".is_none_or(|existing| *existing != node)"),
            "a node only counts as a change when it differs from the one on hand"
        );
    }

    /// The child Agent rail owns its element tree.
    ///
    /// The rail paints whole child timelines with the timeline's own builders,
    /// so it mounts their animations: the running label's shimmer, the thinking
    /// indicator, disclosure springs. Built inline in the workbench's render,
    /// every one of those pumps resolved to the workbench — whose notify
    /// refreshes the sidebar, the primary timeline and every pane — so a child
    /// Agent behind an open rail repainted the whole window, main timeline
    /// included, on every display refresh.
    #[test]
    fn the_child_agent_rail_is_its_own_render_boundary() {
        let source = include_str!("app.rs");
        let view = source
            .split_once("struct ChildAgentRailView {")
            .and_then(|(_, tail)| {
                tail.split_once("\n/// Where a session tab would land inside a group workspace.")
            })
            .map(|(body, _)| body)
            .expect("the child Agent rail's view should remain inspectable");
        assert!(
            view.contains("cx.observe(workbench, |_, _, cx| cx.notify()).detach();"),
            "the rail renders workbench state, so it has to observe the workbench"
        );
        assert!(view.contains("this.render_child_agent_timeline_panel(window, cx)"));

        let panel = source
            .split_once(
                "    fn render_right_rail_panel(&mut self, cx: &mut Context<Self>) -> AnyElement {",
            )
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// The activity bar buttons in the reader's order.")
            })
            .map(|(body, _)| body)
            .expect("the right rail panel should remain inspectable");
        assert!(panel.contains("self.ensure_child_agent_rail_view(cx)"));
        assert!(panel.contains(".cached(StyleRefinement::default().size_full())"));
        // The rail may not be built inside the workbench's own render pass.
        assert!(!panel.contains("self.render_child_agent_timeline_panel(window, cx)"));
        let ensure = source
            .split_once("    fn ensure_child_agent_rail_view(")
            .and_then(|(_, tail)| tail.split_once("\n    fn ensure_timeline_view("))
            .map(|(body, _)| body)
            .expect("the rail's view boundary should remain inspectable");
        assert!(ensure.contains("self.child_agent_rail_view = Some(view.clone());"));
    }

    /// A borrowed view keeps its own Markdown surfaces, and evicts the coldest.
    ///
    /// The child Agent rail paints another session's timeline through the same
    /// builders, so its surfaces used to share — and evict from — the parent's
    /// table. A surface dropped while it is on screen is rebuilt the next frame,
    /// and rebuilding a text view repaints it from scratch, so the row blinked
    /// for as long as the rail was open.
    #[test]
    fn markdown_surface_owners_and_eviction_are_recency_ordered() {
        let source = include_str!("app.rs");
        let state = source
            .split_once("    fn markdown_text_state(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// The session whose timeline owns the Markdown surfaces")
            })
            .map(|(body, _)| body)
            .expect("the Markdown surface store should remain inspectable");
        assert!(state.contains("let owner = self.markdown_surface_owner();"));
        assert!(state.contains("markdown_surface_entry(self, &owner, id)"));
        assert!(state.contains("self.markdown_surface_table(&owner)"));
        assert!(state.contains(".min_by_key(|(_, entry)| entry.last_painted)"));
        // Key order is not a recency order: it dropped whatever sorted first.
        assert!(!state.contains("find(|candidate| candidate.as_str() != id)"));

        let owner = source
            .split_once("    fn markdown_surface_owner(&self) -> MarkdownSurfaceOwner {")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// The table a session's Markdown surfaces")
            })
            .map(|(body, _)| body)
            .expect("the surface owner should remain inspectable");
        assert!(
            owner.contains("MarkdownSurfaceOwner::ChildAgent(session_id.as_str().to_string())")
        );
        assert!(owner.contains("MarkdownSurfaceOwner::BorrowedView"));
    }

    /// Every pane's timeline is its own virtual list.
    ///
    /// The list caches its measured row layout under its element id, so a
    /// constant id made the panes share one cache: a pane drew the other pane's
    /// row heights (a shrunken timeline with a blank band) and picked up its
    /// scroll offset when focus moved.
    #[test]
    fn every_pane_timeline_is_its_own_virtual_list() {
        let source = include_str!("app.rs");
        let workbench = source
            .split_once("    fn render_agent_workbench_for(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_composer_runtime_choice("))
            .map(|(body, _)| body)
            .expect("agent workbench should remain inspectable");
        let list_id = workbench
            .find("let timeline_list_id = SharedString::from(format!(")
            .expect("the timeline list id should be built per session");
        let list = workbench
            .find("timeline_list_id.clone(),")
            .expect("the virtual list should use the per-session id");
        assert!(list_id < list);
        assert!(workbench.contains("\"agent-timeline-turns-{}"));
        assert!(workbench.contains("VibexSessionId::as_str"));
        // The old constant id must be gone from the call.
        assert!(!workbench.contains("\"agent-timeline-turns\","));
    }

    /// A drag that never leaves the pane it started in splits that pane, and a
    /// pane that does not hold the keyboard can still start the drag.
    #[test]
    fn dragging_a_tab_within_its_own_pane_splits_it() {
        let source = include_str!("app.rs");

        let track = source
            .split_once("    fn track_session_group_pane_drop(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Drops a sidebar session on a pane"))
            .map(|(body, _)| body)
            .expect("pane drop tracking should remain inspectable");
        assert!(track.contains("dragged_session_id: Option<&str>"));
        assert!(track.contains("self.session_group_session_pane(session_id).as_deref()"));
        // The region and the ownership check live in one helper, which the
        // tracker must delegate to; resolving a region for a pane the pointer is
        // not inside is the bug this file's region test pins down.
        assert!(track.contains("session_group_pane_drop_region(bounds, position, same_pane)"));

        // The tab drag hands its session to the tracker, so the tracker can tell
        // a same-pane drag from a cross-pane one.
        assert!(source.contains("let session_id = event.drag(cx).session_id.clone();"));
        assert!(source.contains("this.track_session_group_pane_drop(\n                        &pane_id,\n                        Some(session_id.as_str()),"));

        // A tab in a pane that does not hold the keyboard must still be able to
        // start a drag: the capture handler focuses the pane without consuming
        // the press.
        let pane = source
            .split_once("    fn render_session_group_pane(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_session_group_pane_content("))
            .map(|(body, _)| body)
            .expect("group pane renderer should remain inspectable");
        let focus_on_down = pane
            .find("this.focus_session_group_pane(&group_id, &pane_id, cx);")
            .expect("a non-focused pane should focus on mouse down");
        let after = &pane[focus_on_down..];
        let handler_end = after.find("}))").expect("the capture handler should close");
        assert!(!after[..handler_end].contains("cx.stop_propagation()"));
    }

    /// A pane answers for a drag move only when the pointer is inside it.
    ///
    /// GPUI calls every pane's drag-move listener on every move in the window,
    /// so each pane resolves the same pointer against its own bounds and writes
    /// one shared drop target. When a pane the pointer was never in could claim
    /// that target, the pane painted last won every move: a tab dragged inside
    /// its own pane landed on the no-op "merge into this pane" region — so
    /// nothing happened — while a drag onto the pane that happened to paint last
    /// still split. Both halves of that report come from this resolution.
    #[test]
    fn only_the_pane_under_the_pointer_resolves_a_drop_region() {
        // A 400x600 pane at (400, 100): the left half is x < 600, the tab strip
        // is y < 268, and the bottom band starts at y = 532.
        let pane = Bounds {
            origin: gpui::Point {
                x: px(400.0),
                y: px(100.0),
            },
            size: Size {
                width: px(400.0),
                height: px(600.0),
            },
        };
        let at = |x: f32, y: f32| point(px(x), px(y));

        // A pane the pointer is not inside resolves nothing, whichever region of
        // its own box the pointer would have landed in. This is what kept a drag
        // onto the pane under the cursor from being answered by another pane.
        assert_eq!(
            session_group_pane_drop_region(pane, at(900.0, 400.0), true),
            None
        );
        assert_eq!(
            session_group_pane_drop_region(pane, at(900.0, 400.0), false),
            None
        );
        assert_eq!(
            session_group_pane_drop_region(pane, at(500.0, 40.0), true),
            None
        );
        assert_eq!(
            session_group_pane_drop_region(pane, at(399.0, 400.0), false),
            None
        );

        // Inside the pane the edges keep their meaning: the bottom band wins over
        // the right half, the right half splits sideways, and the tab strip is
        // still a merge rather than a split, even for the pane's own tab.
        assert_eq!(
            session_group_pane_drop_region(pane, at(700.0, 600.0), true),
            Some(SessionGroupPaneDropRegion::Bottom)
        );
        assert_eq!(
            session_group_pane_drop_region(pane, at(700.0, 400.0), true),
            Some(SessionGroupPaneDropRegion::Right)
        );
        assert_eq!(
            session_group_pane_drop_region(pane, at(500.0, 150.0), true),
            Some(SessionGroupPaneDropRegion::TabGroup)
        );

        // The middle of the pane a tab already lives in is a request to split,
        // along whichever axis the pointer left the center on.
        assert_eq!(
            session_group_pane_drop_region(pane, at(500.0, 400.0), true),
            Some(SessionGroupPaneDropRegion::Right)
        );
        assert_eq!(
            session_group_pane_drop_region(pane, at(580.0, 330.0), true),
            Some(SessionGroupPaneDropRegion::Bottom)
        );
        // The same middle of a pane the tab does not live in just merges it.
        assert_eq!(
            session_group_pane_drop_region(pane, at(500.0, 400.0), false),
            Some(SessionGroupPaneDropRegion::Content)
        );
    }

