    /// A child session's row is not a drag source.
    ///
    /// Its place in the sidebar is its parent's branch, so there is nothing for
    /// a drag to say about it. A row with no drag source of its own used to let
    /// the press fall through to the project container behind it, which dragged
    /// the whole project; the row claims the press instead, and the drag never
    /// carries a child session even when a shift range puts one in the
    /// selection.
    #[test]
    fn child_session_rows_are_not_drag_sources() {
        let source = include_str!("app.rs");

        let child_row = source
            .split_once("    fn render_delegated_session_row(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// The ownership tree in the order the sidebar draws it.")
            })
            .map(|(body, _)| body)
            .expect("the child session row should remain inspectable");
        assert!(
            child_row
                .contains(".on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())")
        );
        assert!(!child_row.contains(".on_drag("));
        assert!(!child_row.contains("SidebarSessionDrag"));

        // The branch's page row is part of the same band.
        let page_action = source
            .split_once("    fn render_delegated_page_action(")
            .and_then(|(_, tail)| tail.split_once("\n    fn delegated_child_visible_in_branch("))
            .map(|(body, _)| body)
            .expect("the page action should remain inspectable");
        assert!(
            page_action
                .contains(".on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())")
        );

        let helper = source
            .split_once("    fn sidebar_session_is_delegated_child(")
            .and_then(|(_, tail)| tail.split_once("\n    /// The member rows of one group."))
            .map(|(body, _)| body)
            .expect("the child row rule should remain inspectable");
        assert!(helper.contains(".is_some_and(|node| node.parent_session_ref.is_some())"));

        let drag_ids = source
            .split_once("    fn sidebar_group_drag_session_ids(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Reorders the members of one group,"))
            .map(|(body, _)| body)
            .expect("the group drag payload should remain inspectable");
        assert!(drag_ids.contains(".filter(|id| !self.sidebar_session_is_delegated_child(id))"));

        let resolver = source
            .split_once("    fn dragged_group_session_ids(")
            .and_then(|(_, tail)| {
                tail.split_once(
                    "\n    /// Takes dragged sessions out of whatever group holds them.",
                )
            })
            .map(|(body, _)| body)
            .expect("group drop resolution should remain inspectable");
        assert!(resolver.contains("&& !self.sidebar_session_is_delegated_child(session_id)"));
    }

    /// A delegated row is a session row, so it paints a session's status.
    ///
    /// The child has no column of its own: it hands the shared builder the same
    /// description a navigation row hands it — the session's resolved state,
    /// its last message, the queued send it may be waiting for — read from the
    /// live snapshot the runtime streams for the child. Nothing the ownership
    /// node carries stands in for the session: its task phase moves when the
    /// delegation record does, not when the session does. Unread is the one mark
    /// a child leaves to the row above it.
    #[test]
    fn delegated_rows_paint_the_session_status_column_they_share_with_every_row() {
        let source = include_str!("app.rs");

        let child_row = source
            .split_once("    fn render_delegated_session_row(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// The ownership tree in the order the sidebar draws it.")
            })
            .map(|(body, _)| body)
            .expect("the child session row should remain inspectable");
        assert!(child_row.contains("self.registered_session(&session_id)"));
        assert!(child_row.contains("self.sidebar_session_row_state(session)"));
        assert!(child_row.contains("self.render_sidebar_status_column("));
        assert!(child_row.contains("prefix: \"sidebar-delegated\","));
        assert!(child_row.contains("auto_continue_enabled: self.auto_continue_enabled_for"));
        assert!(child_row.contains("last_message_at_ms: session.last_message_at_ms"));
        assert!(child_row.contains("scheduled_at_ms: self.scheduled_message_at_for_row("));
        assert!(child_row.contains("has_unread_completion: false"));
        assert!(child_row.contains(".when_some(status_column, |row, column| row.child(column))"));
        // The row paints no part of the column itself: a mark, a label or a dot
        // built here would be the second scheme this row must not have.
        assert!(!child_row.contains("session_status_mark_for("));
        assert!(!child_row.contains("sidebar_attention_icon("));
        assert!(!child_row.contains("sidebar_status_dot("));
        assert!(!child_row.contains("sidebar_session_state_label("));
        assert!(!child_row.contains("SIDEBAR_STATUS_COLUMN_WIDTH"));
        assert!(!child_row.contains("delegation_node_status("));
        // Nothing in the tree describes a session's status twice: the row hands
        // the shared builder the same description every other row hands it.
        assert!(!child_row.contains("let status_mark"));
        assert!(!child_row.contains("let time_label"));
    }

    /// A session group is a row the user can file like any other.
    ///
    /// The group row is a drag source of its own, but a drag source without a
    /// target resolves to nothing: every surface a session or a folder can be
    /// dropped on has to accept a group too, or the gesture silently ends.
    #[test]
    fn a_group_drag_is_accepted_by_the_surfaces_that_hold_it() {
        let source = include_str!("app.rs");

        let folder = source
            .split_once("    fn render_sidebar_folder(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    fn render_sidebar_project_appearance_popover(")
            })
            .map(|(body, _)| body)
            .expect("folder renderer should remain inspectable");
        assert!(folder.contains("DragMoveEvent<SidebarGroupDrag>"));
        assert!(folder.contains("SidebarOrganizationItem::Group(drag.group_id.clone())"));
        assert!(folder.contains(".on_drop(cx.listener(|this, drag: &SidebarGroupDrag"));

        // The group row orders itself against other groups, the session row
        // places it among the sessions of a band, and the project row is the
        // project's own root.
        let group_row = source
            .split_once("    fn render_sidebar_group(")
            .and_then(|(_, tail)| tail.split_once("\n    fn build_sidebar_group_menu("))
            .map(|(body, _)| body)
            .expect("sidebar group renderer should remain inspectable");
        assert!(group_row.contains("DragMoveEvent<SidebarGroupDrag>"));

        let project = source
            .split_once("    fn render_sidebar_project(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_sidebar_workspace("))
            .map(|(body, _)| body)
            .expect("project renderer should remain inspectable");
        assert!(project.contains("DragMoveEvent<SidebarGroupDrag>"));
        assert!(
            project.contains("SidebarOrganizationScope::Project(project_root_target_project_id")
        );

        let sidebar = source
            .split_once("    fn render_agent_sidebar(")
            .and_then(|(_, tail)| tail.split_once("\n    fn build_sidebar_toolbar_more_menu("))
            .map(|(body, _)| body)
            .expect("sidebar renderer should remain inspectable");
        assert!(sidebar.contains(".on_drop(cx.listener(|this, drag: &SidebarGroupDrag"));
    }

    /// A group paints its member rows from its own order, so a drag that starts
    /// on one of them reorders the group — it must not fall through to the
    /// project row the group sits inside.
    #[test]
    fn dragging_a_group_member_reorders_the_group_it_is_painted_in() {
        let source = include_str!("app.rs");

        let navigation = source
            .split_once("    fn render_group_navigation(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// The slot a session row keeps for its branch toggle")
            })
            .map(|(body, _)| body)
            .expect("group navigation should remain inspectable");
        // The rows are draggable and know the group they belong to.
        assert!(navigation.contains("reorder_enabled: bool"));
        assert!(navigation.contains("reorder_enabled,"));
        assert!(navigation.contains("Some(group_id),"));

        let drag = source
            .split_once("struct SidebarSessionDrag {")
            .and_then(|(_, tail)| tail.split_once("\nimpl Render for SidebarSessionDrag"))
            .map(|(body, _)| body)
            .expect("session drag payload should remain inspectable");
        assert!(drag.contains("group_id: Option<String>"));

        let drag_start = source
            .split_once("    fn start_sidebar_session_drag(")
            .and_then(|(_, tail)| tail.split_once("\n    fn preview_sidebar_session_reorder("))
            .map(|(body, _)| body)
            .expect("session drag setup should remain inspectable");
        // The band it previews is the group's own member list.
        assert!(drag_start.contains("let group_band = drag.group_id.as_deref()"));
        assert!(drag_start.contains("group.member_session_ids.clone()"));
        assert!(drag_start.contains("group_id: drag.group_id.clone(),"));

        let finish = source
            .split_once("    fn finish_sidebar_session_drag(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Applies the group half"))
            .map(|(body, _)| body)
            .expect("session drag finish should remain inspectable");
        // A drop inside the group it came from is an order change; a drop
        // anywhere else is the leave path the group half already owns.
        assert!(finish.contains("if state.group_id.is_some() && keep_group == state.group_id {"));
        assert!(finish.contains(
            "self.reorder_group_members(group_id, &state.session_ids, &target_id, after, cx);"
        ));

        let reorder = source
            .split_once("    fn reorder_group_members(")
            .and_then(|(_, tail)| tail.split_once("\n    fn start_sidebar_folder_drag("))
            .map(|(body, _)| body)
            .expect("group reorder should remain inspectable");
        assert!(reorder.contains(".reorder_group_members(group_id, moving_ids, target_id, after)"));
        assert!(reorder.contains("self.sync_user_session_group(group_id);"));
    }

    /// The rows the sidebar paints as selected are the rows a move acts on: the
    /// current session's row wears the same wash as a move-selected row, so a
    /// drag from any highlighted row has to carry all of them.
    #[test]
    fn the_rows_that_look_selected_are_the_rows_a_move_carries() {
        let source = include_str!("app.rs");
        let helper = source
            .split_once("    fn sidebar_row_is_move_selected(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// The rows a move acts on, in a stable order.")
            })
            .map(|(body, _)| body)
            .expect("the row/selection rule should remain inspectable");
        assert!(helper.contains("if self.sidebar_move_selected_items.contains(item) {"));
        assert!(helper.contains("self.sidebar_move_selection_is_active()"));
        assert!(helper.contains(".selected_session_id"));

        let effective = source
            .split_once("    fn sidebar_move_selection_items(")
            .and_then(|(_, tail)| {
                tail.split_once(
                    "\n    /// The items a drag carries: the whole selection, in sidebar order.",
                )
            })
            .map(|(body, _)| body)
            .expect("the effective selection should remain inspectable");
        assert!(effective.contains(".sidebar_move_selected_items"));
        assert!(effective.contains("items.push(item);"));

        let drag_items = source
            .split_once("    fn sidebar_drag_items(")
            .and_then(|(_, tail)| tail.split_once("\n    fn update_sidebar_move_selection("))
            .map(|(body, _)| body)
            .expect("drag payload builder should remain inspectable");
        assert!(drag_items.contains("if !self.sidebar_row_is_move_selected(primary) {"));
        assert!(drag_items.contains("let selected = self.sidebar_move_selection_items();"));
        assert!(!drag_items.contains("for selected in &self.sidebar_move_selected_items {"));

        let drag_start = source
            .split_once("    fn start_sidebar_session_drag(")
            .and_then(|(_, tail)| tail.split_once("\n    fn finish_sidebar_session_drag("))
            .map(|(body, _)| body)
            .expect("session drag setup should remain inspectable");
        assert!(drag_start.contains("&& self.sidebar_row_is_move_selected(&primary)"));
        assert!(drag_start.contains("self.sidebar_move_selected_items.insert(primary.clone());"));
        // A drag that starts on a row outside the selection carries that row
        // alone, so it must not write a selection of its own: the pointer only
        // has to slip past the drag threshold for the click the user meant to
        // become a drag, and the row it started on would then wear a second
        // selected wash next to the session that is still open.
        assert!(!drag_start.contains("update_sidebar_move_selection("));

        let session_row = source
            .split_once("    fn render_sidebar_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_choice_popover("))
            .map(|(body, _)| body)
            .expect("session row renderer should remain inspectable");
        assert!(
            session_row
                .contains("let move_selected = self.sidebar_row_is_move_selected(&session_item);")
        );

        let group_drop = source
            .split_once("    fn dragged_group_session_ids(")
            .and_then(|(_, tail)| {
                tail.split_once(
                    "\n    /// Takes dragged sessions out of whatever group holds them.",
                )
            })
            .map(|(body, _)| body)
            .expect("group drop resolution should remain inspectable");
        assert!(group_drop.contains("for selected in self.sidebar_move_selection_items() {"));
        // Only a drag that started on a painted row may widen to the selection:
        // a drag on any other row carries that row alone.
        assert!(group_drop.contains("if !self.sidebar_row_is_move_selected(&primary_item) {"));
        assert!(group_drop.contains("return payload_ids.to_vec();"));
    }

    /// A pointer that slips past the drag threshold while the user is clicking
    /// used to leave a one-row selection behind that no longer matched the open
    /// session, so two rows wore the same selected wash. The slip is the click
    /// it replaced now, and it never writes a selection of its own.
    #[test]
    fn a_slipped_press_finishes_as_the_click_it_replaced() {
        let source = include_str!("app.rs");
        let drag_start = source
            .split_once("    fn start_sidebar_session_drag(")
            .and_then(|(_, tail)| tail.split_once("\n    fn finish_sidebar_session_drag("))
            .map(|(body, _)| body)
            .expect("session drag setup should remain inspectable");
        assert!(!drag_start.contains("update_sidebar_move_selection("));

        let finish = source
            .split_once("    fn finish_sidebar_session_drag(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Applies the group half"))
            .map(|(body, _)| body)
            .expect("session drag finish should remain inspectable");
        assert!(finish.contains("let incidental_click = state.session_ids.len() == 1"));
        assert!(finish.contains("&& landed_on == Some(state.session_id.as_str())"));
        assert!(finish.contains("&& state.preview_ids == state.original_ids"));
        assert!(finish.contains("&& self.sidebar_organization_drop_target.is_none()"));
        assert!(finish.contains("&& self.sidebar_organization_root_drop_target.is_none()"));
        assert!(finish.contains("self.select_session(state.session_id.clone(), cx);"));
        // The click is finished before the drop, so a slip never reaches the
        // reorder or the group half of a drop.
        let click = finish
            .find("self.select_session(state.session_id.clone(), cx);")
            .expect("the slip branch should finish the click");
        let moving = finish
            .find("let moving = state")
            .expect("the drop should still resolve the rows it moves");
        assert!(click < moving);
    }

    /// A drop changes the group for every session the user selected, not just
    /// the one the payload the row happened to carry.
    #[test]
    fn a_group_drop_covers_the_whole_selection() {
        let source = include_str!("app.rs");
        let resolver = source
            .split_once("    fn dragged_group_session_ids(")
            .and_then(|(_, tail)| {
                tail.split_once(
                    "\n    /// Takes dragged sessions out of whatever group holds them.",
                )
            })
            .map(|(body, _)| body)
            .expect("group drop resolution should remain inspectable");
        assert!(resolver.contains("for selected in self.sidebar_move_selection_items() {"));
        assert!(resolver.contains("let project_scopes = self.sidebar_row_scopes(&groups);"));
        assert!(resolver.contains("self.sidebar_move_selection_scope_matches("));
        assert!(resolver.contains("&primary_item,"));
        assert!(resolver.contains("&selected,"));

        let finish = source
            .split_once("    fn finish_sidebar_session_drag(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Applies the group half"))
            .map(|(body, _)| body)
            .expect("session drag finish should remain inspectable");
        assert!(
            finish.contains("let group_ids = self.dragged_group_session_ids(&state.session_ids);")
        );
        assert!(finish.contains("self.apply_sidebar_session_group_drop(&group_ids,"));
        assert!(!finish.contains("apply_sidebar_session_group_drop(&state.session_ids"));

        let into_group = source
            .split_once("    fn finish_sidebar_session_drag_into_group(")
            .and_then(|(_, tail)| {
                tail.split_once(
                    "\n    /// Adds one session to a group from the session's own menu.",
                )
            })
            .map(|(body, _)| body)
            .expect("group row drop should remain inspectable");
        assert!(
            into_group.contains("let session_ids = self.dragged_group_session_ids(session_ids);")
        );
        assert!(
            into_group.contains("self.add_sessions_to_group_from_menu(group_id, &session_ids, cx)")
        );
    }

