    #[test]
    fn authoritative_timeline_pagination_requires_a_complete_advancing_prefix() {
        let session_id = VibexSessionId::parse("session_timeline").unwrap();
        let mut page = TimelinePage {
            session_id: session_id.clone(),
            items: Vec::new(),
            start_sequence: Some(1),
            end_sequence: Some(500),
            has_older: false,
            has_newer: true,
            starts_at_turn_start: true,
            leading_turn_start: None,
            omitted: None,
        };

        assert_eq!(
            next_authoritative_timeline_cursor(&session_id, 0, &page).unwrap(),
            Some(500)
        );
        page.has_newer = false;
        assert_eq!(
            next_authoritative_timeline_cursor(&session_id, 500, &page).unwrap(),
            None
        );

        page.has_newer = true;
        let error = next_authoritative_timeline_cursor(&session_id, 500, &page).unwrap_err();
        assert_eq!(error, TimelineRestoreError::PaginationStalled);

        page.has_newer = false;
        page.has_older = true;
        page.start_sequence = Some(2);
        let error = next_authoritative_timeline_cursor(&session_id, 0, &page).unwrap_err();
        assert_eq!(error, TimelineRestoreError::PrefixIncomplete);

        page.session_id = VibexSessionId::parse("session_other").unwrap();
        let error = next_authoritative_timeline_cursor(&session_id, 0, &page).unwrap_err();
        assert_eq!(error, TimelineRestoreError::PageSessionMismatch);
    }

