    #[test]
    fn agent_file_diff_preview_keeps_context_and_bounds_large_changes() {
        let preview = agent_file_diff_preview(Some("same\nold\ntail"), Some("same\nnew\ntail"));
        assert_eq!(preview.removed_lines, 1);
        assert_eq!(preview.added_lines, 1);
        assert_eq!(
            preview
                .lines
                .iter()
                .map(|line| (line.kind, line.text.as_str()))
                .collect::<Vec<_>>(),
            [
                (AgentFileDiffLineKind::Context, "same"),
                (AgentFileDiffLineKind::Delete, "old"),
                (AgentFileDiffLineKind::Add, "new"),
                (AgentFileDiffLineKind::Context, "tail"),
            ]
        );

        let old = (0..400)
            .map(|index| format!("old-{index}"))
            .collect::<Vec<_>>()
            .join("\n");
        let new = (0..400)
            .map(|index| format!("new-{index}"))
            .collect::<Vec<_>>()
            .join("\n");
        let bounded = agent_file_diff_preview(Some(&old), Some(&new));
        assert_eq!(bounded.omitted_lines, 640);
        assert_eq!(
            bounded
                .lines
                .iter()
                .filter(|line| line.kind == AgentFileDiffLineKind::Omitted)
                .count(),
            1
        );
        assert_eq!(bounded.lines.len(), AGENT_FILE_DIFF_MAX_PREVIEW_LINES + 1);
    }

    #[test]
    fn agent_file_diff_preview_counts_distant_edits_independently() {
        let old_lines = (0..220)
            .map(|index| format!("line-{index}"))
            .collect::<Vec<_>>();
        let mut new_lines = old_lines.clone();
        new_lines[12] = "edited-near-start".into();
        new_lines[207] = "edited-near-end".into();

        let preview =
            agent_file_diff_preview(Some(&old_lines.join("\n")), Some(&new_lines.join("\n")));

        assert_eq!(preview.removed_lines, 2);
        assert_eq!(preview.added_lines, 2);
        assert_eq!(
            preview
                .lines
                .iter()
                .filter(|line| line.kind == AgentFileDiffLineKind::Delete)
                .count(),
            2
        );
        assert_eq!(
            preview
                .lines
                .iter()
                .filter(|line| line.kind == AgentFileDiffLineKind::Add)
                .count(),
            2
        );
        assert!(preview.lines.iter().any(|line| {
            line.kind == AgentFileDiffLineKind::Omitted
                && line.text.contains("unchanged lines omitted")
        }));
    }

    #[test]
    fn agent_file_diff_preview_renders_patch_only_timeline_records() {
        let old_text = (0..220)
            .map(|index| format!("line-{index}"))
            .collect::<Vec<_>>()
            .join("\n");
        let new_text = old_text.replace("line-110", "line-110-edited");
        let mut operation = FileOperationPayload {
            operation: FileOperationKind::Edit,
            path: "src/lib.rs".into(),
            summary: "Edit".into(),
            old_text: Some(old_text),
            new_text: Some(new_text),
            patch: None,
            raw_extension: None,
        };
        operation.patch = operation.generated_patch();
        operation.old_text = None;
        operation.new_text = None;

        assert!(file_operation_has_diff(&operation));
        let preview = agent_file_operation_diff_preview(&operation);
        assert_eq!(preview.removed_lines, 1);
        assert_eq!(preview.added_lines, 1);
        assert!(
            preview.lines.iter().any(|line| {
                line.kind == AgentFileDiffLineKind::Delete && line.text == "line-110"
            })
        );
        assert!(preview.lines.iter().any(|line| {
            line.kind == AgentFileDiffLineKind::Add && line.text == "line-110-edited"
        }));
    }

    #[gpui::test]
    fn agent_file_diff_preview_scrolls_without_moving_parent(cx: &mut TestAppContext) {
        cx.update(gpui_component::init);
        let scroll = gpui::ScrollHandle::new();
        let observed_scroll = scroll.clone();
        let parent_scroll = gpui::ScrollHandle::new();
        let observed_parent_scroll = parent_scroll.clone();
        let (_, cx) = cx.add_window_view(|_, _| AgentFileDiffScrollProbe {
            scroll,
            parent_scroll,
        });

        cx.run_until_parked();
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        assert!(observed_parent_scroll.max_offset().y > px(0.0));
        let initial_y = cx
            .debug_bounds("agent-file-diff-last-row")
            .expect("last diff row should be laid out")
            .origin
            .y;

        cx.simulate_event(ScrollWheelEvent {
            position: point(px(20.0), px(20.0)),
            delta: ScrollDelta::Pixels(point(px(0.0), px(-120.0))),
            modifiers: Default::default(),
            touch_phase: gpui::TouchPhase::Moved,
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });

        let scrolled_y = cx
            .debug_bounds("agent-file-diff-last-row")
            .expect("last diff row should remain laid out")
            .origin
            .y;
        assert!(
            scrolled_y < initial_y,
            "initial: {initial_y:?}, scrolled: {scrolled_y:?}"
        );
        assert!(observed_scroll.offset().y < px(0.0));
        assert_eq!(observed_parent_scroll.offset().y, px(0.0));

        cx.simulate_event(ScrollWheelEvent {
            position: point(px(20.0), px(20.0)),
            delta: ScrollDelta::Pixels(point(px(-120.0), px(0.0))),
            modifiers: Default::default(),
            touch_phase: gpui::TouchPhase::Moved,
        });
        cx.run_until_parked();
        assert!(observed_scroll.offset().x < px(0.0));
    }

