        let label = |agent_id: &str| {
            candidates
                .iter()
                .find(|candidate| candidate.agent_id.as_str() == agent_id)
                .map(|candidate| candidate.label.as_str())
        };

        // A configured Agent is searchable under the name the user gave it...
